/*
 * pt_renderer.c - the geometry side of the GPU raster (gpu_vk_raster.cpp): the room drawn from the game's own
 * room data (rl_emit_walk, section rules, z-fight pairs), actor bodies from the projector pools (pt_dc_proj,
 * pt_dc_poolprim), the room library for camera collision, shadows, impact marks and glints. The name is left
 * from the KF2_PT path tracer this file was ported from; the tracer itself (F5) was removed on 18.10.2026.
 */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <windows.h>
#include "pgxp.h"
#include "gpu_sw_renderer.h"
#include "cpu_state.h"
/* 10.10.2026: объявления для бесплатного компилятора установщика (Clang): здесь вызывались функции без объявления
 * выше по файлу - MSVC подставлял int f() сам, Clang требует объявления. */
int dc_fire_recent(void);
int dc_room_live_on(void);
int dc_scene_flag_on(void);
int dc_scripted_now(void);
int dc_shadow_scene_on(void);
int pt_poolgeom_enabled(void);
/* dc_boot.c: DC_DIAG_LOG - the whole of the mod's diagnostic output
 * hangs off this one switch, and it is off in a release build. */
int dc_diag_log(void);
#include "dc_pak.h"   /* ME: the data built into the program (17.09.2026) */

extern int    dc_ws_world(void);   /* 15.09: мир ужат под 16:9 — соотношение из меню SCREEN, на лету (memory.c) */
extern float  dc_ws_sq(void);      /* 10.10: множитель X мира - любая форма картинки (memory.c; было 0.75 / 1) */
extern uint8_t *memory_get_ram_ptr(void);
/* ---- Path B for the RASTER (DC_POOL_GEOM=1) -----------------------------
 * The path tracer draws the body from MODEL vertices times the bone matrix in
 * float, which is why it never loses a polygon. The normal renderer instead
 * recovers screen positions that were quantized to whole pixels by the game,
 * so dense body polygons collide on a pixel and vanish or merge.
 * Here the character assembler publishes, for each vertex word it writes into
 * the GP0 packet, the SAME float position the path tracer would compute. The
 * GP0 parser looks it up by that word's address, so nothing else changes.
 * Off by default; the reference build is untouched unless DC_POOL_GEOM=1. */
/* ---- direct body draw ---------------------------------------------- */
#include "pt_body.h"

#define PT_BODY_MAX 4096
static PtBodyPrim s_bodyp[PT_BODY_MAX];
static int s_bodyp_n = 0;
long g_body_kept = 0, g_body_over = 0;

int pt_body_direct(void) {
    /* O key (2026-08-30): original mode draws her the game's own way — the
     * float reconstruction AND the matching suppression of the game's copies
     * both key off this answer, so one gate flips the whole path at once. */
    /* 15.09 вечер: оригинальный режим рисует как современный — гейт только при DC_ORIG_NATIVE_DRAW=1 (memory.c) */
    { extern int dc_orig_native_draw(void); if (dc_orig_native_draw()) return 0; }
    static int on = -1;
    if (on < 0) { const char *e = getenv("DC_BODY_DIRECT"); on = (e && *e == '1') ? 1 : 0; }
    return on;
}

/* ===== BODY STEADY (2026-08-31, "трясучка в зонах движущихся камер") =====
 * Measured root cause: the game's own bone composites carry a ±6..8-unit
 * sawtooth in the WHOLE body's world position every other tick (motion-frame
 * root offsets are coarsely quantized), while the player position cells step
 * a perfectly even +30/tick (phJ trace: root RMS(d2)=8.14, cells=0.00) and
 * the coherence split of the prim dumps shows the saw is one shared vector
 * for the whole silhouette (mean-dx saw 1.15 prim-px vs 0.27 per-bone). On
 * the PS1 the whole frame — camera included — quantizes just as coarsely, so
 * it drowns; against OUR smooth camera the lone sawing body reads as
 * "Регина трясётся". Cancel just the COHERENT part: per assembly frame,
 * accumulate the body's world centroid c and the cells base b; the shimmer
 * lives in anim = c - b; median-3 it over time and shift the whole body by
 * (b + median(anim)) - c at flush. Pose, animation bob (period >> 3 ticks)
 * and real motion survive; the 2-3-tick quantization saw dies.
 * DC_BODY_STEADY=0 reverts. */
static uint32_t s_pgeo_stamp;            /* defined below with the pgeo table */
static double s_bst_sum[3]; static int s_bst_n = 0;
static float  s_bst_base[3];             /* cells (x, y, z) of the assembly tick */
static float  s_bst_R[9];                /* our camera rotation the body was built with */
static int    s_bst_have = 0;            /* base+R captured for the current stamp */
static unsigned s_bst_stamp = 0;         /* assembly frame the accumulator belongs to */
static float  s_bst_hist[4][3]; static int s_bst_hn = 0;   /* anim history (newest last) */
/* finished per-assembly-frame shifts, matched by stamp at flush time — the
 * flush can run MID-assembly of the next frame (PS1 draws frame N by DMA
 * while the CPU builds N+1; measured: flushes with half a body accumulated,
 * n=582 vs 1172, and a garbage centroid). */
#define BST_RING 4
typedef struct { unsigned stamp; float v[3]; int ok; } BstSlot;
static BstSlot s_bst_ring[BST_RING];
static int s_bst_ring_w = 0;
/* ⛔ OFF BY DEFAULT since 2026-08-31 night. Field verdict on the whole
 * "damp the body" family: the damping is visible as its own artefact (the
 * dead band rectified the step cycle into a sideways drift, the EMA lag
 * reads as a wobble of its own) and the shimmer it was aimed at is NOT
 * primarily the body's — see the O-mode control measurement in
 * dc_pt_camera_jitter. Kept behind DC_BODY_STEADY=1 for experiments. */
int pt_body_steady_enabled(void) {
    static int on = -1;
    if (on < 0) { const char *e = getenv("DC_BODY_STEADY"); on = (e && *e == '1') ? 1 : 0; }
    return on;
}
/* an assembly frame whose list was dropped unflushed: forget its centroid */
void pt_body_steady_drop(void) { s_bst_n = 0; s_bst_sum[0] = s_bst_sum[1] = s_bst_sum[2] = 0; s_bst_have = 0; }
/* assembly side: one world-space vertex of hers. TORSO ONLY by default:
 * the legs swing in counter-phase and CANCEL the torso's saw in a whole-body
 * centroid (measured: anim saw ±0.8 vs the anchors' ±5 — the anchors sit on
 * the torso), so the reference must be the part the eye actually reads.
 * World Y is negative-up; the torso/head live above ~800 units. Threshold in
 * units above the cells base via DC_BODY_STEADY_TORSO (0 = whole body). */
static void bst_add(float wx, float wy, float wz) {
    static float thr = -2.f;
    if (thr < -1.f) { const char *e = getenv("DC_BODY_STEADY_TORSO");
                      thr = e ? (float)atof(e) : 800.f; }
    if (thr > 0.f && (s_bst_base[1] - wy) < thr) return;   /* below the belt */
    s_bst_sum[0] += wx; s_bst_sum[1] += wy; s_bst_sum[2] += wz; s_bst_n++;
}
/* Close the frame accumulated so far: run the filter, park the result in the
 * stamp ring, clear the accumulator. Called when assembly moves to a new
 * stamp, or by the flush when it needs the still-open frame. */
static void bst_finalize(void);
/* assembly side: capture the base ONCE per assembly frame (first prim);
 * a stamp change closes the previous frame first. */
static void bst_frame_begin(const float No[9]) {
    if (s_bst_have && s_bst_stamp != s_pgeo_stamp) bst_finalize();
    if (s_bst_have) return;
    const uint8_t *r = memory_get_ram_ptr();
    s_bst_base[0] = (float)(int16_t)(r[0xB92AC] | (r[0xB92AD] << 8));
    s_bst_base[1] = (float)(int16_t)(r[0xB92AE] | (r[0xB92AF] << 8));
    s_bst_base[2] = (float)(int16_t)(r[0xB92B0] | (r[0xB92B1] << 8));
    for (int i = 0; i < 9; i++) s_bst_R[i] = No[i];
    s_bst_stamp = s_pgeo_stamp;
    s_bst_have = 1;
}
static void bst_finalize(void) {
    int ok = 0;
    if (s_bst_n >= 60 && s_bst_have) {
        float c[3] = { (float)(s_bst_sum[0] / s_bst_n),
                       (float)(s_bst_sum[1] / s_bst_n),
                       (float)(s_bst_sum[2] / s_bst_n) };
        float anim[3] = { c[0] - s_bst_base[0], c[1] - s_bst_base[1], c[2] - s_bst_base[2] };
        /* teleport / motion swap: a big jump resets the history (no smear) */
        if (s_bst_hn > 0) {
            float dj = 0.f;
            for (int i = 0; i < 3; i++) { float e = anim[i] - s_bst_hist[s_bst_hn-1][i]; dj += e*e; }
            if (dj > 200.f*200.f) s_bst_hn = 0;
        }
        if (s_bst_hn == 4) { for (int k = 0; k < 3; k++) for (int i = 0; i < 3; i++) s_bst_hist[k][i] = s_bst_hist[k+1][i]; s_bst_hn = 3; }
        for (int i = 0; i < 3; i++) s_bst_hist[s_bst_hn][i] = anim[i];
        s_bst_hn++;
        /* THE SAW IS BROADBAND (DFT of the control anchors: energy spread
         * over periods 2..7 against a 10-20-tick bob), so notch FIRs cannot
         * split it from the bob: [1,2,2,1]/6 left 0.42-0.45 prim-px, and
         * compensating its 1.5-tick group delay (needed — the raw delayed
         * counter-sway ADDED shimmer to static rooms and the dead band
         * rectified the asymmetric step cycle into a constant sideways
         * drift, player-confirmed) re-admitted the period-4+ half (0.70).
         * DEFAULT MODE ema: pin the torso's horizontal to the perfectly
         * smooth cells and let only the SLOW part of the animation offset
         * through — an adaptive EMA with a fast pull on real manoeuvres
         * (start/stop/turn change anim by >8 units/tick; the residual bob
         * surge is a couple of units and reads fine flattened at 30 fps).
         * DC_BODY_STEADY_MODE=fir restores the notch filter for A/B. */
        static int s_bst_mode = -1;
        if (s_bst_mode < 0) { const char *e = getenv("DC_BODY_STEADY_MODE");
                              s_bst_mode = (e && *e == 'f') ? 1 : 0; }
        float smc[3];
        if (s_bst_mode == 1) {
            float sm[3];
            if (s_bst_hn == 4) {
                for (int i = 0; i < 3; i++)
                    sm[i] = (s_bst_hist[0][i] + 2.f*s_bst_hist[1][i] + 2.f*s_bst_hist[2][i] + s_bst_hist[3][i]) / 6.f;
            } else { for (int i = 0; i < 3; i++) sm[i] = anim[i]; }
            static float s_bst_smp[3]; static int s_bst_smp_ok = 0;
            if (s_bst_smp_ok && s_bst_hn == 4) {
                for (int i = 0; i < 3; i++) smc[i] = sm[i] + 1.5f * (sm[i] - s_bst_smp[i]);
            } else { for (int i = 0; i < 3; i++) smc[i] = sm[i]; }
            for (int i = 0; i < 3; i++) s_bst_smp[i] = sm[i];
            s_bst_smp_ok = (s_bst_hn == 4);
        } else {
            static float ema[3]; static int ema_ok = 0;
            if (!ema_ok || s_bst_hn <= 1) { for (int i = 0; i < 3; i++) ema[i] = anim[i]; ema_ok = 1; }
            else {
                float dx = anim[0] - ema[0], dz = anim[2] - ema[2];
                float dev = sqrtf(dx*dx + dz*dz);
                float alpha = (dev > 8.f) ? 0.5f : 0.10f;   /* manoeuvre: pull fast */
                for (int i = 0; i < 3; i++) ema[i] += (anim[i] - ema[i]) * alpha;
            }
            for (int i = 0; i < 3; i++) smc[i] = ema[i];
        }
        /* horizontal only: the measured saw is in the ground plane (root.x
         * RMS(d2)=8.14 vs a clean, walk-cycle vertical bob). Filtering world
         * Y damped the legitimate bob and, through the camera tilt, leaked
         * into screen X — worse on both axes (measured). */
        float sw[3] = { smc[0] - anim[0], 0.f, smc[2] - anim[2] };
        /* dead band, a safety net only (0.5 unit) */
        for (int i = 0; i < 3; i += 2) {
            float a = sw[i] < 0.f ? -sw[i] : sw[i];
            if (a <= 0.5f) sw[i] = 0.f;
            else sw[i] *= (a - 0.5f) / a;
        }
        /* world -> our view rotation (translation only, so R alone) */
        BstSlot *slot = &s_bst_ring[s_bst_ring_w];
        slot->v[0] = s_bst_R[0]*sw[0] + s_bst_R[1]*sw[1] + s_bst_R[2]*sw[2];
        slot->v[1] = s_bst_R[3]*sw[0] + s_bst_R[4]*sw[1] + s_bst_R[5]*sw[2];
        slot->v[2] = s_bst_R[6]*sw[0] + s_bst_R[7]*sw[1] + s_bst_R[8]*sw[2];
        slot->stamp = s_bst_stamp; slot->ok = 1;
        s_bst_ring_w = (s_bst_ring_w + 1) % BST_RING;
        ok = 1;
        { static int ph = -1;
          if (ph < 0) { const char *e = getenv("DC_PHASEDBG"); ph = (e && *e == '1') ? 1 : 0; }
          if (ph) fprintf(stderr, "phS st=%u n=%d anim=%.1f,%.1f,%.1f sm=%.1f,%.1f,%.1f shv=%.2f,%.2f,%.2f%c",
                          s_bst_stamp, s_bst_n, anim[0], anim[1], anim[2], smc[0], smc[1], smc[2],
                          slot->v[0], slot->v[1], slot->v[2], 10); }
    }
    (void)ok;
    s_bst_n = 0; s_bst_sum[0] = s_bst_sum[1] = s_bst_sum[2] = 0; s_bst_have = 0;
}
/* flush side: the shift for the assembly frame the LIST was built in, matched
 * by stamp. If that frame's accumulator is still open (a flush after a fully
 * assembled frame, before the next one begins), close it now. */
int pt_body_steady_shift(float out_v[3], unsigned stamp) {
    if (!pt_body_steady_enabled()) { pt_body_steady_drop(); return 0; }
    if (s_bst_have && s_bst_stamp == stamp) bst_finalize();
    for (int i = 0; i < BST_RING; i++) {
        if (s_bst_ring[i].ok && s_bst_ring[i].stamp == stamp) {
            out_v[0] = s_bst_ring[i].v[0];
            out_v[1] = s_bst_ring[i].v[1];
            out_v[2] = s_bst_ring[i].v[2];
            return 1;
        }
    }
    return 0;
}
void pt_body_reset(void) { s_bodyp_n = 0; }
/* The list is flushed when the GP0 parser meets the first recognised body
 * primitive of the packet built in the PREVIOUS game frame (the console
 * assembles in one frame and DMAs in the next). If that flush never came -
 * every lookup missed that frame - the list must not survive into the next
 * build or the body is drawn twice. Called from the projector at the first
 * capture of a new frame (stamp = the per-present pgeo stamp). */
/* DC_BODYDBG=1 (15.09.2026, отладка «в сцене перехода пропадает часть полигонов Регины»):
 * покадровый след пути тела — сколько полигонов собрано под каждым штампом, какие списки
 * выброшены без отрисовки, каждый вызов отрисовки тела из потока GP0 и сколько игровых копий
 * подавлено за кадр. Только печать, поведение не меняется. */
static int s_bdbg = -1;
int pt_bodydbg_on(void) {
    if (s_bdbg < 0) { const char *e = getenv("DC_BODYDBG"); s_bdbg = (e && *e == '1') ? 1 : 0; }
    return s_bdbg;
}
static long s_bdbg_added = 0;                  /* полигонов тела под текущим штампом сборки */
static long s_bdbg_flush_n = 0, s_bdbg_flush_calls = 0, s_bdbg_empty_before = 0, s_bdbg_empty_after = 0;
static int  s_bdbg_flushed_this = 0;
/* подписи полигонов, нарисованных последней отрисовкой тела: страница + набор uv */
#define BDBG_SIG 8192
static uint64_t s_bdbg_sig[BDBG_SIG]; static int s_bdbg_sig_n = 0;
static long s_bdbg_unmatched[2], s_bdbg_matched[2];
static uint64_t bdbg_sig(int nv, unsigned tpage, const int *u, const int *v) {
    uint32_t k[4]; int n = nv > 4 ? 4 : nv;
    for (int i = 0; i < n; i++) k[i] = ((uint32_t)(u[i] & 0xFF) << 8) | (uint32_t)(v[i] & 0xFF);
    for (int i = 1; i < n; i++) { uint32_t t = k[i]; int j = i - 1; while (j >= 0 && k[j] > t) { k[j+1] = k[j]; j--; } k[j+1] = t; }
    uint64_t h = 1469598103934665603ull ^ (uint64_t)(tpage & 0x1FFu) ^ ((uint64_t)n << 12);
    for (int i = 0; i < n; i++) { h ^= k[i]; h *= 1099511628211ull; }
    return h;
}
/* вызов из gpu.c перед подавлением игровой копии: path 0 = реестр (kind 3), 1 = pgeo-игрок */
void pt_bodydbg_path(int path, int nv, unsigned tpage, unsigned clut, const int *u, const int *v, const int *x, const int *y) {
    if (!pt_bodydbg_on()) return;
    uint64_t h = bdbg_sig(nv, tpage, u, v);
    int hit = 0;
    for (int i = 0; i < s_bdbg_sig_n; i++) if (s_bdbg_sig[i] == h) { hit = 1; break; }
    if (hit) { s_bdbg_matched[path & 1]++; return; }
    s_bdbg_unmatched[path & 1]++;
    static long nlog = 0;
    if (++nlog <= 400) {
        extern uint64_t s_frame_count;
        fprintf(stderr, "bodydbg: SUPPRESSED-NOT-DRAWN path=%s pkind=%d nv=%d tpage=%03X clut=%04X uv=%d,%d %d,%d %d,%d%s xy=%d,%d %d,%d %d,%d vbl=%llu%c",
                (path & 1) ? "pgeo" : "kind3", path >> 4, nv, tpage & 0x1FFu, clut & 0xFFFFu,
                u[0], v[0], u[1], v[1], u[2], v[2], nv > 3 ? " +1" : "",
                x[0], y[0], x[1], y[1], x[2], y[2], (unsigned long long)s_frame_count, 10);
    }
}
void pt_bodydbg_flush(int n, unsigned list_stamp) {
    if (!pt_bodydbg_on()) return;
    if (n > 0) {
        s_bdbg_sig_n = 0;
        for (int i = 0; i < n && i < s_bodyp_n && s_bdbg_sig_n < BDBG_SIG; i++)
            s_bdbg_sig[s_bdbg_sig_n++] = bdbg_sig(s_bodyp[i].nv, s_bodyp[i].tpage, s_bodyp[i].u, s_bodyp[i].v);
    }
    extern uint64_t s_frame_count; extern uint64_t gpu_flip_seq(void);
    if (n > 0) {
        s_bdbg_flush_calls++; s_bdbg_flush_n += n; s_bdbg_flushed_this = 1;
        { extern int g_dc_pass_id, g_dc_dma_pass;
          fprintf(stderr, "bodydbg: FLUSH n=%d list_stamp=%u cur_stamp=%u pass=%d..%d cur_pass=%d dma_pass=%d vbl=%llu flip=%llu%c",
                n, list_stamp, (unsigned)s_pgeo_stamp, s_bodyp[0].pass, s_bodyp[n - 1].pass, g_dc_pass_id, g_dc_dma_pass,
                (unsigned long long)s_frame_count, (unsigned long long)gpu_flip_seq(), 10); }
    } else if (s_bdbg_flushed_this) s_bdbg_empty_after++;
    else s_bdbg_empty_before++;
}
void pt_body_new_frame(unsigned stamp) {
    static unsigned last = 0xFFFFFFFFu;
    if (stamp != last) {
        if (pt_bodydbg_on()) {
            extern uint64_t s_frame_count;
            if (last != 0xFFFFFFFFu)
                fprintf(stderr, "bodydbg: CAPTURE stamp=%u added=%ld%s%c", last, s_bdbg_added,
                        s_bodyp_n > 0 ? " (not flushed)" : "", 10);
            if (s_bodyp_n > 0)
                { extern int g_dc_pass_id;
                  fprintf(stderr, "bodydbg: DROP n=%d list_stamp=%u new_stamp=%u pass=%d..%d cur_pass=%d vbl=%llu%c",
                        s_bodyp_n, s_bodyp[0].stamp, stamp, s_bodyp[0].pass, s_bodyp[s_bodyp_n - 1].pass, g_dc_pass_id,
                        (unsigned long long)s_frame_count, 10); }
            s_bdbg_added = 0;
        }
        if (s_bodyp_n > 0) { static long n = 0; if (++n <= 4) fprintf(stderr, "body: %d unflushed prims dropped at new frame%c", s_bodyp_n, 10); }
        s_bodyp_n = 0; last = stamp;
    }
}
/* ⭐ СПИСОК ТЕЛА ДЕРЖИТСЯ ЗА ПРОХОД ОТРИСОВКИ ИГРЫ, А НЕ ЗА ПОКАЗ (15.09.2026, игрок, слот 6:
 * «в сцене перехода, где Регина поднимается, пропадает часть её полигонов; так во многих
 * сценах с дверьми», в режиме O бага нет). Замер DC_BODYDBG + DC_PASSDBG + DC_DOOR_DUMP +
 * кольцо GP0: игра присылает все 455 её полигонов в КАЖДОМ кадре сцены, а мы нарисовали
 * 200 / 315 / 427 в трёх кадрах подъёма. Штамп сборки — номер показа, а показ пришёл
 * ПОСРЕДИ сборки тела (игра параллельно грузит следующую комнату, кадр затянулся): 255
 * полигонов под штампом 446, остальные 200 уже под 447 — pt_body_new_frame приняла смену
 * штампа за новый кадр и выбросила первые 255, игровые копии всех 455 подавлены реестром.
 * Оба куска — ОДИН проход 279 (g_dc_pass_id, хук камеры оркестратора). По всей записи
 * (геймплей + сцена + новая комната): 776 отрисовок тела, в каждой ровно один проход,
 * проходы подряд без пропусков, все 3 выброса — внутри прохода. Теперь новый список
 * начинается со сменой прохода; страховка от повтора сборки без отрисовки — тот же адрес
 * первого пакета. DC_BODY_LIST_KEY=stamp — прежнее поведение. */
void pt_body_new_frame(unsigned stamp);
void pt_body_capture_begin(unsigned stamp, int pass, uint32_t pkt) {
    static int key = -1;
    if (key < 0) { const char *e = getenv("DC_BODY_LIST_KEY"); key = (e && *e == 's') ? 0 : 1; }
    if (!key) { pt_body_new_frame(stamp); return; }
    static int last_pass = -0x7FFFFFFF; static uint32_t first_pkt = 0;
    int restart = (pass != last_pass) || (s_bodyp_n > 0 && pkt == first_pkt);
    if (!restart) { if (s_bodyp_n == 0) first_pkt = pkt; return; }
    if (pt_bodydbg_on()) {
        extern uint64_t s_frame_count;
        fprintf(stderr, "bodydbg: CAPTURE pass=%d added=%ld%s%c", last_pass, s_bdbg_added,
                s_bodyp_n > 0 ? " (not flushed)" : "", 10);
        if (s_bodyp_n > 0)
            fprintf(stderr, "bodydbg: DROP n=%d list_pass=%d new_pass=%d same_pkt=%d vbl=%llu%c",
                    s_bodyp_n, s_bodyp[0].pass, pass, (pass == last_pass), (unsigned long long)s_frame_count, 10);
        s_bdbg_added = 0;
    }
    if (s_bodyp_n > 0) { static long n = 0; if (++n <= 4) fprintf(stderr, "body: %d unflushed prims dropped at new pass%c", s_bodyp_n, 10); }
    s_bodyp_n = 0; last_pass = pass; first_pkt = pkt;
}
int pt_body_count(void) { return s_bodyp_n; }
const PtBodyPrim *pt_body_at(int i) {
    return (i >= 0 && i < s_bodyp_n) ? &s_bodyp[i] : 0;
}

/* Same collision story as the owner registry above (2026-08-23 night): every
 * skinned character publishes here, so with Regina + a raptor the live load is
 * ~2000 keys over two stamps and a single-slot 16k table dropped ~110 of them
 * per frame - those polygons fell back to the PGXP pixel cache instead of the
 * reconstruction, a different subset each frame. 64k slots + 4-way probing. */
#define PGEO_HASH 65536u
#define PGEO_PROBE 4u
typedef struct { uint64_t key; uint32_t stamp; int n; float fx[4], fy[4], w[4]; uint8_t player; uint32_t ctx;
                 int pass; int8_t bone[4]; uint32_t ptag[4]; } PGeoEnt;   /* 20.10: bone - её кость вершины (-1 - нет) */           /* 25.09 ночь: pass — проход сборки (g_dc_pass_id), см. pt_shx_take */
                                                                         /* 26.10: ptag - метка куска вершины (пары кусков, 0 - нет) */
/* WHOSE BODY (2026-08-23). Every skinned character - Regina AND the
 * dinosaurs - comes through the assembler pool, so "pool primitive" does not
 * mean "Regina": the first short-boom dissolve dithered a raptor standing
 * next to her. The projector knows the camera-removed world position of the
 * bone it is transforming (trN); Regina's own skeleton publishes the same
 * positions in RAM (node f: P_f @ 0xB9500 + f*172, int32 x3). A bone whose
 * trN coincides with one of hers is hers. pt_poolgeom_prim / _vtxn report the
 * owner of the last primitive served in g_pgeo_last_player; gpu.c turns it
 * into F_ACTOR (the fade) for her and nothing for anyone else. */
int g_pgeo_last_player = 0;
int g_pgeo_last_bone[4] = { -1, -1, -1, -1 };   /* 20.10: её кости вершин последнего поданного из пула полигона */
int g_pps_last_bone = -1;                       /* 20.10: кость последнего узнанного реестром (кисть / оружие / волосы) */
uint32_t g_pgeo_last_ctx = 0;          /* 25.09: владелец кости последнего поданного из пула полигона (F_CHAR) */
/* 26.10.2026: метки кусков вершин последнего поданного из сборки полигона (pt_poolgeom_prim_uv; 0 - нет). Его точные координаты
 * пересчитаны из вершин модели, по ним метку проекции (gte.cpp pgxp_pair_of) не найти: тела зверей и других персонажей в сцене
 * оставались без пары, и кадры между тактами выключались. */
uint32_t g_pgeo_last_ptag[4] = { 0u, 0u, 0u, 0u };
int g_dc_laser_jump = 0;               /* 09.10: сторож лазера (rl_emit_walk) — лазер прыгнул; main.cpp: DC_RING_LASER */
static int s_pool_cur_player = 0;
static uint32_t s_pool_cur_ctx = 0;   /* projector's character context: whose bone this is */
static int pool_bone_is_regina(const float trN[3]) {
    static int en = -1; static float tol = 48.f;
    if (en < 0) { const char *e = getenv("DC_ACTOR_OWNER"); en = (e && *e == '0') ? 0 : 1;
                  e = getenv("DC_ACTOR_OWNER_TOL"); if (e) tol = (float)atof(e); }
    if (!en) return 1;                       /* old behaviour: every pool body is "her" */
    const uint8_t *r = memory_get_ram_ptr(); if (!r) return 1;
    for (int f = 0; f < 20; f++) {
        uint32_t a = 0xB9500u + (uint32_t)f * 172u;
        float px = (float)(int32_t)(r[a]   | (r[a+1] << 8) | (r[a+2] << 16) | (r[a+3] << 24));
        float py = (float)(int32_t)(r[a+4] | (r[a+5] << 8) | (r[a+6] << 16) | (r[a+7] << 24));
        float pz = (float)(int32_t)(r[a+8] | (r[a+9] << 8) | (r[a+10] << 16) | (r[a+11] << 24));
        /* either axis order - the engine frame and the node frame have been
         * seen permuted (z,y,x) against each other; a match in either is hers */
        float d1 = fabsf(trN[0]-px) + fabsf(trN[1]-py) + fabsf(trN[2]-pz);
        float d2 = fabsf(trN[0]-pz) + fabsf(trN[1]-py) + fabsf(trN[2]-px);
        if (d1 < tol || d2 < tol) return 1;
    }
    { static int st = -1; static long n = 0;
      if (st < 0) { const char *e = getenv("DC_OWNER_DBG"); st = (e && *e == '1') ? 1 : 0; }
      if (st && (++n % 200) == 1) {
          uint32_t a = 0xB9500u;
          float px = (float)(int32_t)(r[a] | (r[a+1] << 8) | (r[a+2] << 16) | (r[a+3] << 24));
          float py = (float)(int32_t)(r[a+4] | (r[a+5] << 8) | (r[a+6] << 16) | (r[a+7] << 24));
          float pz = (float)(int32_t)(r[a+8] | (r[a+9] << 8) | (r[a+10] << 16) | (r[a+11] << 24));
          fprintf(stderr, "owner: bone trN=(%.0f,%.0f,%.0f) not hers; her P_0=(%.0f,%.0f,%.0f) cells x=%d z=%d%c",
                  trN[0], trN[1], trN[2], px, py, pz,
                  (int16_t)(r[0xB92B0] | (r[0xB92B1] << 8)), (int16_t)(r[0xB92C0] | (r[0xB92C1] << 8)), 10); } }
    return 0;
}
/* ⭐ 20.10.2026 - ЕЁ КОСТИ ДЛЯ КАДРОВ МЕЖДУ ТАКТАМИ (игрок, слот 42: «в прицеле целюсь вверх-вниз - рука с пистолетом
 * стробит, двигается рывками; влево-вправо ровно; то же с остальным оружием»; «сами анимации не меняй - задача сделать гладким,
 * чтобы не тряслось»). Позу игра собирает раз в такт (30 Гц), а кадры между тактами (Frame Rate 60/120) рисовали её вершины
 * такта как есть: камера шла вверх плавно, рука с оружием стояла на позе прошлого такта и догоняла рывком на следующем (замер
 * aim_vert.py, копия слота 42: пистолет на кадре B на 4-9 точек ниже середины соседних кадров такта). Теперь у каждой её вершины
 * есть номер кости, а у каждого прохода отрисовки игры (g_dc_pass_id) - снимок её мировых костей (rN, trN проектора); кадр между
 * тактами двигает вершины рук, кистей (с оружием) и головы на долю пути от позы этого такта к позе следующего относительно
 * корпуса (gpu_vk_raster.cpp arm_warp_make, dc_raster.vert). Кадры тактов - ровно позы игры. DC_ARM_WARP=0 - как было. */
static int s_pool_cur_bone = -1;             /* её кость, которую сейчас переводит проектор (-1 - не её / не узнана) */
#define SKEL_RING  4
#define SKEL_BONES 16
typedef struct { int pass; uint32_t mask; float rN[SKEL_BONES][9], trN[SKEL_BONES][3], vr[SKEL_BONES][9], vt[SKEL_BONES][3];
                 int dhave; float dD[9], dT[3]; } SkelSnap;
static SkelSnap s_skel[SKEL_RING];
static long s_bone_node = 0, s_bone_pos = 0, s_bone_none = 0, s_bone_diff = 0;   /* DC_ARMWARP_DBG: как узнана кость */
int pt_arm_warp_mode(void) {                 /* 0 - выкл., 1 - в прицеле, 2 - всегда (25.10: умолч., весь скелет - gpu_vk_raster.cpp arm_warp_make) */
    static int v = -1;
    if (v < 0) { const char *e = getenv("DC_ARM_WARP"); v = e ? atoi(e) : 2; }
    return v;
}
static int pool_bone_by_pos(const float trN[3], float tol) {
    const uint8_t *r = memory_get_ram_ptr(); if (!r) return -1;
    int best = -1; float bd = tol;
    for (int f = 0; f < 15; f++) {
        uint32_t a = 0xB9500u + (uint32_t)f * 172u;
        float px = (float)(int32_t)(r[a]   | (r[a+1] << 8) | (r[a+2] << 16) | (r[a+3] << 24));
        float py = (float)(int32_t)(r[a+4] | (r[a+5] << 8) | (r[a+6] << 16) | (r[a+7] << 24));
        float pz = (float)(int32_t)(r[a+8] | (r[a+9] << 8) | (r[a+10] << 16) | (r[a+11] << 24));
        float d1 = fabsf(trN[0]-px) + fabsf(trN[1]-py) + fabsf(trN[2]-pz);
        float d2 = fabsf(trN[0]-pz) + fabsf(trN[1]-py) + fabsf(trN[2]-px);
        float d = d1 < d2 ? d1 : d2;
        if (d < bd) { bd = d; best = f; }
    }
    return best;
}
/* узел кости в s0 проектора - матрица узла 0xB94EC + f*172; иначе - ближайший узел по мировому положению P_f */
static int pool_bone_index(uint32_t node, const float trN[3]) {
    const uint32_t n0 = node & 0x1FFFFFu;
    int fn = -1;
    if (n0 >= 0xB94ECu && n0 < 0xB94ECu + (uint32_t)SKEL_BONES * 172u && (n0 - 0xB94ECu) % 172u == 0u) fn = (int)((n0 - 0xB94ECu) / 172u);
    static int dbg = -1;
    if (dbg < 0) { const char *e = getenv("DC_ARMWARP_DBG"); dbg = (e && *e == '1') ? 1 : 0; }
    if (fn >= 0 && !dbg) { s_bone_node++; return fn; }
    const int fp = pool_bone_by_pos(trN, 48.f);
    if (fn >= 0) { s_bone_node++; if (fp != fn) s_bone_diff++; return fn; }
    if (fp >= 0) s_bone_pos++; else s_bone_none++;
    return fp;
}
static void skel_put(int pass, int f, const float *rN, const float *trN, const float *r9, const float *tr3) {
    if (f < 0 || f >= SKEL_BONES) return;
    SkelSnap *s = &s_skel[pass & (SKEL_RING - 1)];
    if (s->pass != pass) { extern int dc_nots_get_delta(float D[9], float T[3]);
                           s->pass = pass; s->mask = 0; s->dhave = dc_nots_get_delta(s->dD, s->dT); }
    if (s->mask & (1u << f)) return;                        /* кость за проход - первая запись */
    memcpy(s->rN[f], rN, 9 * sizeof(float)); memcpy(s->trN[f], trN, 3 * sizeof(float));
    memcpy(s->vr[f], r9, 9 * sizeof(float)); memcpy(s->vt[f], tr3, 3 * sizeof(float));
    s->mask |= 1u << f;
}
int pt_skel_get(int pass, int f, float rN[9], float trN[3]) {   /* gpu_vk_raster.cpp arm_warp_make */
    if (f < 0 || f >= SKEL_BONES) return 0;
    const SkelSnap *s = &s_skel[pass & (SKEL_RING - 1)];
    if (s->pass != pass || !(s->mask & (1u << f))) return 0;
    memcpy(rN, s->rN[f], 9 * sizeof(float)); memcpy(trN, s->trN[f], 3 * sizeof(float));
    return 1;
}
/* ⭐ 21.10.2026 (2): её кость прохода в ВИДОВОМ пространстве - матрица GTE, которой проектор перевёл её вершины (вид камеры,
 * что их нарисовала). rN/trN выше - «мир» через слот камеры игры 0xBF9F4, а в нашем режиме там неподвижная камера комнаты, не
 * наша: для сдвига костей между тактами (arm_warp_make) годится только видовая. */
int pt_skel_get_view(int pass, int f, float r9[9], float tr3[3]) {
    if (f < 0 || f >= SKEL_BONES) return 0;
    const SkelSnap *s = &s_skel[pass & (SKEL_RING - 1)];
    if (s->pass != pass || !(s->mask & (1u << f))) return 0;
    memcpy(r9, s->vr[f], 9 * sizeof(float)); memcpy(tr3, s->vt[f], 3 * sizeof(float));
    return 1;
}
/* ⭐ 21.10.2026 (3): вид GTE - это вид КАМЕРЫ ИГРЫ (неподвижной камеры комнаты); её вершины в кадре - он же, переприцеленный
 * в нашу камеру: view' = D.view + T (gte.cpp, сборщик тела ниже - dc_nots_get_delta). Дельта прохода - на первой её кости.
 * 0 - переприцела нет (оригинальный режим, сцена): вид кадра и есть вид GTE. */
int pt_skel_get_delta(int pass, float D[9], float T[3]) {
    const SkelSnap *s = &s_skel[pass & (SKEL_RING - 1)];
    if (s->pass != pass || !s->dhave) return 0;
    memcpy(D, s->dD, 9 * sizeof(float)); memcpy(T, s->dT, 3 * sizeof(float));
    return 1;
}
void pt_bone_stat(long *node, long *pos, long *none, long *diff) { *node = s_bone_node; *pos = s_bone_pos; *none = s_bone_none; *diff = s_bone_diff; }
static PGeoEnt s_pgeo[PGEO_HASH];
static uint32_t s_pgeo_stamp = 1;   /* tentatively declared above the body-steady block */
/* ⭐ 19.10.2026 (игрок: «прицел - ускорить»): «враг под перекрестием» (dc_aim_geom_any - перекрестие краснеет) и «чьё тело под
 * перекрестием» (dc_aim_geom_first - выбор цели) каждый кадр прицела проходили ВСЮ таблицу - 65536 записей, 5 МБ, дважды; нужны
 * же из неё только записи этого и прошлого штампа проектора (пара тысяч). Теперь pgeo_put запоминает номер записи в списке своего
 * штампа (два списка: текущий и прошлый, меняются при смене штампа), а проверки идут по номерам из двух списков в порядке
 * возрастания (битовая карта: без повторов, тот же порядок, что у прохода всей таблицы) - ответ тот же: записи вне списков штампа
 * st или st-1 не имеют, проход их и так пропускал. Список переполнен - прежний проход всей таблицы. DC_AIM_FRESH=0 - как было. */
enum { PGEO_FRESH_CAP = 65536 };
static uint16_t s_pgeo_fresh[2][PGEO_FRESH_CAP];
static int      s_pgeo_fresh_n[2] = { 0, 0 }, s_pgeo_fresh_over[2] = { 0, 0 }, s_pgeo_fresh_cur = 0;
static uint32_t s_pgeo_fresh_st[2] = { 1, 0 };          /* штамп каждого списка (начальный штамп - 1) */
static uint64_t s_pgeo_cand[PGEO_HASH / 64];
static int pgeo_fresh_on(void) {                        /* 0 - выкл., 1 - вкл., 2 - оба прохода со сверкой (строки aimfresh:) */
    static int v = -1;
    if (v < 0) { const char *e = getenv("DC_AIM_FRESH"); v = (e && *e == '0') ? 0 : (e && *e == '2') ? 2 : 1; }
    return v;
}
static inline void pgeo_fresh_note(uint32_t idx) {
    const int k = s_pgeo_fresh_cur;
    if (s_pgeo_fresh_n[k] < PGEO_FRESH_CAP) s_pgeo_fresh[k][s_pgeo_fresh_n[k]++] = (uint16_t)idx;
    else s_pgeo_fresh_over[k] = 1;
}
static void pgeo_fresh_advance(void) {                  /* штамп проектора сменился (s_pgeo_stamp уже новый) */
    s_pgeo_fresh_cur ^= 1;
    const int k = s_pgeo_fresh_cur;
    s_pgeo_fresh_n[k] = 0; s_pgeo_fresh_over[k] = 0; s_pgeo_fresh_st[k] = s_pgeo_stamp;
}
/* карта кандидатов для штампа st: записи, написанные при st и st-1; 0 - карты нет (выкл., переполнение, списки не того штампа) */
static int pgeo_fresh_cands(uint32_t st) {
    if (!pgeo_fresh_on()) return 0;
    const int c = s_pgeo_fresh_cur, p = c ^ 1;
    if (s_pgeo_fresh_st[c] != st || s_pgeo_fresh_over[c]) return 0;
    if (s_pgeo_fresh_over[p] && s_pgeo_fresh_st[p] + 1u == st) return 0;
    memset(s_pgeo_cand, 0, sizeof s_pgeo_cand);
    for (int k = 0; k < 2; k++) {
        if (k == p && s_pgeo_fresh_st[p] + 1u != st) continue;     /* прошлого списка нет (самое начало) */
        const uint16_t *L = s_pgeo_fresh[k];
        for (int i = 0; i < s_pgeo_fresh_n[k]; i++) s_pgeo_cand[L[i] >> 6] |= 1ull << (L[i] & 63);
    }
    return 1;
}
/* следующий кандидат с номером >= i (или PGEO_HASH) */
static inline uint32_t pgeo_cand_next(uint32_t i) {
    uint32_t w = i >> 6;
    if (w >= PGEO_HASH / 64) return PGEO_HASH;
    uint64_t m = s_pgeo_cand[w] & (~0ull << (i & 63));
    while (!m) { if (++w >= PGEO_HASH / 64) return PGEO_HASH; m = s_pgeo_cand[w]; }
#if defined(_MSC_VER) && !defined(__clang__)
    unsigned long b; _BitScanForward64(&b, m);
#else
    const unsigned b = (unsigned)__builtin_ctzll(m);
#endif
    return (w << 6) | (uint32_t)b;
}
long g_pgeo_calls = 0, g_pgeo_pub = 0, g_pgeo_far = 0, g_pgeo_behind = 0;

/* Vertex-level table: packed screen word -> exact float position, filled by
 * the PROJECTOR (which runs before the assembler computes NCLIP). It lets the
 * NCLIP hook recognise a body triangle and give the game the TRUE area, so a
 * polygon that merely rounded to zero pixels is no longer discarded. */
/* Per-VERTEX table: the projector publishes every vertex it writes into the
 * character pool - thousands per frame - so 8192 single slots thrashed badly
 * (2026-08-23 night). 256k slots is 6 MB and makes the fallback path reliable
 * instead of a lottery; the entries are keyed by the packed screen word, so a
 * lost one silently downgraded a body vertex to the PGXP pixel cache. */
#define PVX_HASH 262144u
typedef struct { uint32_t packed; uint32_t stamp; float fx, fy, w; uint8_t player; uint8_t amb; uint32_t ctx; int8_t bone; } PVxEnt;   /* 04.10 (2): amb — в этот пиксель за кадр легли разные вершины */
static PVxEnt s_pvx[PVX_HASH];

/* ===== GEOMETRY AIM TEST (2026-08-30, player: "попадания должны считаться
 * по геометрии динозавра, а не по кубу в центре"). The projector publishes
 * every transformed character vertex here with its SCREEN position and a
 * player flag - so "is the crosshair on the enemy" is answerable against the
 * actual posed mesh: any fresh non-player vertex within rad pixels of the
 * projection centre (the crosshair) is a hit. Result cached per stamp. */
extern float g_pt_proj_ofx, g_pt_proj_ofy;
int dc_aim_geom_hit(float rad) {
    static uint32_t lastst = 0; static int cached = 0; static float lastrad = -1.f;
    uint32_t st = s_pgeo_stamp;
    if (st == lastst && rad == lastrad) return cached;
    lastst = st; lastrad = rad;
    float cx = g_pt_proj_ofx, cy = g_pt_proj_ofy;
    float r2 = rad * rad;
    int hit = 0;
    for (uint32_t i = 0; i < PVX_HASH; i++) {
        const PVxEnt* e = &s_pvx[i];
        if (e->player || e->w <= 0.f) continue;
        if (e->stamp != st && e->stamp + 1u != st) continue;
        float dx = e->fx - cx, dy = e->fy - cy;
        if (dx*dx + dy*dy <= r2) { hit = 1; break; }
    }
    cached = hit;
    return hit;
}
/* ===== DOES THE SHOT RAY ACTUALLY CROSS THE CREATURE? (2026-08-31 night) ===
 * The gate used to ask whether any posed VERTEX of a creature fell within a
 * few pixels of the crosshair. Vertices are sparse - between them a shot
 * passes through the body and counts as a miss, and near them a shot that
 * visibly went by counts as a hit - so the gate leaned on a 120-unit "close
 * enough" core, which at shotgun range is a third of the screen wide.
 * This is the real thing: the crosshair is the ray, and the assembler's own
 * projected POLYGONS are the body, so a hit is the crosshair landing inside
 * one of the creature's triangles. Same data the reconstruction already
 * publishes (pgeo, float positions with true w), only the creatures' - the
 * player's own prims are flagged and skipped. Depth must be positive, so a
 * polygon behind the camera cannot register. */
static int pgeo_pt_in_tri(float px, float py,
                          float ax, float ay, float bx, float by, float cx2, float cy2) {
    /* A DEGENERATE TRIANGLE IS NOT A HIT (2026-08-31 night - this was the
     * whole bug behind "целюсь мимо, но попадаю"). A character's projection
     * is full of collapsed polygons every frame: edges turned to the camera,
     * zero-area slivers, bones folded on themselves. For those, all three
     * edge cross-products are 0, so the classic "no mixed signs = inside"
     * test answered INSIDE for every point on the screen - and one such
     * polygon anywhere in the creature made the trace report a hit wherever
     * the crosshair was pointing. Area first, and only then the sign test. */
    float area = (bx-ax)*(cy2-ay) - (cx2-ax)*(by-ay);
    if (area < 0.f) area = -area;
    if (area < 1.0f) return 0;            /* sliver / collapsed: no surface to hit */
    float d1 = (px-bx)*(ay-by) - (ax-bx)*(py-by);
    float d2 = (px-cx2)*(by-cy2) - (bx-cx2)*(py-cy2);
    float d3 = (px-ax)*(cy2-ay) - (cx2-ax)*(py-ay);
    int neg = (d1 < 0.f) || (d2 < 0.f) || (d3 < 0.f);
    int pos = (d1 > 0.f) || (d2 > 0.f) || (d3 > 0.f);
    return !(neg && pos);                 /* all on the same side = inside */
}
/* THE SAME RAY THE DECALS USE (player: "ты же декали проецируешь - вот по
 * такому же принципу", "трейс должен коллайдиться с геометрией динозавра").
 * The decal ray leaves the camera eye along the camera forward and is stopped
 * by the first wall (dc_impact_raycast). This is that ray meeting a creature:
 * the crosshair IS that ray in projection, so a polygon of the creature that
 * covers the crosshair is a polygon the ray passes through - and it only
 * counts if the creature is NEARER than the wall the same ray would hit, so
 * shooting a crate with a raptor behind it is a miss, as it should be.
 * `actor` narrows it to the creature the shot is being credited to: another
 * creature's polygons must never pay for this one. */
float    g_aim_hit_pt[3] = { 0.f, 0.f, 0.f };  /* where the crosshair ray met the creature */
uint32_t g_aim_hit_actor = 0;
uint64_t g_aim_hit_vb    = 0;
/* ===== CREATURES DRAWN FROM MODS (06.10.2026) ==============================
 * Player: "the dinosaurs of other kinds I added are not detected - the reticle does not go red and they cannot be killed; the
 * ten raptors were". A creature whose model comes from mods (dc_meshrep.cpp: an enemy kind of another room drawn with its own
 * pictures from mods\rooms\<ROOM>\kinds, or a model of the player's own) is not built by the game's assembler, so it puts no
 * polygons into pgeo and the crosshair ray found nobody. The mesh path tests the crosshair against the model's own triangles
 * (dc_meshrep.cpp pick_note: same skinning, camera and projection as its drawing) and publishes the nearest depth there, with
 * the projector's stamp; the three tests below take it as a polygon of that creature under the crosshair.
 * DC_AIM_MODPICK=0 - polygons only, as before. */
#define MODPICK_MAX 16
typedef struct { uint32_t ctx, stamp; float depth; } ModPick;
static ModPick s_modpick[MODPICK_MAX];
static int modpick_on(void) {
    static int en = -1;
    if (en < 0) { const char *e = getenv("DC_AIM_MODPICK"); en = (e && *e == '0') ? 0 : 1; }
    return en;
}
void dc_aim_modpick_note(uint32_t ctx, float depth) {
    if (!modpick_on()) return;
    ctx &= 0x1FFFFFu;
    int slot = -1;
    for (int i = 0; i < MODPICK_MAX && slot < 0; i++) if (s_modpick[i].ctx == ctx) slot = i;
    for (int i = 0; i < MODPICK_MAX && slot < 0; i++)
        if (s_modpick[i].stamp != s_pgeo_stamp && s_modpick[i].stamp + 1u != s_pgeo_stamp) slot = i;
    if (slot < 0) return;
    s_modpick[slot].ctx = ctx; s_modpick[slot].stamp = s_pgeo_stamp; s_modpick[slot].depth = depth;
}
/* a creature drawn from mods under the crosshair: the depth of its nearest triangle there, else 0 */
static float modpick_hit(const ModPick *m, uint32_t st, float cx, float cy) {
    (void)cx; (void)cy;
    if (!modpick_on() || !m->ctx || (m->stamp != st && m->stamp + 1u != st)) return 0.f;
    return m->depth > 1.f ? m->depth : 0.f;
}
/* 19.10.2026: три прохода прицела по таблице - вынесены, чтобы ходить по картам кандидатов (fc) или по всей таблице (fc = 0,
 * прежний проход; им же сверка DC_AIM_FRESH=2). Тела проходов - прежние, порядок записей тот же. */
typedef struct { int hit; float best; int nfresh, nmine; uint32_t seen1, seen2; } AimRay;
static void aim_scan_ray(uint32_t st, int fc, uint32_t want, float cx, float cy, AimRay *o) {
    memset(o, 0, sizeof *o); o->best = 1e9f;
    for (uint32_t i = fc ? pgeo_cand_next(0) : 0; i < PGEO_HASH; i = fc ? pgeo_cand_next(i + 1) : i + 1) {
        const PGeoEnt *e = &s_pgeo[i];
        if (e->key == 0 || e->player || e->n < 3) continue;
        if (e->stamp == st || e->stamp + 1u == st) {
            o->nfresh++;
            uint32_t c = e->ctx & 0x1FFFFFu;
            if (!o->seen1) o->seen1 = c; else if (c != o->seen1 && !o->seen2) o->seen2 = c;
        }
        if ((e->ctx & 0x1FFFFFu) != want) continue;        /* this creature only */
        if (e->stamp != st && e->stamp + 1u != st) continue;
        o->nmine++;
        if (e->w[0] <= 1.f || e->w[1] <= 1.f || e->w[2] <= 1.f) continue;
        int in = pgeo_pt_in_tri(cx, cy, e->fx[0], e->fy[0], e->fx[1], e->fy[1], e->fx[2], e->fy[2]);
        if (!in && e->n == 4 && e->w[3] > 1.f)
            in = pgeo_pt_in_tri(cx, cy, e->fx[1], e->fy[1], e->fx[3], e->fy[3], e->fx[2], e->fy[2]);
        if (!in) continue;
        float d0 = e->w[0], d1 = e->w[1], d2 = e->w[2];      /* view depth = distance along the ray */
        float dmin = d0 < d1 ? (d0 < d2 ? d0 : d2) : (d1 < d2 ? d1 : d2);
        if (dmin < o->best) o->best = dmin;
        o->hit = 1;
    }
}
static int aim_scan_any(uint32_t st, int fc, float cx, float cy) {
    int hit = 0;
    for (uint32_t i = fc ? pgeo_cand_next(0) : 0; i < PGEO_HASH && !hit; i = fc ? pgeo_cand_next(i + 1) : i + 1) {
        const PGeoEnt *e = &s_pgeo[i];
        if (e->key == 0 || e->player || e->n < 3) continue;
        if (e->stamp != st && e->stamp + 1u != st) continue;
        if (e->w[0] <= 1.f || e->w[1] <= 1.f || e->w[2] <= 1.f) continue;
        int in = pgeo_pt_in_tri(cx, cy, e->fx[0], e->fy[0], e->fx[1], e->fy[1], e->fx[2], e->fy[2]);
        if (!in && e->n == 4 && e->w[3] > 1.f)
            in = pgeo_pt_in_tri(cx, cy, e->fx[1], e->fy[1], e->fx[3], e->fy[3], e->fx[2], e->fy[2]);
        if (in) hit = 1;
    }
    return hit;
}
static uint32_t aim_scan_first(uint32_t st, int fc, float cx, float cy, float *cdep) {
    uint32_t cached = 0;
    for (uint32_t i = fc ? pgeo_cand_next(0) : 0; i < PGEO_HASH; i = fc ? pgeo_cand_next(i + 1) : i + 1) {
        const PGeoEnt *e = &s_pgeo[i];
        if (e->key == 0 || e->player || e->n < 3) continue;
        if (e->stamp != st && e->stamp + 1u != st) continue;
        if (e->w[0] <= 1.f || e->w[1] <= 1.f || e->w[2] <= 1.f) continue;
        int in = pgeo_pt_in_tri(cx, cy, e->fx[0], e->fy[0], e->fx[1], e->fy[1], e->fx[2], e->fy[2]);
        if (!in && e->n == 4 && e->w[3] > 1.f)
            in = pgeo_pt_in_tri(cx, cy, e->fx[1], e->fy[1], e->fx[3], e->fy[3], e->fx[2], e->fy[2]);
        if (!in) continue;
        float d0 = e->w[0], d1 = e->w[1], d2 = e->w[2];
        float dmin = d0 < d1 ? (d0 < d2 ? d0 : d2) : (d1 < d2 ? d1 : d2);
        if (dmin < *cdep) { *cdep = dmin; cached = e->ctx & 0x1FFFFFu; }
    }
    return cached;
}
static void aim_fresh_check(const char *what, int differ, int a, int b) {
    static long n = 0, bad = 0;
    n++;
    if (differ && ++bad <= 20)
        fprintf(stderr, "aimfresh: %s MISMATCH #%ld: by the lists %d, by the whole table %d (stamp %u)%c", what, bad, a, b, (unsigned)s_pgeo_stamp, 10);
    if (n == 1 || (n % 200) == 0)
        fprintf(stderr, "aimfresh: %ld checks, %ld mismatches; the stamp lists now hold %d + %d records of %u (DC_AIM_FRESH=2)%c",
                n, bad, s_pgeo_fresh_n[s_pgeo_fresh_cur], s_pgeo_fresh_n[s_pgeo_fresh_cur ^ 1], (unsigned)PGEO_HASH, 10);
}
int dc_aim_geom_ray(uint32_t actor) {
    if (!pt_poolgeom_enabled()) return 0;
    uint32_t want = actor & 0x1FFFFFu;
    uint32_t st = s_pgeo_stamp;
    const float cx = g_pt_proj_ofx, cy = g_pt_proj_ofy;
    /* how far the same ray travels before the room stops it */
    float wall = 1e9f;
    {
        extern int dc_impact_raycast(const float o[3], const float d[3], float maxd,
                                     float hit[3], float nrm[3]);
        extern void dc_nots_cam_get(float*, float*, float*);
        extern float g_dc_cam_eye[3];
        float cyaw, cpit, cdst; dc_nots_cam_get(&cyaw, &cpit, &cdst);
        float o[3] = { g_dc_cam_eye[0], g_dc_cam_eye[1], g_dc_cam_eye[2] };
        float d[3] = { sinf(cyaw)*cosf(cpit), sinf(cpit), cosf(cyaw)*cosf(cpit) };
        float hp[3], nn[3];
        if (dc_impact_raycast(o, d, 12000.f, hp, nn)) {
            float dx = hp[0]-o[0], dy = hp[1]-o[1], dz = hp[2]-o[2];
            wall = sqrtf(dx*dx + dy*dy + dz*dz);
        }
    }
    AimRay rr;
    const int fc = pgeo_fresh_cands(st);                     /* 19.10: только записи штампов st и st-1, по порядку */
    aim_scan_ray(st, fc, want, cx, cy, &rr);
    if (fc && pgeo_fresh_on() == 2) {                        /* сверка с проходом всей таблицы */
        AimRay r0; aim_scan_ray(st, 0, want, cx, cy, &r0);
        aim_fresh_check("ray", memcmp(&rr, &r0, sizeof rr) != 0, rr.hit, r0.hit);
    }
    int hit = rr.hit; float best = rr.best;
    const int nfresh = rr.nfresh, nmine = rr.nmine; const uint32_t seen1 = rr.seen1, seen2 = rr.seen2;
    for (int i = 0; i < MODPICK_MAX; i++)                    /* 06.10.2026: drawn from mods - its bones */
        if (s_modpick[i].ctx == want) {
            const float d = modpick_hit(&s_modpick[i], st, cx, cy);
            if (d > 0.f) { if (d < best) best = d; hit = 1; }
        }
    /* OCCLUSION IS OFF BY DEFAULT (2026-08-31 night, player: "урон не
     * проходит"). Rejecting a creature that sits farther than the room ray's
     * first hit is right in principle, but the room ray is not trustworthy
     * enough for it: in the player's own room it came back at 1908 units
     * while the raptor stood at 2620, so every honest hit was thrown away.
     * The trace's job is "did the ray cross the creature" - the room can veto
     * it again once the collision mesh can be relied on. DC_AIM_WALL=1. */
    { static int we = -1;
      if (we < 0) { const char *e2 = getenv("DC_AIM_WALL"); we = (e2 && *e2 == '1') ? 1 : 0; }
      if (we && hit && best > wall + 60.f) hit = 0; }        /* a wall got there first */
    /* PUBLISH THE IMPACT POINT (2026-09-04). The ray already knows where it
     * crossed the creature - `best` is the nearest crossed polygon's depth
     * along it - so the point is the eye plus the direction times that. The
     * game's own blood spawner is then moved here instead of hanging off a
     * random bone (see dc_blood_place). Same units and axes as the actor's
     * own position cells, no conversion. */
    if (hit) {
        extern void dc_nots_cam_get(float*, float*, float*);
        extern float g_dc_cam_eye[3];
        extern uint64_t s_frame_count;
        float cyaw, cpit, cdst; dc_nots_cam_get(&cyaw, &cpit, &cdst);
        float dx2 = sinf(cyaw)*cosf(cpit), dy2 = sinf(cpit), dz2 = cosf(cyaw)*cosf(cpit);
        g_aim_hit_pt[0] = g_dc_cam_eye[0] + dx2 * best;
        g_aim_hit_pt[1] = g_dc_cam_eye[1] + dy2 * best;
        g_aim_hit_pt[2] = g_dc_cam_eye[2] + dz2 * best;
        g_aim_hit_actor = want;
        g_aim_hit_vb    = s_frame_count;
    }
    { static long n = 0; static uint32_t lastn = 0;
      if (st != lastn && ++n < 120) { lastn = st;
          fprintf(stderr, "aimray: actor=%05X hit=%d depth=%.0f wall=%.0f fresh=%d mine=%d ctx=%05X,%05X cross=%.0f,%.0f%c",
                  want, hit, hit ? best : -1.f, wall, nfresh, nmine, seen1, seen2,
                  cx, cy, 10); } }
    return hit;
}
/* ===== IS ANY CREATURE UNDER THE CROSSHAIR RIGHT NOW? (2026-09-04) ========
 * The same polygon test as dc_aim_geom_ray, minus the "whose actor" filter
 * and minus the wall veto: the HUD only needs to know whether the shot would
 * land on a creature, and it needs the answer every frame, not at damage
 * time. Cached per projector stamp, so the reticle costs one pass over the
 * table per emulated frame however often the HUD asks. */
int dc_aim_geom_any(void) {
    static uint32_t lastst = 0; static int cached = 0;
    if (!pt_poolgeom_enabled()) return 0;
    uint32_t st = s_pgeo_stamp;
    if (st == lastst) return cached;
    lastst = st;
    const float cx = g_pt_proj_ofx, cy = g_pt_proj_ofy;
    const int fc = pgeo_fresh_cands(st);                     /* 19.10: только записи штампов st и st-1, по порядку */
    int hit = aim_scan_any(st, fc, cx, cy);
    if (fc && pgeo_fresh_on() == 2) { const int h0 = aim_scan_any(st, 0, cx, cy); aim_fresh_check("any", hit != h0, hit, h0); }
    for (int i = 0; i < MODPICK_MAX && !hit; i++)            /* 06.10.2026: creatures drawn from mods */
        if (modpick_hit(&s_modpick[i], st, cx, cy) > 0.f) hit = 1;
    cached = hit;
    return hit;
}

/* ===== ЧЬЁ ТЕЛО ПОД ПЕРЕКРЕСТИЕМ, БЛИЖНЕЕ ПЕРВЫМ (22.09.2026) ==============
 * Игрок: «пули должны лететь в того врага, на кого я прицелом навёлся; убрать автоприцеливание». Тот же тест полигонов,
 * что dc_aim_geom_any, но он помнит, ЧЕЙ полигон (актёр, которым проектор пометил примитив), и берёт ближний по лучу:
 * двое под перекрестием — выстрел получает передний. Возвращает адрес актёра (21 бит) или 0; depth — глубина по лучу.
 * Кэш на штамп проектора. */
uint32_t dc_aim_geom_first(float *depth) {
    static uint32_t lastst = 0, cached = 0; static float cdep = 0.f;
    if (!pt_poolgeom_enabled()) { if (depth) *depth = 0.f; return 0; }
    uint32_t st = s_pgeo_stamp;
    if (st != lastst) {
        lastst = st; cached = 0; cdep = 1e9f;
        const float cx = g_pt_proj_ofx, cy = g_pt_proj_ofy;
        const int fc = pgeo_fresh_cands(st);                 /* 19.10: только записи штампов st и st-1, по порядку */
        cached = aim_scan_first(st, fc, cx, cy, &cdep);
        if (fc && pgeo_fresh_on() == 2) {
            float d0 = 1e9f; const uint32_t c0 = aim_scan_first(st, 0, cx, cy, &d0);
            aim_fresh_check("first", c0 != cached || d0 != cdep, (int)cached, (int)c0);
        }
        for (int i = 0; i < MODPICK_MAX; i++) {               /* 06.10.2026: creatures drawn from mods */
            const float d = modpick_hit(&s_modpick[i], st, cx, cy);
            if (d > 0.f && d < cdep) { cdep = d; cached = s_modpick[i].ctx; }
        }
    }
    if (depth) *depth = cached ? cdep : 0.f;
    return cached;
}
/* ===== FOCUS AIM (2026-09-04, the Resident Evil remake reticle) ===========
 * In RE2/RE3/RE4 remake the reticle opens when the weapon comes up and draws
 * itself in while the character stands still; a shot throws it wide again,
 * and moving keeps it open. A wide reticle is a weaker shot - measured at
 * roughly +50..75 % between a wide reticle and a fully focused one, plus a
 * much higher critical chance on the focused shot.
 * Here the SAME curve drives the drawn reticle (main.cpp) and the damage
 * applied to a creature (the HP stores in the generated code go through
 * dc_focus_damage_hp below), so what the player sees is what the shot does.
 * We take the penalty direction rather than the bonus one: a settled reticle
 * deals the game's ORIGINAL damage and an open one deals less, so the option
 * can never make Dino Crisis easier than it shipped.
 *   g_opt_focus_mode  0 = off, 1 = reticle only, 2 = reticle + damage
 *   DC_FOCUS_TIME     seconds from wide open to fully settled (default 1.0)
 *   DC_FOCUS_MINDMG   damage factor of a wide-open reticle (default 0.8 since 17.09; was 0.5)
 *   DC_FOCUS_TURN     camera turn rate (rad/s) that stops the settling
 */
int   g_opt_focus_mode = 2;   /* по умолчанию: перекрестие И урон (игрок, 04.09) */
static float s_focus = 0.f;             /* 0 = wide open, 1 = settled */
static float s_focus_shot = 0.f;        /* how settled it was WHEN THE ROUND LEFT */
static float s_hold = 0.f;              /* seconds held at FULL settle */
static float s_down = 0.f;              /* seconds the weapon has read as down */
static float s_hold_shot = 0.f;         /* that hold, latched at the shot */
static int   s_focus_aiming = 0;
/* The bonus is not handed out the instant the ticks stop moving: she has to
 * KEEP it there for a beat (2026-09-04, player: "спустя долю секунды как
 * перекрестие сведено становится 1.5"). DC_FOCUS_HOLD sets the beat. */
/* NO BEAT ANY MORE (2026-09-04, player: "убери задержку в 0.3, пусть сразу
 * сходится, но время сближения увеличь на это 0.3"). The wait moved into the
 * settle itself: 1.5 s + 0.3 s = 1.8 s of drawing in, and the moment the
 * reticle closes it IS the full-power shot. DC_FOCUS_HOLD brings a beat back. */
static float focus_hold_time(void) { static float v = -1.f; if (v < 0.f) { const char *e = getenv("DC_FOCUS_HOLD"); v = e ? (float)atof(e) : 0.0f; if (v < 0.f) v = 0.f; } return v; }
static float focus_curve(float x);      /* defined with dc_focus_level below */
/* 1.5 s: the remakes' handgun takes about a second and a half of standing
 * still to draw the reticle down to its dot. */
/* 30 % FASTER (2026-09-05, player: "ускорь сведение перекрестия на 30%"):
 * 1.8 s -> 1.26 s from wide open to settled. DC_FOCUS_TIME overrides. */
/* 2 s (2026-09-12, player: "пусть сходится на 2 секунды"). */
static float focus_time(void)  { static float v = -1.f; if (v < 0.f) { const char *e = getenv("DC_FOCUS_TIME");   v = e ? (float)atof(e) : 1.3333f; if (v < 0.05f) v = 0.05f; } return v; }   /* 13.09: 2 с → в 1.5 раза быстрее (игрок) */
/* ⭐ РАСХОЖДЕНИЕ ПО СКОРОСТИ, А НЕ ПО ФАКТУ (12.09.2026, игрок: «когда камерой
 * крутишь во время прицеливания или начинаешь ходьбу, если перекрестие сошлось,
 * оно не сразу пусть расходится; по скорости рассчитай — если она небольшая и
 * отклонение камеры небольшое, это слабо влияет»).
 * Раньше любой шаг обнулял сведение, а поворот камеры не трогал его вовсе.
 * Теперь и ход, и поворот дают СКОРОСТЬ раскрытия, пропорциональную их величине,
 * и она вычитается из скорости сведения:
 *   ход      — доля отклонения стика (клавиатура = 1): полный ход раскрывает
 *              сведённый прицел за DC_FOCUS_MOVE_T с (0.45), четверть хода —
 *              вчетверо медленнее, а сведение при этом продолжает тянуть назад;
 *   поворот  — рад/с сверх мёртвой зоны DC_FOCUS_TURN_DEAD (0.12): панорама со
 *              скоростью DC_FOCUS_TURN_REF (1.5 рад/с) раскрывает за
 *              DC_FOCUS_TURN_T с (0.5), медленный довод почти не мешает;
 *   запас    — сведённый прицел сначала копит невидимый запас DC_FOCUS_RESERVE
 *              (0.25 хода, ~0.5 с сведения): лёгкий толчок стика или короткий
 *              довод камеры съедают запас, а нарисованный прицел ещё стоит
 *              сведённым — «не сразу расходится». Урон и картинка считаются от
 *              min(1, состояние), запас на них не влияет.
 * DC_FOCUS_RATE_MODE=0 — прежнее: шаг сбрасывает мгновенно, поворот не считается. */
/* (13.09) раскрытие по скорости, в ВИДИМЫХ единицах: полный ход стика раскрывает за
 * DC_FOCUS_MOVE_T (1.2 с), поворот DC_FOCUS_TURN_REF (2 рад/с) сверх мёртвой зоны
 * DC_FOCUS_TURN_DEAD (0.25 рад/с) — за DC_FOCUS_TURN_T (1 с); обе силы квадратичны
 * по скорости. Сведение гаснет, когда сила раскрытия подходит к DC_FOCUS_OPEN_REF (0.5/с).
 * Запас DC_FOCUS_RESERVE (0.25) сверх 1 тратится первым — пауза перед видимым раскрытием. */
/* 13.09 (игрок: «увеличь силу раскрытия в 2 раза»): MOVE_T 1.2 → 0.6, TURN_T 1.0 → 0.5,
 * OPEN_REF 0.5 → 1.0 (порог гашения сведения в долях стика — прежний) */
static float focus_move_t(void)   { static float v = -1.f; if (v < 0.f) { const char *e = getenv("DC_FOCUS_MOVE_T");    v = e ? (float)atof(e) : 0.6f; if (v < 0.05f) v = 0.05f; } return v; }
/* 13.09 (игрок: «уменьши скорость, при которой прицел начинает расходиться, в 2 раза»):
 * TURN_DEAD 0.25 → 0.125, TURN_REF 2 → 1 рад/с, OPEN_REF 1.0 → 0.2 (порог хода ~0.64 → ~0.33
 * стика), RESERVE 0.25 → 0.12 (видимое раскрытие на малой скорости не ждёт секунду) */
static float focus_turn_dead(void){ static float v = -1.f; if (v < 0.f) { const char *e = getenv("DC_FOCUS_TURN_DEAD"); v = e ? (float)atof(e) : 0.125f; if (v < 0.f) v = 0.f; } return v; }
static float focus_turn_ref(void) { static float v = -1.f; if (v < 0.f) { const char *e = getenv("DC_FOCUS_TURN_REF");  v = e ? (float)atof(e) : 1.0f; if (v < 0.05f) v = 0.05f; } return v; }
static float focus_turn_t(void)   { static float v = -1.f; if (v < 0.f) { const char *e = getenv("DC_FOCUS_TURN_T");    v = e ? (float)atof(e) : 0.5f; if (v < 0.05f) v = 0.05f; } return v; }
static float focus_reserve(void)  { static float v = -1.f; if (v < 0.f) { const char *e = getenv("DC_FOCUS_RESERVE");   v = e ? (float)atof(e) : 0.12f; if (v < 0.f) v = 0.f; if (v > 2.f) v = 2.f; } return v; }
static float focus_open_ref(void) { static float v = -1.f; if (v < 0.f) { const char *e = getenv("DC_FOCUS_OPEN_REF");  v = e ? (float)atof(e) : 0.2f; if (v < 0.01f) v = 0.01f; } return v; }
static float focus_pow(void)      { static float v = -1.f; if (v < 0.f) { const char *e = getenv("DC_FOCUS_POW");       v = e ? (float)atof(e) : 3.0f; if (v < 1.f) v = 1.f; if (v > 12.f) v = 12.f; } return v; }
static int   focus_rate_mode(void){ static int v = -1; if (v < 0) { const char *e = getenv("DC_FOCUS_RATE_MODE"); v = (e && *e == '0') ? 0 : 1; } return v; }
/* HALF DAMAGE WIDE OPEN (2026-09-04, player: "x0.5 надо для выстрела с
 * разведённым прицелом"). RE2 remake's own proportion is ~2/3 (open 100 vs
 * settled 150); the player wants the penalty steeper, so a shot fired with
 * the reticle fully open deals half of Dino Crisis' original damage and a
 * settled one deals all of it. */
/* 17.09.2026 вечер (игрок: «урон у пистолета сейчас от 0.5 или 0.6 минимальный, а надо 0.8»): выстрел с
 * разведённым прицелом — x0.8 вместо x0.5; дальше по той же кривой до x1.0 и x1.5 в замке. Касается пистолета
 * (и неопознанного оружия): у дробовика закон дальности, у гранатомёта своя полоса 0.8..1.1.
 * DC_FOCUS_MINDMG=0.5 — как было. */
static float focus_mindmg(void){ static float v = -1.f; if (v < 0.f) { const char *e = getenv("DC_FOCUS_MINDMG"); v = e ? (float)atof(e) : 0.80f; if (v < 0.05f) v = 0.05f; if (v > 1.f) v = 1.f; } return v; }
/* OFF by default (2026-09-04, player: "ресеть перекрестие ТОЛЬКО если игрок
 * идёт или бежит"). Turning the camera used to hold the reticle open; it no
 * longer does. DC_FOCUS_TURN=<rad/s> brings that penalty back. */
static float focus_turn(void)  { static float v = -1.f; if (v < 0.f) { const char *e = getenv("DC_FOCUS_TURN");   v = e ? (float)atof(e) : 0.0f; } return v; }

/* A round left the weapon: the reticle jumps back open. Called from the ammo
 * watch (dc_ammo_write_note), which is the one place that sees every real
 * shot, held-trigger and launcher included - a trigger PRESS is not a shot. */
/* The damage lands a few frames AFTER the round leaves, and the shot itself
 * opens the reticle - so the value the damage must use is the one latched
 * here, "the focus of the shot that was fired", exactly as the remakes give
 * the bonus to the shot you had lined up rather than to the recoiling one.
 * THE PICTURE LAGS THE SHOT ON PURPOSE (2026-09-04, player: "делай чуть
 * позже, для пистолета через 0.2 с"): the settle state is thrown away
 * immediately - so a second round out of the same burst gets no bonus - but
 * the DRAWN reticle stays closed for DC_FOCUS_SHOTDELAY seconds, so it opens
 * with the recoil rather than a hair before the gun even goes off. */
static float s_vis = 0.f, s_vis_t = 0.f;
static float focus_shot_delay(void) { static float v = -1.f; if (v < 0.f) { const char *e = getenv("DC_FOCUS_SHOTDELAY"); v = e ? (float)atof(e) : 0.15f; if (v < 0.f) v = 0.f; } return v; }
uint64_t g_real_shot_vb = 0;            /* frame a round actually left the gun */
void dc_focus_note_shot(void) { extern uint64_t s_frame_count;
                                s_focus_shot = s_focus; s_hold_shot = s_hold;
                                s_vis = s_focus; s_vis_t = focus_shot_delay();
                                s_focus = 0.f; s_hold = 0.f;
                                g_real_shot_vb = s_frame_count; }
/* Diagnostics window: N frames after a round really left the weapon. The blood
 * spawn happens a few frames after the ammo cell drops, so this is the window
 * a store census must cover. */
int dc_real_shot_window(int frames) {
    extern uint64_t s_frame_count;
    return g_real_shot_vb != 0 && s_frame_count - g_real_shot_vb < (uint64_t)frames;
}

/* One emulated frame of the reticle state machine.
 *   dt      seconds since the last call (real time)
 *   aiming  the weapon is up (action byte 6 / our aim button)
 *   moving  she is walking or running
 *   camyaw  current camera yaw, to notice a fast look */
void dc_focus_tick(float dt, int aiming, float move, float camyaw) {
    static float prevyaw = 0.f; static int haveyaw = 0;
    int moving = (move > 0.001f);
    /* DC_FOCUS_MODE overrides the saved setting once, for A/B runs */
    { static int envdone = 0;
      if (!envdone) { envdone = 1; const char *e = getenv("DC_FOCUS_MODE");
                      if (e) { int n = atoi(e); if (n >= 0 && n <= 2) g_opt_focus_mode = n; } } }
    float turn = 0.f;
    if (haveyaw && dt > 0.0001f) {
        float d = camyaw - prevyaw;
        while (d >  3.14159265f) d -= 6.28318531f;
        while (d < -3.14159265f) d += 6.28318531f;
        turn = (d < 0.f ? -d : d) / dt;
    }
    prevyaw = camyaw; haveyaw = 1;
    if (dt <= 0.f || dt > 0.5f) dt = 0.016f;      /* a hitch must not settle it */
    /* THE SHOT RESETS IT, NOT THE BUTTON (2026-09-04, player: "можно ресетить
     * перекрестие не из-за нажатия на кнопку, а при выстреле непосредственно?").
     * It already is: dc_focus_note_shot fires from the AMMO watch, i.e. when a
     * round actually left the weapon. What used to muddy that is right here -
     * the game drops its action byte out of "weapon up" for a few frames
     * DURING the shot (and during a stumble or a reload), and this tick read
     * that as "she lowered the gun" and zeroed the settle a frame before the
     * ammo watch could. So a short gap is now tolerated: the settle is frozen,
     * not lost, until the weapon has really been down for DC_FOCUS_GRACE
     * seconds. */
    if (!aiming) {
        static float grace = -1.f;
        /* Kept SHORT (2026-09-04, player: "других изменений не надо, чисто
         * небольшая задержка именно при выстреле"): this window exists only
         * to cover the handful of frames the action byte drops out of "weapon
         * up" during the shot itself - long enough for the ammo watch to
         * arrive, short enough that lowering the weapon or re-aiming still
         * resets the settle immediately, as asked earlier. */
        if (grace < 0.f) { const char *e = getenv("DC_FOCUS_GRACE");
                           grace = e ? (float)atof(e) : 0.12f; if (grace < 0.f) grace = 0.f; }
        s_down += dt;
        if (s_down >= grace) { s_focus = 0.f; s_hold = 0.f; s_focus_aiming = 0; }
        return;                                    /* frozen while the gap lasts */
    }
    s_down = 0.f;
    if (!s_focus_aiming) { s_focus = 0.f; s_focus_aiming = 1; }  /* opens on raise */
    if (focus_rate_mode()) {
        /* (13.09, игрок: «прицел не сделан» — после сведения шаг или поворот
         * разводили его сразу). Было: сила раскрытия линейна по скорости и
         * вычиталась в ЛИНЕЙНОМ времени s, а видимый размах = s³ — у s=1 кривая
         * крутая, и малое падение s раскрывало прицел наполовину за 0.1 с.
         * Теперь: сила раскрытия f квадратична по скорости (малая скорость —
         * слабо) и действует в ВИДИМОМ пространстве v = s^p (линейно на глаз);
         * сведение продолжается, пока f мала (гаснет к focus_open_ref); запас
         * сверх 1 тратится первым — пауза перед видимым раскрытием. */
        float mv = move; if (mv > 1.f) mv = 1.f; if (mv < 0.f) mv = 0.f;
        float f = (mv * mv) / focus_move_t();
        float tn = turn - focus_turn_dead();
        if (tn > 0.f) { float r = tn / focus_turn_ref(); f += (r * r) / focus_turn_t(); }
        float cs = 1.f - f / focus_open_ref(); if (cs < 0.f) cs = 0.f; if (cs > 1.f) cs = 1.f;
        s_focus += dt * cs / focus_time();
        if (s_focus > 1.f + focus_reserve()) s_focus = 1.f + focus_reserve();
        if (f > 0.f) {
            float o = f * dt;                            /* видимых единиц за тик */
            if (s_focus > 1.f) {                         /* сначала запас */
                float take = (o < s_focus - 1.f) ? o : (s_focus - 1.f);
                s_focus -= take; o -= take;
            }
            if (o > 0.f && s_focus > 0.f) {
                float p = focus_pow();
                float v = powf(s_focus, p) - o;
                s_focus = (v > 0.f) ? powf(v, 1.f / p) : 0.f;
            }
        }
        if (s_focus < 0.f) s_focus = 0.f;
    } else {
        if (moving) {                              /* "if you move or fire, the
                                                    * reticle will be reset" */
            s_focus = 0.f;
        } else if (turn > focus_turn()) {          /* a fast look holds it open */
            s_focus -= dt * 2.0f;
        } else {
            s_focus += dt / focus_time();
        }
        if (s_focus < 0.f) s_focus = 0.f;
        if (s_focus > 1.f) s_focus = 1.f;
    }
    /* time spent fully settled - the beat before the bonus lands */
    if (focus_curve(s_focus) >= 0.985f) s_hold += dt;
    else                                s_hold  = 0.f;
    if (s_vis_t > 0.f) s_vis_t -= dt;             /* the post-shot picture hold */
}
/* What the HUD должен показывать: the live settle, or - for a moment after a
 * shot - the settle the shot was fired with. */
static float focus_shown(void) { return (s_vis_t > 0.f) ? s_vis : s_focus; }
/* HUD: has the settle turned into the full bonus yet? */
int dc_focus_locked(void) {
    float f = focus_shown();
    float h = (s_vis_t > 0.f) ? s_hold_shot : s_hold;
    return g_opt_focus_mode && focus_curve(f) >= 0.985f && h >= focus_hold_time();
}
/* EASE-IN (2026-09-04, player, correcting the first attempt: "инвертируй.
 * начинает медленно сходиться, быстро [заканчивает]"). The raw state machine
 * above counts linear TIME; the reticle must not move linearly - it barely
 * creeps at first and then snaps home over the last stretch, so the settle
 * reads as a moment rather than a slow drift. Cubic ease-in: x^3, so the
 * first half of the time covers only ~12 % of the travel and the final
 * quarter covers ~58 %.
 * The SAME curve feeds the damage, so what the player sees is what the shot
 * does - no second, invisible number. */
static float focus_curve(float x) {
    /* STRONGER (2026-09-04, player: "сделай из-аут перекрестия более
     * сильным"): the exponent went from 3 to 5, so the reticle hangs open
     * even longer and then slams shut. At half the time it has covered 3 %
     * of the travel (was 12 %), and the last quarter of the time covers
     * 76 % of it. DC_FOCUS_POW tunes the exponent. */
    /* SOFTER AGAIN (2026-09-05, player: "сделай кривую анимации слабее,
     * менее крутой"): the exponent goes back from 5 to 3 - at half the time
     * the ticks have covered 12 % of the travel (was 3 %), the last quarter
     * covers 58 % (was 76 %), so the settle still ends with a snap but no
     * longer hangs open for most of the wait. The damage ramp 0.5 -> 1.0
     * follows the same curve, as before. DC_FOCUS_POW tunes it. */
    float p = focus_pow();
    if (x <= 0.f) return 0.f;
    if (x >= 1.f) return 1.f;
    return powf(x, p);
}
float dc_focus_level(void) { return g_opt_focus_mode ? focus_curve(focus_shown()) : 1.f; }

/* Damage factor of the current reticle: min .. 1.0, linear in the drawn
 * spread so the picture and the number agree. */
/* THE SCALE THE PLAYER ASKED FOR (2026-09-04, third pass):
 *   reticle wide open      x0.5   (DC_FOCUS_MINDMG)
 *   settling               0.5 -> 1.0, along the same ease-in curve the ticks
 *                          travel on, so the picture IS the number
 *   fully settled          x1.5   (DC_FOCUS_MAXDMG) - a step, not a ramp: the
 *                          reward is for holding the aim all the way in, the
 *                          way the remakes hand out their focus bonus.
 * "Fully settled" uses the SAME threshold the HUD uses to call the reticle
 * closed, so the bonus lands exactly when the ticks stop moving. */
float dc_focus_full_mult(void) {
    static float v = -1.f;
    if (v < 0.f) { const char *e = getenv("DC_FOCUS_MAXDMG"); v = e ? (float)atof(e) : 1.5f;
                   if (v < 0.1f) v = 0.1f; if (v > 8.f) v = 8.f; }
    return v;
}
float dc_focus_damage_scale(void) {
    if (g_opt_focus_mode < 2) return 1.f;
    float f = focus_curve(s_focus_shot);
    float m = focus_mindmg();
    /* 0.5 -> 1.0 all the way in, and only after she has HELD it settled for a
     * beat does it become 1.5 - the bonus is for keeping the aim, not for
     * brushing past the moment the ticks close. */
    if (f >= 0.985f)
        return (s_hold_shot >= focus_hold_time()) ? dc_focus_full_mult() : 1.0f;
    return m + (1.f - m) * f;
}

/* ===== PER-WEAPON DAMAGE LAW (2026-09-04, player) =========================
 * The three guns do not answer to the same thing:
 *   HANDGUN  (0x20, and anything unmapped) - the focus law above:
 *            0.5 wide open, up to 1.0 as it settles, 1.5 fully settled.
 *   SHOTGUN  (0x10) - RANGE, not the reticle. Its reticle does not settle at
 *            all (see the HUD), so a shot is judged by how close she is: full
 *            force in her face, half of it across the room. Buckshot spreading
 *            with distance is the real-world reason and the remakes' rule too.
 *   GRENADE  (0x30) - the reticle matters, but barely: 1.0 .. 1.2 since
 *            27.10.2026 (was 0.8 .. 1.1, then a flat 1.0 from 15.10). The round
 *            detonates for area damage, so aiming it well is worth something
 *            and worth little; only the creature it struck gets the aim.
 * dist is in DC world units, measured from Regina to the creature (0 = unknown,
 * which falls back to the mid-range value). Tunable:
 *   DC_SG_NEAR / DC_SG_FAR      the range window (default 700 .. 3000)
 *   DC_SG_MAX  / DC_SG_MIN      its multipliers   (default 1.5 .. 0.5)
 *   DC_GL_MIN  / DC_GL_MAX      the launcher's band (default 1.0 .. 1.2 since 27.10.2026, 1.0 .. 1.0 from 15.10, was 0.8 .. 1.1)
 */
static float envf(const char *name, float def) {
    const char *e = getenv(name);
    return e ? (float)atof(e) : def;
}
float dc_damage_mult(int weapon, float dist) {
    if (g_opt_focus_mode < 2) return 1.f;
    weapon &= 0xF0;                                     /* 20.09: младшая половина байта — модификации оружия */
    if (weapon == 0x10) {                               /* SHOTGUN: range */
        /* THE WINDOW IS MUCH WIDER THAN IT WAS (2026-09-04, player: "урон
         * увеличивается буквально в шаге от динозавра, а надо чтобы с 15
         * шагов; а в шаге от дино весь урон уже шёл"). 700/3000 put the whole
         * ramp inside one room's length, so the falloff only ever showed up
         * point blank. A step reads as roughly 400-500 world units here, so
         * the ramp now starts around fifteen steps out and is already at full
         * force two steps away. */
        static float nr = -1.f, fr, mx, mn;
        if (nr < 0.f) { nr = envf("DC_SG_NEAR", 1000.f); fr = envf("DC_SG_FAR", 6500.f);
                        mx = envf("DC_SG_MAX", 1.5f);   mn = envf("DC_SG_MIN", 0.5f);
                        if (fr <= nr) fr = nr + 1.f; }
        if (dist <= 0.f) return (mx + mn) * 0.5f;       /* unknown range: mid */
        if (dist <= nr) return mx;
        if (dist >= fr) return mn;
        float t = (dist - nr) / (fr - nr);
        return mx + (mn - mx) * t;
    }
    if (weapon == 0x30) {                               /* GRENADE GUN */
        /* ⭐ 15.10.2026 - УРОН ГРАНАТЫ ИГРЫ КАК ЕСТЬ (игрок: «раньше от гранатомёта от первого же выстрела на лёгком уровне
         * раптор умирал, а сейчас от трёх»; «тот, в кого попадает граната, получает 100% урона этой гранаты»). Граната игры
         * даёт раптору 1000 при его 850 HP на лёгком, а полоса 0.8..1.1 по прицелу оставляла ему 50 HP (журнал игрока 07.10:
         * «slot 3 hp 850 -> 50 (x0.80)»). Теперь множитель 1.0; спад у соседей по взрыву - в dc_grenade_tick.
         * DC_GL_MIN=0.8;DC_GL_MAX=1.1 - прежняя полоса. */
        /* 27.10.2026 (игрок: «он должен идти от единички, а если перекрестие сходится, то 1-1.2»): с разведённым прицелом
         * x1.0 - урон гранаты игры как есть, по мере сведения до x1.15 и x1.2 в замке (тот же щелчок кольца, что у
         * пистолета). Только тому, в кого попала граната: соседям по взрыву - один спад по расстоянию (memory.c).
         * DC_GL_MAX=1.0 - как с 15.10. */
        static float lo = -1.f, hi;
        if (lo < 0.f) { lo = envf("DC_GL_MIN", 1.0f); hi = envf("DC_GL_MAX", 1.2f); }
        if (hi - lo < 0.001f) return lo;
        float f = focus_curve(s_focus_shot);
        if (f >= 0.985f)
            return (s_hold_shot >= focus_hold_time()) ? hi : (hi - 0.05f);
        return lo + (hi - 0.05f - lo) * f;              /* 1.0 .. 1.15, then 1.2 */
    }
    return dc_focus_damage_scale();                     /* HANDGUN and the rest */
}

/* ===== DAMAGE READOUT (2026-09-04, player: "можешь выводить в углу сколько
 * урона я наношу... как дебаг чисто"). A small ring of the last hits, filled
 * from the HP-write hook in memory.c and drawn by the HUD as plain text in a
 * corner. Debug instrumentation: off unless the option (or DC_DMG_HUD=1) is
 * on, and it never influences the game. */
typedef struct { int slot, dmg, hp, maxhp; float scale; uint64_t vb; } DcDmgEvt;
#define DC_DMG_RING 6
static DcDmgEvt s_dmg[DC_DMG_RING];
static int      s_dmg_head = 0, s_dmg_used = 0;
static int      s_dmg_max[10];              /* the biggest HP each slot ever showed */
long            g_dmg_total = 0;            /* damage dealt this session */

void dc_dmg_note(int slot, int oldhp, int newhp, float scale) {
    extern uint64_t s_frame_count;
    if (slot < 0 || slot >= 10) return;
    if (oldhp > s_dmg_max[slot]) s_dmg_max[slot] = oldhp;
    DcDmgEvt *e = &s_dmg[s_dmg_head];
    s_dmg_head = (s_dmg_head + 1) % DC_DMG_RING;
    if (s_dmg_used < DC_DMG_RING) s_dmg_used++;
    e->slot = slot; e->dmg = oldhp - newhp; e->hp = newhp;
    e->maxhp = s_dmg_max[slot]; e->scale = scale; e->vb = s_frame_count;
    g_dmg_total += e->dmg;
    /* witness: tells "the panel is not drawing" apart from "no hits arrived" */
    { static long n = 0;
      if (++n < 5000)
          fprintf(stderr, "dmgnote: slot %d -%d hp %d/%d x%.2f f=%llu\n",
                  slot, e->dmg, e->hp, e->maxhp, (double)scale, (unsigned long long)s_frame_count); }
}
/* Newest first. Returns 0 when i is past the end. age = frames since the hit. */
int dc_dmg_entry(int i, int *slot, int *dmg, int *hp, int *maxhp, float *scale, int *age) {
    extern uint64_t s_frame_count;
    if (i < 0 || i >= s_dmg_used) return 0;
    int idx = (s_dmg_head - 1 - i + 2 * DC_DMG_RING) % DC_DMG_RING;
    const DcDmgEvt *e = &s_dmg[idx];
    if (slot)  *slot  = e->slot;
    if (dmg)   *dmg   = e->dmg;
    if (hp)    *hp    = e->hp;
    if (maxhp) *maxhp = e->maxhp;
    if (scale) *scale = e->scale;
    if (age)   *age   = (int)(s_frame_count - e->vb);
    return 1;
}
long g_pvx_put = 0;

/* Set by the projector hook: the next few RTPS calls belong to body vertices,
 * so gte.cpp publishes their EXACT packed word together with the float
 * position. Using the GTE's own packed value removes any rounding mismatch. */
int g_pvx_window = 0;
/* Address range the projector writes body vertices into, learned live. */
static uint32_t s_pool_lo = 0xFFFFFFFFu, s_pool_hi = 0;
void pt_poolgeom_note_pool(uint32_t addr) {
    uint32_t p = addr & 0x1FFFFFu;
    if (p < s_pool_lo) s_pool_lo = p;
    if (p > s_pool_hi) s_pool_hi = p;
}
/* Called from the swc2 hook: the projector just stored a BODY vertex into the
 * pool. `packed` is the exact word the assembler will feed to the GTE before
 * NCLIP, and (fx,fy) is its true sub-pixel position — pair them, so the NCLIP
 * hook can recognise a body triangle and give the game its real area instead
 * of the rounded-to-zero one. */
int pt_poolgeom_is_pool(uint32_t addr) {
    uint32_t p = addr & 0x1FFFFFu;
    return s_pool_hi >= s_pool_lo && p >= s_pool_lo && p <= s_pool_hi;
}
/* 17.09.2026 вечер (разбор «что ещё можно»): ДЕФЕКТ ХЕША. Слот брался младшими 18 битами (packed * 2654435761), а младшие
 * биты произведения зависят только от младших бит множимого: 18 бит packed = x и y&3. Вершины тела в одном столбце
 * экрана (и с одинаковым y&3) делили слот — одна запись на слот, поздняя затирала раннюю, и площадь / вершины тела
 * для гейта NCLIP и растра промахивались. Фибоначчи-хеш берёт СТАРШИЕ биты: >> (32 − 18). DC_PVX_HASH_OLD=1 — как было. */
