        sig = (sig ^ (uint32_t)(int)sec[ns].pos[0]) * 16777619u; sig = (sig ^ (uint32_t)(int)sec[ns].pos[1]) * 16777619u; sig = (sig ^ (uint32_t)(int)sec[ns].pos[2]) * 16777619u;
