            float ext[3]; int okx = 1;
            for (int c = 0; c < 3; c++) { ext[c] = A->hi[c] - A->lo[c]; if (ext[c] < 800.f || ext[c] > 20000.f) okx = 0; }
            if (!okx) continue;
