/* предмет: центр и радиус модели (треугольники 40 б, четырёхугольники 52 б; вершина - s16 x,y,z + 2) в вид камеры */
static int rl_glint_setup(const uint8_t *ram, uint32_t tri, int ntri, uint32_t quad, int nquad,
                          const float *R, const float *TR, const float *D, const float *T) {
    float lo[3] = { 1e9f, 1e9f, 1e9f }, hi[3] = { -1e9f, -1e9f, -1e9f };
    int nvx = 0;
    for (int pass = 0; pass < 2; pass++) {
        const uint32_t base = pass ? quad : tri; const int n = pass ? nquad : ntri; const int nv = pass ? 4 : 3;
        const uint32_t sz = pass ? 52u : 40u;
        if (n <= 0 || base < 0x100000u || base + (uint32_t)n * sz > 0x200000u) continue;
        for (int i = 0; i < n; i++)
            for (int k = 0; k < nv; k++) {
                const uint32_t vo = base + (uint32_t)i * sz + (uint32_t)k * 8u;
                const float m[3] = { (float)rrm_s16(ram, vo), (float)rrm_s16(ram, vo + 2u), (float)rrm_s16(ram, vo + 4u) };
                for (int c = 0; c < 3; c++) { if (m[c] < lo[c]) lo[c] = m[c]; if (m[c] > hi[c]) hi[c] = m[c]; }
                nvx++;
            }
    }
    if (nvx < 3) return 0;
    const float c[3] = { 0.5f * (lo[0] + hi[0]), 0.5f * (lo[1] + hi[1]), 0.5f * (lo[2] + hi[2]) };
    const float dx = hi[0] - lo[0], dy = hi[1] - lo[1], dz = hi[2] - lo[2];
    const float r = 0.5f * sqrtf(dx * dx + dy * dy + dz * dz);
    if (r < 1.f) return 0;
    const float w0 = R[0] * c[0] + R[1] * c[1] + R[2] * c[2] + TR[0];
    const float w1 = R[3] * c[0] + R[4] * c[1] + R[5] * c[2] + TR[1];
    const float w2 = R[6] * c[0] + R[7] * c[1] + R[8] * c[2] + TR[2];
    s_rl_glint_cx = D[0] * w0 + D[1] * w1 + D[2] * w2 + T[0];
    s_rl_glint_cy = D[3] * w0 + D[4] * w1 + D[5] * w2 + T[1];
    s_rl_glint_k = 1.f / (2.828427f * r);
    return 1;
}
static inline float rl_glint_at(float x, float y) {
    float g = ((x - s_rl_glint_cx) + (y - s_rl_glint_cy)) * s_rl_glint_k + 0.5f;
    if (g < 0.f) g = 0.f; if (g > 1.f) g = 1.f;
    return 16.f + g;
}
