/* 14.09 вечер: отложенные решётки — скрыть накрытые рабицей, остальные нарисовать (см. mt_red_covered) */
static void rl_emit_poly(const uint8_t *ram, uint32_t rec, int nv, const float *R, const float *TR,
                         const float *D, const float *T, float h, float ofx, float ofy, float wsx,
                         int world_space, int is_object);
static void mt_flush(const uint8_t *ram) {
    s_mt_walking = 0;
    int hidden = 0, kept = 0, held = 0;
    if (s_mt_sk_on < 0) { const char *e = getenv("DC_MESH_TWIN_STICKY"); s_mt_sk_on = (e && *e == '0') ? 0 : 1; }
    if (s_room_by_lba != s_mt_sk_room) { s_mt_sk_room = s_room_by_lba; s_mt_sk_n = 0; }   /* 28.09: новая комната — память листов с нуля */
    if (s_mt_dn > 0) {
        float dim0 = s_rl_dim, pull0 = s_cur_plate_pull_units; int np0 = s_rl_piece_npoly; const char *src0 = s_rl_emit_src;
        int otm0 = s_rl_ot_mode, ots0 = s_rl_ot_slot, oto0 = s_rl_ot_order; const int lk0 = s_rl_live_k;
        const uint32_t pt0 = s_rl_ptag;
        s_mt_flushing = 1;
        for (int i = 0; i < s_mt_dn; i++) {
            const MtDef *d = &s_mt_d[i];
            const uint8_t *dm = d->mem ? d->mem : ram;
            float vv[4][3];
            for (int k = 0; k < d->nv; k++) {
                uint32_t vo = d->rec + (uint32_t)k * 8u;
                float mx = (float)rrm_s16(dm, vo), my = (float)rrm_s16(dm, vo + 2), mz = (float)rrm_s16(dm, vo + 4);
                vv[k][0] = d->R[0] * mx + d->R[1] * my + d->R[2] * mz + d->TR[0];
                vv[k][1] = d->R[3] * mx + d->R[4] * my + d->R[5] * mz + d->TR[1];
                vv[k][2] = d->R[6] * mx + d->R[7] * my + d->R[8] * mz + d->TR[2];
            }
            /* 28.09: лист в кадре один? (у объекта с несколькими копиями запись общая — такой не запоминаем) */
            const uint32_t rkey = d->rec & 0x1FFFFFu;
            int uniq = s_mt_sk_on > 0 && d->mem == ram;
            for (int j = 0; uniq && j < s_mt_dn; j++) if (j != i && (s_mt_d[j].rec & 0x1FFFFFu) == rkey) uniq = 0;
            uint32_t by = 0;
            if (mt_red_covered(vv, d->nv, &by)) { hidden++; if (uniq) mt_sticky_note(rkey, by); continue; }
            if (uniq) { const int si = mt_sticky_find(rkey);
                        if (si >= 0 && mt_green_in_frame(s_mt_sk_grn[si])) { hidden++; held++; continue; } }
            s_rl_dim = d->dim; s_rl_piece_npoly = d->npoly; s_rl_emit_src = d->src;
            s_rl_ot_mode = d->ot_mode; s_rl_ot_slot = d->ot_slot; s_rl_ot_order = d->ot_order; s_rl_live_k = d->live_k;
            s_rl_ptag = d->ptag;
            rl_emit_poly(dm, d->rec, d->nv, d->R, d->TR, d->D, d->T, d->h, d->ofx, d->ofy, d->wsx, d->world_space, d->is_object);
            kept++;
        }
        s_mt_flushing = 0;
        s_rl_dim = dim0; s_cur_plate_pull_units = pull0; s_rl_piece_npoly = np0; s_rl_emit_src = src0;
        s_rl_ot_mode = otm0; s_rl_ot_slot = ots0; s_rl_ot_order = oto0; s_rl_live_k = lk0;
        s_rl_ptag = pt0;
    }
    { static int lh = -1, lk = -1, lhd = -1, n = 0;
      if ((hidden != lh || kept != lk || held != lhd) && n < 60 && s_rl_target == 1) { lh = hidden; lk = kept; lhd = held; n++;
          fprintf(stderr, "mesh twin: %d grates hidden (covered by chain-link; %d of them - their chain-link moved away, the sheet is kept hidden), %d drawn, chain-link in the frame %d%c",
                  hidden, held, kept, s_mt_gn, 10); } }
    s_mt_dn = 0;
}
