static void rl_dbg_xf(const float *m, const float *R, const float *TR, const float *D, const float *T, float *o) {
    float vx = R[0]*m[0] + R[1]*m[1] + R[2]*m[2] + TR[0], vy = R[3]*m[0] + R[4]*m[1] + R[5]*m[2] + TR[1], vz = R[6]*m[0] + R[7]*m[1] + R[8]*m[2] + TR[2];
    o[0] = D[0]*vx + D[1]*vy + D[2]*vz + T[0]; o[1] = D[3]*vx + D[4]*vy + D[5]*vz + T[1]; o[2] = D[6]*vx + D[7]*vy + D[8]*vz + T[2];
}
static double rlp_ms(void) {
    static double inv = 0.0; LARGE_INTEGER c;
    if (inv == 0.0) { LARGE_INTEGER f; QueryPerformanceFrequency(&f); inv = 1000.0 / (double)f.QuadPart; }
    QueryPerformanceCounter(&c); return (double)c.QuadPart * inv;
}
