/* ⭐ 04.10 (4) — ЛЕСТНИЦЫ БЕЗ ИСТОРИИ МАТРИЦ (игрок, слот 20: «вся комната теперь трясётся и в конце мусорная геометрия на пару
 * кадров возникает. Откати этот фикс, но сделай, чтобы не обрезалась комната при переходах по лестнице»). Замер (skipq/s20_rec.py
 * + shake.py, показанные кадры подряд): в сцене ходьбы по лестнице камера игры ЕДЕТ каждую сборку (ведомая), а обход рисует куски
 * таблицы матрицей прошлой сборки (история слота: hist / ownrel / fillm) — ближняя стена скачет на ±5..10 px (¼ размера), 37
 * разворотов сдвига на 76 пар, в конце сцены 2 кадра чужого вида. С DC_ROOM_MTX_PREV=0 — 0 разворотов и чистый конец. Без обхода
 * (рисует игра) тоже ровно, но пропадают куски, которые есть только у нашей достройки (машина в центре комнаты 119 на спуске).
 * Теперь в сцене лестницы (dc_scene_stairs_room) обход берёт текущую матрицу записи. DC_STAIRS_NOHIST=0 — как было 04.10 (3). */
static int s_rl_stairs_nohist = 0;
static int stairs_nohist_env(void) { static int v = -1; if (v < 0) { const char *e = getenv("DC_STAIRS_NOHIST"); v = (e && *e == '0') ? 0 : 1; } return v; }
/* ⭐ 15.10.2026 (5) - ВЕЩЬ КОМНАТЫ, ПОВЁРНУТАЯ ВОКРУГ СВОЕЙ ОСИ (игрок: «в комнате с третьей энергией за загадкой energy нужно
 * стул повертуть на 90 по часовой относительно него»). Только отрисовка: матрица куска умножается справа на поворот вокруг его
 * вертикали - M·Ry, в его собственных координатах (ось - начало модели; у стула ST300 это стойка). Кусок узнаётся по комнате,
 * месту записи таблицы (±2 ед.) и числу граней группы: второй такой же стул ST300 (та же группа, другое место) не задет.
 * Пути: обход таблицы (матрица записи, вся история слота строится от неё) и достройка поставленных кусков (bp_emit).
 * Список - DC_OBJ_TURN=<комната>:<x>,<y>,<z>:<граней группы, 0 - любое>:<угол, 4096 = 360°, плюс - по часовой, если смотреть
 * сверху>[/...]; умолчание - стул ST300 у пульта; DC_OBJ_TURN=0 - как было. */
#define RL_OT_MAX 8
static struct { char room[8]; int x, y, z, np, ang, said; float Ry[9]; } s_ot[RL_OT_MAX];
static int s_ot_n = -1, s_ot_room = -2, s_ot_here = 0;
static void rl_obj_turn_init(void) {
    s_ot_n = 0;
    const char *e = getenv("DC_OBJ_TURN");
    if (!e) e = "ST300:2700,0,4250:43:1024";
    if (e[0] == '0' && e[1] == 0) { fprintf(stderr, "obj turn: off (DC_OBJ_TURN=0)%c", 10); return; }
    while (*e && s_ot_n < RL_OT_MAX) {
        char room[8] = { 0 }; int x = 0, y = 0, z = 0, np = 0, a = 0;
        if (sscanf(e, "%7[^:]:%d,%d,%d:%d:%d", room, &x, &y, &z, &np, &a) == 6) {
            const float t = (float)a * (6.28318530718f / 4096.f), c = cosf(t), s = sinf(t);
            const float Ry[9] = { c, 0.f, s,  0.f, 1.f, 0.f,  -s, 0.f, c };
            memcpy(s_ot[s_ot_n].room, room, sizeof room);
            s_ot[s_ot_n].x = x; s_ot[s_ot_n].y = y; s_ot[s_ot_n].z = z; s_ot[s_ot_n].np = np; s_ot[s_ot_n].ang = a;
            s_ot[s_ot_n].said = 0;
            memcpy(s_ot[s_ot_n].Ry, Ry, sizeof Ry);
            fprintf(stderr, "obj turn: %s piece at (%d,%d,%d), %d polys - turned by %d around its own axis in drawing "
                            "(4096 = 360, + clockwise from above; DC_OBJ_TURN=0 off)%c", room, x, y, z, np, a, 10);
            s_ot_n++;
        }
        while (*e && *e != '/') e++;
        if (*e == '/') e++;
    }
}
static int rl_obj_turn(const uint8_t *ram, uint32_t gp, int px, int py, int pz, float *M, const char *path) {
    if (s_ot_n < 0) rl_obj_turn_init();
    if (s_ot_n == 0) return 0;
    if (s_ot_room != s_room_by_lba) {                  /* the list is per room: names checked once per room */
        s_ot_room = s_room_by_lba; s_ot_here = 0;
        const char *nm = dc_room_name(s_room_by_lba);
        for (int i = 0; i < s_ot_n; i++) if (strcmp(nm, s_ot[i].room) == 0) s_ot_here |= 1 << i;
    }
    if (!s_ot_here) return 0;
    gp &= 0x1FFFFFu;
    if (gp < 0x100000u || gp + 12u >= 0x200000u) return 0;
    const int np = rrm_u16(ram, gp + 8) + rrm_u16(ram, gp + 10);
    for (int i = 0; i < s_ot_n; i++) {
        if (!((s_ot_here >> i) & 1)) continue;
        if (abs(px - s_ot[i].x) > 2 || abs(py - s_ot[i].y) > 2 || abs(pz - s_ot[i].z) > 2) continue;
        if (s_ot[i].np > 0 && np != s_ot[i].np) continue;
        float C[9];
        for (int r = 0; r < 3; r++) for (int c = 0; c < 3; c++)
            C[r * 3 + c] = M[r * 3] * s_ot[i].Ry[c] + M[r * 3 + 1] * s_ot[i].Ry[3 + c] + M[r * 3 + 2] * s_ot[i].Ry[6 + c];
        memcpy(M, C, sizeof C);
        if (s_ot[i].said < 4) { s_ot[i].said++;
            fprintf(stderr, "obj turn: %s grp %06X at (%d,%d,%d) turned by %d (%s)%c", s_ot[i].room, gp, px, py, pz, s_ot[i].ang, path, 10); }
        return 1;
    }
    return 0;
}
/* ⭐ 21.10.2026 - ВЕЩЬ КОМНАТЫ, ПРИПОДНЯТАЯ НАД СОСЕДЯМИ (игрок: «в комнате босса за загадкой D.D.K, где нужно ввести слово HEAD,
 * на столе листы бумаги зифайтятся между собой, разнеси их немного»). Три верхних листа стола ST202 - записи таблицы 21-23 с одной
 * группой 10563C (один квад) на одной высоте (место y -730, модель y -60): ключ полигона у копий один, поэтому смещение G
 * (dc_zfsel_user.cfg, 94264A9C) двигает все три разом, и порядок консоли (zc_*) копии одной записи между собой тоже не делит.
 * Средний лист (место -1250,-730,280) лежит на обоих соседях - так его рисует и консоль с камеры игры. Только отрисовка: кусок
 * поднимается вдоль своей вертикали на N единиц, как пол rf_lift. Кусок узнаётся, как в DC_OBJ_TURN: комната, место записи
 * (±2 ед.) и число граней группы. Пути те же: обход таблицы и достройка поставленных кусков (bp_emit).
 * Список - DC_OBJ_LIFT=<комната>:<x>,<y>,<z>:<граней группы, 0 - любое>:<подъём в ед., плюс - вверх>[/...]; умолчание - средний
 * лист ST202 на 2 ед.; DC_OBJ_LIFT=0 - как было. */
#define RL_OL_MAX 8
static struct { char room[8]; int x, y, z, np, lift, said; } s_ol[RL_OL_MAX];
static int s_ol_n = -1, s_ol_room = -2, s_ol_here = 0;
static void rl_obj_lift_init(void) {
    s_ol_n = 0;
    const char *e = getenv("DC_OBJ_LIFT");
    if (!e) e = "ST202:-1250,-730,280:1:2";
    if (e[0] == '0' && e[1] == 0) { fprintf(stderr, "obj lift: off (DC_OBJ_LIFT=0)%c", 10); return; }
    while (*e && s_ol_n < RL_OL_MAX) {
        char room[8] = { 0 }; int x = 0, y = 0, z = 0, np = 0, l = 0;
        if (sscanf(e, "%7[^:]:%d,%d,%d:%d:%d", room, &x, &y, &z, &np, &l) == 6 && l != 0) {
            memcpy(s_ol[s_ol_n].room, room, sizeof room);
            s_ol[s_ol_n].x = x; s_ol[s_ol_n].y = y; s_ol[s_ol_n].z = z; s_ol[s_ol_n].np = np; s_ol[s_ol_n].lift = l;
            s_ol[s_ol_n].said = 0;
            fprintf(stderr, "obj lift: %s piece at (%d,%d,%d), %d polys - raised by %d units along its own vertical in drawing "
                            "(DC_OBJ_LIFT=0 off)%c", room, x, y, z, np, l, 10);
            s_ol_n++;
        }
        while (*e && *e != '/') e++;
        if (*e == '/') e++;
    }
}
/* подъём куска в единицах, 0 - не из списка; вверх в игре - минус Y модели */
static int rl_obj_lift(const uint8_t *ram, uint32_t gp, int px, int py, int pz, const char *path) {
    if (s_ol_n < 0) rl_obj_lift_init();
    if (s_ol_n == 0) return 0;
    if (s_ol_room != s_room_by_lba) {
        s_ol_room = s_room_by_lba; s_ol_here = 0;
        const char *nm = dc_room_name(s_room_by_lba);
        for (int i = 0; i < s_ol_n; i++) if (strcmp(nm, s_ol[i].room) == 0) s_ol_here |= 1 << i;
    }
    if (!s_ol_here) return 0;
    gp &= 0x1FFFFFu;
    if (gp < 0x100000u || gp + 12u >= 0x200000u) return 0;
    const int np = rrm_u16(ram, gp + 8) + rrm_u16(ram, gp + 10);
    for (int i = 0; i < s_ol_n; i++) {
        if (!((s_ol_here >> i) & 1)) continue;
        if (abs(px - s_ol[i].x) > 2 || abs(py - s_ol[i].y) > 2 || abs(pz - s_ol[i].z) > 2) continue;
        if (s_ol[i].np > 0 && np != s_ol[i].np) continue;
        if (s_ol[i].said < 4) { s_ol[i].said++;
            fprintf(stderr, "obj lift: %s grp %06X at (%d,%d,%d) raised by %d (%s)%c", s_ol[i].room, gp, px, py, pz, s_ol[i].lift, path, 10); }
        return s_ol[i].lift;
    }
    return 0;
}
static void rl_emit_walk_body(void);
static void rl_emit_walk(void) {                         /* 06.10.2026: рамка обхода для ответов «раз на обход» (rl_sor) */
    s_rl_walkseq++; s_rl_in_walk = 1;
    s_rl_ptag = 0;
    rl_emit_walk_body();
    s_rl_ptag = 0;
    s_rl_in_walk = 0;
}
