        float dir[3] = { tgt[0] - pos[0], tgt[1] - pos[1], tgt[2] - pos[2] };
        float L = sqrtf(dir[0]*dir[0] + dir[1]*dir[1] + dir[2]*dir[2]); if (L < 1.f) L = 1.f;
