#pragma pop_macro("fclose")
#undef _stat64
#pragma pop_macro("_stat64")
#undef _findfirst
#pragma pop_macro("_findfirst")
#undef _findnext
#pragma pop_macro("_findnext")
#undef _findclose
#pragma pop_macro("_findclose")
#endif

static void shroom_save(void) {
#ifdef DCME_RELEASE
    return;   /* ME V3: no dc_shadows_user.cfg written - the F8 window is not in a release */
#endif
    FILE *f = fopen("dc_shadows_user.cfg", "w");
    if (!f) return;
    fprintf(f, "# shadows: per-room edits (the F8 panel). Line: <room> <parameter> <value>\n");
    for (int i = 0; i < s_shroom_n; i++)
        for (int k = 0; k < SHP_N; k++)
            if (s_shroom[i].has[k])
                fprintf(f, "%d %s %.4f\n", s_shroom[i].room, s_shp[k].key, s_shroom[i].v[k]);
    fclose(f);
}

/* ⭐ 25.09 ночь — ОБЩИЙ ВЫКЛЮЧАТЕЛЬ ТЕНЕЙ (меню GRAPHICS -> Shadows, main.cpp; F8): 0 — ни теней от ламп, ни луны, диски
 * игры на месте (как в оригинале), поверх любых правок F8 и комнат */
int g_dc_gfx_shadows = 1;
/* действующее значение: комната -> общее */
float dc_shadow_par(int i) {
    if (i < 0 || i >= SHP_N) return 0.f;
    if (i == SHP_ON && !g_dc_gfx_shadows) return 0.f;
    shp_base_init(); shroom_load();
    const ShRoomPar *r = shroom_find(dc_room_effective(), 0);
    if (r && r->has[i]) return r->v[i];
    return s_shp_base[i];
}
int   dc_shadow_on(void) { return dc_shadow_par(SHP_ON) > 0.5f; }
int   dc_shadow_par_count(void) { return SHP_N; }
const char *dc_shadow_par_name(int i) { return (i >= 0 && i < SHP_N) ? s_shp[i].key : ""; }
const char *dc_shadow_par_hint(int i) { return (i >= 0 && i < SHP_N) ? s_shp[i].hint : ""; }
void  dc_shadow_par_range(int i, float *lo, float *hi) {
    if (i < 0 || i >= SHP_N) return;
    if (lo) *lo = s_shp[i].lo;
    if (hi) *hi = s_shp[i].hi;
}
float dc_shadow_par_base(int i) { shp_base_init(); return (i >= 0 && i < SHP_N) ? s_shp_base[i] : 0.f; }
void  dc_shadow_par_base_set(int i, float v) {
    if (i < 0 || i >= SHP_N) return;
    shp_base_init();
    if (v < s_shp[i].lo) v = s_shp[i].lo;
    if (v > s_shp[i].hi) v = s_shp[i].hi;
    s_shp_base[i] = v;
}
int   dc_shadow_par_room_has(int i, int room) {
    shroom_load();
    const ShRoomPar *r = shroom_find(room, 0);
    return (r && i >= 0 && i < SHP_N) ? r->has[i] : 0;
}
void  dc_shadow_par_room_set(int i, int room, float v) {
    if (i < 0 || i >= SHP_N) return;
    shroom_load();
    ShRoomPar *r = shroom_find(room, 1);
    if (!r) return;
    if (v < s_shp[i].lo) v = s_shp[i].lo;
    if (v > s_shp[i].hi) v = s_shp[i].hi;
    r->v[i] = v; r->has[i] = 1;
}
void  dc_shadow_par_room_clear(int i, int room) {
    shroom_load();
    ShRoomPar *r = shroom_find(room, 0);
    if (r && i >= 0 && i < SHP_N) r->has[i] = 0;
}
void  dc_shadow_par_save(void) { shroom_save(); }
int   dc_shadow_par_rooms(int *out, int max) {
    shroom_load();
    int n = 0;
    for (int i = 0; i < s_shroom_n && n < max; i++) {
        int any = 0;
        for (int k = 0; k < SHP_N; k++) if (s_shroom[i].has[k]) any = 1;
        if (any) out[n++] = s_shroom[i].room;
    }
    return n;
}

/* ===== ОРИГИНАЛЬНАЯ «ТЕНЬ» ИГРЫ (тёмный диск под персонажем) ==========
 * Игра кладёт под каждого персонажа плоский тёмный полупрозрачный диск.
 * Пока тени не было, он её изображал; теперь под Региной их два сразу, и
 * игрок попросил её диск убрать. Прячем ТОЛЬКО её: диск узнаётся по цвету
 * (почти чёрный), по глубине и по тому, что лежит у её ног. Диски других
 * персонажей остаются — своей тени у них нет. DC_SHADOW_BLOB=0 — не прятать. */
static int   s_blob_live = 0;

/* ⭐ 25.09 вечер (игрок, слот 2, сцена у сетки с Гейлом: «в режиме наших теней не должно быть этих оригинальных теней —
 * декалей круглых под всеми существами»). Диск прятался, только если В ЭТОМ КАДРЕ наша тень дорисовалась до конца
 * (s_blob_live): кадр без ламп рядом, без персонажей-окклюдеров или без камеры возвращал диски игры. Теперь признак — сам
 * РЕЖИМ наших теней (blob_mode_now: тени включены, не родной режим O, не сцена при выключенной галке «и в сценах»), а не
 * успех кадра. DC_SHADOW_BLOB_MODE=0 — как было (только кадры, где тень нарисована). */
/* режим наших теней — считается в момент проверки диска (раз за кадр): на первых кадрах после загрузки сейва диски игры
 * приходят раньше, чем dc_shadow_draw этого кадра успевает его посчитать */
static int blob_mode_now(void) {
    extern uint64_t s_frame_count;
    static uint64_t fr = ~0ull; static int v = 0, en = -1;
    if (fr == s_frame_count) return v;
    fr = s_frame_count;
    if (en < 0) { const char *e = getenv("DC_SHADOW"); en = (e && *e == '0') ? 0 : 1; }
    extern int g_dc_orig_mode; extern int dc_scripted_now(void); extern int dc_scene_flag_on(void); extern int dc_cut_camera(void);
    extern int dcvk_shadow_ready(void);
    const int scene = dc_scripted_now() || dc_scene_flag_on() || dc_cut_camera();
    extern int dc_orig_nogfx(void);                  /* 28.09 (7): в режиме O — как в современном (DC_ORIG_GFX=0 — как было) */
    v = en && dc_shadow_par(SHP_ON) > 0.5f && dcvk_shadow_ready() && !dc_orig_nogfx() && !(scene && !dc_shadow_scene_on())
        && dc_room_live_on() && dcvk_enabled();
    (void)g_dc_orig_mode;
    return v;
}
static int blob_mode_rule(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("DC_SHADOW_BLOB_MODE"); v = (e && *e == '0') ? 0 : 1; }
    return v;
}
int dc_shadow_blob_hide(int textured, const float *fx, const float *fy, const float *w,
                        unsigned int col, unsigned int tex) {
    static int lg = -1;
    if (lg < 0) { const char *e = getenv("DC_SHADOW_BLOBLOG"); lg = (e && *e == '1') ? 1 : 0; }
    if (dc_shadow_par(SHP_BLOB) < 0.5f) return 0;
    if (lg && textured) {        /* замер: диски, которые фильтр ПРОПУСТИЛ (по причинам) */
        int r = (int)(col & 255u), g = (int)((col >> 8) & 255u), b = (int)((col >> 16) & 255u);
        float x0 = fx[0], x1 = fx[0], y0 = fy[0], y1 = fy[0];
        for (int i = 1; i < 3; i++) { if (fx[i] < x0) x0 = fx[i]; if (fx[i] > x1) x1 = fx[i];
                                      if (fy[i] < y0) y0 = fy[i]; if (fy[i] > y1) y1 = fy[i]; }
        if (r == g && g == b && r <= 48 && (x1 - x0) <= 260.f && (y1 - y0) <= 260.f) {
            static long nmode = 0, nlive = 0, ndepth = 0, nall = 0;
            nall++;
            if (!(blob_mode_rule() ? blob_mode_now() : s_blob_live)) nmode++;
            else if (!s_blob_live) nlive++;
            if (!(w[0] > 1.5f && w[1] > 1.5f && w[2] > 1.5f)) {
                extern int g_sw_blob_ui;
                ndepth++;
                if (ndepth <= 40) {
                    const uint8_t *rr = memory_get_ram_ptr();
                    fprintf(stderr, "blobnodepth: #%ld size=%.0fx%.0f center=%.0f,%.0f w=%.1f,%.1f,%.1f color=%d tex=%u ui=%d screen=%d mode=%d%c",
                            ndepth, x1 - x0, y1 - y0, (x0 + x1) * 0.5f, (y0 + y1) * 0.5f, w[0], w[1], w[2], r, tex,
                            g_sw_blob_ui, rr ? rr[0xB7878] : -1, rr ? rr[0xB92C8] : -1, 10);
                }
            }
            if ((nall % 240) == 1)
                fprintf(stderr, "blobmiss: %ld candidates, not hidden: shadow mode off %ld, no depth %ld; hidden only by the new rule %ld%c",
                        nall, nmode, ndepth, nlive, 10);
        }
    }
    if (!(blob_mode_rule() ? blob_mode_now() : s_blob_live)) return 0;
    if (!(w[0] > 1.5f && w[1] > 1.5f && w[2] > 1.5f)) {           /* без глубины — не диск... */
        /* ...кроме пришедшего через GTE (не 2D-обёртка интерфейса) на экране мира: в сценах диск иногда приходит без глубины
         * PGXP и без соседней крошки полупрозрачного (dc_semw_adopt) — рисовался поверх всего (DC_SHADOW_BLOB_NODEPTH=0 — как было) */
        static int nd = -1;
        if (nd < 0) { const char *e = getenv("DC_SHADOW_BLOB_NODEPTH"); nd = (e && *e == '0') ? 0 : 1; }
        /* замер (слот 2): такие диски — на первых кадрах после загрузки сейва, помечены 2D-обёрткой, страница 0x5E (эффекты
         * 896,256, вычитание, 4 бита — у всех дисков-«теней»); интерфейс с этой страницы и этим цветом не рисуется */
        extern int g_sw_blob_ui;
        const uint8_t *rr = memory_get_ram_ptr();
        if (!nd || !textured || !rr || rr[0xB7878] != 3) return 0;
        if (g_sw_blob_ui && (tex & 0x7Fu) != 0x5Eu) return 0;
    }
    float x0 = fx[0], x1 = fx[0], y0 = fy[0], y1 = fy[0];
    for (int i = 1; i < 3; i++) {
        if (fx[i] < x0) x0 = fx[i]; if (fx[i] > x1) x1 = fx[i];
        if (fy[i] < y0) y0 = fy[i]; if (fy[i] > y1) y1 = fy[i];
    }
    float cw = (w[0] + w[1] + w[2]) / 3.f;
    int r = (int)(col & 255u), g = (int)((col >> 8) & 255u), b = (int)((col >> 16) & 255u);
    int mx = r > g ? r : g; if (b > mx) mx = b;
    if (lg) {
        static long n = 0;
        if (n < 150 && (x1 - x0) < 260.f && (y1 - y0) < 260.f) {
            n++;
            fprintf(stderr, "blob?: %s size=%.0fx%.0f center=%.0f,%.0f w=%.0f color=%d,%d,%d tex=%u%c",
                    textured ? "textured" : "flat", x1 - x0, y1 - y0,
                    (x0 + x1) * 0.5f, (y0 + y1) * 0.5f, cw, r, g, b, tex, 10);
        }
    }
    /* Диск-«тень» игры (замер 18.09 вечер, DC_SHADOW_BLOBLOG): текстурированный
     * полупрозрачный лоскут с глубиной, модуляция РОВНО серая и тёмная
     * (32,32,32), размером с персонажа — 62x61 у Регины вблизи, 23x11 у
     * солдата в глубине комнаты. Ни тело, ни кровь, ни вспышки под это не
     * подходят: у них модуляция цветная или светлее. */
    if (!textured) return 0;
    if (r != g || g != b || r > 48) return 0;
    /* 01.10.2026 (слот 3, ST600): диск крупного существа (динозавр — два квада 380x170) больше предела 260 — прячется, если он
     * со страницы дисков-«теней» 0x5E (эффекты 896,256, вычитание, 4 бита). DC_SHADOW_BLOB_BIG=0 — как было (крупные видны). */
    { static int big = -1; if (big < 0) { const char *e = getenv("DC_SHADOW_BLOB_BIG"); big = (e && *e == '0') ? 0 : 1; }
      if (((x1 - x0) > 260.f || (y1 - y0) > 260.f) && !(big && (tex & 0x7Fu) == 0x5Eu)) return 0; }
    if (lg) { static long h = 0; if ((++h % 120) == 1)
        fprintf(stderr, "blob: disc hidden (%.0fx%.0f, w=%.0f, color %d)%c", x1 - x0, y1 - y0, cw, r, 10); }
    (void)mx; (void)tex;
    return 1;
}

/* ===== ЛУНА (25.09 вечер, игрок: «в локациях с текстурой неба (и луны) добавь источник света от луны — слабый, но чтобы
 * чуть-чуть тени было»). Комнаты с небом нашлись по экспортным атласам (s1016/moon/sky_scan.py): текстура облаков из ST112
 * есть в 13 комнатах, диск луны — только в самой ST112. Лунный свет в этих комнатах у игры уже есть — общий направленный
 * источник таблицы света (двор ST112 и сетка ST10D: 108,120,139, голубоватый), от него и направление. Наша луна, как и
 * лампы, ничего не добавляет к запечённому свету — только слабая тень от персонажей. DC_MOON=0 — без луны; DC_MOON_ROOMS —
 * свой список (ST112,ST10D,… / all / none); в F8 у параметра «moon» галка «только в этой комнате» — луна в любой комнате. */
static int moon_sky_room(int room) {
    static const char *const def[] = { "ST10A", "ST10D", "ST10E", "ST112", "ST114", "ST200", "ST201", "ST202",
                                       "ST400", "ST403", "ST404", "ST405", "ST407", 0 };
    static char envl[512]; static int envs = -1;
    if (envs < 0) { const char *e = getenv("DC_MOON_ROOMS"); envs = 0;
                    if (e && *e) { snprintf(envl, sizeof envl, ",%s,", e); envs = 1; } }
    const char *nm = dc_room_name(room);
    if (!nm || nm[0] != 'S') return 0;
    if (envs) {
        if (strstr(envl, ",all,")) return 1;
        char key[24]; snprintf(key, sizeof key, ",%s,", nm);
        return strstr(envl, key) != 0;
    }
    for (int i = 0; def[i]; i++) if (!strcmp(def[i], nm)) return 1;
    return 0;
}
/* ⭐ 01.10.2026 (игрок, слот 3, ST600 — большой динозавр у экрана в полу: «нашу тень отобрази, а диск скрой»; «диски
 * отображаются, когда наши тени в настройках выключены»). Динозавра игра освещает только общим направленным светом комнаты
 * (сверху: 0,-1200,0, цвет 60,70,80) — ламп рядом нет, и наша тень у него не рождалась (DC_SHADOW_WHY: «без-ламп»), а диск
 * игры (380x170 точек) был крупнее предела прятки. В таких комнатах тень даёт тот же слой «луны» — лампа на бесконечности по
 * общему свету комнаты, — но без её света: в комнате без неба свет не добавляется, только тень. Список — DC_SHADOW_DIR_ROOMS
 * (умолчание ST600; через запятую, all / none). Галка «луна» в F8 на комнату по-прежнему главнее. */
static int dir_shadow_room(int room) {
    static char envl[512]; static int envs = -1;
    if (envs < 0) { const char *e = getenv("DC_SHADOW_DIR_ROOMS"); snprintf(envl, sizeof envl, ",%s,", e ? e : "ST600"); envs = 1; }
    const char *nm = dc_room_name(room);
    if (!nm || nm[0] != 'S') return 0;
    if (strstr(envl, ",all,")) return 1;
    char key[24]; snprintf(key, sizeof key, ",%s,", nm);
    return strstr(envl, key) != 0;
}
static int moon_light_room(int room) {   /* свет луны — только в комнатах с небом или с галкой F8 на комнату */
    return dc_shadow_par_room_has(SHP_MOON, room) || moon_sky_room(room);
}
int dc_moon_now(void) {           /* луна в этой комнате: правка комнаты (F8) главнее списка комнат с небом */
    const int room = dc_room_effective();
    if (dc_shadow_par_room_has(SHP_MOON, room)) return dc_shadow_par(SHP_MOON) > 0.5f;
    return dc_shadow_par(SHP_MOON) > 0.5f && (moon_sky_room(room) || dir_shadow_room(room));
}

/* почему в этом кадре тени нет — по счётчику причин (DC_SHADOW_WHY=1) */
static long s_shwhy[6] = { 0, 0, 0, 0, 0, 0 };
static void shwhy(int k) {
    static int on = -1;
    if (on < 0) { const char *e = getenv("DC_SHADOW_WHY"); on = (e && *e == '1') ? 1 : 0; }
    if (k >= 0 && k < 6) s_shwhy[k]++;
    if (!on) return;
    static long wn = 0;
    if ((++wn % 120) == 1)
        fprintf(stderr, "shadowwhy: no-occluders %ld no-world %ld no-lamps %ld scene %ld no-camera %ld ok %ld%c",
                s_shwhy[0], s_shwhy[1], s_shwhy[2], s_shwhy[3], s_shwhy[4], s_shwhy[5], 10);
}


/* ===== ДАЛЬНОСТЬ ТЕНЕЙ (25.09.2026, игрок, слот 13: «можешь их дальность увеличить? сейчас они не рендерятся дальше
 * пары метров от Регины»). Замер DC_SHADOW_DBG=2 (покрытие карт): в комнате одна подходящая лампа (G01, высота 4000,
 * радиус 5000) между Региной и раптором; её карта смотрела НА РЕГИНУ с полем 120° и кончалась у ног раптора — его тень
 * падает от лампы вглубь комнаты, за край карты, и срезалась. Лампы тоже выбирались только по Регине.
 * Теперь: (1) лампа берётся по БЛИЖАЙШЕМУ персонажу — Регина и все занятые слоты актёров; (2) карта каждой лампы
 * нацелена на персонажей в её досягаемости (радиус × radk) и на КОНЦЫ их теней на полу — проекция макушки из точки
 * лампы до уровня ног, не дальше, чем тень вообще видна (радиус × fade); поле раскрывается, чтобы всё это вошло
 * (не уже поля fov из панели, не шире 160°), ось и раскрытие сглажены по лампе — карта не дёргается от шагов.
 * DC_SHADOW_REACH=0 — как было (лампы и карта по Регине). */
static int shadow_reach_on(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("DC_SHADOW_REACH"); v = (e && *e == '0') ? 0 : 1; }
    return v;
}
/* 27.09 (2): номера GLAMP_MAX..+3 — слои нового пути теней (сглаживание оси и раскрытия карты — за слоем, не за лампой) */
#define REACH_N (GLAMP_MAX + 4)
static float s_reach_half[REACH_N]; static int s_reach_np[REACH_N];   /* для строки журнала */
static float s_rf_ax[REACH_N][3], s_rf_half[REACH_N]; static uint64_t s_rf_seen[REACH_N];   /* сглаживание по лампе/слою */
static void shadow_reach_reset(int li) { if (li >= 0 && li < REACH_N) s_rf_seen[li] = 0; }
static void shadow_reach_frustum(int li, const float L[3], float rad, float radk, float fade, float tan_min,
                                 const float *cx, const float *cy, const float *cz, const float *ch, int nch,
                                 float aim[3], float *znear, float *zfar, float *th) {
    float pts[36][3]; int np = 0;
    const float reach = rad * radk, rr = rad * fade;
    for (int c = 0; c < nch && np + 3 <= 36; c++) {
        const float dx = cx[c] - L[0], dy = cy[c] - L[1], dz = cz[c] - L[2];
        if (dx*dx + dy*dy + dz*dz > reach * reach) continue;
        if (L[1] > cy[c] - 150.f) continue;                   /* лампа не над ним */
        const float ty = cy[c] - ch[c];                       /* макушка (Y вниз) */
        pts[np][0] = cx[c]; pts[np][1] = cy[c]; pts[np][2] = cz[c]; np++;
        pts[np][0] = cx[c]; pts[np][1] = ty;    pts[np][2] = cz[c]; np++;
        float e[3];
        const float hl = cy[c] - L[1], ht = ty - L[1];        /* насколько ноги и макушка ниже лампы */
        if (ht > 50.f) {                                      /* конец тени: луч «лампа -> макушка» до уровня ног */
            const float k = hl / ht;
            e[0] = L[0] + (cx[c] - L[0]) * k; e[1] = cy[c]; e[2] = L[2] + (cz[c] - L[2]) * k;
        } else {                                              /* макушка вровень с лампой — тень до края её света */
            float hx = cx[c] - L[0], hz = cz[c] - L[2];
            float hn = sqrtf(hx*hx + hz*hz); if (hn < 1.f) { hx = 1.f; hz = 0.f; hn = 1.f; }
            e[0] = L[0] + hx / hn * rr; e[1] = cy[c]; e[2] = L[2] + hz / hn * rr;
        }
        { const float ex = e[0] - L[0], ey = e[1] - L[1], ez = e[2] - L[2];
          const float ed = sqrtf(ex*ex + ey*ey + ez*ez);
          if (ed > rr && ed > 1.f) { const float k = rr / ed; e[0] = L[0] + ex*k; e[1] = L[1] + ey*k; e[2] = L[2] + ez*k; } }
        pts[np][0] = e[0]; pts[np][1] = e[1]; pts[np][2] = e[2]; np++;
    }
    if (li >= 0 && li < REACH_N) s_reach_np[li] = np / 3;
    if (np == 0) return;                                      /* некого — карта как была, на Регину */
    float u[36][3], ax[3] = { 0.f, 0.f, 0.f }, dmin = 1e30f, dmax = 0.f;
    for (int k = 0; k < np; k++) {
        const float vx = pts[k][0] - L[0], vy = pts[k][1] - L[1], vz = pts[k][2] - L[2];
        float d = sqrtf(vx*vx + vy*vy + vz*vz); if (d < 1.f) d = 1.f;
        u[k][0] = vx / d; u[k][1] = vy / d; u[k][2] = vz / d;
        ax[0] += u[k][0]; ax[1] += u[k][1]; ax[2] += u[k][2];
        if (d < dmin) dmin = d;
        if (d > dmax) dmax = d;
    }
    { const float al = sqrtf(ax[0]*ax[0] + ax[1]*ax[1] + ax[2]*ax[2]);
      if (al < 1e-3f) { ax[0] = 0.f; ax[1] = 1.f; ax[2] = 0.f; } else { ax[0] /= al; ax[1] /= al; ax[2] /= al; } }
    /* сглаживание оси по лампе, затем раскрытие — под СГЛАЖЕННУЮ ось, чтобы ни одна точка не выпала */
    float (*const s_ax)[3] = s_rf_ax; float *const s_half = s_rf_half; uint64_t *const s_seen = s_rf_seen;   /* 27.09 (2): вынесены */
    extern uint64_t s_frame_count;
    int cont = (li >= 0 && li < REACH_N && s_seen[li] && s_frame_count - s_seen[li] <= 8u);
    if (li >= 0 && li < REACH_N) {
        if (cont) {
            for (int q = 0; q < 3; q++) s_ax[li][q] += (ax[q] - s_ax[li][q]) * 0.25f;
            const float nl = sqrtf(s_ax[li][0]*s_ax[li][0] + s_ax[li][1]*s_ax[li][1] + s_ax[li][2]*s_ax[li][2]);
            if (nl > 1e-3f) for (int q = 0; q < 3; q++) s_ax[li][q] /= nl;
        } else for (int q = 0; q < 3; q++) s_ax[li][q] = ax[q];
        for (int q = 0; q < 3; q++) ax[q] = s_ax[li][q];
    }
    float mc = 1.f;
    for (int k = 0; k < np; k++) { const float c = u[k][0]*ax[0] + u[k][1]*ax[1] + u[k][2]*ax[2]; if (c < mc) mc = c; }
    if (mc < -1.f) mc = -1.f;
    float half = acosf(mc) + 0.105f;                          /* +6°: у края карты тень гаснет плавно */
    const float hmin = atanf(tan_min), hmax = 1.396f;         /* не уже поля fov из панели, не шире 160° */
    if (half < hmin) half = hmin;
    if (half > hmax) half = hmax;
    if (li >= 0 && li < REACH_N) {                            /* расширяется сразу (не резать), сужается плавно */
        if (cont && half < s_half[li]) half = s_half[li] + (half - s_half[li]) * 0.15f;
        s_half[li] = half; s_seen[li] = s_frame_count ? s_frame_count : 1u;
        s_reach_half[li] = half;
    }
    aim[0] = L[0] + ax[0] * 1000.f; aim[1] = L[1] + ax[1] * 1000.f; aim[2] = L[2] + ax[2] * 1000.f;
    { static int fd = -1; static long nf = 0;
      if (fd < 0) { const char *e = getenv("DC_SHCAM_DBG"); fd = (e && *e == '1') ? 1 : 0; }
      if (fd && nf < 150) { nf++;
          float worst = 0.f; int wk = -1;
          for (int k = 0; k < np; k++) { const float c = acosf(fminf(1.f, u[k][0]*ax[0] + u[k][1]*ax[1] + u[k][2]*ax[2]));
                                         if (c > worst) { worst = c; wk = k; } }
          fprintf(stderr, "reachdbg: f=%llu G%02d ax %.2f,%.2f,%.2f half %.1f cont %d np %d worst %.1f deg at %.0f,%.0f,%.0f%c",
                  (unsigned long long)s_frame_count, li, ax[0], ax[1], ax[2], half * 57.2958f, cont, np, worst * 57.2958f,
                  wk >= 0 ? pts[wk][0] : 0.f, wk >= 0 ? pts[wk][1] : 0.f, wk >= 0 ? pts[wk][2] : 0.f, 10); } }
    *znear = dmin * 0.2f; if (*znear < 60.f) *znear = 60.f;
    *zfar  = dmax * 1.15f + 300.f;
    *th    = tanf(half);
}

/* ⭐ 25.09.2026 — ТЕНИ И В СЦЕНАХ НА ДВИЖКЕ (игрок, слот 0: «в катсценах на движке реалистичные тени не включаются»).
 * Тени стояли на двух запретах: явный выход в сцене (режим 4 / признак 0xB8F30) и дельта нашей камеры, которой в сцене нет
 * — сцену ведёт камера игры. Но в сцене комнату рисует наш эмиттер с ЕДИНИЧНОЙ дельтой (dc_room_get_delta): видовое
 * пространство кадра — это пространство камеры игры, и «комната -> вид» = матрица комнаты этого кадра. Её же и берём, если
 * в собранном кадре есть наша комната (матрица s_rl_best_* свежая только тогда). Оригинальный режим (O) — как был, без
 * теней. DC_SHADOW_SCENE=0 — как было (в сценах теней нет); переключатель — в F8 рядом с главным. */
static int s_sh_scene = -1;
int  dc_shadow_scene_on(void) {
    if (s_sh_scene < 0) { const char *e = getenv("DC_SHADOW_SCENE"); s_sh_scene = (e && *e == '0') ? 0 : 1; }
    return s_sh_scene;
}
void dc_shadow_scene_set(int on) { s_sh_scene = on ? 1 : 0; }

/* Камера кадра: дельта нашей камеры D,T (или единичная, где кадр снят камерой игры) и матрица комнаты R,TR.
 * Вид = D·(R·p + TR) + T для точки комнаты p. allow_orig: в оригинальном режиме камера — тоже игры (вспышкам можно,
 * теням — нет, там всё как было). *game_cam = 1, если взята камера игры. */
static int rr_matrix_from_sections(float Rout[9], float Tout[3]);
static int sh_camera(const uint8_t *ram, int allow_orig, float D[9], float T[3], float R[9], float TR[3], int *game_cam) {
    extern int dc_nots_get_delta(float D[9], float T[3]); extern int dc_scripted_now(void); extern int dc_scene_flag_on(void);
    int gc = 0;
    if (!dc_nots_get_delta(D, T)) {
        extern int g_dc_orig_mode; extern int dc_cut_camera(void); extern int dcvk_stream_room_verts(void);
        const int scene = dc_scripted_now() || dc_scene_flag_on() || dc_cut_camera();
        /* 28.09 (7): режим O — камера игры, как в сцене (тени, блики, отражения, дымка); DC_ORIG_GFX=0 — как было (только вспышки) */
        extern int dc_orig_gfx(void);
        if (g_dc_orig_mode ? !(allow_orig || dc_orig_gfx()) : (!scene || !dc_shadow_scene_on())) return 0;
        for (int i = 0; i < 9; i++) D[i] = (i % 4 == 0) ? 1.0f : 0.0f;
        T[0] = T[1] = T[2] = 0.0f;
        gc = 1;
        /* матрица комнаты: наша комната в кадре — та, что взял эмиттер (как в игре); комнату рисует сама игра (сейв
         * посреди сцены, сцена в новой комнате) — с секций: движок каждый кадр переписывает их под ТЕКУЩУЮ камеру */
        if (!(s_rl_best_w > 0 && dcvk_stream_room_verts() > 0)) {
            extern uint64_t s_frame_count; extern int dc_nots_get_pairf(float R9[9], float T3[3]);
            float sR[9], sT[3]; const int sec = rr_matrix_from_sections(sR, sT);
            float pR[9], pT[3]; const int pair = dc_nots_get_pairf(pR, pT);
            static int src = -1;      /* 0 авто, 1 пара, 2 GTE, 3 секции */
            if (src < 0) { const char *e = getenv("DC_SHCAM_SRC");
                           src = !e ? 0 : (*e == 'p') ? 1 : (*e == 'g') ? 2 : (*e == 's') ? 3 : 0; }
            if (pair && (src == 0 || src == 1)) {
                for (int q = 0; q < 9; q++) R[q] = pR[q];
                for (int q = 0; q < 3; q++) TR[q] = pT[q];
                if (game_cam) *game_cam = 4;
            } else if (s_gcam_frame && s_frame_count - s_gcam_frame <= 2u && src != 3) {
                for (int q = 0; q < 9; q++) R[q] = s_gcam_R[q];
                for (int q = 0; q < 3; q++) TR[q] = s_gcam_T[q];
                if (game_cam) *game_cam = 3;
            } else if (sec) {
                for (int q = 0; q < 9; q++) R[q] = sR[q];
                for (int q = 0; q < 3; q++) TR[q] = sT[q];
                if (game_cam) *game_cam = 2;
            } else return 0;
            { static int fd = -1; static long nf = 0;       /* DC_SHCAM_DBG=1: полная камера и проекция (сверка по дампу примитивов) */
              if (fd < 0) { const char *e = getenv("DC_SHCAM_DBG"); fd = (e && *e == '1') ? 1 : 0; }
              if (fd && (++nf % 30) == 1) {
                  extern void gpu_get_draw_offset(int *ox, int *oy); int dox = 0, doy = 0; gpu_get_draw_offset(&dox, &doy);
                  fprintf(stderr, "shcamfull: f=%llu R=%.4f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f,%.4f T=%.1f,%.1f,%.1f ofx=%.2f ofy=%.2f H=%.1f dox=%d doy=%d ws=%d reg=%d,%d,%d%c",
                          (unsigned long long)s_frame_count, R[0], R[1], R[2], R[3], R[4], R[5], R[6], R[7], R[8], TR[0], TR[1], TR[2],
                          g_pt_proj_ofx, g_pt_proj_ofy, g_pt_proj_h, dox, doy, dc_ws_world(),
                          rrm_s16(ram, 0xB92ACu), rrm_s16(ram, 0xB92AEu), rrm_s16(ram, 0xB92B0u), 10); } }
            { static long nd = 0;                        /* сверка: защёлка GTE против секций */
              if (++nd == 1 || nd % 600 == 0) {   /* 18.10: скобки - строки feet view шли на каждый вызов */
                  fprintf(stderr, "shcam: pair(%d) R0=%.3f,%.3f,%.3f T=%.0f,%.0f,%.0f | gte(%s, %ld tri) R0=%.3f,%.3f,%.3f T=%.0f,%.0f,%.0f | sections(%d) R0=%.3f,%.3f,%.3f T=%.0f,%.0f,%.0f%c",
                          pair, pR[0], pR[1], pR[2], pT[0], pT[1], pT[2],
                          (s_gcam_frame && s_frame_count - s_gcam_frame <= 2u) ? "fresh" : "stale", s_gcam_n,
                          s_gcam_R[0], s_gcam_R[1], s_gcam_R[2], s_gcam_T[0], s_gcam_T[1], s_gcam_T[2],
                          sec, sR[0], sR[1], sR[2], sT[0], sT[1], sT[2], 10);
                  /* куда каждый источник кладёт ноги Регины на экране (сверить с кадром) */
                  const float fp[3] = { (float)rrm_s16(ram, 0xB92ACu), (float)rrm_s16(ram, 0xB92AEu), (float)rrm_s16(ram, 0xB92B0u) };
                  const float *Ms[3] = { pR, s_gcam_R, sR }, *Ts[3] = { pT, s_gcam_T, sT };
                  const float sq = dc_ws_sq();
                  for (int c = 0; c < 3; c++) {
                      const float *M = Ms[c], *V = Ts[c];
                      const float vx = M[0]*fp[0] + M[1]*fp[1] + M[2]*fp[2] + V[0];
                      const float vy = M[3]*fp[0] + M[4]*fp[1] + M[5]*fp[2] + V[1];
                      const float vz = M[6]*fp[0] + M[7]*fp[1] + M[8]*fp[2] + V[2];
                      fprintf(stderr, "shcam:   %s -> feet view %.0f,%.0f,%.0f scr %.0f,%.0f%c", c == 0 ? "pair" : c == 1 ? "gte " : "sect",
                              vx, vy, vz, vz > 1.f ? g_pt_proj_ofx + g_pt_proj_h * vx / vz * sq : -1.f,
                              vz > 1.f ? g_pt_proj_ofy + g_pt_proj_h * vy / vz : -1.f, 10);
                  } } }
            return 1;
        }
    } else {
        extern int dc_nots_get_delta_submit(float Dp[9], float Tp[3]);
        float Dp[9], Tp[3];
        if (dc_nots_get_delta_submit(Dp, Tp)) {
            for (int i = 0; i < 9; i++) D[i] = Dp[i];
            for (int i = 0; i < 3; i++) T[i] = Tp[i];
        }
    }
    if (s_rl_best_w > 0) {
        for (int q = 0; q < 9; q++) R[q] = s_rl_best_R[q];
        for (int q = 0; q < 3; q++) TR[q] = s_rl_best_T[q];
    } else {
        if (gc) return 0;
        for (int q = 0; q < 9; q++)
            R[q] = (float)rrm_s16(ram, 0xBF9F4u + (uint32_t)q * 2u) * (1.0f / 4096.0f);
        TR[0] = (float)(int32_t)rrm_u32(ram, 0xBFA08u);
        TR[1] = (float)(int32_t)rrm_u32(ram, 0xBFA0Cu);
        TR[2] = (float)(int32_t)rrm_u32(ram, 0xBFA10u);
    }
    if (game_cam) *game_cam = gc;
    return 1;
}

/* ===== ЧАСТИ ПЕРСОНАЖА, КОТОРЫЕ ИГРА НЕ РИСУЕТ — В КАРТУ ТЕНЕЙ (25.09.2026 ночь) =====================================
 * Игрок: «за кадром полигоны персонажей режутся и с ними режется визуально и их тень — если можно сохранять тень цельной,
 * сделай». Сборщики персонажа (func_80075770 — треугольники, func_8007599C — четырёхугольники) выбрасывают полигон, у
 * которого все вершины за краем кадра (x вне 0..320 или y вне 0..240), и полигон спиной к камере (NCLIP). В карту теней
 * шло только нарисованное: тень обрезалась вместе с моделью, а от лампы сбоку силуэт тени был «полым» (одна половина
 * модели). Хук в конце каждого шага сборщика (dc_hooks_ops.json, блоки 0x80075964 и 0x80075C08): полигон, не дошедший до
 * pt_dc_poolprim, берётся из пула проектора (модель × матрица кости + сдвиг нашей камеры — ровно как нарисованные) и
 * копится по проходу сборки (g_dc_pass_id). Растр в кадре A дописывает их за вершинами кадра (pt_shx_take) — рисует только
 * проход карты теней (dc_shadow.vert: метка u = -1000, точка уже в видовом пространстве, годится и позади камеры).
 * Проход — тот же, что у полигонов персонажа, пришедших в поток кадра; их не было — последний законченный. Панель теней:
 * chr_off (за краем кадра), chr_back (спиной к камере); DC_SHADOW_OFFSCREEN=0 / DC_SHADOW_BACKFACE=0 — как было.
 * DC_SHX_LOG=1 — счётчики «shx:» раз в 2 с. */
#define SHX_SLOTS  4
#define SHX_MAXTRI 8192
typedef struct { int pass; int n; float v[SHX_MAXTRI][9]; unsigned char fl[SHX_MAXTRI]; } ShxList;
static ShxList *s_shx = NULL;
static long s_shx_cnt[5];               /* за краем, спиной, промах пула, переполнение, не персонаж */
/* 04.10: DC_POOLPRIM_DBG=1 — полигоны персонажей по страницам текстур за кадр: дошло до пакета / выброшено сборщиком
 * (слот 44: у Гейла вдали нет четверти полигонов головы — кто их не рисует) */
int s_ppdbg_miss[512];                          /* 04.10 (2): промахи вершин пула (pv_find) по страницам, замер DC_POOLPRIM_DBG */
static void pp_dbg_note(CPUState *cpu, uint32_t prim, int emitted, uint32_t poolBase, int nv) {
    static int on = -1; if (on < 0) { const char *e = getenv("DC_POOLPRIM_DBG"); on = (e && *e == '1') ? 1 : 0; }
    if (!on) return;
    extern int g_dc_pass_id;
    static int pass = -9; static int em[512], rj[512], rjb[512], rjz[512]; static long frames = 0;
    if (pass != g_dc_pass_id) {
        if (pass != -9 && (++frames % 60) == 1) {
            char buf[1600]; int n = 0;
            for (int t = 0; t < 512 && n < (int)sizeof buf - 70; t++)
                if (em[t] || rj[t]) n += snprintf(buf + n, sizeof buf - n, " tp%d:%d/%d(back %d zero %d, vertex miss %d)", t, em[t], rj[t], rjb[t], rjz[t], s_ppdbg_miss[t]);
            fprintf(stderr, "ppdbg: pass %d (emitted/rejected by tpage):%s%c", pass, buf, 10);
        }
        pass = g_dc_pass_id; memset(em, 0, sizeof em); memset(rj, 0, sizeof rj); memset(rjb, 0, sizeof rjb); memset(rjz, 0, sizeof rjz);
        memset(s_ppdbg_miss, 0, sizeof s_ppdbg_miss);
    }
    const uint32_t uv1w = cpu->read_word(prim + 12);
    const int tp = (int)((uv1w >> 16) & 0x1FF);
    if (emitted) em[tp]++;
    else {
        rj[tp]++;
        if (nv >= 3 && nv <= 4) {                      /* 04.10 (2): почему выброшен — по целым координатам пула, как у сборщика */
            int sx[3], sy[3];
            for (int k = 0; k < 3; k++) {
                const uint32_t off = (uint32_t)(uint16_t)cpu->read_half(prim + (uint32_t)k * 2u) << 2;
                const uint32_t w = cpu->read_word(poolBase + off);
                sx[k] = (int16_t)(w & 0xFFFF); sy[k] = (int16_t)(w >> 16);
            }
            const long long m = (long long)sx[0] * sy[1] + (long long)sx[1] * sy[2] + (long long)sx[2] * sy[0]
                              - (long long)sx[0] * sy[2] - (long long)sx[1] * sy[0] - (long long)sx[2] * sy[1];
            if (m < 0) rjb[tp]++; else if (m == 0) rjz[tp]++;
        }
    }
}
void pt_dc_poolprim_end(CPUState *cpu, uint32_t prim, uint32_t poolBase, int nv) {
    { extern int dc_burst_nodraw(void); if (dc_burst_nodraw()) { s_pp_acc_prim = 0; return; } }   /* 12.10: прогон пропуска */
    pp_dbg_note(cpu, prim, prim == s_pp_acc_prim, poolBase, nv);
    if (prim == s_pp_acc_prim) { s_pp_acc_prim = 0; return; }   /* дошёл до пакета — нарисован, в карте и так */
    s_pp_acc_prim = 0;
    extern int g_dc_pass_id; extern int dc_orig_nogfx(void);   /* 28.09 (7): и в режиме O — тени персонажей целые */
    if (nv < 3 || nv > 4 || dc_orig_nogfx() || !pt_poolgeom_enabled()) return;
    static int fk = -2, on_sh = 0, on_off = 1, on_back = 1;
    if (fk != g_dc_pass_id) { fk = g_dc_pass_id;
        on_sh = dc_shadow_par(SHP_ON) > 0.5f;
        on_off = dc_shadow_par(SHP_CHR_OFF) > 0.5f; on_back = dc_shadow_par(SHP_CHR_BACK) > 0.5f; }
    if (!on_sh || (!on_off && !on_back)) return;
    uint32_t off[4]; int sx[4], sy[4];
    for (int k = 0; k < nv; k++) {
        off[k] = (uint32_t)(uint16_t)cpu->read_half(prim + (uint32_t)k * 2u) << 2;
        const uint32_t w = cpu->read_word(poolBase + off[k]);
        sx[k] = (int16_t)(w & 0xFFFF); sy[k] = (int16_t)(w >> 16);
    }
    /* почему выброшен: NCLIP по трём первым вершинам, как у сборщика (< 0 — спиной), иначе — рамка кадра */
    const long long mac0 = (long long)sx[0] * sy[1] + (long long)sx[1] * sy[2] + (long long)sx[2] * sy[0]
                         - (long long)sx[0] * sy[2] - (long long)sx[1] * sy[0] - (long long)sx[2] * sy[1];
    const int back = mac0 < 0;
    if (back ? !on_back : !on_off) return;
    extern int dc_nots_get_delta(float D[9], float T[3]);
    float Dn[9], Tn[3];
    const int reaim = dc_nots_get_delta(Dn, Tn);
    float P[4][3]; int player = 0; uint32_t ctx = 0;
    for (int k = 0; k < nv; k++) {
        const PoolVtx *pv = pv_find(poolBase + off[k]);
        if (!pv) { s_shx_cnt[2]++; return; }
        const float *R = pv->r, *T = pv->tr;
        const float X = (float)pv->mx, Y = (float)pv->my, Z = (float)pv->mz;
        float vx = R[0]*X + R[1]*Y + R[2]*Z + T[0];
        float vy = R[3]*X + R[4]*Y + R[5]*Z + T[1];
        float vz = R[6]*X + R[7]*Y + R[8]*Z + T[2];
        if (reaim) {
            const float ax = Dn[0]*vx + Dn[1]*vy + Dn[2]*vz + Tn[0];
            const float ay = Dn[3]*vx + Dn[4]*vy + Dn[5]*vz + Tn[1];
            const float az = Dn[6]*vx + Dn[7]*vy + Dn[8]*vz + Tn[2];
            vx = ax; vy = ay; vz = az;
        }
        P[k][0] = vx; P[k][1] = vy; P[k][2] = vz;
        if (k == 0) { player = pv->player; ctx = pv->ctx; }
    }
    {   /* в сцене на движке — только персонаж (как F_CHAR у нарисованных, dc_char_prim_ok) */
        const uint32_t c = ctx & 0x1FFFFFu;
        const int chr = !dc_char_rule_now() || player || (c >= 0xB9280u && c < 0xB9300u) ||
                        (c >= 0xB7ACCu && c < 0xB7ACCu + 16u * 608u && ((c - 0xB7ACCu) % 608u) == 0u);
        if (!chr) { s_shx_cnt[4]++; return; } }
    if (!s_shx) {
        s_shx = (ShxList *)calloc(SHX_SLOTS, sizeof(ShxList));
        if (!s_shx) return;
        for (int i = 0; i < SHX_SLOTS; i++) s_shx[i].pass = -1;
    }
    ShxList *L = NULL;
    for (int i = 0; i < SHX_SLOTS; i++) if (s_shx[i].pass == g_dc_pass_id) { L = &s_shx[i]; break; }
    if (!L) {                                   /* новый проход сборки — место самого старого */
        int oi = 0;
        for (int i = 1; i < SHX_SLOTS; i++) if (s_shx[i].pass < s_shx[oi].pass) oi = i;
        L = &s_shx[oi]; L->pass = g_dc_pass_id; L->n = 0;
    }
    static const int TRI[2][3] = { { 0, 1, 2 }, { 1, 3, 2 } };
    for (int tq = 0; tq < (nv == 4 ? 2 : 1); tq++) {
        if (L->n >= SHX_MAXTRI) { s_shx_cnt[3]++; break; }
        float *o = L->v[L->n];
        for (int j = 0; j < 3; j++) { const float *q = P[TRI[tq][j]]; o[j*3+0] = q[0]; o[j*3+1] = q[1]; o[j*3+2] = q[2]; }
        L->fl[L->n] = (unsigned char)(player ? 1 : 0);
        L->n++;
    }
    s_shx_cnt[back ? 1 : 0]++;
}
/* растр, кадр A (перед проходом карты теней): вершины хвоста в dst (vfloats на вершину), число вершин */
int pt_shx_take(float *dst, int maxVerts, int vfloats) {
    extern int g_dc_pass_id;
    static int lg = -1; static long nk = 0;
    if (lg < 0) { const char *e = getenv("DC_SHX_LOG"); lg = (e && *e == '1') ? 1 : 0; }
    if (!s_shx || !dst || maxVerts < 3 || vfloats < 13) return 0;
    /* выключено (панель теней / DC_SHADOW_OFFSCREEN, DC_SHADOW_BACKFACE) — старые списки не рисовать */
    if (dc_shadow_par(SHP_CHR_OFF) < 0.5f && dc_shadow_par(SHP_CHR_BACK) < 0.5f) return 0;
    const ShxList *L = NULL;
    const int want = g_shx_stream_pass;
    if (want >= 0) {                            /* проход полигонов персонажа этого потока: его список (нет — нечего) */
        for (int i = 0; i < SHX_SLOTS; i++) if (s_shx[i].pass == want) { L = &s_shx[i]; break; }
    } else {                                    /* в потоке нет полигонов персонажа — последний законченный, если свежий */
        int best = -1;
        for (int i = 0; i < SHX_SLOTS; i++)
            if (s_shx[i].pass >= 0 && s_shx[i].pass < g_dc_pass_id && s_shx[i].pass >= g_dc_pass_id - 2 && s_shx[i].pass > best)
                { best = s_shx[i].pass; L = &s_shx[i]; }
    }
    int nv = 0;
    extern int dc_regina_hidden(void);
    const int hid = dc_regina_hidden();         /* 19.10 вечер: CAMERA -> Hide Regina - и её тени нет */
    if (L) for (int tq = 0; tq < L->n && nv + 3 <= maxVerts; tq++) {
        if (hid && L->fl[tq]) continue;
        for (int j = 0; j < 3; j++) {
            float *v = dst + (size_t)nv * (size_t)vfloats;
            for (int k = 0; k < vfloats; k++) v[k] = 0.f;
            v[0] = L->v[tq][j*3+0]; v[1] = L->v[tq][j*3+1];
            v[2] = -1000.f;                               /* метка: точка уже в видовом пространстве */
            v[11] = (float)(8388608 | (L->fl[tq] ? 16 : 0));   /* F_CHAR (+ F_ACTOR у Регины) */
            v[12] = L->v[tq][j*3+2];
            nv++;
        }
    }
    if (lg && (++nk % 120) == 1)
        fprintf(stderr, "shx: pass %d (in the stream %d, now %d) - %d triangles | in all: past the edge %ld, back-facing %ld, pool miss %ld, overflow %ld, not a character %ld%c",
                L ? L->pass : -1, want, g_dc_pass_id, nv / 3, s_shx_cnt[0], s_shx_cnt[1], s_shx_cnt[2], s_shx_cnt[3], s_shx_cnt[4], 10);
    return nv;
}

/* ===== ЛАМПЫ-ТЕКСТУРЫ ДЛЯ ТЕНЕЙ (27.09) ===================================================================================
 * Игрок: «попробуй сделать тени также только от ламп-текстур (с учетом их фигуры и размеров), а не от расставленных разрабами
 * источников света» — лампы таблицы игры не совпадают с нарисованными ни числом, ни местом. Лампа = связная группа
 * треугольников комнаты (меш из RAM, s_rrm_*) с текстурой «светится» (выбор игрока в приложении, dc_tex_class бит 4): центр
 * по площади, площадь, форма — главные оси разброса вершин (длинная A и короткая B — полудлины векторами). Отметка
 * треугольника держится весь визит в комнату (экраны анимированы — хеш окна меняется), досбор раз в ~секунду. Радиус света —
 * как у света от светящихся текстур (glow_light_rad × размер 0.6..1.6 по √площади/300), сила — по размеру. dc_shadow_draw
 * берёт эти лампы вместо таблицы игры, где они есть (в комнате без ламп-текстур — прежние лампы игры); мягкость тени и её
 * форма — по фигуре лампы (эллипс выборок в карте, dc_raster.frag shadowLit, UBO lsh). DC_SHADOW_TEXLAMPS=0 — как было. */
static GameLamp s_tlamp[GLAMP_MAX];
static float    s_tl_A[GLAMP_MAX][3], s_tl_B[GLAMP_MAX][3], s_tl_area[GLAMP_MAX];
static int      s_tlamp_n = 0;
static int tlamp_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("DC_SHADOW_TEXLAMPS"); v = (e && *e == '0') ? 0 : 1; } return v; }
static float tlamp_softk(void) { static float v = -1.f; if (v < 0.f) { const char *e = getenv("DC_SHADOW_TEXSOFT"); v = e ? (float)atof(e) : 1.0f; if (v < 0.f) v = 0.f; } return v; }
static int tl_find(int *par, int i) { while (par[i] != i) { par[i] = par[par[i]]; i = par[i]; } return i; }
static void tlamp_refresh(void) {
    extern int dc_tex_class(uint16_t tpage, uint16_t clut_x, uint16_t clut_y, const int *u, const int *v, int n);
    extern unsigned dc_tex_class_gen(void);
    extern int dcvk_post_par_find(const char *key);
    extern float dcvk_post_par(int i);
    static uint32_t sig = 0; static unsigned gen = 0; static long tick = 0;
    static uint8_t *mark = NULL; static int mcap = 0, nmark = 0, grouped = -1;
    const unsigned g = dc_tex_class_gen();
    int fresh = 0;
    if (sig != s_rrm_sig || gen != g || !mark || mcap < s_rrm_n) {
        if (mcap < s_rrm_n) { free(mark); mcap = s_rrm_n + 1024; mark = (uint8_t *)calloc((size_t)mcap, 1); }
        else if (mark) memset(mark, 0, (size_t)mcap);
        sig = s_rrm_sig; gen = g; nmark = 0; grouped = -1; fresh = 1;
    }
    if (!mark || s_rrm_n <= 0 || !s_rrm_v || !s_rrm_uv) { s_tlamp_n = 0; return; }
    if (!fresh && (++tick % 60) != 0 && grouped == nmark) return;      /* досбор — раз в ~секунду */
    for (int t = 0; t < s_rrm_n; t++) {
        if (mark[t]) continue;
        const int16_t *uv = &s_rrm_uv[t * 6];
        const int u[3] = { uv[0], uv[2], uv[4] }, v[3] = { uv[1], uv[3], uv[5] };
        if (dc_tex_class(s_rrm_tp[t], s_rrm_cx[t], s_rrm_cy[t], u, v, 3) & 4) { mark[t] = 1; nmark++; }
    }
    if (grouped == nmark) return;                                    /* набор тот же — лампы те же */
    grouped = nmark;
    /* группы: соседние треугольники (центры ближе суммы их размахов + 30 ед.) — одна лампа */
    enum { TLN = 2048 };
    static int ti[TLN], par[TLN]; static float cen[TLN][3], ar[TLN], ext[TLN];
    int ng = 0, nsemi = 0; unsigned codes[256 / 32] = { 0 };
    static int semi_ok = -1;
    if (semi_ok < 0) { const char *e = getenv("DC_SHADOW_TEXLAMP_SEMI"); semi_ok = (e && *e == '1') ? 1 : 0; }
    for (int t = 0; t < s_rrm_n && ng < TLN; t++) {
        if (!mark[t]) continue;
        /* полупрозрачное (лазеры, стекло — код команды GPU 0x20..0x3F с битом 1) — не лампа для теней: сквозь него светит,
         * но само оно комнату не освещает; DC_SHADOW_TEXLAMP_SEMI=1 — брать и его */
        const unsigned cd = s_rrm_code ? s_rrm_code[t] : 0u;
        codes[cd >> 5] |= 1u << (cd & 31);
        if (!semi_ok && cd >= 0x20u && cd <= 0x3Fu && (cd & 2u)) { nsemi++; continue; }
        const int16_t *m = &s_rrm_v[t * 9];
        float p[3][3];
        for (int k = 0; k < 3; k++) for (int q = 0; q < 3; q++) p[k][q] = (float)m[k * 3 + q];
        const float e1[3] = { p[1][0] - p[0][0], p[1][1] - p[0][1], p[1][2] - p[0][2] };
        const float e2[3] = { p[2][0] - p[0][0], p[2][1] - p[0][1], p[2][2] - p[0][2] };
        const float cx = e1[1] * e2[2] - e1[2] * e2[1], cy = e1[2] * e2[0] - e1[0] * e2[2], cz = e1[0] * e2[1] - e1[1] * e2[0];
        ti[ng] = t; par[ng] = ng; ar[ng] = 0.5f * sqrtf(cx * cx + cy * cy + cz * cz);
        for (int q = 0; q < 3; q++) cen[ng][q] = (p[0][q] + p[1][q] + p[2][q]) / 3.f;
        float mx = 0.f;
        for (int k = 0; k < 3; k++) {
            const float dx = p[k][0] - cen[ng][0], dy = p[k][1] - cen[ng][1], dz = p[k][2] - cen[ng][2];
            const float d = sqrtf(dx * dx + dy * dy + dz * dz); if (d > mx) mx = d;
        }
        ext[ng] = mx; ng++;
    }
    for (int i = 0; i < ng; i++)
        for (int j = i + 1; j < ng; j++) {
            const float dx = cen[i][0] - cen[j][0], dy = cen[i][1] - cen[j][1], dz = cen[i][2] - cen[j][2];
            const float lim = ext[i] + ext[j] + 30.f;
            if (dx * dx + dy * dy + dz * dz < lim * lim) { const int a = tl_find(par, i), b = tl_find(par, j); if (a != b) par[b] = a; }
        }
    /* по группе: площадь, центр, разброс вершин -> оси (степенной метод по матрице разброса) */
    static float gA[TLN], gC[TLN][3]; static int gRoot[TLN];
    int nr = 0;
    for (int i = 0; i < ng; i++) if (tl_find(par, i) == i) { gRoot[nr] = i; gA[nr] = 0.f; gC[nr][0] = gC[nr][1] = gC[nr][2] = 0.f; nr++; }
    for (int i = 0; i < ng; i++) {
        const int r = tl_find(par, i); int k = 0; while (k < nr && gRoot[k] != r) k++;
        gA[k] += ar[i]; for (int q = 0; q < 3; q++) gC[k][q] += cen[i][q] * ar[i];
    }
    /* самые крупные — первыми */
    int ord[TLN]; for (int k = 0; k < nr; k++) ord[k] = k;
    for (int a = 0; a < nr; a++) for (int b = a + 1; b < nr; b++) if (gA[ord[b]] > gA[ord[a]]) { const int tt = ord[a]; ord[a] = ord[b]; ord[b] = tt; }
    const int ir = dcvk_post_par_find("glow_light_rad");
    const float lrad = ir >= 0 ? dcvk_post_par(ir) : 2200.f;
    int n = 0;
    for (int oi = 0; oi < nr && n < GLAMP_MAX; oi++) {
        const int k = ord[oi];
        if (gA[k] < 1.f) continue;
        float c[3] = { gC[k][0] / gA[k], gC[k][1] / gA[k], gC[k][2] / gA[k] };
        double S[9] = { 0 };
        for (int i = 0; i < ng; i++) {
            if (tl_find(par, i) != gRoot[k]) continue;
            const int16_t *m = &s_rrm_v[ti[i] * 9];
            for (int v = 0; v < 3; v++) {
                const double d[3] = { m[v * 3] - c[0], m[v * 3 + 1] - c[1], m[v * 3 + 2] - c[2] };
                for (int r = 0; r < 3; r++) for (int q = 0; q < 3; q++) S[r * 3 + q] += d[r] * d[q] * ar[i];
            }
        }
        double e1[3] = { 1.0, 0.31, 0.17 }, e2[3] = { 0.13, 1.0, 0.29 };
        for (int it = 0; it < 32; it++) {                 /* длинная ось */
            double w[3] = { S[0]*e1[0] + S[1]*e1[1] + S[2]*e1[2], S[3]*e1[0] + S[4]*e1[1] + S[5]*e1[2], S[6]*e1[0] + S[7]*e1[1] + S[8]*e1[2] };
            const double l = sqrt(w[0]*w[0] + w[1]*w[1] + w[2]*w[2]); if (l < 1e-12) break;
            e1[0] = w[0] / l; e1[1] = w[1] / l; e1[2] = w[2] / l;
        }
        for (int it = 0; it < 32; it++) {                 /* вторая ось — поперёк первой */
            double w[3] = { S[0]*e2[0] + S[1]*e2[1] + S[2]*e2[2], S[3]*e2[0] + S[4]*e2[1] + S[5]*e2[2], S[6]*e2[0] + S[7]*e2[1] + S[8]*e2[2] };
            const double dd = w[0]*e1[0] + w[1]*e1[1] + w[2]*e1[2];
            w[0] -= dd * e1[0]; w[1] -= dd * e1[1]; w[2] -= dd * e1[2];
            const double l = sqrt(w[0]*w[0] + w[1]*w[1] + w[2]*w[2]); if (l < 1e-12) break;
            e2[0] = w[0] / l; e2[1] = w[1] / l; e2[2] = w[2] / l;
        }
        float ha = 0.f, hb = 0.f;                          /* полудлины — по крайним вершинам */
        for (int i = 0; i < ng; i++) {
            if (tl_find(par, i) != gRoot[k]) continue;
            const int16_t *m = &s_rrm_v[ti[i] * 9];
            for (int v = 0; v < 3; v++) {
                const double d[3] = { m[v * 3] - c[0], m[v * 3 + 1] - c[1], m[v * 3 + 2] - c[2] };
                const float pa = (float)fabs(d[0]*e1[0] + d[1]*e1[1] + d[2]*e1[2]), pb = (float)fabs(d[0]*e2[0] + d[1]*e2[1] + d[2]*e2[2]);
                if (pa > ha) ha = pa; if (pb > hb) hb = pb;
            }
        }
        float sz = sqrtf(gA[k]) / 300.f; if (sz < 0.6f) sz = 0.6f; if (sz > 1.6f) sz = 1.6f;
        GameLamp *L = &s_tlamp[n];
        memset(L, 0, sizeof *L);
        for (int q = 0; q < 3; q++) { L->p[q] = c[q]; L->col[q] = 128.f * sz; s_tl_A[n][q] = (float)e1[q] * ha; s_tl_B[n][q] = (float)e2[q] * hb; }
        L->rad = lrad * sz; L->on = 1; L->set = 1; L->s14 = 0.f;
        s_tl_area[n] = gA[k];
        n++;
    }
    s_tlamp_n = n;
    fprintf(stderr, "texlamp: %d texture lamps (%d 'glows' triangles, of them semi-transparent - not lamps: %d; codes:", n, nmark, nsemi);
    for (int c = 0; c < 256; c++) if (codes[c >> 5] & (1u << (c & 31))) fprintf(stderr, " %02X", c);
    fprintf(stderr, ") - shadows from them%s%c", tlamp_on() ? "" : " (off: DC_SHADOW_TEXLAMPS=0)", 10);
    for (int i = 0; i < n && i < 12; i++) {
        const float a = sqrtf(s_tl_A[i][0]*s_tl_A[i][0] + s_tl_A[i][1]*s_tl_A[i][1] + s_tl_A[i][2]*s_tl_A[i][2]);
        const float b = sqrtf(s_tl_B[i][0]*s_tl_B[i][0] + s_tl_B[i][1]*s_tl_B[i][1] + s_tl_B[i][2]*s_tl_B[i][2]);
        fprintf(stderr, "  T%02d center %.0f,%.0f,%.0f area %.0f shape %.0f x %.0f radius %.0f%c", i,
                s_tlamp[i].p[0], s_tlamp[i].p[1], s_tlamp[i].p[2], s_tl_area[i], 2.f * a, 2.f * b, s_tlamp[i].rad, 10);
    }
}

/* ===== СВЕТИЛЬНИКИ ДЛЯ СВЕТА ОТ СВЕТЯЩИХСЯ ТЕКСТУР (27.10.2026) ===========================================================
 * Игрок (слот 1): «свечение от ламп нужно сделать, чтобы оно все-таки было привязано к их источникам ... это свечение, оно
 * остается на месте, а там уже этой лампы, так сказать, нету источника. То есть такие вот, как это, остаточный след
 * остается». Свет (gpu_vk_raster.cpp «СВЕТ ОТ СВЕТЯЩИХСЯ ТЕКСТУР») собирал ВИДИМЫЕ треугольники «светится» в группы: ближе
 * 800 ед. к центру первой подходящей. Состав групп зависел от того, что видно, и в каком порядке: в ST107 (потолочное кольцо
 * ламп) при простом повороте камеры центры групп уезжали на 1000-1700 ед., а прежний след держался секунду там, где лампы
 * нет. Теперь светильники - из меша комнаты (как лампы-текстуры для теней): связные треугольники «светится»; шире 1600 ед. -
 * на равные плитки по своей рамке. У светильника неподвижный центр по площади, площадь и рамка в координатах комнаты; растр
 * относит к нему видимый треугольник по рамке, и точка света стоит на светильнике, что бы ни было видно.
 * DC_GLOW_LIGHT_FIX=0 - группы видимого, как было. */
/* GLF_MAX, GLF_TILE - выше, у отметок обхода (glfix_drawn) */
static float    s_glf_c[GLF_MAX][4];        /* центр (комната) и площадь */
static float    s_glf_b[GLF_MAX][6];        /* рамка вершин: min xyz, max xyz */
static unsigned s_glf_key[GLF_MAX];         /* по центру (сетка 32 ед.): тот же светильник после пересборки - тот же ключ */
static int      s_glf_n = 0;
/* 28.10: треугольники светильников - треугольник меша, его светильник, площадь (растр берёт по ним цвет и размер лампы) */
static int      s_glf_tt[GLF_TRI];
static int16_t  s_glf_tf[GLF_TRI];
static float    s_glf_ta[GLF_TRI];
static int      s_glf_tn = 0;
static unsigned s_glf_gen = 0;              /* растёт с каждой пересборкой светильников */
static int glroom_on(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("DC_GLOW_LIGHT_ROOM"); v = (e && *e == '0') ? 0 : 1; }
    return v;
}
static void glfix_clear(void) { s_glf_n = 0; s_glf_tn = 0; s_glh_sig = 0; s_glf_gen++; }
static void glfix_refresh(void) {
    extern int dc_tex_class(uint16_t tpage, uint16_t clut_x, uint16_t clut_y, const int *u, const int *v, int n);
    extern unsigned dc_tex_class_gen(void);
    static uint32_t sig = 0; static unsigned gen = 0; static long tick = 0;
    static uint8_t *mark = NULL; static int mcap = 0, nmark = 0, grouped = -1;
    if (rrm_refresh() <= 0 || !s_rrm_v || !s_rrm_uv) { if (s_glf_n || s_glh_sig) glfix_clear(); sig = 0; return; }
    const unsigned g = dc_tex_class_gen();
    int fresh = 0;
    if (sig != s_rrm_sig || gen != g || mcap < s_rrm_n) {
        if (mcap < s_rrm_n) {
            free(mark); mcap = s_rrm_n + 1024; mark = (uint8_t *)calloc((size_t)mcap, 1);
            if (!mark) { mcap = 0; glfix_clear(); return; }
        } else memset(mark, 0, (size_t)mcap);
        sig = s_rrm_sig; gen = g; nmark = 0; grouped = -1; fresh = 1;
    }
    if (!fresh && (++tick % 60) != 0) return;                        /* досбор - раз в ~секунду (экраны анимированы) */
    for (int t = 0; t < s_rrm_n; t++) {
        if (mark[t]) continue;
        const int16_t *uv = &s_rrm_uv[t * 6];
        const int u[3] = { uv[0], uv[2], uv[4] }, v[3] = { uv[1], uv[3], uv[5] };
        if (dc_tex_class(s_rrm_tp[t], s_rrm_cx[t], s_rrm_cy[t], u, v, 3) & 4) { mark[t] = 1; nmark++; }
    }
    if (grouped == nmark) return;                                    /* набор тот же - светильники те же */
    grouped = nmark;
    /* связность - как у ламп-текстур: центры ближе суммы размахов + 30 ед. */
    enum { GFN = 2048 };
    static int ti[GFN], par[GFN], lab[GFN]; static float cen[GFN][3], ar[GFN], ext[GFN];
    int ng = 0;
    for (int t = 0; t < s_rrm_n && ng < GFN; t++) {
        if (!mark[t]) continue;
        const int16_t *m = &s_rrm_v[t * 9];
        float p[3][3];
        for (int k = 0; k < 3; k++) for (int q = 0; q < 3; q++) p[k][q] = (float)m[k * 3 + q];
        const float e1[3] = { p[1][0] - p[0][0], p[1][1] - p[0][1], p[1][2] - p[0][2] };
        const float e2[3] = { p[2][0] - p[0][0], p[2][1] - p[0][1], p[2][2] - p[0][2] };
        const float cx = e1[1] * e2[2] - e1[2] * e2[1], cy = e1[2] * e2[0] - e1[0] * e2[2], cz = e1[0] * e2[1] - e1[1] * e2[0];
        const float a = 0.5f * sqrtf(cx * cx + cy * cy + cz * cz);
        if (a < 0.5f) continue;
        ti[ng] = t; par[ng] = ng; ar[ng] = a;
        for (int q = 0; q < 3; q++) cen[ng][q] = (p[0][q] + p[1][q] + p[2][q]) / 3.f;
        float mx = 0.f;
        for (int k = 0; k < 3; k++) {
            const float dx = p[k][0] - cen[ng][0], dy = p[k][1] - cen[ng][1], dz = p[k][2] - cen[ng][2];
            const float d = sqrtf(dx * dx + dy * dy + dz * dz); if (d > mx) mx = d;
        }
        ext[ng] = mx; ng++;
    }
    for (int i = 0; i < ng; i++)
        for (int j = i + 1; j < ng; j++) {
            const float dx = cen[i][0] - cen[j][0], dy = cen[i][1] - cen[j][1], dz = cen[i][2] - cen[j][2];
            const float lim = ext[i] + ext[j] + 30.f;
            if (dx * dx + dy * dy + dz * dz < lim * lim) { const int a = tl_find(par, i), b = tl_find(par, j); if (a != b) par[b] = a; }
        }
    /* рамка каждой связной группы; шире GLF_TILE по оси - равные плитки по этой оси (до 8), треугольник - в плитку по центру */
    static float rb[GFN][6];
    for (int i = 0; i < ng; i++) if (tl_find(par, i) == i) { for (int q = 0; q < 3; q++) { rb[i][q] = 1e30f; rb[i][3 + q] = -1e30f; } }
    for (int i = 0; i < ng; i++) {
        const int r = tl_find(par, i);
        const int16_t *m = &s_rrm_v[ti[i] * 9];
        for (int k = 0; k < 3; k++) for (int q = 0; q < 3; q++) {
            const float x = (float)m[k * 3 + q];
            if (x < rb[r][q]) rb[r][q] = x;
            if (x > rb[r][3 + q]) rb[r][3 + q] = x;
        }
    }
    for (int i = 0; i < ng; i++) {
        const int r = tl_find(par, i);
        int ix[3];
        for (int q = 0; q < 3; q++) {
            const float e = rb[r][3 + q] - rb[r][q];
            int nt = (int)ceilf(e / (float)GLF_TILE); if (nt < 1) nt = 1; if (nt > 8) nt = 8;
            int k = (int)((cen[i][q] - rb[r][q]) / (e > 1e-3f ? e : 1.f) * (float)nt);
            if (k < 0) k = 0; if (k > nt - 1) k = nt - 1;
            ix[q] = k;
        }
        lab[i] = (r << 9) | (ix[0] << 6) | (ix[1] << 3) | ix[2];
    }
    /* светильники: площадь, центр по площади, рамка вершин */
    static int fl[GFN], gfi[GFN], f2n[GFN]; static float fa[GFN], fc[GFN][3], fb[GFN][6];
    int nf = 0;
    for (int i = 0; i < ng; i++) {
        int f = 0; while (f < nf && fl[f] != lab[i]) f++;
        if (f == nf) { fl[nf] = lab[i]; fa[nf] = 0.f; for (int q = 0; q < 3; q++) { fc[nf][q] = 0.f; fb[nf][q] = 1e30f; fb[nf][3 + q] = -1e30f; } nf++; }
        gfi[i] = f;
        fa[f] += ar[i];
        for (int q = 0; q < 3; q++) fc[f][q] += cen[i][q] * ar[i];
        const int16_t *m = &s_rrm_v[ti[i] * 9];
        for (int k = 0; k < 3; k++) for (int q = 0; q < 3; q++) {
            const float x = (float)m[k * 3 + q];
            if (x < fb[f][q]) fb[f][q] = x;
            if (x > fb[f][3 + q]) fb[f][3 + q] = x;
        }
    }
    /* больше GLF_MAX - самые крупные */
    int ord[GFN]; for (int f = 0; f < nf; f++) ord[f] = f;
    for (int a = 1; a < nf; a++) { const int k = ord[a]; int b = a - 1; while (b >= 0 && fa[ord[b]] < fa[k]) { ord[b + 1] = ord[b]; b--; } ord[b + 1] = k; }
    for (int f = 0; f < nf; f++) f2n[f] = -1;
    int n = 0;
    for (int oi = 0; oi < nf && n < GLF_MAX; oi++) {
        const int f = ord[oi];
        if (fa[f] < 1.f) continue;
        for (int q = 0; q < 3; q++) s_glf_c[n][q] = fc[f][q] / fa[f];
        s_glf_c[n][3] = fa[f];
        for (int q = 0; q < 6; q++) s_glf_b[n][q] = fb[f][q];
        const int qx = (int)floorf(s_glf_c[n][0] / 32.f), qy = (int)floorf(s_glf_c[n][1] / 32.f), qz = (int)floorf(s_glf_c[n][2] / 32.f);
        s_glf_key[n] = (((unsigned)qx * 73856093u) ^ ((unsigned)qy * 19349663u) ^ ((unsigned)qz * 83492791u)) | 1u;
        f2n[f] = n;
        n++;
    }
    s_glf_n = n;
    /* 28.10: треугольники светильников и таблица «адрес записи -> треугольник меша» для отметок обхода; отметки - по
     * треугольникам меша, пересборка светильников того же меша их не теряет */
    s_glf_tn = 0; s_glh_sig = 0; s_glf_gen++;
    memset(s_glh_rec, 0, sizeof s_glh_rec);
    if (glroom_on() && !s_rrm_tws) s_rrm_tws = (long *)calloc((size_t)RRM_MAX, sizeof(long));
    { static uint32_t tws_sig = 0;
      if (s_rrm_tws && tws_sig != s_rrm_sig) { memset(s_rrm_tws, 0, sizeof(long) * RRM_MAX); tws_sig = s_rrm_sig; } }
    for (int i = 0; i < ng && s_glf_tn < GLF_TRI; i++) {
        const int fo = f2n[gfi[i]];
        if (fo < 0) continue;
        const int t = ti[i];
        s_glf_tt[s_glf_tn] = t; s_glf_tf[s_glf_tn] = (int16_t)fo; s_glf_ta[s_glf_tn] = ar[i]; s_glf_tn++;
        const uint32_t r = s_rrm_rec ? s_rrm_rec[t] : 0u;
        if (!r) continue;
        unsigned h = glh_slot(r);
        for (int k = 0; k < GLH_N; k++, h = (h + 1) & (GLH_N - 1)) {
            if (!s_glh_rec[h]) { s_glh_rec[h] = r; s_glh_t[h] = t; break; }
            if (s_glh_rec[h] == r) break;                      /* вторая половина того же четырёхугольника */
        }
    }
    if (s_glf_tn > 0 && s_rrm_tws && glroom_on()) s_glh_sig = s_rrm_sig;
    int nroot = 0; for (int i = 0; i < ng; i++) nroot += tl_find(par, i) == i;
    fprintf(stderr, "glowfix: %d light fixtures from %d 'glows' triangles of the room mesh (%d connected groups); %d triangles %s%c",
            n, nmark, nroot, s_glf_tn, s_glh_sig ? "watched on the walk (DC_GLOW_LIGHT_ROOM)" : "not watched", 10);
    for (int i = 0; i < n && i < 24; i++)
        fprintf(stderr, "  F%02d center %.0f,%.0f,%.0f area %.0f box %.0f..%.0f x %.0f..%.0f x %.0f..%.0f%c", i,
                s_glf_c[i][0], s_glf_c[i][1], s_glf_c[i][2], s_glf_c[i][3], s_glf_b[i][0], s_glf_b[i][3],
                s_glf_b[i][1], s_glf_b[i][4], s_glf_b[i][2], s_glf_b[i][5], 10);
}
/* для растра (gpu_vk_raster.cpp gl_lights_build, кадр A - тот же поток, что и разбор комнаты): светильники комнаты;
 * 0 - их нет или правило выключено */
int dc_glow_fixtures(const float **cen4, const float **box6, const unsigned **key) {
    static int en = -1;
    if (en < 0) { const char *e = getenv("DC_GLOW_LIGHT_FIX"); en = (e && *e == '0') ? 0 : 1;
        fprintf(stderr, "glowfix: light of 'glows' textures - %s (DC_GLOW_LIGHT_FIX)%c",
                en ? "at the room's fixed light fixtures, held only for blinking lamps" : "groups of what is visible (as before)", 10); }
    if (!en || !dc_room_live_on()) return 0;
    glfix_refresh();
    *cen4 = &s_glf_c[0][0]; *box6 = &s_glf_b[0][0]; *key = s_glf_key;
    return s_glf_n;
}
/* 28.10: для растра (после dc_glow_fixtures того же кадра): что из светильников нарисовал обход в одном из 3 последних обходов
 * растра, рисовавших комнату (в кадре это или нет): pres[f] - светильник f, td[i] - i-й треугольник светильников (как у
 * dc_glow_fixture_tri); *walk_seq - счёт таких обходов (стоит - комнату рисует игра: судить по потоку); *gen - номер сборки
 * светильников (сменился - цвет и площадь по мешу заново). Возврат - число светильников, 0 - правило выключено или таблицы нет */
int dc_glow_fixture_present(unsigned char *pres, int cap, unsigned char *td, int tcap, long *walk_seq, unsigned *gen) {
    *walk_seq = s_glf_dseq;
    *gen = s_glf_gen;
    if (!s_glh_sig || s_glh_sig != s_rrm_sig || !s_rrm_tws) return 0;
    const int n = s_glf_n < cap ? s_glf_n : cap;
    for (int f = 0; f < n; f++) pres[f] = 0;
    for (int i = 0; i < s_glf_tn; i++) {
        const long w = s_rrm_tws[s_glf_tt[i]];
        const int d = w != 0 && w + 2 >= s_glf_dseq;
        if (i < tcap) td[i] = (unsigned char)d;
        if (d && s_glf_tf[i] < n) pres[s_glf_tf[i]] = 1;
    }
    return n;
}
/* 28.10: i-й треугольник светильников (цвет текстуры и площадь лампы по мешу комнаты): светильник, страница (9 бит, как у
 * потока), CLUT (точка видеопамяти), UV, цвета вершин, код команды GPU (бит 1 - полупрозрачный, бит 0 - без смешения с цветом),
 * площадь, вершины в координатах комнаты, *two - обход не режет его изнанку (полупрозрачный или с прозрачными текселями:
 * окно UV - по обеим половинам четырёхугольника, как у обхода); 0 - больше нет */
int dc_glow_fixture_tri(int i, int *fix, int *tp, int *cx, int *cy, int uv[6], int rgb[9], int *code, float *area, float v9[9], int *two) {
    if (i < 0 || i >= s_glf_tn || !s_rrm_uv || !s_rrm_rgb || !s_rrm_v) return 0;
    const int t = s_glf_tt[i];
    if (t >= s_rrm_n) return 0;
    *fix = s_glf_tf[i]; *tp = s_rrm_tp[t] & 0x1FF; *cx = s_rrm_cx[t]; *cy = s_rrm_cy[t];
    for (int k = 0; k < 6; k++) uv[k] = s_rrm_uv[t * 6 + k];
    for (int k = 0; k < 9; k++) { rgb[k] = s_rrm_rgb[t * 9 + k]; v9[k] = (float)s_rrm_v[t * 9 + k]; }
    *code = s_rrm_code ? s_rrm_code[t] : 0;
    *area = s_glf_ta[i];
    *two = (*code & 2) != 0;
    if (!*two) {
        int u[6], v[6], n = 0;
        for (int k = 0; k < 3; k++) { u[n] = s_rrm_uv[t * 6 + k * 2]; v[n] = s_rrm_uv[t * 6 + k * 2 + 1]; n++; }
        const uint32_t r = s_rrm_rec ? s_rrm_rec[t] : 0u;
        const int o = (r && t + 1 < s_rrm_n && s_rrm_rec[t + 1] == r) ? t + 1 : (r && t > 0 && s_rrm_rec[t - 1] == r) ? t - 1 : -1;
        if (o >= 0) for (int k = 0; k < 3; k++) { u[n] = s_rrm_uv[o * 6 + k * 2]; v[n] = s_rrm_uv[o * 6 + k * 2 + 1]; n++; }
        *two = dc_tex_has_alpha_pub(s_rrm_tp[t], (uint16_t)(((unsigned)s_rrm_cx[t] / 16u) | ((unsigned)s_rrm_cy[t] << 6)), u, v, n);
    }
    return 1;
}

/* 27.09: слои карты теней этого кадра — габарит группы ламп (координаты комнаты) на слой; по нему объёмный свет
 * (dc_vol_frame) узнаёт, у какой лампы есть тень персонажей для дымки */
static float s_shcl_min[4][3], s_shcl_max[4][3];
static int   s_shcl_n = 0;
/* 27.09 (2): сила света лампы (для доли света в новом пути теней): яркость цвета × сила вектора света игры (+14) */
static float shadow_lamp_pow(const GameLamp *L) {
    float br = L->col[0]; if (L->col[1] > br) br = L->col[1]; if (L->col[2] > br) br = L->col[2];
    return (br / 128.f) * (L->s14 > 0.f ? L->s14 / 4096.f : 1.f);
}
/* точка комнаты -> видовое пространство кадра: вид = D·(R·p + TR) + T */
static void sh_room2view(const float R[9], const float TR[3], const float D[9], const float T[3], const float p[3], float out[3]) {
    const float vx = R[0]*p[0] + R[1]*p[1] + R[2]*p[2] + TR[0];
    const float vy = R[3]*p[0] + R[4]*p[1] + R[5]*p[2] + TR[1];
    const float vz = R[6]*p[0] + R[7]*p[1] + R[8]*p[2] + TR[2];
    out[0] = D[0]*vx + D[1]*vy + D[2]*vz + T[0];
    out[1] = D[3]*vx + D[4]*vy + D[5]*vz + T[1];
    out[2] = D[6]*vx + D[7]*vy + D[8]*vz + T[2];
}
/* оси плоскости карты лампы (как в shadow_build_vp): r — по x карты, u — по y */
static void shadow_map_basis(const float L[3], const float aim[3], float rr[3], float uu[3]) {
    float f[3] = { aim[0]-L[0], aim[1]-L[1], aim[2]-L[2] };
    float fl = sqrtf(f[0]*f[0] + f[1]*f[1] + f[2]*f[2]);
    if (fl < 1e-3f) { f[0] = 0.f; f[1] = 1.f; f[2] = 0.f; fl = 1.f; }
    f[0] /= fl; f[1] /= fl; f[2] /= fl;
    float up[3] = { 0.f, 0.f, 1.f };
    if (fabsf(f[2]) > 0.9f) { up[0] = 0.f; up[1] = 1.f; up[2] = 0.f; }
    rr[0] = up[1]*f[2] - up[2]*f[1]; rr[1] = up[2]*f[0] - up[0]*f[2]; rr[2] = up[0]*f[1] - up[1]*f[0];
    float rl = sqrtf(rr[0]*rr[0] + rr[1]*rr[1] + rr[2]*rr[2]); if (rl < 1e-4f) rl = 1.f;
    rr[0] /= rl; rr[1] /= rl; rr[2] /= rl;
    uu[0] = f[1]*rr[2] - f[2]*rr[1]; uu[1] = f[2]*rr[0] - f[0]*rr[2]; uu[2] = f[0]*rr[1] - f[1]*rr[0];
}
/* 27.09 (2): БОЛЬШАЯ ЛАМПА-ТЕКСТУРА (светящийся потолок, панель в полстены: в ST107 — 7800 x 6000 ед.) светит на персонажа
 * ПЯТНОМ над ним: ближайшая к точке at часть лампы (в её плоскости), полуоси пятна — не больше pmax. Из середины такой лампы
 * тень летела вкось за тысячи единиц и размазывалась по всей её ширине до невидимости; под светящимся потолком она падает
 * вниз и мягкая по размеру пятна. 1 — лампа больше пятна (P, A, B — пятно), 0 — лампа как есть. */
static int tlamp_patch(int hd, const float at[3], float pmax, float P[3], float A[3], float B[3]) {
    if (hd < 0 || hd >= s_tlamp_n || pmax <= 0.f) return 0;
    const float *c = s_tlamp[hd].p, *LA = s_tl_A[hd], *LB = s_tl_B[hd];
    const float ha = sqrtf(LA[0]*LA[0] + LA[1]*LA[1] + LA[2]*LA[2]), hb = sqrtf(LB[0]*LB[0] + LB[1]*LB[1] + LB[2]*LB[2]);
    if (ha <= pmax && hb <= pmax) return 0;
    float e1[3] = { 0.f, 0.f, 0.f }, e2[3] = { 0.f, 0.f, 0.f };
    for (int q = 0; q < 3; q++) { if (ha > 1e-3f) e1[q] = LA[q] / ha; if (hb > 1e-3f) e2[q] = LB[q] / hb; }
    const float pa = ha < pmax ? ha : pmax, pb = hb < pmax ? hb : pmax;
    const float d[3] = { at[0] - c[0], at[1] - c[1], at[2] - c[2] };
    float s = d[0]*e1[0] + d[1]*e1[1] + d[2]*e1[2], t = d[0]*e2[0] + d[1]*e2[1] + d[2]*e2[2];
    if (s > ha - pa) s = ha - pa; if (s < -(ha - pa)) s = -(ha - pa);
    if (t > hb - pb) t = hb - pb; if (t < -(hb - pb)) t = -(hb - pb);
    for (int q = 0; q < 3; q++) { P[q] = c[q] + e1[q] * s + e2[q] * t; A[q] = e1[q] * pa; B[q] = e2[q] * pb; }
    return 1;
}
/* ===== СТАБИЛЬНЫЕ ТЕНИ (23.10.2026) ===== Игрок, слот 1 (ST10D, Гейл у сетки): «смотришь на Гейла, на тень под ним, и
 * идёшь Региной вперёд и назад - видно, что тень меняется. Сделай, чтобы тени были стабильны на всей комнате и видны из самого
 * дальнего угла, а не рандомно пропадают и меняются». Лампы теней и их слои зависели от того, где стоит Регина: (1) СЛИЯНИЕ шло
 * по углу из её точки (tgt), центр группы - по весам от расстояний до персонажей: место слоя лампы Гейла ходило 565,-3301,-384
 * -> 2097,-3159,-1240 -> 2431,-3191,-1367 (к T02 подмешивались T01 и T00), сила 1.6 -> 5.9 -> 4.8; (2) три слоя доставались
 * трём сильнейшим лампам у кого угодно - лампы у Регины вытесняли лампу Гейла, и его тень гасла. Теперь (stable): группы - по
 * месту самих ламп на всю комнату (лампа ближе merge_d к сильнейшей - в её группе, центр - по их силе), слои - сначала главной
 * лампе каждого персонажа (Регине первой), затем вторым (у других персонажей раньше, чем у Регины: её тень и так меняется на
 * ходу, а тень стоящего не должна), доля света - в том же порядке; пятно большой лампы-текстуры - над тем персонажем, ради
 * кого взят слой. DC_SHADOW_STABLE=0 - как было. */
typedef struct { int nl, n, head[GLAMP_MAX], grp[GLAMP_MAX], nm[GLAMP_MAX];
                 float c[GLAMP_MAX][3], mn[GLAMP_MAX][3], mx[GLAMP_MAX][3], rad[GLAMP_MAX], pow[GLAMP_MAX]; } ShStGroups;
static void sh_static_groups(const GameLamp *LMP, int n, float md, ShStGroups *G) {
    if (n > GLAMP_MAX) n = GLAMP_MAX;
    if (n < 0) n = 0;
    int ord[GLAMP_MAX]; float pw[GLAMP_MAX], sw[GLAMP_MAX];
    for (int i = 0; i < n; i++) { ord[i] = i; pw[i] = shadow_lamp_pow(&LMP[i]); }
    for (int a = 0; a < n - 1; a++)                                   /* сильнейшие - головы групп */
        for (int b = a + 1; b < n; b++)
            if (pw[ord[b]] > pw[ord[a]] || (pw[ord[b]] == pw[ord[a]] && ord[b] < ord[a])) { const int t = ord[a]; ord[a] = ord[b]; ord[b] = t; }
    G->nl = n; G->n = 0;
    for (int q = 0; q < n; q++) {
        const int i = ord[q]; const GameLamp *L = &LMP[i];
        int g = -1;
        if (md > 0.f)
            for (int k = 0; k < G->n; k++) {
                const float *H = LMP[G->head[k]].p;
                const float dx = L->p[0] - H[0], dy = L->p[1] - H[1], dz = L->p[2] - H[2];
                if (dx*dx + dy*dy + dz*dz <= md * md) { g = k; break; }
            }
        if (g < 0) {
            g = G->n++;
            G->head[g] = i; G->nm[g] = 0; G->pow[g] = 0.f; G->rad[g] = 0.f; sw[g] = 0.f;
            for (int k = 0; k < 3; k++) { G->c[g][k] = 0.f; G->mn[g][k] = G->mx[g][k] = L->p[k]; }
        }
        G->grp[i] = g; G->nm[g]++;
        const float w = pw[i] > 1e-4f ? pw[i] : 1e-4f;
        for (int k = 0; k < 3; k++) {
            G->c[g][k] += L->p[k] * w;
            if (L->p[k] < G->mn[g][k]) G->mn[g][k] = L->p[k];
            if (L->p[k] > G->mx[g][k]) G->mx[g][k] = L->p[k];
        }
        sw[g] += w;
        if (L->on) G->pow[g] += pw[i];
        const float r = L->rad > 0.f ? L->rad : 3000.f;
        if (r > G->rad[g]) G->rad[g] = r;
    }
    for (int g = 0; g < G->n; g++) for (int k = 0; k < 3; k++) G->c[g][k] /= sw[g];
}
/* очередь групп кадра (stable): у каждого персонажа его группы по весу (у группы со слоем - запас x1.3), место r в этом ряду
 * даёт ключ 2r + t: t = 0 для главной лампы Регины и для вторых и дальше у других персонажей, t = 1 - наоборот; ключ группы -
 * наименьший по персонажам (меньше - раньше) */
static void sh_stable_keys(int nc, int nch, float cwc[12][GLAMP_MAX], const int *lk, int nlay, int scene, int *key) {
    float hw[GLAMP_MAX];
    for (int k = 0; k < nc; k++) { hw[k] = 1.f; for (int L = 0; L < nlay; L++) if (lk && lk[L] == k) { hw[k] = 1.3f; break; } }
    for (int c = 0; c < nch && c < 12; c++) {
        int ord[GLAMP_MAX], no = 0;
        for (int k = 0; k < nc; k++) if (cwc[c][k] > 0.f) ord[no++] = k;
        for (int a = 0; a < no - 1; a++)
            for (int b = a + 1; b < no; b++)
                if (cwc[c][ord[b]] * hw[ord[b]] > cwc[c][ord[a]] * hw[ord[a]]) { const int t = ord[a]; ord[a] = ord[b]; ord[b] = t; }
        const int reg = (c == 0 && !scene);
        for (int r = 0; r < no; r++) {
            const int kk = r * 2 + ((r == 0) ? (reg ? 0 : 1) : (reg ? 1 : 0));
            if (kk < key[ord[r]]) key[ord[r]] = kk;
        }
    }
}
/* карта лампы (stable) - строго вниз, на весь круг, докуда видна её тень (радиус x fade), на уровне ног персонажей под ней:
 * от того, где Регина, не зависит. Прежняя карта целилась в персонажей и концы их теней, и её ось ходила за Региной (у лампы
 * Гейла T06 -0.02,0.65,0.76 -> 0.63,0.67,0.39 за пару шагов): Гейл съезжал к краю карты, где тень гаснет, и тексели его тени
 * менялись. Высота - до самых низких ног в этом круге, ступенями по 250 (на ровном полу не меняется) */
static void sh_down_frustum(const float L[3], float rad, float fade, float tan_min, const float *cx, const float *cy, const float *cz,
                            int nch, float aim[3], float *znear, float *zfar, float *th) {
    const float R = rad * fade;
    float h = 0.f;
    for (int c = 0; c < nch; c++) {
        const float dx = cx[c] - L[0], dz = cz[c] - L[2];
        if (dx*dx + dz*dz > R * R) continue;
        const float d = cy[c] - L[1];                          /* ноги ниже лампы (Y вниз) */
        if (d > h) h = d;
    }
    if (h <= 0.f) h = 1200.f;
    h = ceilf(h / 250.f) * 250.f;
    if (h < 500.f) h = 500.f;
    float t = R / h;
    const float tmax = tanf(1.396f);                           /* не шире 160°, как прежняя */
    if (t < tan_min) t = tan_min;
    if (t > tmax) t = tmax;
    aim[0] = L[0]; aim[1] = L[1] + 1000.f; aim[2] = L[2];
    *znear = 60.f;
    *zfar = sqrtf(h * h * (1.f + t * t)) * 1.15f + 300.f;
    *th = t;
}
/* ===== КАРТА ЛАМПЫ ПО ТЕЛАМ (26.10) ===== Игрок: «тени бывают обрезаны, по какому принципу - не очень понятно ... в самом
 * начале (слот 8), у Гейла в первой сцене на движке». Тень лежит на луче лампа -> тело: если направление на часть тела вне
 * карты лампы, тень этой части срезана краем карты (на стене - прямой линией). Карта вниз (sh_down_frustum) вмещает углы только
 * до круга тени на полу: в слоте 8 лампа G08 ниже голов (верх тела над её плоскостью - тень на стене срезало на высоте лампы),
 * в первой сцене G01 на 250 выше головы Гейла и в 755 вбок (голова на 72° от низа, карта - до 62°). Теперь углы габаритов
 * заслонивших (s_ocl) у лампы (ближняя точка не дальше её радиуса x DC_SHADOW_FIT_REACH) проверяются по карте вниз:
 *   - влезают (не дальше 0.94 от середины, дальше край гаснет) - карта как была, бит в бит;
 *   - не влезают - карта конусом: наименьший охватывающий конус углов и кольца прежней карты (круг тени на полу; не влезло в
 *     80° - углов и дальних групп до радиуса тени, нет - только углов; нет и так - карта вниз), с запасом 5°. Конус держится,
 *     пока все в нём (тень стоящего не меняется от каждого шага Регины), назад вниз - когда влезут в неё с запасом (0.85) и
 *     продержатся так 0.5 с (габариты групп от кадра к кадру шумят).
 * ⛔ Пробовал сперва ту же карту вниз, шире ступенями x1.25 (ось стоит): в первой сцене нужное раскрытие ходило 4.9..6.1 около
 * предела 5.67, и карта металась между «шире вниз» и конусом каждые 10-20 кадров; конус с кольцом к тому же уже (4.8).
 * DC_SHADOW_FIT=0 - как до 26.10. Части тел вне кадра в s_ocl не попадают - для них карта прежняя. */
static int sh_fit_on(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("DC_SHADOW_FIT"); v = (e && *e == '0') ? 0 : 1; }
    return v;
}
static float sh_fit_reach(void) {
    static float v = -1.f;
    if (v < 0.f) { const char *e = getenv("DC_SHADOW_FIT_REACH"); v = (e && *e) ? (float)atof(e) : 1.f; if (!(v >= 0.f)) v = 1.f; }
    return v;
}
static int sh_fit_dbg(void) {
    static int v = -1;
    if (v < 0) { const char *e = getenv("DC_SHCAM_DBG"); v = (e && *e == '1') ? 1 : 0; }
    return v;
}
#define SH_FIT_NP   (OCC_CL * 8)
/* слой: s_fit_md 0 - карта вниз как была, 1 - конус (ось, раскрытие, предел угла от оси; с кольцом прежней карты или без, с
 * дальними группами или без); s_fit_t0 - с какого кадра тела влезают вниз с запасом (0 - не влезают) */
static int      s_fit_md[4], s_fit_ring[4], s_fit_far[4];
static float    s_fit_ax[4][3], s_fit_th[4], s_fit_lim[4];
static uint64_t s_fit_t0[4];
static long     s_fit_nl = 0;
static void sh_fit_reset(int L) { if (L >= 0 && L < 4) { s_fit_md[L] = 0; s_fit_t0[L] = 0; } }
/* углы габаритов групп заслонивших - направления от лампы: N - группы, чья ближняя к лампе точка не дальше reach, F - дальше, но
 * не дальше R (туда ещё доходит её тень). Всё тело группы - в выпуклой оболочке углов: что вмещает углы, вмещает и его. Углы
 * ближе 250 к лампе - мимо */
static void sh_fit_corners(const float L[3], float reach, float R, float N[][3], int *nn, float F[][3], int *nf, int *ng) {
    *nn = 0; *nf = 0; *ng = 0;
    for (int c = 0; c < s_ocl_cnt && c < OCC_CL; c++) {
        float dd = 0.f;
        for (int k = 0; k < 3; k++) {
            const float v = L[k] < s_ocl_lo[c][k] ? s_ocl_lo[c][k] - L[k] : (L[k] > s_ocl_hi[c][k] ? L[k] - s_ocl_hi[c][k] : 0.f);
            dd += v * v;
        }
        if (dd > R * R) continue;
        const int nearg = dd <= reach * reach;
        if (nearg) (*ng)++;
        for (int m = 0; m < 8; m++) {
            const float d[3] = { ((m & 1) ? s_ocl_hi[c][0] : s_ocl_lo[c][0]) - L[0], ((m & 2) ? s_ocl_hi[c][1] : s_ocl_lo[c][1]) - L[1],
                                 ((m & 4) ? s_ocl_hi[c][2] : s_ocl_lo[c][2]) - L[2] };
            const float dl = sqrtf(d[0]*d[0] + d[1]*d[1] + d[2]*d[2]);
            if (dl < 250.f) continue;
            float *o = nearg ? N[(*nn)++] : F[(*nf)++];
            o[0] = d[0] / dl; o[1] = d[1] / dl; o[2] = d[2] / dl;
        }
    }
}
/* какое раскрытие нужно карте вниз, чтобы направления P легли не дальше 0.94 от середины (x карты = -dx, y = dz, глубина = dy);
 * у плоскости лампы и выше - 1e9 */
static float sh_fit_tneed(const float P[][3], int n) {
    float t = 0.f;
    for (int i = 0; i < n; i++) {
        if (P[i][1] < 1e-3f) return 1e9f;
        const float ax = fabsf(P[i][0]), az = fabsf(P[i][2]);
        const float q = (ax > az ? ax : az) / (P[i][1] * 0.94f);
        if (q > t) t = q;
    }
    return t;
}
/* кольцо прежней карты вниз: 16 направлений на её раскрытии вокруг низа (круг тени на полу) */
static int sh_fit_ring_dirs(float tdn, float U[][3]) {
    const float a = atanf(tdn), sa = sinf(a), ca = cosf(a);
    for (int k = 0; k < 16; k++) {
        const float ph = (float)k * 0.39269908f;
        U[k][0] = sa * cosf(ph); U[k][1] = ca; U[k][2] = sa * sinf(ph);
    }
    return 16;
}
static int sh_fit_in(const float a[3], const float ax[3], float c) { return a[0]*ax[0] + a[1]*ax[1] + a[2]*ax[2] >= c - 1e-6f; }
/* наименьший конус на два и на три направления (ось ax, вернуть cos половины раскрытия) */
static float sh_fit_cap2(const float a[3], const float b[3], float ax[3]) {
    const float s[3] = { a[0] + b[0], a[1] + b[1], a[2] + b[2] };
    const float l = sqrtf(s[0]*s[0] + s[1]*s[1] + s[2]*s[2]);
    if (l < 1e-6f) { ax[0] = a[0]; ax[1] = a[1]; ax[2] = a[2]; return -1.f; }   /* противоположные - не вместить */
    ax[0] = s[0] / l; ax[1] = s[1] / l; ax[2] = s[2] / l;
    return a[0]*ax[0] + a[1]*ax[1] + a[2]*ax[2];
}
static float sh_fit_cap3(const float a[3], const float b[3], const float c[3], float ax[3]) {
    const float u[3] = { b[0] - a[0], b[1] - a[1], b[2] - a[2] }, v[3] = { c[0] - a[0], c[1] - a[1], c[2] - a[2] };
    float n[3] = { u[1]*v[2] - u[2]*v[1], u[2]*v[0] - u[0]*v[2], u[0]*v[1] - u[1]*v[0] };
    const float l = sqrtf(n[0]*n[0] + n[1]*n[1] + n[2]*n[2]);
    if (l < 1e-7f) {                                     /* два совпали - пара самых далёких */
        float t1[3], t2[3], t3[3];
        const float c1 = sh_fit_cap2(a, b, t1), c2 = sh_fit_cap2(a, c, t2), c3 = sh_fit_cap2(b, c, t3);
        const float *bt = t1; float bc = c1;
        if (c2 < bc) { bt = t2; bc = c2; }
        if (c3 < bc) { bt = t3; bc = c3; }
        ax[0] = bt[0]; ax[1] = bt[1]; ax[2] = bt[2];
        return bc;
    }
    n[0] /= l; n[1] /= l; n[2] /= l;
    float d = n[0]*a[0] + n[1]*a[1] + n[2]*a[2];
    if (d < 0.f) { n[0] = -n[0]; n[1] = -n[1]; n[2] = -n[2]; d = -d; }
    ax[0] = n[0]; ax[1] = n[1]; ax[2] = n[2];
    return d;                                            /* на большом круге - 0 (полусфера, не влезет) */
}
/* наименьший конус, вмещающий направления U (как наименьший круг на плоскости: тройной перебор, точки в одной полусфере);
 * вернуть точный cos половины раскрытия по всем */
static float sh_fit_cap(const float U[][3], int n, float ax[3]) {
    ax[0] = 0.f; ax[1] = 1.f; ax[2] = 0.f;
    if (n <= 0) return 1.f;
    ax[0] = U[0][0]; ax[1] = U[0][1]; ax[2] = U[0][2];
    float c = 1.f;
    for (int i = 1; i < n; i++) {
        if (sh_fit_in(U[i], ax, c)) continue;
        ax[0] = U[i][0]; ax[1] = U[i][1]; ax[2] = U[i][2]; c = 1.f;
        for (int j = 0; j < i; j++) {
            if (sh_fit_in(U[j], ax, c)) continue;
            c = sh_fit_cap2(U[i], U[j], ax);
            for (int k = 0; k < j; k++) {
                if (sh_fit_in(U[k], ax, c)) continue;
                c = sh_fit_cap3(U[i], U[j], U[k], ax);
            }
        }
    }
    float mc = 1.f;
    for (int i = 0; i < n; i++) { const float d = U[i][0]*ax[0] + U[i][1]*ax[1] + U[i][2]*ax[2]; if (d < mc) mc = d; }
    return mc;
}
/* карта слоя L (stable): sh_down_frustum, а если тела у лампы в неё не влезают - конусом на них (см. выше); axo - ось карты
 * (для строк журнала) */
static void sh_fit_frustum(int L, int hd, const float Lr[3], float rad, float fade, float tan_min,
                           const float *cx, const float *cy, const float *cz, int nch,
                           float aim[3], float *znear, float *zfar, float *th, float axo[3]) {
    sh_down_frustum(Lr, rad, fade, tan_min, cx, cy, cz, nch, aim, znear, zfar, th);
    axo[0] = 0.f; axo[1] = 1.f; axo[2] = 0.f;
    if (L < 0 || L >= 4) return;
    if (!sh_fit_on()) { s_fit_md[L] = 0; s_fit_t0[L] = 0; return; }
    extern uint64_t s_frame_count;
    const float R = rad * fade, tdn = *th, tmax = tanf(1.396f), hlim = atanf(0.94f * tmax), zf2 = R * 1.15f + 300.f;
    float N[SH_FIT_NP][3], F[SH_FIT_NP][3]; int nn = 0, nf = 0, ng = 0;
    const uint64_t age = s_frame_count - s_occ_frame;          /* группы старше 0.5 с (в кадр давно никто не попадал) - мимо */
    if (s_occ_frame != ~0ull && age < 30u) sh_fit_corners(Lr, rad * sh_fit_reach(), R, N, &nn, F, &nf, &ng);
    const float tn = sh_fit_tneed(N, nn);
    const int md0 = s_fit_md[L];
    if (md0 == 0) {
        if (tn <= tdn) return;                                 /* все в карте вниз - она и остаётся */
    } else {
        /* влезли вниз с запасом (0.85) и держатся так 0.5 с - назад вниз */
        if (tn * (0.94f / 0.85f) <= tdn) {
            if (!s_fit_t0[L]) s_fit_t0[L] = s_frame_count;
            if (s_frame_count - s_fit_t0[L] >= 30u) {
                s_fit_md[L] = 0; s_fit_t0[L] = 0;
                if (sh_fit_dbg() && s_fit_nl < 400) {
                    s_fit_nl++;
                    fprintf(stderr, "shfit: f=%llu layer %d lamp %02d R %.0f down t %.2f need %.2f -> the down map as before | near corners %d groups %d, ocl age %llu%c",
                            (unsigned long long)s_frame_count, L, hd, R, tdn, tn, nn, ng, (unsigned long long)age, 10);
                }
                return;
            }
        } else s_fit_t0[L] = 0;
        /* конус держится, пока у лампы (и кольцо, и дальние, если брались) не дальше предела от оси */
        const float cl = cosf(s_fit_lim[L]);
        int ok = 1;
        for (int i = 0; i < nn && ok; i++) ok = sh_fit_in(N[i], s_fit_ax[L], cl);
        if (ok && s_fit_far[L]) for (int i = 0; i < nf && ok; i++) ok = sh_fit_in(F[i], s_fit_ax[L], cl);
        if (ok && s_fit_ring[L]) {
            float Q[16][3]; sh_fit_ring_dirs(tdn, Q);
            for (int i = 0; i < 16 && ok; i++) ok = sh_fit_in(Q[i], s_fit_ax[L], cl);
        }
        if (ok) {
            for (int q = 0; q < 3; q++) { aim[q] = Lr[q] + s_fit_ax[L][q] * 1000.f; axo[q] = s_fit_ax[L][q]; }
            *znear = 60.f; if (*zfar < zf2) *zfar = zf2; *th = s_fit_th[L];
            return;
        }
    }
    /* новый конус: углы у лампы + кольцо прежней карты; не влезло в 80° - + дальние группы; нет - только у лампы */
    float U[SH_FIT_NP * 2 + 16][3], ax[3] = { 0.f, 1.f, 0.f }, half = 9.f;
    int ok = 0, ring = 0, wfar = 0;
    for (int tr = 0; tr < 3 && !ok; tr++) {
        if (tr == 1 && nf == 0) continue;
        int nu = 0;
        for (int i = 0; i < nn; i++) { U[nu][0] = N[i][0]; U[nu][1] = N[i][1]; U[nu][2] = N[i][2]; nu++; }
        if (tr == 0) nu += sh_fit_ring_dirs(tdn, &U[nu]);
        if (tr == 1) for (int i = 0; i < nf; i++) { U[nu][0] = F[i][0]; U[nu][1] = F[i][1]; U[nu][2] = F[i][2]; nu++; }
        const float mc = sh_fit_cap(U, nu, ax);
        half = mc >= 1.f ? 0.f : (mc <= -1.f ? 3.1416f : acosf(mc));
        if (half + (tr < 2 ? 0.087f : 0.f) <= hlim) { ok = 1; ring = (tr == 0); wfar = (tr == 1); }
    }
    if (!ok) {                                                 /* конус не влез (лампа в габарите тела) - карта как была */
        s_fit_md[L] = 0; s_fit_t0[L] = 0;
        static long nfail = 0;
        if (sh_fit_dbg() && s_fit_nl < 400 && (md0 != 0 || (nfail++ % 300) == 0)) {
            s_fit_nl++;
            fprintf(stderr, "shfit: f=%llu layer %d lamp %02d R %.0f down t %.2f need %.2f -> no cone fits (half %.1f), the down map as before | near corners %d groups %d%c",
                    (unsigned long long)s_frame_count, L, hd, R, tdn, tn, half * 57.2958f, nn, ng, 10);
        }
        return;
    }
    float hm = half + 0.087f; if (hm > hlim) hm = hlim;
    float t = tanf(hm) / 0.94f;
    if (t < tan_min) t = tan_min;
    if (t > tmax) t = tmax;
    float lim = atanf(0.94f * t); if (lim < half + 0.02f) lim = half + 0.02f;
    s_fit_md[L] = 1; s_fit_th[L] = t; s_fit_lim[L] = lim; s_fit_ring[L] = ring; s_fit_far[L] = wfar;
    for (int q = 0; q < 3; q++) { s_fit_ax[L][q] = ax[q]; aim[q] = Lr[q] + ax[q] * 1000.f; axo[q] = ax[q]; }
    *znear = 60.f; if (*zfar < zf2) *zfar = zf2; *th = t;
    if (sh_fit_dbg() && s_fit_nl < 400) {
        s_fit_nl++;
        fprintf(stderr, "shfit: f=%llu layer %d lamp %02d R %.0f down t %.2f need %.2f -> cone ax %.2f,%.2f,%.2f half %.1f t %.2f ring %d far %d | near corners %d groups %d, far corners %d, ocl age %llu%c",
                (unsigned long long)s_frame_count, L, hd, R, tdn, tn, ax[0], ax[1], ax[2], half * 57.2958f, t, ring, wfar,
                nn, ng, nf, (unsigned long long)age, 10);
    }
}
/* персонаж, ради которого группа k в кадре (наибольший вес); prev - прежний (номер слота), держится, пока его вес не меньше
 * 2/3 наибольшего */
static int sh_owner(int k, int nch, float cwc[12][GLAMP_MAX], const int *chs, int prev) {
    int best = -1; float bw = 0.f;
    for (int c = 0; c < nch && c < 12; c++) if (cwc[c][k] > bw) { bw = cwc[c][k]; best = c; }
    if (best < 0) return -1;
    for (int c = 0; c < nch && c < 12; c++) if (chs[c] == prev && cwc[c][k] >= bw * 0.667f) return c;
    return best;
}
void dc_shadow_draw(void) {
    s_shcl_n = 0;
    extern void dcvk_shadow_set(const float *vp, const float *par, const float *lpos,
                                int n, float bias, float dbg, float self_shadow, float rsel_k,
                                float spread_k);
    extern void dcvk_shadow_clear(void);
    extern int  dcvk_shadow_ready(void);
    static int en = -1, dbg = -1;
    if (en < 0) {
        const char *e = getenv("DC_SHADOW"); en = (e && *e == '0') ? 0 : 1;
        e = getenv("DC_SHADOW_DBG");  dbg  = e ? atoi(e) : 0;
    }
    /* каждый кадр: значение комнаты, иначе общее (панель F8 правит их на лету) */
    const float str    = dc_shadow_par(SHP_STR);
    const float soft   = dc_shadow_par(SHP_SOFT);
    const float bias   = dc_shadow_par(SHP_BIAS);
    const float fade   = dc_shadow_par(SHP_FADE);
    const float spread = dc_shadow_par(SHP_SPREAD);
    const float radk   = dc_shadow_par(SHP_RADK);
    const int   maxl   = (int)(dc_shadow_par(SHP_MAXL) + 0.5f);
    const int   self_sh = dc_shadow_par(SHP_SELF) > 0.5f ? 1 : 0;
    const float tanhalf = tanf(dc_shadow_par(SHP_FOV) * 0.5f * 3.14159265f / 180.0f);    if (!en || dc_shadow_par(SHP_ON) < 0.5f || !dcvk_shadow_ready()) {
        s_blob_live = 0;
        dcvk_shadow_clear();                 /* выключено — растр снова без теней */
        return;
    }
    dcvk_shadow_clear();
    s_blob_live = 0;
    /* ⛔ 18.09 вечер: здесь нельзя спрашивать про ГАБАРИТ (s_occ_n) — он
     * копится только после того, как эта функция опубликует матрицу
     * «видовое -> комната», и получалась взаимная блокировка: тени не было
     * вовсе. Спрашиваем про сами треугольники персонажей. */
    if (s_shd_n <= 0) { shwhy(0); return; }        /* персонажей в кадре нет */
    if (!dc_room_live_on() || !dcvk_enabled()) { shwhy(1); return; }
    const uint8_t *ram = memory_get_ram_ptr(); if (!ram) return;
    if ((dc_scripted_now() || dc_scene_flag_on()) && !dc_shadow_scene_on()) { shwhy(3); return; }   /* 25.09: в сценах — можно */

    if (glamp_check_on()) glamp_refresh();          /* 25.09 поздно: таблица ламп сверяется каждый кадр */
    else { static uint32_t sig = 0;
      uint32_t s2 = rrm_signature(ram);
      if (s2 != sig) { sig = s2; glamp_read(); } }
    /* 27.09: лампы-текстуры («светится» в меше комнаты) вместо таблицы игры — где они есть (см. «ЛАМПЫ-ТЕКСТУРЫ ДЛЯ ТЕНЕЙ») */
    tlamp_refresh();
    const int tex = tlamp_on() && s_tlamp_n > 0;
    const GameLamp *LMP = tex ? s_tlamp : s_glamp;
    const int NLMP = tex ? s_tlamp_n : s_glamp_n;
    { static int lt = -1; if (tex != lt) { lt = tex;
          fprintf(stderr, "shadow: lamps - %s%c", tex ? "the room's 'glows' TEXTURES (their shape and size)" : "the game's table", 10); } }
    const int moon = dc_moon_now();                 /* 25.09 вечер: луна — и там, где ламп нет вовсе */
    if (NLMP <= 0 && !moon) { shwhy(2); return; }

    /* 25.09: камера кадра — общая с вспышками (sh_camera); в сцене на движке — камера игры */
    float D[9], T[3], Rb[9], TRb[3]; int shgc = 0;
    if (!sh_camera(ram, 0, D, T, Rb, TRb, &shgc)) { shwhy(4); return; }
    const float *R = Rb, *TR = TRb;
    { static int lastgc = -1;
      if (shgc != lastgc) { lastgc = shgc;
          fprintf(stderr, "shadow: frame camera - %s%c", shgc == 4 ? "the GAME's (an engine scene; the game draws the room, the game's working camera)"
                  : shgc == 3 ? "the GAME's (an engine scene; the game draws the room, matrix from the GTE)"
                  : shgc == 2 ? "the GAME's (an engine scene; the game draws the room, matrix from the sections)"
                  : shgc ? "the GAME's (an engine scene, our room)" : "ours", 10); } }

    /* «видовое -> комната»: view = D*R*p + (D*TR + T), значит p = inv(D*R)*(view - c) */
    float DR[9];
    for (int r2 = 0; r2 < 3; r2++)
        for (int c2 = 0; c2 < 3; c2++)
            DR[r2*3 + c2] = D[r2*3+0]*R[0*3+c2] + D[r2*3+1]*R[1*3+c2] + D[r2*3+2]*R[2*3+c2];
    float A3[9];
    if (!shadow_inv3(DR, A3)) return;
    float cw[3];
    for (int r2 = 0; r2 < 3; r2++)
        cw[r2] = D[r2*3+0]*TR[0] + D[r2*3+1]*TR[1] + D[r2*3+2]*TR[2] + T[r2];
    float V2R[16] = {
        A3[0], A3[3], A3[6], 0.f,
        A3[1], A3[4], A3[7], 0.f,
        A3[2], A3[5], A3[8], 0.f,
        -(A3[0]*cw[0] + A3[1]*cw[1] + A3[2]*cw[2]),
        -(A3[3]*cw[0] + A3[4]*cw[1] + A3[5]*cw[2]),
        -(A3[6]*cw[0] + A3[7]*cw[1] + A3[8]*cw[2]), 1.f
    };
    for (int q = 0; q < 16; q++) s_v2r[q] = V2R[q];     /* её возьмёт dc_shadow_note */
    s_v2r_ok = 1;

    float px = (float)rrm_s16(ram, 0xB92ACu);
    float py = (float)rrm_s16(ram, 0xB92AEu);
    float pz = (float)rrm_s16(ram, 0xB92B0u);
    /* 25.09: в сцене на движке фигуры ведёт сцена — позиция игрока в RAM может быть совсем не там, где нарисована Регина
     * (слот 0: 3225,-1971 против нарисованной ~2000,570). Персонажи — группы заслонивших этого кадра (их вершины в
     * координатах комнаты, dc_shadow_note), первая — вместо «Регины». DC_SHADOW_SCENE_CHARS=0 — позиции из RAM. */
    static int scn_ch = -1;
    if (scn_ch < 0) { const char *e = getenv("DC_SHADOW_SCENE_CHARS"); scn_ch = (e && *e == '0') ? 0 : 1; }
    const int scene_chars = scn_ch && shgc != 0 && s_ocl_cnt > 0;
    if (scene_chars) { px = s_ocl_c[0][0]; py = s_ocl_hi[0][1]; pz = s_ocl_c[0][2]; }

    /* габарит окклюдеров кадра — в координаты комнаты (8 углов) */
    float ocorn[8][3]; float ocen[3] = { px, py - 700.f, pz };
    if (s_occ_n > 0) {
        float mid[3] = { 0.f, 0.f, 0.f };
        for (int c = 0; c < 8; c++) {
            ocorn[c][0] = (c & 1) ? s_occ_hi[0] : s_occ_lo[0];   /* уже в комнате */
            ocorn[c][1] = (c & 2) ? s_occ_hi[1] : s_occ_lo[1];
            ocorn[c][2] = (c & 4) ? s_occ_hi[2] : s_occ_lo[2];
            for (int r2 = 0; r2 < 3; r2++) mid[r2] += ocorn[c][r2] * 0.125f;
        }
        for (int r2 = 0; r2 < 3; r2++) ocen[r2] = mid[r2];
    }

    /* цель фрустума — середина этого габарита, сглаженная: карта не должна
     * дёргаться от подрагивания позиций в RAM */
    static float tgt[3] = { 0.f, 0.f, 0.f };
    static int tgt_on = 0;
    { float cur[3] = { px, py - 700.f, pz };
      float dx = cur[0]-tgt[0], dy = cur[1]-tgt[1], dz = cur[2]-tgt[2];
      if (!tgt_on || (dx*dx + dy*dy + dz*dz) > 1200.f*1200.f) {
          tgt[0] = cur[0]; tgt[1] = cur[1]; tgt[2] = cur[2]; tgt_on = 1;
      } else {
          tgt[0] += dx * 0.25f; tgt[1] += dy * 0.25f; tgt[2] += dz * 0.25f;
      } }

    /* персонажи для выбора ламп и для карты (25.09, дальность): Регина + занятые слоты актёров; рост — оценка сверху */
    const int reach = shadow_reach_on();
    float chx[12], chy[12], chz[12], chh[12]; int nch = 0;
    int chs[12];                               /* 23.10: кто это - -1 Регина, номер слота актёра, 100+ группа заслонивших сцены */
    chx[nch] = px; chy[nch] = py; chz[nch] = pz; chh[nch] = 1900.f; chs[nch] = -1; nch++;
    if (scene_chars) {                         /* 25.09: сцена — все группы заслонивших (ноги = наибольший y, ось вниз) */
        nch = 0;
        for (int c = 0; c < s_ocl_cnt && nch < 12; c++) {
            chx[nch] = s_ocl_c[c][0]; chz[nch] = s_ocl_c[c][2]; chy[nch] = s_ocl_hi[c][1];
            float hh = s_ocl_hi[c][1] - s_ocl_lo[c][1] + 150.f; if (hh < 600.f) hh = 600.f;
            chh[nch] = hh; chs[nch] = 100 + c; nch++;
        }
        { static long nl = 0;
          if (++nl == 1 || nl % 600 == 0) {
              fprintf(stderr, "shadow: scene - characters by occluders: %d%c", nch, 10);
              for (int c = 0; c < nch; c++)
                  fprintf(stderr, "   #%d at %.0f,%.0f,%.0f height %.0f%c", c, chx[c], chy[c], chz[c], chh[c], 10); } }
    } else if (reach)
        for (int k = 0; k < 10 && nch < 12; k++) {
            const uint32_t a = 0xB7ACCu + (uint32_t)k * 608u;
            if (!(rrm_u32(ram, a + 48u) & 1u)) continue;
            chx[nch] = (float)rrm_s16(ram, a + 32u);
            chy[nch] = (float)rrm_s16(ram, a + 34u);
            chz[nch] = (float)rrm_s16(ram, a + 36u);
            chh[nch] = (ram[a + 80u] == 0x0A) ? 6500.f : 2200.f;   /* тиранозавр (вид +80 = 0x0A) выше всех */
            chs[nch] = k; nch++;
        }
    /* лампы: включённые, в чьём радиусе стоит персонаж и которые выше него (25.09: любой персонаж, не только Регина) */
    int idx[GLAMP_MAX]; float wgt[GLAMP_MAX], dst[GLAMP_MAX];
    int nc = 0;
    const int stable = dc_shadow_par(SHP_STABLE) > 0.5f;   /* 23.10: см. «СТАБИЛЬНЫЕ ТЕНИ» */
    float cwl[12][GLAMP_MAX]; memset(cwl, 0, sizeof cwl);   /* 23.10: вес лампы для каждого персонажа */
    /* ===== ЛАМПЫ КАК У ИГРЫ (25.09 поздно) ===== Игрок: «лампы точно корректны? смотрю, как освещаются вертексы
     * (оригинальной системой псевдоосвещения), и тени от наших ламп с этим не совпадают». Игра (func_8004A910 ->
     * func_8004AB30 на объект) освещает персонажа так: слот 0 — общий направленный свет 1 (флаг +6 бит 0) ИЛИ ПЕРВАЯ ПО ПОРЯДКУ
     * включённая лампа набора 1, в чей радиус (+10, расстояние от точки объекта obj+32..36 до лампы, в 3D) он попал; слот 1 —
     * то же для набора 2 (бит 1); вектор на лампу длиной +14 × (1 − d/r), цвет лампы. Остальные лампы в радиусе игра этому
     * объекту НЕ даёт. Мы брали все лампы в 2.2 радиуса и сортировали по яркости — в ST105 у точки сейва игра светит Регину
     * одной G01, а у нас были ещё G07 и G02 (вне их радиуса у игры). Теперь тени — от ламп игры (объединение по персонажам),
     * вес = цвет × (1 − d/r) × (+14)/4096; появление и уход лампы — плавно за ~0.3 с (при смене «первой в радиусе» у игры
     * свет переключается скачком). Лампа ниже ног тени не даёт (но и следующую игра не берёт). gamelamps = 0
     * (DC_SHADOW_GAMELAMPS=0) — прежний выбор (radk). */
    static float s_lfade[GLAMP_MAX], s_lw[GLAMP_MAX], s_ld[GLAMP_MAX]; static uint32_t s_lfade_tab = 0; static int s_lfade_ep = -1;
    const int gamerule = !tex && dc_shadow_par(SHP_GAMELAMPS) > 0.5f;   /* 27.09: у ламп-текстур правила игры нет */
    if (gamerule) {
        /* новая таблица — затухания с нуля; 19.10: и новая комната или быстрая загрузка (таблица у комнат лежит по тому же
         * адресу, и лампа с тем же номером в новой комнате ещё ~0.3 с несла тень лампы прежней) */
        if (s_lfade_tab != s_glamp_addr || s_lfade_ep != dc_light_epoch()) {
            s_lfade_tab = s_glamp_addr; s_lfade_ep = dc_light_epoch();
            for (int i = 0; i < GLAMP_MAX; i++) { s_lfade[i] = 0.f; s_lw[i] = 0.f; s_ld[i] = 0.f; }
        }
        float gw[GLAMP_MAX], gd[GLAMP_MAX], gx[GLAMP_MAX]; unsigned char gin[GLAMP_MAX];
        for (int i = 0; i < GLAMP_MAX; i++) { gw[i] = 0.f; gd[i] = 0.f; gx[i] = 0.f; gin[i] = 0; }
        const float ext = dc_shadow_par(SHP_EXT);
        for (int c = 0; c < nch; c++)
            for (int set = 1; set <= 2; set++) {
                if (s_glamp_flags & set) continue;   /* этот слот у игры — общий направленный свет */
                int inr = 0;
                for (int i = 0; i < s_glamp_n; i++) {
                    const GameLamp *L = &s_glamp[i];
                    if (L->set != set || !L->on) continue;
                    const float dx = L->p[0] - chx[c], dy = L->p[1] - chy[c], dz = L->p[2] - chz[c];
                    const float d = sqrtf(dx*dx + dy*dy + dz*dz);
                    if (L->rad <= 0.f || d > L->rad) continue;
                    /* первая в радиусе — её и берёт игра (следующие в наборе этому объекту уже не светят) */
                    inr = 1;
                    if (L->p[1] <= chy[c] - 150.f) {
                        float br = L->col[0]; if (L->col[1] > br) br = L->col[1]; if (L->col[2] > br) br = L->col[2];
                        const float w = (br / 128.f) * (1.f - d / L->rad) * (L->s14 > 0.f ? L->s14 / 4096.f : 1.f);
                        if (w > gw[i]) { gw[i] = w; gd[i] = d; }
                        if (w > cwl[c][i]) cwl[c][i] = w;
                        if (w > 0.f) gin[i] = 1;
                    }
                    break;
                }
                /* 19.10.2026: ни одна лампа набора до персонажа не достаёт - тень даёт ближайшая по доле радиуса лампа за
                 * краем (выше ног), слабея от полной на радиусе к нулю на ext радиусах; вес - ниже любой лампы в радиусе */
                if (!inr && ext > 1.001f) {
                    int bi = -1; float bq = ext, bd = 0.f;
                    for (int i = 0; i < s_glamp_n; i++) {
                        const GameLamp *L = &s_glamp[i];
                        if (L->set != set || !L->on || L->rad <= 0.f || L->p[1] > chy[c] - 150.f) continue;
                        const float dx = L->p[0] - chx[c], dy = L->p[1] - chy[c], dz = L->p[2] - chz[c];
                        const float d = sqrtf(dx*dx + dy*dy + dz*dz), q = d / L->rad;
                        if (q < bq) { bq = q; bi = i; bd = d; }
                    }
                    if (bi >= 0) {
                        const GameLamp *L = &s_glamp[bi];
                        const float k = (ext - bq) / (ext - 1.f);
                        float br = L->col[0]; if (L->col[1] > br) br = L->col[1]; if (L->col[2] > br) br = L->col[2];
                        const float w = (br / 128.f) * 1e-3f * k * (L->s14 > 0.f ? L->s14 / 4096.f : 1.f);
                        if (w > gw[bi]) { gw[bi] = w; gd[bi] = bd; }
                        if (w > cwl[c][bi]) cwl[c][bi] = w;
                        if (k > gx[bi]) gx[bi] = k;
                    }
                }
            }
        for (int i = 0; i < s_glamp_n && i < GLAMP_MAX; i++) {
            if (gw[i] > 0.f) { s_lw[i] = gw[i]; s_ld[i] = gd[i]; }
            const float tgt_f = gin[i] ? 1.f : gx[i];                          /* в радиусе - 1; за краем - доля */
            s_lfade[i] += (tgt_f - s_lfade[i]) * 0.2f;
            if (s_lfade[i] < 0.02f || s_lw[i] <= 0.f) continue;
            idx[nc] = i; dst[nc] = s_ld[i]; wgt[nc] = s_lw[i] * s_lfade[i]; nc++;
        }
    }
    if (!gamerule)
    for (int i = 0; i < NLMP; i++) {
        const GameLamp *L = &LMP[i];
        if (!L->on) continue;
        float rad = (L->rad > 0.f) ? L->rad * radk : 3000.f;
        float bk = -1.f, bd = 0.f;
        float br = L->col[0]; if (L->col[1] > br) br = L->col[1]; if (L->col[2] > br) br = L->col[2];
        for (int c = 0; c < nch; c++) {
            float dx = L->p[0]-chx[c], dy = L->p[1]-chy[c], dz = L->p[2]-chz[c];
            float d = sqrtf(dx*dx + dy*dy + dz*dz);
            if (d > rad) continue;
            if (L->p[1] > chy[c] - 150.f) continue;
            float k = 1.f - d / rad; if (k < 0.f) k = 0.f;
            if (k > bk) { bk = k; bd = d; }
            if (c < 12) cwl[c][i] = (br / 128.f) * k;
        }
        if (bk < 0.f) continue;
        idx[nc] = i; dst[nc] = bd; wgt[nc] = (br / 128.f) * bk; nc++;
    }
    if (nc <= 0 && !moon) { shwhy(2); return; }
    for (int a = 0; a < nc - 1; a++)
        for (int b = a + 1; b < nc; b++)
            if (wgt[b] > wgt[a]) {
                int ti = idx[a]; idx[a] = idx[b]; idx[b] = ti;
                float tw = wgt[a]; wgt[a] = wgt[b]; wgt[b] = tw;
                float td = dst[a]; dst[a] = dst[b]; dst[b] = td;
            }
    /* ===== СЛИЯНИЕ ЛАМП (25.09 поздно) ===== Игрок (слот 9, ST105): «в комнате тройная тень — похоже, в одном месте
     * примерно 3 источника света стоит; надо такого избегать». В таблице игры там три лампы в ряд через 1500 ед. (G06, G13,
     * G03 — светильник из трёх ламп), в 10–12 тыс. ед. от Регины: три почти одинаковые тени со сдвигом ~8°. Теперь лампы,
     * которые из точки опоры (tgt) видны под углом меньше merge° от центра уже набранной группы, сливаются в неё: одна тень
     * из центра группы (среднее по весам), сила — сильнейшей лампы, радиус — наибольший, край чуть мягче на размер группы
     * (+0.2 × размах, не больше ×2.5 обычного). Голова группы — сильнейшая лампа (её номер ведёт сглаживание поля карты).
     * merge = 0 (DC_SHADOW_MERGE=0) — как было, у каждой лампы своя тень. */
    float clp[GLAMP_MAX][3], clw[GLAMP_MAX], clrad[GLAMP_MAX], clmin[GLAMP_MAX][3], clmax[GLAMP_MAX][3];
    float clpow[GLAMP_MAX];                          /* 27.09 (2): сила света группы (сумма её ламп) — для доли света */
    int clnm[GLAMP_MAX];
    int ncl = 0;
    float cwc[12][GLAMP_MAX];                        /* 23.10 (stable): вес группы для каждого персонажа */
    memset(cwc, 0, sizeof cwc);
    if (stable) {
        /* 23.10: группы - по месту самих ламп (sh_static_groups); в группе этого кадра - её лампы-кандидаты (вес для персонажа -
         * наибольший из её ламп), а место, радиус, сила и размах - всей группы: от того, где Регина, не зависят */
        static ShStGroups G;
        const float md = dc_shadow_par(SHP_MERGE) > 0.f ? dc_shadow_par(SHP_MERGE_D) : 0.f;
        sh_static_groups(LMP, NLMP, md, &G);
        { static int ln = -1, lg = -1; static float lmd = -1.f;
          if (G.nl != ln || G.n != lg || md != lmd) { ln = G.nl; lg = G.n; lmd = md;
              fprintf(stderr, "shadow: lamp groups by the lamps' own places (stable) - %d lamps -> %d groups (one shadow within %.0f units of the strongest)%c",
                      G.nl, G.n, md, 10); } }
        int gk[GLAMP_MAX]; for (int g = 0; g < GLAMP_MAX; g++) gk[g] = -1;
        for (int a = 0; a < nc; a++) {                  /* кандидаты уже по весу: голова кадра - сильнейшая лампа-кандидат группы */
            const int li = idx[a]; const float wa = wgt[a], da = dst[a];
            const int g = (li >= 0 && li < G.nl) ? G.grp[li] : -1;
            if (g < 0) continue;
            int k = gk[g];
            if (k < 0) {
                if (ncl >= GLAMP_MAX) continue;
                k = gk[g] = ncl++;
                idx[k] = li; wgt[k] = wa; dst[k] = da;
                for (int q = 0; q < 3; q++) { clp[k][q] = G.c[g][q]; clmin[k][q] = G.mn[g][q]; clmax[k][q] = G.mx[g][q]; }
                clw[k] = wa > 1e-4f ? wa : 1e-4f; clrad[k] = G.rad[g]; clnm[k] = G.nm[g]; clpow[k] = G.pow[g];
            }
            for (int c = 0; c < nch && c < 12; c++) if (cwl[c][li] > cwc[c][k]) cwc[c][k] = cwl[c][li];
        }
    } else
    {   const float mang = dc_shadow_par(SHP_MERGE) * 3.14159265f / 180.f;
        const float cmin = cosf(mang);
        for (int a = 0; a < nc; a++) {
            const GameLamp *GA = &LMP[idx[a]];
            const float ra = (GA->rad > 0.f) ? GA->rad : 3000.f;
            int k = -1;
            if (mang > 0.f)
                for (int c = 0; c < ncl; c++) {
                    const float ux = GA->p[0] - tgt[0], uy = GA->p[1] - tgt[1], uz = GA->p[2] - tgt[2];
                    const float vx = clp[c][0] - tgt[0], vy = clp[c][1] - tgt[1], vz = clp[c][2] - tgt[2];
                    const float lu = sqrtf(ux*ux + uy*uy + uz*uz), lv = sqrtf(vx*vx + vy*vy + vz*vz);
                    if (lu < 1.f || lv < 1.f) continue;
                    if ((ux*vx + uy*vy + uz*vz) / (lu * lv) > cmin) { k = c; break; }
                }
            if (k < 0) {
                if (ncl >= GLAMP_MAX) continue;
                k = ncl++;
                idx[k] = idx[a]; wgt[k] = wgt[a]; dst[k] = dst[a];
                for (int q = 0; q < 3; q++) { clp[k][q] = GA->p[q]; clmin[k][q] = clmax[k][q] = GA->p[q]; }
                clw[k] = wgt[a] > 1e-4f ? wgt[a] : 1e-4f; clrad[k] = ra; clnm[k] = 1;
                clpow[k] = shadow_lamp_pow(GA);
            } else {
                const float wa = wgt[a] > 1e-4f ? wgt[a] : 1e-4f;
                for (int q = 0; q < 3; q++) {
                    clp[k][q] = (clp[k][q] * clw[k] + GA->p[q] * wa) / (clw[k] + wa);
                    if (GA->p[q] < clmin[k][q]) clmin[k][q] = GA->p[q];
                    if (GA->p[q] > clmax[k][q]) clmax[k][q] = GA->p[q];
                }
                clw[k] += wa; if (ra > clrad[k]) clrad[k] = ra; clnm[k]++;
                clpow[k] += shadow_lamp_pow(GA);
            }
        }
    }
    nc = ncl;
    int n = (nc < maxl) ? nc : maxl;
    if (moon && n > 3) n = 3;                       /* слоёв карты 4: один — луне */
    float wmax = (nc > 0) ? wgt[0] : 1.f; if (wmax < 1e-4f) wmax = 1e-4f;

    float vp[4*16], par[4*4], lpos[4*4];
    float shE[4*4];                                  /* 27.09: эллипс мягкости на слой (лампы-текстуры), 1 0 0 1 — круг */
    for (int q = 0; q < 4; q++) { shE[q*4+0] = 1.f; shE[q*4+1] = 0.f; shE[q*4+2] = 0.f; shE[q*4+3] = 1.f; }
    /* ===== НОВЫЙ ПУТЬ ТЕНЕЙ (27.09 (2)) ===== Игрок: «тени выглядят очень шумными и не совсем точными. От нескольких источников
     * сложение не реалистично работает». (1) Слой карты ЗАКРЕПЛЁН за лампой (узнаётся по месту, в 400 ед.): новая лампа
     * появляется, ушедшая гаснет плавно (~0.2 с), у лампы со слоем запас ×1.3 — прежде тройка сильнейших набиралась заново
     * каждый кадр, и тень пропадала скачком. (2) Сила тени — в шейдере, ДОЛЕЙ света лампы в точке: свет лампы / (общий свет
     * комнаты amb + все лампы рядом, со слоем и без); лампы без своего слоя идут только в долю (v2lp). Прежде каждая тень
     * затемняла на str и тени умножались. (3) Полутень — по настоящему размеру лампы: полуоси лампы-текстуры в плоскости карты
     * (прежде бралась полная длина — вдвое шире), у ламп игры и групп — прежний «размер» soft (он же нижняя граница). Сами слои
     * читаются пирамидой без зерна (gpu_vk_raster.cpp «ТЕНИ БЕЗ ЗЕРНА»). DC_SHADOW_V2=0 (панель: v2) — прежние тени. */
    const int v2 = dc_shadow_par(SHP_V2) > 0.5f;
    float v2pow[4] = { 0.f, 0.f, 0.f, 0.f }, v2ax[16], v2lp[32], v2lw[8];
    int v2mask = 0, v2nlo = 0;
    static int   s_v2on[4], s_v2hd[4], s_v2nm[4], s_v2pt[4], s_v2room = -99, s_v2tex = -1;
    static int   s_v2own[4] = { -2, -2, -2, -2 }; static float s_v2anc[4][3];   /* 23.10 (stable): чей слой и где пятно */
    int shk[8] = { 0 };                              /* 23.10: какие группы в доле света (строка DC_SHADOW_TRACE) */
    static float s_v2f[4], s_v2p[4][3], s_v2r[4], s_v2w[4], s_v2mn[4][3], s_v2mx[4][3];
    for (int q = 0; q < 16; q++) v2ax[q] = 0.f;
    if (v2) {
        const float FSTEP = 0.15f, MATCH = 400.f;
        const float texmax = dc_shadow_par(SHP_TEXMAX);
        const int room = dc_room_effective();
        if (room != s_v2room || tex != s_v2tex) {           /* другая комната / другой источник ламп — слои с нуля */
            s_v2room = room; s_v2tex = tex;
            for (int L = 0; L < 4; L++) { s_v2on[L] = 0; s_v2f[L] = 0.f; s_v2own[L] = -2; }
        }
        int nlay = moon ? 3 : 4; if (maxl < nlay) nlay = maxl; if (nlay < 1) nlay = 1;
        for (int L = nlay; L < 4; L++) { s_v2on[L] = 0; s_v2f[L] = 0.f; }
        /* какой группе ламп этого кадра соответствует слой — по месту лампы */
        int lk[4] = { -1, -1, -1, -1 };
        for (int L = 0; L < nlay; L++) {
            if (!s_v2on[L]) continue;
            float bd = MATCH * MATCH;
            for (int k = 0; k < nc; k++) {
                const float dx = clp[k][0] - s_v2p[L][0], dy = clp[k][1] - s_v2p[L][1], dz = clp[k][2] - s_v2p[L][2];
                const float dd = dx*dx + dy*dy + dz*dz;
                int used = 0; for (int M2 = 0; M2 < L; M2++) if (lk[M2] == k) used = 1;
                if (!used && dd < bd) { bd = dd; lk[L] = k; }
            }
        }
        /* цель — nlay сильнейших; у кого слой уже есть — с запасом ×1.3 (равные лампы не перещёлкиваются) */
        unsigned char want[GLAMP_MAX]; memset(want, 0, sizeof want);
        /* 23.10 (stable): раньше - очередь по персонажам (sh_stable_keys), внутри неё - сильнейшие */
        int key[GLAMP_MAX];
        for (int k = 0; k < nc; k++) key[k] = stable ? (1 << 20) : 0;
        if (stable) sh_stable_keys(nc, nch, cwc, lk, nlay, scene_chars, key);
        for (int t = 0; t < nlay; t++) {
            int best = -1; float bw = 0.f;
            for (int k = 0; k < nc; k++) {
                if (want[k]) continue;
                float w = wgt[k];
                for (int L = 0; L < nlay; L++) if (lk[L] == k) { w *= 1.3f; break; }
                if (best < 0 || key[k] < key[best] || (key[k] == key[best] && w > bw)) { best = k; bw = w; }
            }
            if (best < 0) break;
            want[best] = 1;
        }
        for (int L = 0; L < nlay; L++) {
            if (!s_v2on[L]) continue;
            const int k = lk[L];
            s_v2f[L] += (k >= 0 && want[k]) ? FSTEP : -FSTEP;
            if (s_v2f[L] > 1.f) s_v2f[L] = 1.f;
            if (s_v2f[L] <= 0.f) { s_v2on[L] = 0; s_v2f[L] = 0.f; lk[L] = -1; continue; }
            if (k >= 0) {                                   /* лампа на месте — данные свежие (группа могла сдвинуться) */
                for (int q = 0; q < 3; q++) { s_v2p[L][q] = clp[k][q]; s_v2mn[L][q] = clmin[k][q]; s_v2mx[L][q] = clmax[k][q]; }
                s_v2r[L] = clrad[k]; s_v2w[L] = clpow[k]; s_v2hd[L] = idx[k]; s_v2nm[L] = clnm[k];
            }                                               /* лампы уже нет — гаснет с прежними данными */
        }
        for (int k = 0; k < nc; k++) {                      /* новые — в свободный слой (нет свободного — ждёт) */
            if (!want[k]) continue;
            int has = 0; for (int L = 0; L < nlay; L++) if (lk[L] == k) has = 1;
            if (has) continue;
            int fl = -1; for (int L = 0; L < nlay; L++) if (!s_v2on[L]) { fl = L; break; }
            if (fl < 0) break;
            s_v2on[fl] = 1; s_v2f[fl] = FSTEP; lk[fl] = k; s_v2own[fl] = -2;
            for (int q = 0; q < 3; q++) { s_v2p[fl][q] = clp[k][q]; s_v2mn[fl][q] = clmin[k][q]; s_v2mx[fl][q] = clmax[k][q]; }
            s_v2r[fl] = clrad[k]; s_v2w[fl] = clpow[k]; s_v2hd[fl] = idx[k]; s_v2nm[fl] = clnm[k];
            shadow_reach_reset(GLAMP_MAX + fl);             /* ось и раскрытие карты слоя — с этой лампы заново */
            sh_fit_reset(fl);                               /* 26.10: и карта по телам */
        }
        n = 0;
        for (int L = 0; L < nlay; L++) if (s_v2on[L]) n = L + 1;
        if (moon) n = nlay;                                 /* луна — следующий слой после ламп */
        /* 23.10 (stable): чей слой - пятно большой лампы-текстуры над этим персонажем (у Регины - сглаженная tgt, как было) */
        for (int L = 0; L < nlay; L++) {
            if (!s_v2on[L]) continue;
            const int oc = (stable && lk[L] >= 0) ? sh_owner(lk[L], nch, cwc, chs, s_v2own[L]) : -1;
            if (oc < 0 && stable && s_v2own[L] != -2) continue;   /* ни у кого веса нет (лампа уходит) - пятно где было */
            s_v2own[L] = oc >= 0 ? chs[oc] : -1;
            const int regi = (oc < 0 || (oc == 0 && !scene_chars));
            for (int q = 0; q < 3; q++) s_v2anc[L][q] = regi ? tgt[q] : (q == 0 ? chx[oc] : q == 1 ? chy[oc] - 700.f : chz[oc]);
        }
        for (int L = 0; L < n; L++) {
            for (int q = 0; q < 16; q++) vp[L*16+q] = 0.f;  /* пустой слой: в его карту ничего не ляжет */
            par[L*4+0] = 0.f; par[L*4+1] = 1.f; par[L*4+2] = 1.f; par[L*4+3] = 0.f;
            lpos[L*4+0] = lpos[L*4+1] = lpos[L*4+2] = 0.f; lpos[L*4+3] = 1.f;
            for (int q = 0; q < 3; q++) { s_shcl_min[L][q] = 1.f; s_shcl_max[L][q] = -1.f; }   /* пусто — дымке не найдётся */
            if (!s_v2on[L]) continue;
            float Lr[3] = { s_v2p[L][0], s_v2p[L][1], s_v2p[L][2] };
            float PA[3], PB[3];                             /* большая лампа-текстура — пятно над персонажем (tlamp_patch) */
            const int patch = tex ? tlamp_patch(s_v2hd[L], stable ? s_v2anc[L] : tgt, texmax, Lr, PA, PB) : 0;
            s_v2pt[L] = patch;
            const float rad = s_v2r[L];
            float softi = soft;                             /* группа ламп — источник пошире */
            if (s_v2nm[L] > 1) {
                const float ex = s_v2mx[L][0] - s_v2mn[L][0], ey = s_v2mx[L][1] - s_v2mn[L][1], ez = s_v2mx[L][2] - s_v2mn[L][2];
                softi = soft + 0.2f * sqrtf(ex*ex + ey*ey + ez*ez);
                if (softi > 2.5f * soft) softi = 2.5f * soft;
            }
            const float dxv = tgt[0]-Lr[0], dyv = tgt[1]-Lr[1], dzv = tgt[2]-Lr[2];
            float dist = sqrtf(dxv*dxv + dyv*dyv + dzv*dzv); if (dist < 1.f) dist = 1.f;
            float znear = dist * 0.2f; if (znear < 60.f) znear = 60.f;
            float zfar = dist + rad, th = tanhalf;
            float aim[3] = { tgt[0], tgt[1], tgt[2] };
            if (stable) {                                   /* 23.10: строго вниз на весь круг тени (sh_down_frustum); 26.10: тела у лампы
                                                             * в неё не влезают - конусом на них (sh_fit_frustum) */
                float fax[3];
                sh_fit_frustum(L, s_v2hd[L], Lr, rad, fade, tanhalf, chx, chy, chz, nch, aim, &znear, &zfar, &th, fax);
                s_rf_half[GLAMP_MAX + L] = atanf(th); s_rf_ax[GLAMP_MAX + L][0] = fax[0]; s_rf_ax[GLAMP_MAX + L][1] = fax[1]; s_rf_ax[GLAMP_MAX + L][2] = fax[2];
                s_rf_seen[GLAMP_MAX + L] = 0;                   /* к прежней карте (stable=0) - с нуля */
            } else
            if (reach) shadow_reach_frustum(GLAMP_MAX + L, Lr, rad, radk, fade, tanhalf, chx, chy, chz, chh, nch, aim, &znear, &zfar, &th);
            shadow_build_vp(Lr, aim, znear, zfar, th, V2R, &vp[L*16]);
            /* полуоси полутени в плоскости карты (базис как в shadow_build_vp): лампа-текстура — её собственные полуоси */
            float rr[3], uu[3]; shadow_map_basis(Lr, aim, rr, uu);
            float a2x = softi, a2y = 0.f, b2x = 0.f, b2y = softi;
            if (tex && s_v2hd[L] >= 0 && s_v2hd[L] < GLAMP_MAX) {
                const float *LA = patch ? PA : s_tl_A[s_v2hd[L]], *LB = patch ? PB : s_tl_B[s_v2hd[L]];
                const float kk = tlamp_softk();
                a2x = (LA[0]*rr[0] + LA[1]*rr[1] + LA[2]*rr[2]) * kk; a2y = (LA[0]*uu[0] + LA[1]*uu[1] + LA[2]*uu[2]) * kk;
                b2x = (LB[0]*rr[0] + LB[1]*rr[1] + LB[2]*rr[2]) * kk; b2y = (LB[0]*uu[0] + LB[1]*uu[1] + LB[2]*uu[2]) * kk;
            }
            float la = sqrtf(a2x*a2x + a2y*a2y), lb = sqrtf(b2x*b2x + b2y*b2y);
            if (lb > la) { const float t0 = a2x, t1 = a2y, tl = la; a2x = b2x; a2y = b2y; b2x = t0; b2y = t1; la = lb; lb = tl; }
            if (la < softi) { if (la > 1e-3f) { a2x *= softi / la; a2y *= softi / la; } else { a2x = softi; a2y = 0.f; } la = softi; }
            if (lb < softi) { b2x = -a2y / la * softi; b2y = a2x / la * softi; lb = softi; }   /* поперёк длинной, не меньше soft */
            const float kuv = 1.f / (2.f * th);
            v2ax[L*4+0] = a2x * kuv; v2ax[L*4+1] = a2y * kuv; v2ax[L*4+2] = b2x * kuv; v2ax[L*4+3] = b2y * kuv;
            shE[L*4+0] = a2x / la; shE[L*4+1] = a2y / la; shE[L*4+2] = b2x / la; shE[L*4+3] = b2y / la;   /* запасной путь */
            float lv[3]; sh_room2view(R, TR, D, T, Lr, lv);
            lpos[L*4+0] = lv[0]; lpos[L*4+1] = lv[1]; lpos[L*4+2] = lv[2];
            lpos[L*4+3] = rad * fade;                       /* докуда свет лампы — там гаснет и её доля */
            const float gf = (gamerule && s_v2hd[L] >= 0 && s_v2hd[L] < GLAMP_MAX) ? s_lfade[s_v2hd[L]] : 1.f;
            par[L*4+0] = str * s_v2f[L] * gf;               /* сила тени (доля — в шейдере) × появление/угасание слоя */
            par[L*4+1] = zfar / (zfar - znear);
            par[L*4+2] = zfar * znear / (zfar - znear);
            par[L*4+3] = la / (2.f * th);                   /* запасной путь: размер источника */
            v2pow[L] = s_v2w[L];
            v2mask |= 1 << L;
            for (int q = 0; q < 3; q++) { s_shcl_min[L][q] = s_v2mn[L][q]; s_shcl_max[L][q] = s_v2mx[L][q]; }
        }
        /* лампы без своего слоя — только в долю света (до 8 сильнейших); 23.10 (stable) - в той же очереди по персонажам */
        int so[GLAMP_MAX];
        for (int k = 0; k < nc; k++) so[k] = k;
        if (stable)
            for (int a = 0; a < nc - 1; a++)
                for (int b = a + 1; b < nc; b++)
                    if (key[so[b]] < key[so[a]] || (key[so[b]] == key[so[a]] && wgt[so[b]] > wgt[so[a]])) { const int t = so[a]; so[a] = so[b]; so[b] = t; }
        for (int qk = 0; qk < nc && v2nlo < 8; qk++) {
            const int k = so[qk];
            int inl = 0; for (int L = 0; L < nlay; L++) if (s_v2on[L] && lk[L] == k) inl = 1;
            if (inl) continue;
            float lpk[3] = { clp[k][0], clp[k][1], clp[k][2] }, PA[3], PB[3];
            float anc[3] = { tgt[0], tgt[1], tgt[2] };
            if (stable) { const int oc = sh_owner(k, nch, cwc, chs, -9);
                          if (oc > 0 || (oc == 0 && scene_chars)) { anc[0] = chx[oc]; anc[1] = chy[oc] - 700.f; anc[2] = chz[oc]; } }
            if (tex) (void)tlamp_patch(idx[k], anc, texmax, lpk, PA, PB);   /* большая — её ближняя часть */
            shk[v2nlo] = k;
            float lv[3]; sh_room2view(R, TR, D, T, lpk, lv);
            v2lp[v2nlo*4+0] = lv[0]; v2lp[v2nlo*4+1] = lv[1]; v2lp[v2nlo*4+2] = lv[2]; v2lp[v2nlo*4+3] = clrad[k] * fade;
            v2lw[v2nlo] = clpow[k] * ((gamerule && idx[k] >= 0 && idx[k] < GLAMP_MAX) ? s_lfade[idx[k]] : 1.f);
            v2nlo++;
        }
    } else
    for (int i = 0; i < n; i++) {
        float Lr[3] = { clp[i][0], clp[i][1], clp[i][2] };
        float dxv = tgt[0]-Lr[0], dyv = tgt[1]-Lr[1], dzv = tgt[2]-Lr[2];
        float dist = sqrtf(dxv*dxv + dyv*dyv + dzv*dzv);
        if (dist < 1.f) dist = 1.f;
        float rad = clrad[i];
        float softi = soft;                          /* группа ламп — источник пошире: край чуть мягче */
        if (clnm[i] > 1) {
            const float ex = clmax[i][0] - clmin[i][0], ey = clmax[i][1] - clmin[i][1], ez = clmax[i][2] - clmin[i][2];
            softi = soft + 0.2f * sqrtf(ex*ex + ey*ey + ez*ez);
            if (softi > 2.5f * soft) softi = 2.5f * soft;
        }
        float znear = dist * 0.2f; if (znear < 60.f) znear = 60.f;
        float zfar  = dist + rad;
        float th = tanhalf;
        float aim[3] = { tgt[0], tgt[1], tgt[2] };
        if (reach)          /* 25.09: карта на персонажей у этой лампы и на концы их теней */
            shadow_reach_frustum(idx[i], Lr, rad, radk, fade, tanhalf, chx, chy, chz, chh, nch, aim, &znear, &zfar, &th);
        shadow_build_vp(Lr, aim, znear, zfar, th, V2R, &vp[i*16]);
        /* 27.09: лампа-текстура — мягкость и форма полутени по её фигуре: оси лампы (A — длинная, B — короткая, полудлины)
         * в плоскости карты (базис как в shadow_build_vp) -> эллипс выборок E (столбцы A2/M, B2/M), размер источника 2M */
        shE[i*4+0] = 1.f; shE[i*4+1] = 0.f; shE[i*4+2] = 0.f; shE[i*4+3] = 1.f;
        if (tex) {
            const int hl = idx[i];
            float f[3] = { aim[0]-Lr[0], aim[1]-Lr[1], aim[2]-Lr[2] };
            float fl = sqrtf(f[0]*f[0] + f[1]*f[1] + f[2]*f[2]);
            if (fl < 1e-3f) { f[0] = 0.f; f[1] = 1.f; f[2] = 0.f; fl = 1.f; }
            f[0] /= fl; f[1] /= fl; f[2] /= fl;
            float up[3] = { 0.f, 0.f, 1.f };
            if (fabsf(f[2]) > 0.9f) { up[0] = 0.f; up[1] = 1.f; up[2] = 0.f; }
            float rr[3] = { up[1]*f[2] - up[2]*f[1], up[2]*f[0] - up[0]*f[2], up[0]*f[1] - up[1]*f[0] };
            float rl = sqrtf(rr[0]*rr[0] + rr[1]*rr[1] + rr[2]*rr[2]); if (rl < 1e-4f) rl = 1.f;
            rr[0] /= rl; rr[1] /= rl; rr[2] /= rl;
            const float uu[3] = { f[1]*rr[2] - f[2]*rr[1], f[2]*rr[0] - f[0]*rr[2], f[0]*rr[1] - f[1]*rr[0] };
            const float *LA = s_tl_A[hl], *LB = s_tl_B[hl];
            const float a2x = LA[0]*rr[0] + LA[1]*rr[1] + LA[2]*rr[2], a2y = LA[0]*uu[0] + LA[1]*uu[1] + LA[2]*uu[2];
            const float b2x = LB[0]*rr[0] + LB[1]*rr[1] + LB[2]*rr[2], b2y = LB[0]*uu[0] + LB[1]*uu[1] + LB[2]*uu[2];
            const float la = sqrtf(a2x*a2x + a2y*a2y), lb = sqrtf(b2x*b2x + b2y*b2y), M = la > lb ? la : lb;
            if (M > 1.f) {
                shE[i*4+0] = a2x / M; shE[i*4+1] = a2y / M; shE[i*4+2] = b2x / M; shE[i*4+3] = b2y / M;
                const float st = 2.f * M * tlamp_softk();
                if (st > softi) softi = st;
            }
        }
        /* лампа в видовом пространстве — по ней грани, отвёрнутые от света,
         * тень не получают, и по ней же смещение сравнения по наклону */
        float vx = R[0]*Lr[0] + R[1]*Lr[1] + R[2]*Lr[2] + TR[0];
        float vy = R[3]*Lr[0] + R[4]*Lr[1] + R[5]*Lr[2] + TR[1];
        float vz = R[6]*Lr[0] + R[7]*Lr[1] + R[8]*Lr[2] + TR[2];
        lpos[i*4+0] = D[0]*vx + D[1]*vy + D[2]*vz + T[0];
        lpos[i*4+1] = D[3]*vx + D[4]*vy + D[5]*vz + T[1];
        lpos[i*4+2] = D[6]*vx + D[7]*vy + D[8]*vz + T[2];
        lpos[i*4+3] = rad * fade;      /* где свет лампы сходит на нет — там гаснет и тень */
        par[i*4+0] = str * (wgt[i] / wmax);            /* доля света этой лампы */
        par[i*4+1] = zfar / (zfar - znear);            /* A и B: из глубины карты */
        par[i*4+2] = zfar * znear / (zfar - znear);    /*   обратно в расстояние */
        par[i*4+3] = softi / (2.0f * th);             /* размер источника в UV·расстояние */
        for (int q = 0; q < 3; q++) { s_shcl_min[i][q] = clmin[i][q]; s_shcl_max[i][q] = clmax[i][q]; }   /* 27.09: для дымки */
    }
    const int nlamps = n;
    s_shcl_n = n;

    /* ЛУНА (25.09 вечер): ещё один слой карты — «лампа на бесконечности» по направлению общего света комнаты. Карта
     * нацелена на опору (первый персонаж, с шагом 1500 ед. — не ползёт от каждого шага) и раскрыта на ноги, макушки и концы
     * теней персонажей в 9000 ед. от неё (ступенями по 1000 ед.: шире — сразу, уже — через 2 с). Мягкость — не «размер
     * лампы», а расхождение края на единицу зазора (moon_soft): из PCSS шейдера kp = s·D / (2·tg). */
    if (moon && nch > 0 && n < 4) {
        float m[3];
        if (s_gdir_on) {
            m[0] = s_gdir[0]; m[1] = s_gdir[1]; m[2] = s_gdir[2];
            if (m[1] > 0.f) { m[0] = -m[0]; m[1] = -m[1]; m[2] = -m[2]; }   /* луна над головой: ось Y вниз */
        } else { m[0] = 0.55f; m[1] = -0.77f; m[2] = 0.32f; }
        float ml = sqrtf(m[0]*m[0] + m[1]*m[1] + m[2]*m[2]);
        if (ml < 1e-3f) { m[0] = 0.f; m[1] = -1.f; m[2] = 0.f; ml = 1.f; }
        m[0] /= ml; m[1] /= ml; m[2] /= ml;
        {   const float emin = dc_shadow_par(SHP_MOON_ELEV) * 3.14159265f / 180.f, emax = 85.f * 3.14159265f / 180.f;
            const float el = asinf(fminf(1.f, fmaxf(-1.f, -m[1])));
            const float ec = el < emin ? emin : (el > emax ? emax : el);
            if (ec != el) {
                float hx = m[0], hz = m[2], hl = sqrtf(hx*hx + hz*hz);
                if (hl < 1e-4f) { hx = 1.f; hz = 0.f; hl = 1.f; }
                m[0] = hx / hl * cosf(ec); m[1] = -sinf(ec); m[2] = hz / hl * cosf(ec);
            } }
        const float Q = 1500.f, Dm = 30000.f;
        /* 23.10 (stable): опора - середина всех персонажей, и в карту - все в 16000 от неё (было - Регина и всё в 9000 от неё: тот,
         * кто дальше, оставался без лунной тени, а опора ползла за Региной) */
        float Fx = chx[0], Fz = chz[0];
        if (stable && nch > 1) {
            float x0 = chx[0], x1 = chx[0], z0 = chz[0], z1 = chz[0];
            for (int c = 1; c < nch; c++) { x0 = fminf(x0, chx[c]); x1 = fmaxf(x1, chx[c]); z0 = fminf(z0, chz[c]); z1 = fmaxf(z1, chz[c]); }
            if (x1 - x0 < 30000.f && z1 - z0 < 30000.f) { Fx = 0.5f * (x0 + x1); Fz = 0.5f * (z0 + z1); }
        }
        const float F[3] = { floorf(Fx / Q + 0.5f) * Q, chy[0], floorf(Fz / Q + 0.5f) * Q };
        const float mcut = stable ? 16000.f : 9000.f;
        const float Lm[3] = { F[0] + m[0] * Dm, F[1] + m[1] * Dm, F[2] + m[2] * Dm };
        const float ax[3] = { -m[0], -m[1], -m[2] };
        float need = 0.f, dmin = 1e30f, dmax = 0.f; int np = 0;
        for (int c = 0; c < nch; c++) {
            const float ddx = chx[c] - F[0], ddz = chz[c] - F[2];
            if (ddx*ddx + ddz*ddz > mcut * mcut) continue;
            float t = chh[c] / fmaxf(-m[1], 0.05f); if (t > 6000.f) t = 6000.f;
            const float P[3][3] = { { chx[c], chy[c], chz[c] }, { chx[c], chy[c] - chh[c], chz[c] },
                                    { chx[c] - m[0] * t, chy[c], chz[c] - m[2] * t } };
            for (int k = 0; k < 3; k++) {
                const float vx = P[k][0] - Lm[0], vy = P[k][1] - Lm[1], vz = P[k][2] - Lm[2];
                const float along = vx*ax[0] + vy*ax[1] + vz*ax[2];
                const float d2 = vx*vx + vy*vy + vz*vz;
                const float perp = sqrtf(fmaxf(0.f, d2 - along*along));
                if (perp > need) need = perp;
                if (along < dmin) dmin = along;
                if (along > dmax) dmax = along;
                np++;
            }
        }
        if (np > 0) {
            extern uint64_t s_frame_count;
            static float s_mw = 0.f; static uint64_t s_mw_small = 0;
            float halfw = ceilf((need + 1500.f) / 1000.f) * 1000.f; if (halfw < 5000.f) halfw = 5000.f;
            if (halfw >= s_mw) { s_mw = halfw; s_mw_small = 0; }
            else if (!s_mw_small) s_mw_small = s_frame_count ? s_frame_count : 1u;
            else if (s_frame_count - s_mw_small > 120u) { s_mw = halfw; s_mw_small = 0; }
            const float th = s_mw / Dm;
            float zn = dmin - 3000.f; if (zn < 100.f) zn = 100.f;
            const float zf = dmax + 3000.f;
            const int i = n;
            shadow_build_vp(Lm, F, zn, zf, th, V2R, &vp[i*16]);
            const float vx = R[0]*Lm[0] + R[1]*Lm[1] + R[2]*Lm[2] + TR[0];
            const float vy = R[3]*Lm[0] + R[4]*Lm[1] + R[5]*Lm[2] + TR[1];
            const float vz = R[6]*Lm[0] + R[7]*Lm[1] + R[8]*Lm[2] + TR[2];
            lpos[i*4+0] = D[0]*vx + D[1]*vy + D[2]*vz + T[0];
            lpos[i*4+1] = D[3]*vx + D[4]*vy + D[5]*vz + T[1];
            lpos[i*4+2] = D[6]*vx + D[7]*vy + D[8]*vz + T[2];
            lpos[i*4+3] = 2.5f * Dm;                   /* «радиус» луны: тень не гаснет с расстоянием от источника */
            par[i*4+0] = dc_shadow_par(SHP_MOON_STR);
            {   /* 01.10: комната из DC_SHADOW_DIR_ROOMS (свет комнаты — главный свет персонажей, тень вместо диска игры): сила как
                 * у тени, а не как у слабой луны — DC_SHADOW_DIR_STR (0.6); правка moon_str на комнату в F8 главнее */
                const int rr3 = dc_room_effective();
                if (!moon_light_room(rr3) && !dc_shadow_par_room_has(SHP_MOON_STR, rr3)) {
                    static float dstr = -1.f;
                    if (dstr < 0.f) { const char *e = getenv("DC_SHADOW_DIR_STR"); dstr = e ? (float)atof(e) : 0.6f; if (dstr < 0.f) dstr = 0.f; }
                    par[i*4+0] = dstr;
                } }
            par[i*4+1] = zf / (zf - zn);
            par[i*4+2] = zf * zn / (zf - zn);
            par[i*4+3] = dc_shadow_par(SHP_MOON_SOFT) * Dm / (2.0f * th);
            {   /* свет луны: направление на неё в видовое пространство (без сдвига), цвет — общего света комнаты */
                extern void dcvk_moon_set(const float *dir, const float *col, float layer, float wrap);
                const float ux = R[0]*m[0] + R[1]*m[1] + R[2]*m[2];
                const float uy = R[3]*m[0] + R[4]*m[1] + R[5]*m[2];
                const float uz = R[6]*m[0] + R[7]*m[1] + R[8]*m[2];
                float dv[3] = { D[0]*ux + D[1]*uy + D[2]*uz, D[3]*ux + D[4]*uy + D[5]*uz, D[6]*ux + D[7]*uy + D[8]*uz };
                const float dl = sqrtf(dv[0]*dv[0] + dv[1]*dv[1] + dv[2]*dv[2]);
                if (dl > 1e-4f) { dv[0] /= dl; dv[1] /= dl; dv[2] /= dl; }
                float mc[3] = { 0.75f, 0.85f, 1.0f };
                if (s_gdir_on) {
                    float mx = s_gdircol[0]; if (s_gdircol[1] > mx) mx = s_gdircol[1]; if (s_gdircol[2] > mx) mx = s_gdircol[2];
                    if (mx > 8.f) { mc[0] = s_gdircol[0] / mx; mc[1] = s_gdircol[1] / mx; mc[2] = s_gdircol[2] / mx; }
                }
                const float kl = moon_light_room(dc_room_effective()) ? dc_shadow_par(SHP_MOON_LIGHT) : 0.f;   /* 01.10: без неба — только тень */
                const float col[3] = { mc[0] * kl, mc[1] * kl, mc[2] * kl };
                /* обтекание 0.2; 27.09 вечер: знак — луна на персонажах ровно (+) или по граням, как было (−1 − обтекание) */
                dcvk_moon_set(dv, col, (float)i, dc_shadow_par(SHP_MOON_CHR) > 0.5f ? 0.2f : -1.2f);
            }
            {   /* 25.09 ночь: луна гладкой тенью — шаг размытия в текселях ужатой карты (σ = 3 шага): поле луны ±s_mw на
                 * dcvk_moon_pf_res() текселей, край размыт на moon_blur единиц комнаты */
                extern void dcvk_moon_pf(int on, float step, float gapFull, float bias, float softZ);
                extern int dcvk_moon_pf_res(void);
                const float texw = 2.f * s_mw / (float)(dcvk_moon_pf_res() > 0 ? dcvk_moon_pf_res() : 1024);
                float step = dc_shadow_par(SHP_MOON_BLUR) / (3.f * texw);
                if (step < 0.f) step = 0.f; if (step > 8.f) step = 8.f;
                dcvk_moon_pf(dc_shadow_par(SHP_MOON_PF) > 0.5f, step, 1500.f, 40.f, 80.f);
            }
            n++;
            { static int lr = -2; static long nl = 0; const int rr2 = dc_room_effective();
              if (rr2 != lr || (++nl % 1800) == 0) { lr = rr2;
                  fprintf(stderr, "shadow: MOON in room %d (%s) - towards the moon %.2f,%.2f,%.2f (elevation %.0f deg, %s), strength %.2f, field +-%.0f units%c",
                          rr2, dc_room_name(rr2), m[0], m[1], m[2], asinf(-m[1]) * 57.29578f,
                          s_gdir_on ? "by the room's ambient light" : "the room's light is not set - our own",
                          par[i*4+0], s_mw, 10); } }
        }
    }

    s_blob_live = 1;                 /* наша тень в этом кадре дорисована */

    /* параметры проекции (центр и сдвиг области рисования) добирает сам растр:
     * только там сдвиг известен на момент кадра */
    /* radk/fade: в шейдере даёт радиус, в котором игра считает лампу для
     * объекта — дальше него персонаж в её карту не попадает, иначе у него
     * появляется тень от чужой лампы (игрок: «вторая тень при подходе») */
    /* ⭐ гаснет тень РАНЬШЕ, чем лампа вылетает из набора: иначе на отдалении
     * тень пропадала скачком и дальше вспыхивала от следующей лампы
     * (игрок, 18.09 вечер) */
    shwhy(5);
    { static int fd = -1; static long nf = 0;
      if (fd < 0) { const char *e = getenv("DC_SHCAM_DBG"); fd = (e && *e == '1') ? 1 : 0; }
      extern uint64_t s_frame_count;
      if (fd && s_ocl_cnt > 0 && (++nf % 20) == 1) {
          for (int c = 0; c < s_ocl_cnt && c < 3; c++) {
              const float fp[3] = { s_ocl_c[c][0], s_ocl_c[c][1], s_ocl_c[c][2] };
              const float vx = R[0]*fp[0] + R[1]*fp[1] + R[2]*fp[2] + TR[0];
              const float vy = R[3]*fp[0] + R[4]*fp[1] + R[5]*fp[2] + TR[1];
              const float vz = R[6]*fp[0] + R[7]*fp[1] + R[8]*fp[2] + TR[2];
              const float ex = D[0]*vx + D[1]*vy + D[2]*vz + T[0];
              const float ey = D[3]*vx + D[4]*vy + D[5]*vz + T[1];
              const float ez = D[6]*vx + D[7]*vy + D[8]*vz + T[2];
              float cl[4];
              for (int r2 = 0; r2 < 4; r2++) cl[r2] = vp[0 + r2] * ex + vp[4 + r2] * ey + vp[8 + r2] * ez + vp[12 + r2];
              /* и обратно: видовая точка -> комната через V2R (должна вернуть центр группы) */
              const float bx = V2R[0]*ex + V2R[4]*ey + V2R[8]*ez + V2R[12];
              const float by = V2R[1]*ex + V2R[5]*ey + V2R[9]*ez + V2R[13];
              const float bz = V2R[2]*ex + V2R[6]*ey + V2R[10]*ez + V2R[14];
              fprintf(stderr, "uvdbg: f=%llu group %d room %.0f,%.0f,%.0f view %.0f,%.0f,%.0f -> clip w %.0f uv %.3f,%.3f z %.3f | back %.0f,%.0f,%.0f%c",
                      (unsigned long long)s_frame_count, c, fp[0], fp[1], fp[2], ex, ey, ez, cl[3],
                      cl[3] != 0.f ? cl[0] / cl[3] * 0.5f + 0.5f : -9.f, cl[3] != 0.f ? cl[1] / cl[3] * 0.5f + 0.5f : -9.f,
                      cl[3] != 0.f ? cl[2] / cl[3] : -9.f, bx, by, bz, 10);
          } } }
    { extern void dcvk_shadow_shape(const float *e16, int n); dcvk_shadow_shape(shE, nlamps); }   /* 27.09: форма мягкости */
    dcvk_shadow_set(vp, par, lpos, n, bias, (float)dbg, (float)self_sh,
                    dc_shadow_par(SHP_LOSS) / fade, spread / fade);
    if (v2) {   /* 27.09 (2): новый путь — доля света, полуоси полутени, лампы без своего слоя; слои ламп — в пирамиду */
        extern void dcvk_shadow_v2(int on, float amb, float bias, float tw, float wrap, const float *pow4, const float *ax16,
                                   int mask, const float *lp32, const float *lw8, int nlo);
        dcvk_shadow_v2(1, dc_shadow_par(SHP_AMB), bias, 80.f, 0.2f, v2pow, v2ax, v2mask, v2lp, v2lw, v2nlo);
        static long nl2 = 0; static int lastm = -1;
        if (v2mask != lastm || (++nl2 % 600) == 1) {
            lastm = v2mask;
            fprintf(stderr, "shadow v2: %d lamp layers (mask %X)%s, lamps only in the light share %d, ambient light %.2f:%c",
                    nlamps, v2mask, moon ? " + moon" : "", v2nlo, dc_shadow_par(SHP_AMB), 10);
            for (int L = 0; L < nlamps && L < 4; L++)
                if (s_v2on[L])
                    fprintf(stderr, "   layer %d: %s%02d%s at %.0f,%.0f,%.0f radius %.0f light strength %.2f fade-in %.2f -> shadow %.2f | half-axes %.0f x %.0f (UV*dist)%c",
                            L, tex ? "T" : "G", s_v2hd[L], s_v2pt[L] ? " (a spot above the character)" : "",
                            s_v2p[L][0], s_v2p[L][1], s_v2p[L][2], s_v2r[L], s_v2w[L], s_v2f[L],
                            par[L*4+0], sqrtf(v2ax[L*4]*v2ax[L*4] + v2ax[L*4+1]*v2ax[L*4+1]),
                            sqrtf(v2ax[L*4+2]*v2ax[L*4+2] + v2ax[L*4+3]*v2ax[L*4+3]), 10);
        }
        /* 23.10: DC_SHADOW_TRACE=1 - строка на кадр: слои (лампа, место, появление, сила тени, раскрытие и ось карты, чей) и лампы
         * доли света - проверка, что тень стоящего персонажа не зависит от шагов Регины */
        { static int tr = -1; if (tr < 0) { const char *e = getenv("DC_SHADOW_TRACE"); tr = (e && *e == '1') ? 1 : 0; }
          if (tr) {
              extern uint64_t s_frame_count;
              fprintf(stderr, "shtrace: f=%llu regina %.0f,%.0f chars %d stable %d |", (unsigned long long)s_frame_count, px, pz, nch, stable);
              for (int L = 0; L < nlamps && L < 4; L++)
                  if (s_v2on[L]) {
                      const int ri = GLAMP_MAX + L;
                      fprintf(stderr, " L%d %s%02d at %.0f,%.0f,%.0f in %.2f str %.3f half %.1f ax %.2f,%.2f,%.2f who %d;", L, tex ? "T" : "G",
                              s_v2hd[L], s_v2p[L][0], s_v2p[L][1], s_v2p[L][2], s_v2f[L], par[L*4+0], s_rf_half[ri] * 57.2958f,
                              s_rf_ax[ri][0], s_rf_ax[ri][1], s_rf_ax[ri][2], s_v2own[L]);
                  }
              fprintf(stderr, " | share");
              for (int j = 0; j < v2nlo; j++) fprintf(stderr, " %s%02d/%.2f", tex ? "T" : "G", idx[shk[j]], v2lw[j]);
              fprintf(stderr, "%c", 10);
          } }
    }
    /* ЗАМЕР (18.09 вечер): куда по нашей математике попадают ноги персонажа
     * в карте первой лампы — сверяется с тем, что видит шейдер (DC_SHADOW_DBG=5/6) */
    { static long c2 = 0;
      if ((++c2 % 300) == 1) {
          float fp[3] = { px, py, pz };
          float vx = R[0]*fp[0] + R[1]*fp[1] + R[2]*fp[2] + TR[0];
          float vy = R[3]*fp[0] + R[4]*fp[1] + R[5]*fp[2] + TR[1];
          float vz = R[6]*fp[0] + R[7]*fp[1] + R[8]*fp[2] + TR[2];
          float ex = D[0]*vx + D[1]*vy + D[2]*vz + T[0];
          float ey = D[3]*vx + D[4]*vy + D[5]*vz + T[1];
          float ez = D[6]*vx + D[7]*vy + D[8]*vz + T[2];
          float cl[4];
          for (int r2 = 0; r2 < 4; r2++)
              cl[r2] = vp[0 + r2] * ex + vp[4 + r2] * ey + vp[8 + r2] * ez + vp[12 + r2];
          float sx = (cl[3] != 0.f) ? (cl[0]/cl[3] * 0.5f + 0.5f) : -1.f;
          float sy = (cl[3] != 0.f) ? (cl[1]/cl[3] * 0.5f + 0.5f) : -1.f;
          float sz = (cl[3] != 0.f) ? (cl[2]/cl[3]) : -1.f;
          fprintf(stderr, "shadowchk: feet room=%.0f,%.0f,%.0f view=%.0f,%.0f,%.0f -> uv %.3f,%.3f z %.3f | scr=%.0f,%.0f w=%.0f%c",
                  fp[0], fp[1], fp[2], ex, ey, ez, sx, sy, sz,
                  g_pt_proj_ofx + g_pt_proj_h * ex / ez * dc_ws_sq(),
                  g_pt_proj_ofy + g_pt_proj_h * ey / ez, ez, 10);
      } }
    { static long cnt = 0; static int last = -1;
      const int i0 = (nc > 0 && nlamps > 0) ? idx[0] : -1;
      if (i0 != last || (++cnt % 600) == 1) { last = i0;
          fprintf(stderr, "shadow: %d lamp(s)%s, debug %d, occluders %d (Regina %ld, others %ld):%c",
                  n, gamerule ? " (as the game has it)" : "", dbg, s_occ_n, s_occ_kind[1], s_occ_kind[2], 10);
          fprintf(stderr, "   of the 'others': semi-transparent %ld, without depth %ld%c", s_occ_semi, s_occ_now, 10);
          s_occ_kind[1] = s_occ_kind[2] = 0; s_occ_semi = s_occ_now = 0;
          for (int i = 0; i < nlamps && !v2; i++)          /* 27.09 (2): новый путь пишет свои строки «shadow v2:» */
              fprintf(stderr, "   G%02d%s at %.0f,%.0f,%.0f dist %.0f rad %.0f -> strength %.2f | field %.0f deg on %d chars%c",
                      idx[i], clnm[i] > 1 ? (clnm[i] == 2 ? " +1 lamp nearby (one shadow)" : clnm[i] == 3 ? " +2 lamps nearby (one shadow)"
                                                                                           : " + lamps nearby (one shadow)") : "",
                      clp[i][0], clp[i][1], clp[i][2],
                      dst[i], clrad[i], par[i*4+0],
                      (reach ? (double)s_reach_half[idx[i]] : (double)atanf(tanhalf)) * 2.0 * 57.29578,
                      reach ? s_reach_np[idx[i]] : 1, 10); } }
}

/* ===== ВСПЫШКИ ВЫСТРЕЛОВ И ВЗРЫВОВ КАК НАСТОЯЩИЙ СВЕТ (25.09.2026) =====================================================
 * Игрок: «вспышка выстрела и взрыва как настоящий свет: на кадр-два освещает стены, пол и Регину». Выстрел — списание
 * патрона (dc_ammo_write_note: один store, уменьшивший счётчик на 1, — ушёл заряд, любое оружие), взрыв — конец гранаты
 * (dc_grenade_tick: запись перестала быть живой гранатой). Свет — точечный источник в видовом пространстве растра (блок
 * ShadowUBO, поля flp/flc, dc_raster.frag): фрагмент получает альбедо × свет со спадом (1 − d/R)² и по нормали из
 * производных (грань, отвёрнутая от вспышки, почти не светится; «обтекание» — сколько света заходит за край). Свет
 * складывается ПОСЛЕ теней ламп — это другой источник. Своей тени у вспышки нет. Где вспышка: выстрел — правая кисть
 * (узел 3 скелета Регины, мировая позиция int32 ×3 с 0xB9500) + вперёд по её курсу; взрыв — точка удара гранаты,
 * отнесённая от поверхности по нормали. Параметры — таблица «Картинки», группа 1 (dc_post_user.cfg, F8 «Вспышки…»);
 * DC_FLASH=0 — выключить; DC_FLASH_DBG=1 — строка на каждую вспышку и кадры её света. */
static struct { int on, kind; double t0; float p[3], mul, radk; } s_fl;
static float s_fl_view[3];
static int   s_fl_view_ok = 0;
static double fl_now_ms(void) {
    static LARGE_INTEGER f = { 0 };
    LARGE_INTEGER c;
    if (!f.QuadPart) QueryPerformanceFrequency(&f);
    QueryPerformanceCounter(&c);
    return (double)c.QuadPart * 1000.0 / (double)f.QuadPart;
}
static float fl_par(const char *key, int *idx) {
    extern int dcvk_post_par_find(const char *key); extern float dcvk_post_par(int i);
    if (*idx == -2) *idx = dcvk_post_par_find(key);
    return (*idx >= 0) ? dcvk_post_par(*idx) : 0.f;
}
static int fl_dbg(void) { static int d = -1; if (d < 0) { const char *e = getenv("DC_FLASH_DBG"); d = (e && *e == '1') ? 1 : 0; } return d; }
static int s_fi_on = -2, s_fi_sstr = -2, s_fi_srad = -2, s_fi_sms = -2, s_fi_bstr = -2, s_fi_brad = -2, s_fi_bms = -2, s_fi_wrap = -2,
           s_fi_sync = -2;
/* выстрел взведён: ждём спрайт вспышки игры (fl_sync), см. dc_flash_sprite_note */
static struct { int on, kind; uint32_t cell; double t0; float p[3]; } s_fl_arm;   /* kind 0 выстрел, 1 взрыв (точка p) */
int dc_flash_on(void) { return fl_par("fl_on", &s_fi_on) > 0.5f; }

/* огибающая 0..1: выстрел — ровная вершина четверть времени и быстрый спад; взрыв — короткий подъём, долгий спад и мерцание */
static float fl_level(int kind, double t) {
    const float dur = kind ? fl_par("fl_boom_ms", &s_fi_bms) : fl_par("fl_shot_ms", &s_fi_sms);
    if (t < 0.0 || dur < 1.f || t >= dur) return 0.f;
    const float x = (float)t / dur;
    if (kind == 0) { if (x < 0.25f) return 1.f; const float y = 1.f - (x - 0.25f) / 0.75f; return y * y; }
    const float rise = (t < 25.0) ? (0.5f + 0.5f * (float)t / 25.f) : 1.f;                 /* вспыхивает за 25 мс */
    const float fall = (x < 0.15f) ? 1.f : powf(1.f - (x - 0.15f) / 0.85f, 1.6f);          /* держится, потом гаснет */
    const float flick = 0.9f + 0.1f * sinf((float)t * 0.095f) * sinf((float)t * 0.031f + 1.3f);   /* лёгкое мерцание огня */
    return rise * fall * flick;
}
static void fl_fire(int kind, const float p[3], float mul, float radk, const char *what) {
    if (!dc_flash_on()) return;
    const double now = fl_now_ms();
    /* одна вспышка разом: новая сменяет прежнюю, но выстрел не гасит ещё яркий взрыв */
    if (s_fl.on && s_fl.kind == 1 && kind == 0 && fl_level(1, now - s_fl.t0) > 0.35f) return;
    s_fl.on = 1; s_fl.kind = kind; s_fl.t0 = now; s_fl.mul = mul; s_fl.radk = radk;
    for (int i = 0; i < 3; i++) s_fl.p[i] = p[i];
    s_fl_view_ok = 0;
    { static long n = 0;
      if (fl_dbg() || ++n <= 40)
          fprintf(stderr, "flash: %s at %.0f,%.0f,%.0f (x%.2f)%c", what, p[0], p[1], p[2], mul, 10); }
}
/* выстрел: cell — ячейка патронов, у которой убыл заряд (0xB94D0 дробовик, 0xB94D2 пистолет, 0xB94D4 гранатомёт) */
static void fl_shot_now(uint32_t cell) {
    const uint8_t *r = memory_get_ram_ptr(); if (!r) return;
    float mul = 1.f, radk = 1.f, fwd = 230.f; const char *what = "shot (handgun)";
    if (cell == 0xB94D0u) {
        if ((uint8_t)(r[0xB94D1] - 2u) < 4u) { mul = 0.45f; radk = 0.8f; fwd = 380.f; what = "shot (dart)"; }
        else                                 { mul = 1.4f;  radk = 1.2f; fwd = 380.f; what = "shot (shotgun)"; }
    } else if (cell == 0xB94D4u)             { mul = 1.2f;  radk = 2.2f; fwd = 330.f; what = "shot (grenade launcher)"; }
    /* 25.09 вечер (игрок): радиус выстрела вдвое меньше (fl_shot_rad 4500 -> 2250), у гранатомёта — как был (x1.1 -> x2.2) */
    /* дуло: правая кисть + вперёд по курсу; кисть проверяем на здравость (рядом с Региной), иначе — грудь */
    const float rx = (float)rrm_s16(r, 0xB92ACu), ry = (float)rrm_s16(r, 0xB92AEu), rz = (float)rrm_s16(r, 0xB92B0u);
    const uint32_t nb = 0xB9500u + 3u * 172u;
    float p[3] = { (float)(int32_t)rrm_u32(r, nb), (float)(int32_t)rrm_u32(r, nb + 4u), (float)(int32_t)rrm_u32(r, nb + 8u) };
    { const float dx = p[0] - rx, dy = p[1] - ry, dz = p[2] - rz;
      if (dx * dx + dy * dy + dz * dz > 2500.f * 2500.f) { p[0] = rx; p[1] = ry - 1300.f; p[2] = rz; } }
    const float h = (float)(rrm_s16(r, 0xB92B6u) & 0xFFF) * (6.2831853f / 4096.f);
    p[0] += sinf(h) * fwd; p[2] += cosf(h) * fwd;
    fl_fire(0, p, mul, radk, what);
}
/* ⭐ 25.09: свет — ВМЕСТЕ со спрайтом вспышки игры. Патрон списывается в начале анимации выстрела, а звезда у ствола
 * появляется позже (пистолет: +6 показанных кадров, ~100 мс; замер DC_PRESDUMP, слот 1) — свет на списании опережал её.
 * Теперь списание только взводит, а зажигает первый прямоугольник со страницы эффектов игры (896,256) — оттуда рисуются
 * звезда выстрела и огонь взрыва (dc_flash_sprite_note из gpu.c). Ждём до 400 мс; спрайта нет (дротик) — света нет.
 * fl_sync = 0 (DC_FLASH_SYNC=0) — в момент списания, как было. */
void dc_flash_shot(uint32_t cell) {
    const uint8_t *r = memory_get_ram_ptr(); if (!r) return;
    if (r[0xB7878] != 3) return;                                  /* только экран мира (не меню) */
    if (!dc_flash_on()) return;
    if (fl_par("fl_sync", &s_fi_sync) > 0.5f) {
        s_fl_arm.on = 1; s_fl_arm.kind = 0; s_fl_arm.cell = cell; s_fl_arm.t0 = fl_now_ms();
        if (fl_dbg()) fprintf(stderr, "flash: armed by the shot (cell %05X), waiting for the game's flash sprite%c", cell, 10);
        return;
    }
    fl_shot_now(cell);
}
/* gpu.c: текстурные прямоугольники (GP0 0x64/0x7C) и многоугольники (FT3/FT4/GT3/GT4) со страницы эффектов (896,256) — tp =
 * страница текстуры, w/h — размер (у многоугольника — по UV). Звезда = элемент, которого не было до выстрела, от 12 текселей
 * (замер, слот 1, пистолет: постоянные UV 0,72 47x47 и 0,120 7x15 каждый кадр; звезда UV 48,88 23x23 x5 через ~97 мс;
 * искры 7x7 — мелкие). Привязки к UV нет — годится для любого ствола. */
void dc_flash_sprite_note(int tp, int u, int v, int w, int h, int semi) {
    const int px = (tp & 15) * 64, py = ((tp >> 4) & 1) * 256;
    if (px != 896 || py != 256) return;                   /* только страница эффектов игры */
    /* что на странице рисуется ПОСТОЯННО (свечения, гильзы на полу…): ключ UV+размер, первое и последнее появление */
    enum { FK = 48 };
    static struct { uint32_t key; double first, last; } k_[FK];
    static int kn = 0;
    const double now = fl_now_ms();
    const uint32_t key = ((uint32_t)u & 255u) | (((uint32_t)v & 255u) << 8) | (((uint32_t)w & 255u) << 16) | (((uint32_t)h & 255u) << 24);
    int i = 0;
    for (; i < kn; i++) if (k_[i].key == key) break;
    if (i == kn) {
        if (kn < FK) kn++;
        else { int o = 0; for (int j = 1; j < FK; j++) if (k_[j].last < k_[o].last) o = j; i = o; }
        k_[i].key = key; k_[i].first = now; k_[i].last = now;
    } else {
        if (now - k_[i].last > 100.0) k_[i].first = now;   /* перерыв — снова «новый» */
        k_[i].last = now;
    }
    if (!s_fl_arm.on) return;
    const double t = now - s_fl_arm.t0;
    if (t > 400.0) {
        s_fl_arm.on = 0;
        { static long n = 0; if (fl_dbg() || ++n <= 20) fprintf(stderr, "flash: no game flash sprite within 400 ms - no light%c", 10); }
        return;
    }
    const int fresh = (k_[i].first >= s_fl_arm.t0 - 1.0);
    const int hit = fresh && w >= 12 && h >= 12;
    if (fl_dbg()) fprintf(stderr, "flash: page 896,256 uv %d,%d %dx%d semi %d at +%.0f ms %s%s%c", u, v, w, h, semi, t,
                          fresh ? "new" : "old", hit ? " -> LIGHT" : "", 10);
    if (!hit) return;
    s_fl_arm.on = 0;
    if (s_fl_arm.kind == 1) fl_fire(1, s_fl_arm.p, 1.f, 1.f, "grenade explosion (with the game's fire)");
    else fl_shot_now(s_fl_arm.cell);
}
/* взрыв гранаты в точке p комнаты: с fl_sync — ждём огонь взрыва игры (облако появляется на 3-4 кадра позже конца гранаты) */
void dc_flash_boom(const float p[3]) {
    if (!dc_flash_on()) return;
    if (fl_par("fl_sync", &s_fi_sync) > 0.5f) {
        s_fl_arm.on = 1; s_fl_arm.kind = 1; s_fl_arm.t0 = fl_now_ms();
        for (int i = 0; i < 3; i++) s_fl_arm.p[i] = p[i];
        if (fl_dbg()) fprintf(stderr, "flash: armed by the grenade's end at %.0f,%.0f,%.0f, waiting for the game's fire%c", p[0], p[1], p[2], 10);
        return;
    }
    fl_fire(1, p, 1.f, 1.f, "grenade explosion");
}
/* F8: пробная вспышка — выстрел у кисти или взрыв в 1800 ед. перед Региной */
void dc_flash_test(int kind) {
    const uint8_t *r = memory_get_ram_ptr(); if (!r) return;
    if (!kind) { fl_shot_now(0xB94D2u); return; }
    const float h = (float)(rrm_s16(r, 0xB92B6u) & 0xFFF) * (6.2831853f / 4096.f);
    const float p[3] = { (float)rrm_s16(r, 0xB92ACu) + sinf(h) * 1800.f, (float)rrm_s16(r, 0xB92AEu) - 400.f,
                         (float)rrm_s16(r, 0xB92B0u) + cosf(h) * 1800.f };
    fl_fire(1, p, 1.f, 1.f, "test explosion");
}
/* каждый показанный кадр: frameA = 1 перед dcvk_render (точка вспышки пересчитывается в вид этого кадра),
 * 0 перед кадром B (точка та же — её вершины и карта в пространстве кадра A, меняется только яркость) */
void dc_flash_frame(int frameA) {
    extern void dcvk_flash_set(const float *pos, float rad, const float *col, float wrap);
    static const float SHOT_COL[3] = { 1.00f, 0.80f, 0.52f }, BOOM_COL[3] = { 1.00f, 0.62f, 0.30f };
    { static int ep = -1; const int e = dc_light_epoch();          /* 19.10: вспышка прежней комнаты или мира до загрузки */
      if (e != ep) { ep = e; s_fl.on = 0; s_fl_arm.on = 0; s_fl_view_ok = 0; } }
    if (s_fl_arm.on) {
        const double ta = fl_now_ms() - s_fl_arm.t0;
        if (s_fl_arm.kind == 1 && ta > 250.0) {                /* взрыв светит всегда: огня игры не видно — сами */
            s_fl_arm.on = 0; fl_fire(1, s_fl_arm.p, 1.f, 1.f, "grenade explosion (no fire sprite seen)"); }
        else if (ta > 400.0) s_fl_arm.on = 0;                 /* выстрел взведён, а вспышки так и не было (дротик) */
    }
    if (!s_fl.on) { dcvk_flash_set(0, 0.f, 0, 0.f); return; }
    const double t = fl_now_ms() - s_fl.t0;
    const float lv = fl_level(s_fl.kind, t);
    if (lv <= 0.002f || !dc_flash_on()) { s_fl.on = 0; s_fl_view_ok = 0; dcvk_flash_set(0, 0.f, 0, 0.f); return; }
    if (frameA || !s_fl_view_ok) {
        const uint8_t *ram = memory_get_ram_ptr();
        float D[9], T[3], R[9], TR[3];
        if (!ram || !sh_camera(ram, 1, D, T, R, TR, 0)) { s_fl_view_ok = 0; dcvk_flash_set(0, 0.f, 0, 0.f); return; }
        const float *p = s_fl.p;
        const float vx = R[0]*p[0] + R[1]*p[1] + R[2]*p[2] + TR[0];
        const float vy = R[3]*p[0] + R[4]*p[1] + R[5]*p[2] + TR[1];
        const float vz = R[6]*p[0] + R[7]*p[1] + R[8]*p[2] + TR[2];
        s_fl_view[0] = D[0]*vx + D[1]*vy + D[2]*vz + T[0];
        s_fl_view[1] = D[3]*vx + D[4]*vy + D[5]*vz + T[1];
        s_fl_view[2] = D[6]*vx + D[7]*vy + D[8]*vz + T[2];
        s_fl_view_ok = 1;
    }
    const int k = s_fl.kind;
    const float I = lv * s_fl.mul * (k ? fl_par("fl_boom_str", &s_fi_bstr) : fl_par("fl_shot_str", &s_fi_sstr));
    const float rad = s_fl.radk * (k ? fl_par("fl_boom_rad", &s_fi_brad) : fl_par("fl_shot_rad", &s_fi_srad));
    const float *base = k ? BOOM_COL : SHOT_COL;
    const float col[3] = { base[0] * I, base[1] * I, base[2] * I };
    dcvk_flash_set(s_fl_view, rad, col, fl_par("fl_wrap", &s_fi_wrap));
    if (fl_dbg()) fprintf(stderr, "flash: t=%.0f ms level %.2f I %.2f rad %.0f view %.0f,%.0f,%.0f %s%c",
                          t, lv, I, rad, s_fl_view[0], s_fl_view[1], s_fl_view[2], frameA ? "A" : "B", 10);
}
/* 25.10.2026: кадры между тактами в потоке показа (main.cpp DC_PRESENT_THREAD) - вспышка снимком. Главный поток после показа
 * кадра такта снимает её (dc_flash_take), поток показа ставит яркость на свой миг (dc_flash_put): s_fl и память игры он не
 * трогает, их в это время пишет эмуляция следующего такта. Точка - в виде кадра A, как у кадра B. */
void dc_flash_take(double o[9]) {
    o[0] = s_fl.on; o[1] = s_fl.kind; o[2] = s_fl.t0; o[3] = s_fl.mul; o[4] = s_fl.radk; o[5] = s_fl_view_ok;
    o[6] = s_fl_view[0]; o[7] = s_fl_view[1]; o[8] = s_fl_view[2];
}
void dc_flash_put(const double o[9]) {
    extern void dcvk_flash_set(const float *pos, float rad, const float *col, float wrap);
    static const float SHOT_COL[3] = { 1.00f, 0.80f, 0.52f }, BOOM_COL[3] = { 1.00f, 0.62f, 0.30f };
    const int k = (int)o[1];
    const float lv = (o[0] != 0.0 && o[5] != 0.0) ? fl_level(k, fl_now_ms() - o[2]) : 0.f;
    if (lv <= 0.002f || !dc_flash_on()) { dcvk_flash_set(0, 0.f, 0, 0.f); return; }
    const float view[3] = { (float)o[6], (float)o[7], (float)o[8] };
    const float I = lv * (float)o[3] * (k ? fl_par("fl_boom_str", &s_fi_bstr) : fl_par("fl_shot_str", &s_fi_sstr));
    const float rad = (float)o[4] * (k ? fl_par("fl_boom_rad", &s_fi_brad) : fl_par("fl_shot_rad", &s_fi_srad));
    const float *base = k ? BOOM_COL : SHOT_COL;
    const float col[3] = { base[0] * I, base[1] * I, base[2] * I };
    dcvk_flash_set(view, rad, col, fl_par("fl_wrap", &s_fi_wrap));
}

/* ===== ЛАМПЫ ИГРЫ ДЛЯ БЛИКОВ МАТЕРИАЛОВ (25.09 ночь) =====================================================================
 * Игрок (слот 13, ST108): «материал металла кажется не работает» — металлом отмечена кодовая панель на стене, а материал
 * давал только отражение на полу. Теперь у поверхности с материалом есть блик (dc_raster.frag «БЛИКИ МАТЕРИАЛОВ»); его
 * источники — лампы таблицы игры (ctx+348, те же, что у теней): до 4 самых заметных возле Регины (яркость × близость в
 * полтора радиуса лампы), точка — в вид этого кадра через ту же камеру, что у теней (sh_camera), цвет — цвет лампы
 * (128 = белый, x4 у игры) / 160. Зовётся из main.cpp в кадре A. */
void dc_spec_frame(void) {
    extern void dcvk_spec_lamps(const float *pos4, const float *col4, int n);
    extern void dcvk_spec_up(const float *up, int ok);
    const uint8_t *ram = memory_get_ram_ptr();
    float D[9], T[3], R[9], TR[3]; int gc = 0;
    if (!ram || !dc_room_live_on() || !dcvk_enabled() || !sh_camera(ram, 0, D, T, R, TR, &gc)) { dcvk_spec_lamps(0, 0, 0); dcvk_spec_up(0, 0); return; }
    {   /* «вверх» комнаты (ось Y игры вниз) в видовое пространство кадра — для отблеска окружения */
        const float up[3] = { -R[1], -R[4], -R[7] };
        float n[3] = { D[0]*up[0] + D[1]*up[1] + D[2]*up[2], D[3]*up[0] + D[4]*up[1] + D[5]*up[2], D[6]*up[0] + D[7]*up[1] + D[8]*up[2] };
        const float nl = sqrtf(n[0]*n[0] + n[1]*n[1] + n[2]*n[2]);
        if (nl > 1e-4f) { n[0] /= nl; n[1] /= nl; n[2] /= nl; dcvk_spec_up(n, 1); } else dcvk_spec_up(0, 0);
    }
    if (glamp_check_on()) glamp_refresh();
    else { static uint32_t sig = 0; const uint32_t s2 = rrm_signature(ram); if (s2 != sig) { sig = s2; glamp_read(); } }
    /* 19.10.2026 (игрок: «увеличь дальность бликов материалов»): лампы брались только у Регины (в полутора радиусах от неё), и
     * блики на дальних поверхностях у их собственных ламп гасли, стоило ей отойти. Теперь важность лампы - большая из двух: у
     * Регины (как было) и у камеры. Блик лампы виден на поверхностях в её полутора радиусах: камера внутри этой сферы - лампа
     * важна вся, дальше - по углу, под которым сфера видна; сфера целиком позади камеры или в стороне от взгляда (больше 60° от
     * оси) - не берётся. Состав меняется плавно: лампа разгорается и гаснет за ~0.2 с (s_spf, цвет × доля), у горящей запас
     * ×1.3 - равные не перещёлкиваются; новая комната или загрузка - с нуля. DC_SPEC_NEAR=1 - только у Регины, как было. */
    if (s_glamp_n <= 0) { dcvk_spec_lamps(0, 0, 0); return; }
    static float s_spf[GLAMP_MAX]; static int s_spf_ep = -1, near_only = -1;
    if (near_only < 0) { const char *e = getenv("DC_SPEC_NEAR"); near_only = (e && *e == '1') ? 1 : 0; }
    if (s_spf_ep != dc_light_epoch()) { s_spf_ep = dc_light_epoch(); memset(s_spf, 0, sizeof s_spf); }
    const float fx = (float)rrm_s16(ram, 0xB92ACu), fy = (float)rrm_s16(ram, 0xB92AEu), fz = (float)rrm_s16(ram, 0xB92B0u);
    const int nl = s_glamp_n < GLAMP_MAX ? s_glamp_n : GLAMP_MAX;
    float score[GLAMP_MAX], vp[GLAMP_MAX][3];
    for (int i = 0; i < nl; i++) {
        const GameLamp *L = &s_glamp[i];
        score[i] = 0.f;
        {   const float vx = R[0]*L->p[0] + R[1]*L->p[1] + R[2]*L->p[2] + TR[0];
            const float vy = R[3]*L->p[0] + R[4]*L->p[1] + R[5]*L->p[2] + TR[1];
            const float vz = R[6]*L->p[0] + R[7]*L->p[1] + R[8]*L->p[2] + TR[2];
            vp[i][0] = D[0]*vx + D[1]*vy + D[2]*vz + T[0];
            vp[i][1] = D[3]*vx + D[4]*vy + D[5]*vz + T[1];
            vp[i][2] = D[6]*vx + D[7]*vy + D[8]*vz + T[2]; }
        if (!L->on || !(L->rad > 0.f)) continue;
        const float reach = 1.5f * L->rad;
        float br = L->col[0]; if (L->col[1] > br) br = L->col[1]; if (L->col[2] > br) br = L->col[2];
        const float dx = L->p[0] - fx, dy = L->p[1] - fy, dz = L->p[2] - fz;
        const float d = sqrtf(dx*dx + dy*dy + dz*dz);
        float s = (d < reach) ? (br / 128.f) * (1.f - d / reach) : 0.f;            /* у Регины - как было */
        if (!near_only) {
            const float dc = sqrtf(vp[i][0]*vp[i][0] + vp[i][1]*vp[i][1] + vp[i][2]*vp[i][2]);
            float sc = 0.f;
            if (dc <= reach) sc = br / 128.f;                                         /* камера в сфере блика */
            else if (vp[i][2] > -reach) {
                const float ang = acosf(fminf(1.f, fmaxf(-1.f, vp[i][2] / dc))) - asinf(reach / dc);
                if (ang < 1.0471976f) sc = (br / 128.f) * reach / dc;                 /* сфера достаёт до конуса взгляда */
            }
            if (sc > s) s = sc;
        }
        if (s > 0.f && s_spf[i] > 0.02f) s *= 1.3f;
        score[i] = s;
    }
    unsigned char want[GLAMP_MAX]; memset(want, 0, sizeof want);
    for (int t = 0; t < 4; t++) {
        int best = -1;
        for (int i = 0; i < nl; i++) if (!want[i] && score[i] > 0.f && (best < 0 || score[i] > score[best])) best = i;
        if (best < 0) break;
        want[best] = 1;
    }
    for (int i = 0; i < GLAMP_MAX; i++) {
        s_spf[i] += ((i < nl && want[i] ? 1.f : 0.f) - s_spf[i]) * 0.3f;
        if (s_spf[i] < 0.02f) s_spf[i] = 0.f;
    }
    int idx[4]; int n = 0;                                                            /* до 4 горящих: ярче разгоревшиеся */
    for (int t = 0; t < 4; t++) {
        int best = -1;
        for (int i = 0; i < nl; i++) {
            if (s_spf[i] <= 0.f) continue;
            int used = 0; for (int k = 0; k < n; k++) if (idx[k] == i) used = 1;
            if (!used && (best < 0 || s_spf[i] > s_spf[best] || (s_spf[i] == s_spf[best] && score[i] > score[best]))) best = i;
        }
        if (best < 0) break;
        idx[n++] = best;
    }
    float pos4[16], col4[16];
    for (int j = 0; j < n; j++) {
        const GameLamp *L = &s_glamp[idx[j]];
        pos4[j*4+0] = vp[idx[j]][0]; pos4[j*4+1] = vp[idx[j]][1]; pos4[j*4+2] = vp[idx[j]][2];
        pos4[j*4+3] = 1.5f * L->rad;
        for (int q = 0; q < 3; q++) { float c = L->col[q] / 160.f; col4[j*4+q] = (c > 1.2f ? 1.2f : c) * s_spf[idx[j]]; }
        col4[j*4+3] = 0.f;
    }
    dcvk_spec_lamps(pos4, col4, n);
    { static int dbg = -1; static long k = 0;
      if (dbg < 0) { const char *e = getenv("DC_SPEC_LOG"); dbg = (e && *e == '1') ? 1 : 0; }
      if (dbg && (++k % 120) == 1) {
          fprintf(stderr, "spec: %d lamps for highlights:", n);
          for (int j = 0; j < n; j++) fprintf(stderr, " G%02d view %.0f,%.0f,%.0f r %.0f", idx[j], pos4[j*4], pos4[j*4+1], pos4[j*4+2], pos4[j*4+3]);
          fprintf(stderr, "%c", 10); } }
}

/* ===== ОБЪЁМНЫЙ СВЕТ У ЛАМП (27.09) =====================================================================================
 * Игрок: «Попробуй объемный свет у ламп сделать (дымка и пыль в лучах)» (№4 списка улучшений от 24.09: «Позиции, радиусы и
 * цвета ламп мы из игры уже читаем»). Каждый кадр A: до 8 ламп таблицы игры (ctx+348), которые видны камере — перед ней или
 * вокруг неё, самые заметные (яркость × радиус / расстояние), точка — в вид этого кадра той же камерой, что у теней
 * (sh_camera), радиус — из таблицы, цвет — цвет лампы (128 = белый); слой карты теней — если лампа в группе, для которой
 * dc_shadow_draw снял карту персонажей (тени в дымке). И матрицы «вид -> комната» / «комната -> вид»: пыль и клубы висят в
 * комнате. Дымку и пыль рисует растр (gpu_vk_raster.cpp «ОБЪЁМНЫЙ СВЕТ У ЛАМП»). Зовётся из main.cpp в кадре A. */
void dc_vol_frame(void) {
    extern void dcvk_vol_set(const float *pos4, const float *col4, int n, const float *v2r12, const float *r2v12, int ok);
    const uint8_t *ram = memory_get_ram_ptr();
    float D[9], T[3], R[9], TR[3]; int gc = 0;
    if (!ram || !dc_room_live_on() || !dcvk_enabled() || !sh_camera(ram, 0, D, T, R, TR, &gc)) { dcvk_vol_set(0, 0, 0, 0, 0, 0); return; }
    /* комната -> вид: v = M·p + c, M = D·R, c = D·TR + T; обратная — честная 3x3 (не транспонирование, см. dc_pt_pair_inverse) */
    double M[9], c[3], Mi[9], ci[3];
    for (int r = 0; r < 3; r++) {
        for (int k = 0; k < 3; k++) M[r*3+k] = (double)D[r*3]*R[k] + (double)D[r*3+1]*R[3+k] + (double)D[r*3+2]*R[6+k];
        c[r] = (double)D[r*3]*TR[0] + (double)D[r*3+1]*TR[1] + (double)D[r*3+2]*TR[2] + (double)T[r];
    }
    const double det = M[0]*(M[4]*M[8] - M[5]*M[7]) - M[1]*(M[3]*M[8] - M[5]*M[6]) + M[2]*(M[3]*M[7] - M[4]*M[6]);
    if (fabs(det) < 1e-12) { dcvk_vol_set(0, 0, 0, 0, 0, 0); return; }
    Mi[0] =  (M[4]*M[8] - M[5]*M[7]) / det; Mi[1] = -(M[1]*M[8] - M[2]*M[7]) / det; Mi[2] =  (M[1]*M[5] - M[2]*M[4]) / det;
    Mi[3] = -(M[3]*M[8] - M[5]*M[6]) / det; Mi[4] =  (M[0]*M[8] - M[2]*M[6]) / det; Mi[5] = -(M[0]*M[5] - M[2]*M[3]) / det;
    Mi[6] =  (M[3]*M[7] - M[4]*M[6]) / det; Mi[7] = -(M[0]*M[7] - M[1]*M[6]) / det; Mi[8] =  (M[0]*M[4] - M[1]*M[3]) / det;
    for (int r = 0; r < 3; r++) ci[r] = -(Mi[r*3]*c[0] + Mi[r*3+1]*c[1] + Mi[r*3+2]*c[2]);
    float v2r[12], r2v[12];
    for (int r = 0; r < 3; r++) {
        for (int k = 0; k < 3; k++) { v2r[r*4+k] = (float)Mi[r*3+k]; r2v[r*4+k] = (float)M[r*3+k]; }
        v2r[r*4+3] = (float)ci[r]; r2v[r*4+3] = (float)c[r];
    }
    if (glamp_check_on()) glamp_refresh();
    else { static uint32_t sig = 0; const uint32_t s2 = rrm_signature(ram); if (s2 != sig) { sig = s2; glamp_read(); } }
    int idx[8]; float sc[8]; float vp[8][3]; int n = 0;
    for (int i = 0; i < s_glamp_n && i < GLAMP_MAX; i++) {
        const GameLamp *L = &s_glamp[i];
        if (!L->on || !(L->rad > 0.f)) continue;
        float v[3];
        for (int r = 0; r < 3; r++) v[r] = (float)(M[r*3]*L->p[0] + M[r*3+1]*L->p[1] + M[r*3+2]*L->p[2] + c[r]);
        const float d = sqrtf(v[0]*v[0] + v[1]*v[1] + v[2]*v[2]);
        if (v[2] < -0.5f * L->rad || d > 16000.f + L->rad) continue;   /* далеко позади камеры или очень далеко */
        float br = L->col[0]; if (L->col[1] > br) br = L->col[1]; if (L->col[2] > br) br = L->col[2];
        const float s = (br / 128.f) * L->rad / (d > L->rad ? d : L->rad);
        int at = n < 8 ? n : -1;
        if (at < 0) { int wi = 0; for (int k = 1; k < 8; k++) if (sc[k] < sc[wi]) wi = k; if (s > sc[wi]) at = wi; }
        if (at < 0) continue;
        idx[at] = i; sc[at] = s; vp[at][0] = v[0]; vp[at][1] = v[1]; vp[at][2] = v[2];
        if (n < 8) n++;
    }
    float pos4[32], col4[32];
    for (int j = 0; j < n; j++) {
        const GameLamp *L = &s_glamp[idx[j]];
        pos4[j*4+0] = vp[j][0]; pos4[j*4+1] = vp[j][1]; pos4[j*4+2] = vp[j][2]; pos4[j*4+3] = L->rad;
        for (int q = 0; q < 3; q++) { float cc = L->col[q] / 128.f; col4[j*4+q] = cc > 1.5f ? 1.5f : cc; }
        int layer = -1;                                /* лампа в группе, у которой в этом кадре карта персонажей */
        for (int k = 0; k < s_shcl_n && k < 4; k++)
            if (L->p[0] >= s_shcl_min[k][0] - 1.f && L->p[0] <= s_shcl_max[k][0] + 1.f &&
                L->p[1] >= s_shcl_min[k][1] - 1.f && L->p[1] <= s_shcl_max[k][1] + 1.f &&
                L->p[2] >= s_shcl_min[k][2] - 1.f && L->p[2] <= s_shcl_max[k][2] + 1.f) { layer = k; break; }
        col4[j*4+3] = (float)layer;
    }
    dcvk_vol_set(pos4, col4, n, v2r, r2v, 1);
    { static int dbg = -1; static long k = 0;
      if (dbg < 0) { const char *e = getenv("DC_VOL_LOG"); dbg = (e && *e == '1') ? 1 : 0; }
      if (dbg && (++k % 120) == 1) {
          fprintf(stderr, "vol: %d lamps for the haze:", n);
          for (int j = 0; j < n; j++)
              fprintf(stderr, " G%02d room %.0f,%.0f,%.0f view %.0f,%.0f,%.0f r %.0f col %.2f,%.2f,%.2f layer %d", idx[j],
                      s_glamp[idx[j]].p[0], s_glamp[idx[j]].p[1], s_glamp[idx[j]].p[2], pos4[j*4], pos4[j*4+1], pos4[j*4+2],
                      pos4[j*4+3], col4[j*4], col4[j*4+1], col4[j*4+2], (int)col4[j*4+3]);
          fprintf(stderr, "%c", 10); } }
}

/* ===== ОТРАЖЕНИЯ НА ПОЛУ: ПЛОСКОСТЬ (25.09 вечер) ======================================================================
 * Игрок: «отражения на полу: на кафеле и металле отражались бы лазеры, лампы и Регина». Растр (gpu_vk_raster.cpp, проход
 * отражения) зеркалит персонажей и светящееся плоскостью пола, пол из списка «блестит» берёт картинку. Плоскость — на уровне
 * ног: в игре — позиция игрока (0xB92AC..B0), в сцене на движке — ноги первой группы заслонивших (как у теней: там позиция
 * игрока — не нарисованная Регина). Нормаль — «вверх» комнаты (ось Y вниз), в видовое пространство кадра через ту же камеру,
 * что у теней и вспышек (sh_camera), и развёрнута к камере. Зовётся из main.cpp в кадре A. */
void dc_refl_frame(void) {
    extern void dcvk_refl_plane(const float *n, float d, int ok);
    const uint8_t *ram = memory_get_ram_ptr();
    float D[9], T[3], R[9], TR[3]; int gc = 0;
    if (!ram || !dc_room_live_on() || !dcvk_enabled() || !sh_camera(ram, 0, D, T, R, TR, &gc)) { dcvk_refl_plane(0, 0.f, 0); return; }
    float fx = (float)rrm_s16(ram, 0xB92ACu), fy = (float)rrm_s16(ram, 0xB92AEu), fz = (float)rrm_s16(ram, 0xB92B0u);
    /* 27.10.2026: в оригинальном режиме (O) камера кадра - игры (gc = 1) и в обычной игре, и плоскость вставала на «ноги
     * группы»: самую низкую вершину Регины, пересчитанную в комнату матрицей ПРОШЛОГО кадра. Пока камера игры едет за идущей
     * Региной, эта точка ниже пола на 1-16 единиц и скачет с шагом; ниже на 10 и больше пол уже не отсекается проходом
     * отражения (dc_raster.frag: v_rfd < 3), и перевёрнутый пол закрывает всё отражение (игрок, слот 1: «с включенными
     * материалами отражения в оригинальном режиме дрожат и мигают все постоянно»). В игре в режиме O - позиция игрока, как в
     * обычном режиме; «ноги группы» - только в сценах. DC_REFL_ORIG_PLAYER=0 - как было. */
    static int orig_pl = -1;
    if (orig_pl < 0) { const char *e = getenv("DC_REFL_ORIG_PLAYER"); orig_pl = (e && *e == '0') ? 0 : 1; }
    extern int g_dc_orig_mode; extern int dc_scripted_now(void); extern int dc_scene_flag_on(void); extern int dc_cut_camera(void);
    const int orig_world = orig_pl && g_dc_orig_mode && !(dc_scripted_now() || dc_scene_flag_on() || dc_cut_camera());
    const int grp = gc != 0 && s_ocl_cnt > 0 && !orig_world;
    if (grp) { fx = s_ocl_c[0][0]; fy = s_ocl_hi[0][1]; fz = s_ocl_c[0][2]; }
    const float up[3] = { -R[1], -R[4], -R[7] };                         /* R·(0,-1,0): «вверх» комнаты */
    float n[3] = { D[0]*up[0] + D[1]*up[1] + D[2]*up[2], D[3]*up[0] + D[4]*up[1] + D[5]*up[2], D[6]*up[0] + D[7]*up[1] + D[8]*up[2] };
    const float nl = sqrtf(n[0]*n[0] + n[1]*n[1] + n[2]*n[2]);
    if (nl < 1e-4f) { dcvk_refl_plane(0, 0.f, 0); return; }
    n[0] /= nl; n[1] /= nl; n[2] /= nl;
    const float vx = R[0]*fx + R[1]*fy + R[2]*fz + TR[0];
    const float vy = R[3]*fx + R[4]*fy + R[5]*fz + TR[1];
    const float vz = R[6]*fx + R[7]*fy + R[8]*fz + TR[2];
    const float p[3] = { D[0]*vx + D[1]*vy + D[2]*vz + T[0], D[3]*vx + D[4]*vy + D[5]*vz + T[1], D[6]*vx + D[7]*vy + D[8]*vz + T[2] };
    float d = n[0]*p[0] + n[1]*p[1] + n[2]*p[2];
    if (d > 0.f) { n[0] = -n[0]; n[1] = -n[1]; n[2] = -n[2]; d = -d; }   /* камера (начало вида) — со стороны нормали */
    dcvk_refl_plane(n, d, 1);
    { static int dbg = -1; static long k = 0;
      if (dbg < 0) { const char *e = getenv("DC_FX_LOG"); dbg = e ? atoi(e) : 0; }
      if (dbg == 1 && (++k % 120) == 1)
          fprintf(stderr, "refl: floor y=%.0f (%s) - in view n=%.2f,%.2f,%.2f d=%.0f%c", fy, grp ? "scene" : "player", n[0], n[1], n[2], d, 10);
      if (dbg >= 2) {               /* 27.10: каждый кадр - та же плоскость через позицию игрока (сверка с ногами группы) */
          extern uint64_t s_frame_count;
          const float qx = (float)rrm_s16(ram, 0xB92ACu), qy = (float)rrm_s16(ram, 0xB92AEu), qz = (float)rrm_s16(ram, 0xB92B0u);
          const float wx = R[0]*qx + R[1]*qy + R[2]*qz + TR[0], wy = R[3]*qx + R[4]*qy + R[5]*qz + TR[1], wz = R[6]*qx + R[7]*qy + R[8]*qz + TR[2];
          const float q[3] = { D[0]*wx + D[1]*wy + D[2]*wz + T[0], D[3]*wx + D[4]*wy + D[5]*wz + T[1], D[6]*wx + D[7]*wy + D[8]*wz + T[2] };
          fprintf(stderr, "refl: f=%llu gc %d groups %d use %s floor %.0f,%.0f,%.0f (player %.0f,%.0f,%.0f) n=%.3f,%.3f,%.3f d=%.1f player d=%.1f%c",
                  (unsigned long long)s_frame_count, gc, s_ocl_cnt, grp ? "group" : "player", fx, fy, fz, qx, qy, qz, n[0], n[1], n[2], d,
                  n[0]*q[0] + n[1]*q[1] + n[2]*q[2], 10);
      } }
}

void dc_room_emit_live(void) {
    extern int g_dcvk_room_pass;
    s_rl_target = 1;
    { extern void dc_meshrep_room_walk(void); dc_meshrep_room_walk(); }   /* 05.10 ночь (2): новый обход — меши комнаты из mods заново */
    g_dcvk_room_pass = 1;      /* ours: draw it, but keep it out of the vote */
    rl_emit_walk();
    g_dcvk_room_pass = 0;
}

/* ⭐ 22.09.2026 — КОМНАТА РИСУЕТСЯ КАЖДЫЙ КАДР, А НЕ ТОЛЬКО ПО ТРИГГЕРУ ИГРЫ (игрок, слот 13, подъём в вентиляцию:
 * «есть мигания»). Обход запускался из обработки ПЕРВОГО примитива комнаты, присланного игрой. На кадре смены
 * ракурса игра перестраивает таблицу порядка и шлёт одних актёров — триггера нет, комнаты в кадре нет, и он выходит
 * чёрным с Региной и лампами (замер DC_FRAME_DBG: соседние кадры «комната 713 draws» и «105 draws», между ними
 * «комната draws=0»). Теперь перед сборкой кадра, если в этом флипе обхода не было, он делается сам.
 * DC_ROOM_ALWAYS=0 — как было. */
void dc_room_emit_missing(void) {
    static int en = -1;
    if (en < 0) { const char *e = getenv("DC_ROOM_ALWAYS"); en = (e && *e == '1') ? 1 : 0; }
    extern uint64_t gpu_flip_seq(void);
    const uint64_t f0 = gpu_flip_seq();
    { static long dn = 0; static int dbg = -1;
      if (dbg < 0) { const char *e = getenv("DC_ROOM_ALWAYS_DBG"); dbg = (e && *e == '1') ? 1 : 0; }
      if (dbg && ++dn <= 40) fprintf(stderr, "roomalways: call #%ld live=%d flip=%llu emitted=%llu n=%d%c",
                                     dn, dc_room_live_on(), (unsigned long long)f0,
                                     (unsigned long long)s_rl_emitted_frame, s_rl_n, 10); }
    if (!en || !dc_room_live_on()) return;
    /* ⭐ Память проекта (dc_room_cut_artifacts, 30.08): заслон «одна комната на отрисованный поток» оставляет
     * КАДР С ОТЛОЖЕННЫМ ВЫВОДОМ без комнаты — «чёрный кадр с одной Региной». Решение там же: на сборке-продолжении
     * комнату не пропускать, а перерисовать. Поэтому смотрим не на флип, а на ФАКТ: есть ли наша комната в
     * собранном кадре. Нет — делаем обход, даже если в этом флипе он уже был. */
    { extern int dcvk_stream_room_verts(void);
      if (dcvk_stream_room_verts() > 0) return; }
    const uint64_t f = f0;
    dc_room_emit_live();
    if (s_rl_n > 0) {
        s_rl_emitted_frame = f;
        static long n = 0;
        if (++n <= 8) fprintf(stderr, "room: a frame without the game's room primitives - the walk was done by us #%ld%c", n, 10);
    }
}

/* THE ROOM'S OWN MATRIX, TAKEN OFF A VISIBLE SECTION (2026-08-25).
 * The emitter could only get its matrix by watching the game draw a room
 * triangle it recognised. Outdoors that never happens: at the pier the game
 * references just 5 of the room's 34 mesh groups, and the latch matched none
 * of their triangles - so the emitter sat on 4795 parsed triangles with
 * nowhere to put them and drew nothing. That is the black half of the view.
 * The matrix is right there in the section entries - the room's own BODY
 * pieces all share ONE transform, while a sign, a keypad or a door carries
 * its own. Measured at the pier: of the five sections being drawn, three
 * carry TR=8395,911,9773 and two carry TRs of their own - so the shared one
 * is the room and the odd ones out are placed things. Cluster the drawn
 * sections by their transform and take the heaviest cluster; a lone object
 * can never outweigh the room body, so a moving thing cannot become the
 * room's frame. (Comparing against the engine's camera translation was tried
 * first and is no good: at this spot 0xBFA08 reads 0,0,0.)
 * DC_ROOM_MTX_FALLBACK=0 restores latch-only behaviour. */
static int rr_matrix_from_sections(float Rout[9], float Tout[3])
{
    const uint8_t *ram = memory_get_ram_ptr();
    const uint8_t *sp  = memory_get_scratchpad_ptr();
    if (!ram || !sp) return 0;
    uint32_t S = ((uint32_t)sp[0] | ((uint32_t)sp[1] << 8) |
                  ((uint32_t)sp[2] << 16) | ((uint32_t)sp[3] << 24)) & 0x1FFFFFFFu;
    if (!S || S + 0x8FFCu >= 0x200000u) return 0;
    float Rs[90][9]; float Ts[90][3]; long W[90]; int n = 0;
    for (int k = 0; k < 36; k++) {
        uint32_t e = S + 0x7CDCu + 136u * (uint32_t)k;
        if (e + 136u > 0x200000u) continue;
        if ((rrm_u32(ram, e + 48) & 3u) != 3u) continue;        /* not being drawn */
        uint32_t gp = rrm_u32(ram, e + 60) & 0x1FFFFFFFu;
        if (gp < 0x100000u || gp + 12u >= 0x200000u) continue;  /* room block only */
        float R[9];
        for (int i = 0; i < 9; i++)
            R[i] = (float)rrm_s16(ram, e + (uint32_t)i * 2u) * (1.0f / 4096.0f);
        float n0 = R[0]*R[0] + R[1]*R[1] + R[2]*R[2];
        float n1 = R[3]*R[3] + R[4]*R[4] + R[5]*R[5];
        if (n0 < 0.85f || n0 > 1.15f || n1 < 0.85f || n1 > 1.15f) continue;
        for (int i = 0; i < 9; i++) Rs[n][i] = R[i];
        Ts[n][0] = (float)(int32_t)rrm_u32(ram, e + 20u);
        Ts[n][1] = (float)(int32_t)rrm_u32(ram, e + 24u);
        Ts[n][2] = (float)(int32_t)rrm_u32(ram, e + 28u);
        W[n] = (long)rrm_u16(ram, gp + 8) + (long)rrm_u16(ram, gp + 10) * 2;
        if (++n >= 90) break;
    }
    if (n <= 0) return 0;
    int bi = -1; long bw = -1;
    for (int i = 0; i < n; i++) {
        long w = 0;
        for (int j = 0; j < n; j++) {
            float dt = fabsf(Ts[i][0]-Ts[j][0]) + fabsf(Ts[i][1]-Ts[j][1])
                     + fabsf(Ts[i][2]-Ts[j][2]);
            if (dt > 1.0f) continue;
            float dr = 0.f;
            for (int q = 0; q < 9; q++) dr += fabsf(Rs[i][q] - Rs[j][q]);
            if (dr > 0.02f) continue;
            w += W[j];
        }
        if (w > bw) { bw = w; bi = i; }
    }
    if (bi < 0) return 0;
    /* NO COMPOSITION WITH THE CAMERA (2026-08-25, measured).
     * An earlier version multiplied this by the camera pair, on the assumption
     * that a section entry stores the piece's matrix BEFORE the camera. It does
     * not. Sampled live across four camera shots, the entry's rotation tracked
     * the camera matrix at 0xBF9F4 exactly - camera (3954,0,-1068) against
     * section (3954,0,-1068), and so on through the shots. The engine rewrites
     * these fields every frame with the CURRENT camera, and the geometry's own
     * placement lives in the model coordinates. Composing therefore applied the
     * camera twice and threw the room across the screen. Use it as it stands. */
    for (int i = 0; i < 9; i++) Rout[i] = Rs[bi][i];
    for (int i = 0; i < 3; i++) Tout[i] = Ts[bi][i];
    return 1;
}

/* DC_ROOM_EMIT_DBG=1: one line per frame from the room substitution, so a
 * black frame can be told apart from a frame where the room was never
 * emitted at all. have/cand/best/bestn describe the game-side transform the
 * injected room rides on; pushed/skipped are the triangles we actually sent. */
static void rr_emit_dbg(const char *why, int have, int ncand, int best,
                        long bestn, long pushed, long skipped, int nrrm)
{
    static int en = -1;
    if (en < 0) { const char *e = getenv("DC_ROOM_EMIT_DBG"); en = (e && *e == '1') ? 1 : 0; }
    if (!en) return;
    fprintf(stderr, "roomemit: %-8s have=%d cand=%d best=%d bestn=%ld "
                    "pushed=%ld skipped=%ld rrm=%d%c",
            why, have, ncand, best, bestn, pushed, skipped, nrrm, 10);
}

void dc_raster_emit_room(void) {
    int have = s_rr_have;
    int best = -1; long bestn = 0;
    for (int i = 0; i < s_cand_cnt; i++) if (s_cand_n[i] > bestn) { bestn = s_cand_n[i]; best = i; }
    int ncand = s_cand_cnt;
    /* 25.09: матрица комнаты, которую игра подала в GTE в этом кадре (камера игры) — для теней и вспышек в сцене */
    if (have && best >= 0) {
        extern uint64_t s_frame_count;
        for (int k = 0; k < 9; k++) s_gcam_R[k] = s_cand_R[best][k];
        for (int k = 0; k < 3; k++) s_gcam_T[k] = s_cand_T[best][k];
        s_gcam_frame = s_frame_count ? s_frame_count : 1ull; s_gcam_n = bestn;
    }
    s_rr_have = 0; s_cand_cnt = 0;
    int dhave = s_rr_dhave; s_rr_dhave = 0;
    /* Nothing latched this frame? The room's own sections still carry the
     * matrix (see rr_matrix_from_sections above), and the delta is available
     * every frame, so the room can still be placed. */
    float fbR[9], fbT[3]; int usefb = 0;
    if ((!have || best < 0) && dc_raster_fullroom_on() && dcvk_enabled() && s_rrm_n > 0) {
        static int fb = -1;
        if (fb < 0) { const char *e = getenv("DC_ROOM_MTX_FALLBACK");
                      fb = (e && *e == '0') ? 0 : 1; }
        if (fb && rr_matrix_from_sections(fbR, fbT)) {
            usefb = 1;
            if (!dhave) dhave = dc_nots_get_delta(s_rr_D, s_rr_DT);
        }
    }
    if (((!have || best < 0) && !usefb) || !dc_raster_fullroom_on() || !dcvk_enabled()) {
        rr_emit_dbg("NOCAND", have, ncand, best, bestn, 0, 0, s_rrm_n);
        if (s_tri_cand) memset(s_tri_cand, 0, RRM_MAX);
        return;
    }
    /* DRAW ONLY WHAT THE ROOM'S SCRIPT LISTS FOR ITS SHOTS, AND ONLY WHAT THE
     * GAME IS NOT DRAWING ITSELF. The script's shot routines name the room's
     * own geometry; story variants live in other routines and are never in
     * this list, so a wrecked piece cannot appear. Groups the game has in a
     * live section are left to it, so nothing is drawn twice. */
    extern void dc_room_script_scan(void);
    uint8_t gok[64]; memset(gok, 0, sizeof gok);
    if (usefb) {
        dc_room_script_scan();
        const uint8_t *ram2 = memory_get_ram_ptr();
        const uint8_t *sp2  = memory_get_scratchpad_ptr();
        uint32_t S2 = 0;
        if (sp2) S2 = ((uint32_t)sp2[0] | ((uint32_t)sp2[1] << 8) |
                       ((uint32_t)sp2[2] << 16) | ((uint32_t)sp2[3] << 24)) & 0x1FFFFFFFu;
        for (int g = 0; g < s_rrm_ng && g < 64; g++) {
            uint32_t gh = s_rrm_ghdr[g] & 0x1FFFFFFFu;
            int listed = 0;
            for (int k = 0; k < s_script_n; k++)
                if ((s_script_gp[k] & 0x1FFFFFFFu) == gh) { listed = 1; break; }
            if (!listed) continue;
            int live = 0;
            if (ram2 && S2 && S2 + 0x8FFCu < 0x200000u)
                for (int i = 0; i < 36; i++) {
                    uint32_t e2 = S2 + 0x7CDCu + 136u * (uint32_t)i;
                    if ((rrm_u32(ram2, e2 + 48) & 3u) != 3u) continue;
                    if ((rrm_u32(ram2, e2 + 60) & 0x1FFFFFFFu) == gh) { live = 1; break; }
                }
            gok[g] = live ? 0 : 1;
        }
    }
    uint8_t own;
    if (usefb) {
        for (int k = 0; k < 9; k++) s_rr_R[k] = fbR[k];
        for (int k = 0; k < 3; k++) s_rr_T[k] = fbT[k];
        own = 0;            /* nothing was latched, so nothing to exclude */
    } else {
        for (int k = 0; k < 9; k++) s_rr_R[k] = s_cand_R[best][k];
        for (int k = 0; k < 3; k++) s_rr_T[k] = s_cand_T[best][k];
        own = (uint8_t)(best + 1);
    }
    if (s_rrm_n <= 0 || !dhave) {
        rr_emit_dbg(dhave ? "NORRM" : "NODELTA", have, ncand, best, bestn, 0, 0, s_rrm_n);
        if (s_tri_cand) memset(s_tri_cand, 0, RRM_MAX); return; }
    { static int lastc = -1; static long lastn = -1;
      if (ncand != lastc || bestn / 64 != lastn / 64) { lastc = ncand; lastn = bestn;
          fprintf(stderr, "raster fullroom: %d transform(s) this frame, dominant drew %ld tris%c",
                  ncand, bestn, 10); } }

    float h = g_pt_proj_h;
    if (!(h > 0.0f)) return;
    float ofx = g_pt_proj_ofx, ofy = g_pt_proj_ofy;
    const int ws = dc_ws_world();   /* 15.09: соотношение сторон из меню SCREEN — на лету (memory.c) */
    float wsx = ws ? dc_ws_sq() : 1.0f;
    const float *D = s_rr_D, *T = s_rr_DT;

    long pushed = 0, skipped = 0;
    for (int t = 0; t < s_rrm_n; t++) {
        /* Drawn with a DIFFERENT transform this frame -> that piece belongs to
         * something the game moves on its own; leave it to the game. */
        if (s_tri_cand && s_tri_cand[t] && s_tri_cand[t] != own) { skipped++; continue; }
        if (usefb) {
            int g = s_rrm_gi ? (int)s_rrm_gi[t] : 255;
            if (g >= 64 || !gok[g]) { skipped++; continue; }
        }
        RRVert tri[3];
        for (int k = 0; k < 3; k++) {
            const int16_t *m = &s_rrm_v[t * 9 + k * 3];
            float wx = (float)m[0], wy = (float)m[1], wz = (float)m[2];
            float vx = s_rr_R[0]*wx + s_rr_R[1]*wy + s_rr_R[2]*wz + s_rr_T[0];
            float vy = s_rr_R[3]*wx + s_rr_R[4]*wy + s_rr_R[5]*wz + s_rr_T[1];
            float vz = s_rr_R[6]*wx + s_rr_R[7]*wy + s_rr_R[8]*wz + s_rr_T[2];
            tri[k].x  = D[0]*vx + D[1]*vy + D[2]*vz + T[0];
            tri[k].y  = D[3]*vx + D[4]*vy + D[5]*vz + T[1];
            tri[k].zr = D[6]*vx + D[7]*vy + D[8]*vz + T[2];
            /* MEASURED: the game divides by the RE-AIMED depth, same as the
             * numerator (probe: z=313 -> divisor 312, z=273 -> 272). The cases
             * that looked like "it divides by something else" were the PS1
             * divider SATURATING: gte_divide returns its 2.0 ceiling whenever
             * SZ*2 <= H, so below H/2 the game itself projects garbage. */
            tri[k].zo = tri[k].zr;
            tri[k].u = (float)s_rrm_uv[t*6 + k*2];
            tri[k].v = (float)s_rrm_uv[t*6 + k*2 + 1];
            const uint8_t *c = &s_rrm_rgb[t*9 + k*3];
            tri[k].r = (float)c[0]; tri[k].g = (float)c[1]; tri[k].b = (float)c[2];
        }
        RRVert poly[4];
        int n = rr_clip_near(tri, poly);
        if (n < 3) continue;
        float sx[4], sy[4];
        for (int i = 0; i < n; i++) {
            float z = poly[i].zo;
            sx[i] = ofx + h * poly[i].x / z * wsx;
            sy[i] = ofy + h * poly[i].y / z;
        }
        for (int k = 1; k + 1 < n; k++) {
            const int idx[3] = { 0, k, k + 1 };
            float vv[3 * RR_VF];
            for (int j = 0; j < 3; j++) {
                const RRVert *s = &poly[idx[j]];
                float *o = &vv[j * RR_VF];
                o[0] = sx[idx[j]]; o[1] = sy[idx[j]];
                o[2] = s->u;  o[3] = s->v;
                o[4] = s->r;  o[5] = s->g;  o[6] = s->b;  o[7] = 0.0f;
                o[8] = (float)s_rrm_tp[t];
                o[9] = (float)s_rrm_cx[t];
                o[10] = (float)s_rrm_cy[t];
                o[11] = 1.0f;
                o[12] = (s->zr > 1.0f ? s->zr : 1.0f) * RR_PUSH;
            }
            dcvk_push_tri(vv, -1, 1);
            pushed++;
        }
    }
    if (s_tri_cand) memset(s_tri_cand, 0, RRM_MAX);
    rr_emit_dbg(usefb ? "OK-SECT" : "OK", have, ncand, best, bestn, pushed, skipped, s_rrm_n);
    { static long last = -1;
      if (pushed / 128 != last / 128) { last = pushed;
          fprintf(stderr, "raster fullroom: %ld/%d tris from RAM (%ld left to the game)%c",
                  pushed, s_rrm_n, skipped, 10); } }
}


/* ---- WHO DECIDES WHICH ROOM PORTIONS GET DRAWN --------------------------
 * func_80073240 walks a list of 36 entries of 136 bytes starting at S+0x7CDC
 * (S = word 0 of the scratchpad) and draws an entry only when
 *     (word at entry+48) & 3 == 3
 * so that word is the visibility state. DC_DRAWLIST_WATCH=1 reports which game
 * routine writes it — the routine that culls, which is what has to be found.
 * The write path already funnels through psx_write_word, so the hook is one
 * range test on a store. */
extern volatile uint32_t g_dc_fn_ring[32];
extern volatile uint32_t g_dc_fn_pos;
extern uint8_t *memory_get_scratchpad_ptr(void);

void dc_drawlist_watch(uint32_t phys, uint32_t val, int size) {
    static int en = -1;
    if (en < 0) { const char *e = getenv("DC_DRAWLIST_WATCH"); en = (e && *e == '1') ? 1 : 0; }
    if (!en) return;
    const uint8_t *sp = memory_get_scratchpad_ptr();
    if (!sp) return;
    uint32_t S = (uint32_t)sp[0] | ((uint32_t)sp[1] << 8) | ((uint32_t)sp[2] << 16) | ((uint32_t)sp[3] << 24);
    S &= 0x1FFFFFFFu;
    if (!S || S >= 0x200000u) return;
    uint32_t lo = S + 0x7CDCu, hi = S + 0x8FFCu;
    if (phys < lo || phys >= hi) return;
    uint32_t off = (phys - lo) % 136u;
    /* +48 = visibility state, +60 = mesh-group header, +64 = object struct the
     * walker loads the GTE matrix from. The pair (+60,+64) IS the group->matrix
     * association we need, and it is published once when the room is built. */
    int want = (off <= 51u && off + (uint32_t)size > 48u)
            || (off <= 67u && off + (uint32_t)size > 60u);
    if (!want) return;
    enum { NW = 32 };
    static uint32_t wa[NW]; static long wc[NW]; static int wn = 0; static long tot = 0;
    uint32_t caller = 0;
    for (int k = 1; k <= 32; k++) {
        uint32_t a = g_dc_fn_ring[(g_dc_fn_pos - k) & 31];
        if (a >= 0x80010000u && a < 0x800A0000u) { caller = a; break; }
    }
    int i = 0; for (; i < wn; i++) if (wa[i] == caller) break;
    if (i == wn) { if (wn >= NW) return; wa[wn] = caller; wc[wn] = 0; wn++; }
    wc[i]++;
    tot++;
    if (off >= 60u && off <= 67u && val != 0) {
        static long np = 0;
        if (++np <= 60)
            fprintf(stderr, "drawlist PTR: entry %u  +%u = %08X  by func_%08X%c",
                    (phys - lo) / 136u, off, val, caller, 10);
    }
    if (val != 0 && off < 60u) {       /* who ENABLES a slot */
        static long nz = 0;
        if (++nz <= 40)
            fprintf(stderr, "drawlist SET#%ld: entry %u  off+%u  size %d  val %08X  by func_%08X%c",
                    nz, (phys - lo) / 136u, off, size, val, caller, 10);
    }
    /* ⭐ 18.09.2026 (лишняя батарея в первой загадке): DC_DRAWLIST_ENTRY=<номер> — печатать КАЖДУЮ
     * запись именно в эту запись таблицы, с обратным адресом. Скрипт комнаты создаёт пятую секцию
     * с моделью батареи и тут же прячет её (CREATE 4 + SHOW 4 0), ни один ракурс её не показывает,
     * но в сохранении игрока её слово видимости = 3. Нужно поймать, кто его туда пишет при входе
     * в комнату: сводка по писателям этого не показывает, она считает по всей таблице. */
    { static int want_e = -2;
      if (want_e == -2) { const char *ee = getenv("DC_DRAWLIST_ENTRY"); want_e = ee ? atoi(ee) : -1; }
      if (want_e >= 0 && (int)((phys - lo) / 136u) == want_e) {
          static long ne = 0;
          if (++ne <= 200) {
              extern uint64_t gpu_flip_seq(void);
              fprintf(stderr, "drawlist E%d #%ld: off+%u size %d val %08X by func_%08X (flip %llu)%c",
                      want_e, ne, off, size, val, caller,
                      (unsigned long long)gpu_flip_seq(), 10);
          }
      } }
    if (tot <= 20)
        fprintf(stderr, "drawlist w#%ld: entry %u  off+%u  size %d  val %08X  by func_%08X%c",
                tot, (phys - lo) / 136u, off, size, val, caller, 10);
    else if ((tot % 500) == 0) {
        fprintf(stderr, "drawlist: %ld writes; writers:%c", tot, 10);
        for (int k = 0; k < wn; k++)
            if (wc[k] * 10 > tot) fprintf(stderr, "   func_%08X  x%ld%c", wa[k], wc[k], 10);
    }
}


/* Ground truth for the draw list: dump every entry the walker iterates, so the
 * gate can be read off real values instead of inferred from the disassembly. */
void dc_drawlist_dump(void) {
    static int en = -1;
    if (en < 0) { const char *e = getenv("DC_DRAWLIST_DUMP"); en = (e && *e == '1') ? 1 : 0; }
    if (!en) return;
    static long f = 0;
    if ((f++ % 240) != 0) return;
    const uint8_t *sp = memory_get_scratchpad_ptr();
    const uint8_t *ram = memory_get_ram_ptr();
    if (!sp || !ram) return;
    uint32_t S = ((uint32_t)sp[0] | ((uint32_t)sp[1] << 8) | ((uint32_t)sp[2] << 16) | ((uint32_t)sp[3] << 24)) & 0x1FFFFFFFu;
    if (!S || S >= 0x200000u) return;
    uint32_t lo = S + 0x7CDCu;
    fprintf(stderr, "drawlist dump: S=%08X base=%08X%c", S, lo, 10);
    int drawn = 0;
    for (int i = 0; i < 36; i++) {
        uint32_t e = lo + (uint32_t)i * 136u;
        if (e + 136 > 0x200000u) break;
        uint32_t st = rrm_u32(ram, e + 48);
        uint32_t pt = rrm_u32(ram, e + 64);
        uint32_t g0 = rrm_u32(ram, e + 0);
        if ((st & 3u) == 3u) drawn++;
        if (i < 12 || (st & 3u) == 3u)
            fprintf(stderr, "   e%-2d +0=%08X  +48=%08X (&3=%u)  +64=%08X%c",
                    i, g0, st, st & 3u, pt, 10);
    }
    fprintf(stderr, "   entries passing the (state&3)==3 gate: %d/36%c", drawn, 10);
}


/* DC_ROOM_STICKY=1 — KEEP ROOM PORTIONS ONCE THE SCRIPT HAS SHOWN THEM.
 * The room is split into portions listed at S+0x7CDC (S = scratchpad word 0),
 * 36 entries of 136 bytes; func_80073240 draws an entry only when
 * (word at entry+48) & 3 == 3. That word is written by func_8005580C — an
 * opcode handler of the game's script VM — so the portions are switched on and
 * off by the room script on triggers. Measured: only 2 of 36 entries are live
 * at once, which is exactly the two transforms the recorder saw (718 + 32
 * triangles) and why a walk of the whole corridor only ever reached 750 of the
 * room's 2959 triangles.
 * Forcing all 36 on crashes: slots the script never initialised hold garbage
 * pointers. So remember which slots the script itself enabled since this room
 * was loaded, and refuse to let them be switched off again — the room
 * accumulates as you walk instead of losing what you passed. The sticky set is
 * cleared when the room block in RAM changes (new room, or a variant swapped
 * in by a cutscene). */
static uint8_t s_sticky[36];
static uint32_t s_sticky_sig = 0;

void dc_room_sticky_tick(void) {
    static int en = -1;
    if (en < 0) { const char *e = getenv("DC_ROOM_STICKY"); en = (e && *e == '1') ? 1 : 0; }
    if (!en) return;
    const uint8_t *sp = memory_get_scratchpad_ptr();
    uint8_t *ram = (uint8_t*)memory_get_ram_ptr();
    if (!sp || !ram) return;
    if (rrm_u32(ram, RRM_BASE + 7 * 4) != RRM_VADDR + 0x28) return;
    uint32_t sig = rrm_signature(ram);
    if (sig != s_sticky_sig) { s_sticky_sig = sig; memset(s_sticky, 0, sizeof s_sticky); }
    uint32_t S = ((uint32_t)sp[0] | ((uint32_t)sp[1] << 8) | ((uint32_t)sp[2] << 16) | ((uint32_t)sp[3] << 24)) & 0x1FFFFFFFu;
    if (!S || S >= 0x200000u) return;
    uint32_t lo = S + 0x7CDCu;
    int held = 0, live = 0;
    for (int i = 0; i < 36; i++) {
        uint32_t e = lo + (uint32_t)i * 136u;
        if (e + 136u > 0x200000u) break;
        uint32_t st = rrm_u32(ram, e + 48);
        if ((st & 3u) == 3u) { s_sticky[i] = 1; live++; continue; }
        if (!s_sticky[i]) continue;
        uint32_t nv = (st & ~3u) | 3u;             /* keep the other bits intact */
        ram[e + 48] = (uint8_t)(nv & 0xFF);
        ram[e + 49] = (uint8_t)((nv >> 8) & 0xFF);
        ram[e + 50] = (uint8_t)((nv >> 16) & 0xFF);
        ram[e + 51] = (uint8_t)((nv >> 24) & 0xFF);
        held++;
    }
    { static int last_h = -1, last_l = -1;
      if (held != last_h || live != last_l) { last_h = held; last_l = live;
          fprintf(stderr, "room sticky: %d portions live, %d held open%c", live, held, 10); } }
}


/* DC_ROOM_ALLGROUPS=1 — PUT THE ROOM'S MISSING PORTIONS BACK INTO THE DRAW LIST.
 * Established by tracing: func_80073240 walks 36 entries of 136 bytes at
 * S+0x7CDC; an entry is drawn when (word at entry+48)&3 == 3 and it renders
 * exactly ONE mesh group, whose {tri_ptr,quad_ptr,n_tri,n_quad} header address
 * sits at entry+60. The room has 14 such groups but only about two are ever
 * listed, which is why a full walk of the corridor reached 750 of 2959
 * triangles. The switching is done by func_8005580C — a script-VM opcode
 * handler — i.e. the split is authored per room on triggers.
 * Rather than fight the script, clone a LIVE room entry (it already carries the
 * correct transform and flags) into free slots, changing only the group pointer
 * so the portions the script left out are drawn too. Everything is still drawn
 * by the game itself. */
/* WHICH GROUPS THE ROOM'S SCRIPT WOULD LIST (2026-08-25).
 * There is no baked visibility table - the room SCRIPT is it. Header pointer
 * ptr[5] leads to a u32 table of routine offsets (its first word is the table
 * size) followed by bytecode. One routine per camera shot, each opening with a
 * 4-byte 0x0F and then running opcode 0x23 (CREATE SECTION, 32 bytes: slot in
 * code[1], mesh-group pointer in u32 code[8]).
 * Story variants are DIFFERENT routines - they begin by destroying a slot
 * (opcode 0x2F) and then create it from another group, which is how the
 * walkway gets its wrecked version. Taking only runs that begin with 0x23
 * therefore collects the room's shots and never a variant.
 * We only READ here. Writing these groups into the game's own section table
 * cannot work: the script recycles the same 36 slots per shot (measured: slot
 * 0 held group 0x1048B8 in one shot and 0x10C448 in the next), so the room has
 * more groups than the table has room for. The list is for drawing them
 * ourselves instead.
 * Verified on ST201: 32 script entries, 5 pure shot lists, 45 creates. */

void dc_room_script_scan(void)
{
    const uint8_t *ram = memory_get_ram_ptr();
    if (!ram) return;
    if (rrm_u32(ram, RRM_BASE + 7 * 4) != RRM_VADDR + 0x28) { s_script_n = 0; return; }
    if (rrm_refresh() <= 0) { s_script_n = 0; return; }
    if (s_script_sig == s_rrm_sig && s_script_n > 0) return;   /* same room */
    s_script_sig = s_rrm_sig; s_script_n = 0;
    uint32_t ptr5 = rrm_u32(ram, RRM_BASE + 5 * 4) & 0x1FFFFFu;
    if (ptr5 < 0x100000u || ptr5 + 4u >= 0x200000u) return;
    uint32_t first = rrm_u32(ram, ptr5);
    if (first < 4u || first > 0x4000u || (first & 3u)) return;
    int nent = (int)(first >> 2); if (nent <= 0 || nent > 512) return;
    int routines = 0, creates = 0;
    for (int i = 0; i < nent; i++) {
        uint32_t off = rrm_u32(ram, ptr5 + (uint32_t)i * 4u);
        uint32_t pc = ptr5 + off;
        if (off == 0u || pc + 32u >= 0x200000u) continue;
        if (ram[pc] == 0x0F) pc += 4u;              /* shot routines open with this */
        if (pc + 32u >= 0x200000u || ram[pc] != 0x23) continue;
        routines++;
        while (pc + 32u < 0x200000u && ram[pc] == 0x23) {
            uint32_t gp = rrm_u32(ram, pc + 8) & 0x1FFFFFFFu;
            creates++;
            if (gp >= 0x100000u && gp + 12u < 0x200000u) {
                int k = 0; for (; k < s_script_n; k++) if (s_script_gp[k] == gp) break;
                if (k == s_script_n && s_script_n < 128) {
                    s_script_gp[s_script_n] = gp;
                    s_script_n++;
                }
            }
            pc += 32u;
        }
    }
    fprintf(stderr, "room script: %d shot routines, %d creates, %d distinct groups%c",
            routines, creates, s_script_n, 10);
}

/* ======================= ROOM ASSEMBLY BY SCRIPT REPLAY ====================
 * Decoded 2026-08-25 from ST201 (all 32 routines decode with zero slack).
 *
 * The room is NOT chosen at load. Header ptr[3] is the camera table - u32
 * count then that many 68-byte records - and byte +2 of each record is the
 * script routine for that camera. On a shot change the engine runs that
 * routine, and every one of them opens by DESTROYING slots 0..20 and building
 * again. So the room is rebuilt from scratch per camera, which is why only a
 * handful of sections are ever live, and why "switch on what the script
 * toggles" cannot work - it does not toggle, it demolishes and rebuilds.
 *
 * To show the whole room under a free camera we therefore have to ASSEMBLE it:
 * replay every camera's routine and union what they build. Two things make
 * that honest rather than a guess:
 *   - the story state is a single flag (bank 3 bit 39), read from the game's
 *     own flag banks, so routines that branch on it branch the way they would
 *     right now;
 *   - routines that DO test the flag are authoritative for the slots they
 *     fill. Some cameras build parts unconditionally (ST201's cam1 and cam4
 *     create the intact planks with no test at all), so a plain union shows
 *     intact geometry in every state and, once the flag is up, the wreck on
 *     top of it. Letting a flag-tested decision win over an untested one for
 *     the same slot is what keeps the two apart.
 * DC_ROOM_BUILD=0 falls back to the old behaviour. */
/* Verified 2026-08-25 against the exported room (room_022 = ST201:
 * 34 groups / 4795 triangles). Three findings decide the rule below.
 *
 * 1. The script creates the WHOLE room. Every one of the 34 groups is the
 *    target of some CREATE; none is unreachable. So nothing has to be
 *    invented - assembling is only a matter of reaching every create.
 * 2. DESTROY must be ignored. Each camera opens by demolishing slots 0..20
 *    and rebuilding its own shot, so replaying destroys leaves a quarter of
 *    the room (measured: 1204 of 4795 tri). The slot a piece lands in is
 *    meaningless to us - only the group matters.
 * 3. Only creates with no position and no angle may be taken. Those are the
 *    room body in world space, and they need no placement at all (56 of 73
 *    creates, 4463 tri = 93%). The other 17 carry a transform - doors,
 *    hatches, crates - and are exactly what used to end up piled in the
 *    middle of the room. The game places those itself, so we leave them.
 *
 * Story state is honoured by walking only from the real entry points - the
 * room-init routine and the camera table - and following CALL/START_TASK
 * through the flag branches. That is what keeps the wrecked variant out:
 * ST201's debris (grp01, 331 tri) hangs off bank 3 bit 39 and off tasks that
 * only start when their own flag is up, so with the flag down it is simply
 * never reached. Measured: 4000 of 4795 tri assembled with the corridor
 * intact, and every excluded piece is either an inactive story variant or a
 * positioned object. Walking all routines blindly instead would drag the
 * debris in regardless of the flag.
 * DC_ROOM_BUILD=0 turns the assembly off. */
static uint32_t s_build_gp[64];
static int      s_build_n = 0; static uint32_t s_build_sig = 0;
static int s_build_n_fwd(void) { return s_build_n; }
static uint32_t s_build_gp_fwd(int g) { return (g >= 0 && g < s_build_n) ? s_build_gp[g] : 0u; }
static int      s_build_cams = 0;
/* 17.09 день: записи таблицы ракурсов, которые берутся в сборку при текущей фазе зон (блок rp_*, перед dc_room_script_build) */
static uint8_t  s_rb_cam_use[64];


/* handed to the room emitter, which draws these itself */
static int rb_assembled(const uint32_t **out) { *out = s_build_gp; return s_build_n; }

/* Opcode sizes, taken from the handlers themselves (each adds a constant to
 * the task PC). 0 marks the ones that move the PC on their own. */
static const uint8_t s_op_size[128] = {
  1,4,4,4,0,4,4,4, 4,8,4,4,0,4,0,0,
  0,0,4,4,4,8,4,4, 4,1,1,1,1,1,1,1,
 24,8,4,32,8,4,4,4, 32,8,8,8,4,4,20,4,
  4,4,4,4,4,8,8,8, 4,4,12,4,8,12,4,8,
 12,4,20,8,8,8,8,4, 4,4,4,12,32,8,8,8,
  8,8,4,12,4,12,28,8, 8,20,4,44,4,4,20,12,
  4,4,8,8,4,4,4,8, 8,4,8,4,4,4,4,4,
  1,1,4,4,4,4,4,4, 4,4,4,4,4,4,4,4 };

/* Which flags the last walk actually asked about. The assembled set is a
 * function of the story flags, but the room block does not change when one
 * flips - so caching on the block signature alone re-serves a set built for
 * the wrong state: a variant that swaps while the room stays loaded is never
 * picked up, and a quickload (which replaces RAM but not our statics) reuses
 * the set assembled for the pre-load progress. Remember every (bank,bit) the
 * replay read and re-check just those each tick - a handful of words. */
static uint16_t s_flagq[128]; static int s_flagq_n = 0; static int s_flagq_rec = 0;
static uint32_t s_build_flagsig = 0xFFFFFFFFu;
static uint8_t  s_flagq_val[128]; static int s_build_phase_was = -1;   /* 21.09: значения флагов на момент сборки (замер room rebuild why:) */

static int rb_flag(const uint8_t *ram, int bank, int bit)
{
    if (s_flagq_rec) {                       /* recording during a walk */
        uint16_t key = (uint16_t)(((bank & 0xFF) << 8) | (bit & 0xFF));
        int seen = 0;
        for (int i = 0; i < s_flagq_n; i++) if (s_flagq[i] == key) { seen = 1; break; }
        if (!seen && s_flagq_n < 128) s_flagq[s_flagq_n++] = key;
    }
    /* func_8004A8D4: banks = 0x8009CB48; arr = *(u32*)(banks + 8*bank); */
    uint32_t bt = 0x9CB48u + (uint32_t)bank * 8u;
    if (bt + 4u >= 0x200000u) return 0;
    uint32_t arr = rrm_u32(ram, bt) & 0x1FFFFFu;
    uint32_t w = arr + (uint32_t)(bit >> 5) * 4u;
    if (!arr || w + 4u >= 0x200000u) return 0;
    return (int)((rrm_u32(ram, w) >> (bit & 31)) & 1u);
}

/* hash of the flags the last walk depended on, as they read RIGHT NOW */
static uint32_t rb_flagsig(const uint8_t *ram)
{
    uint32_t h = 2166136261u;
    for (int i = 0; i < s_flagq_n; i++) {
        int bank = (s_flagq[i] >> 8) & 0xFF, bit = s_flagq[i] & 0xFF;
        h = (h ^ (uint32_t)s_flagq[i]) * 16777619u;
        h = (h ^ (uint32_t)rb_flag(ram, bank, bit)) * 16777619u;
    }
    return h ? h : 1u;
}
/* 15.09 ночь: режим (+3) и слот (+4) таблицы порядка из записи CREATE — обработчик func_800570F8
 * кладёт их в +72/+74 записи таблицы; для двойников в достройке (rl_dup_lose) */
static uint8_t  s_build_mode[64];
static uint16_t s_build_slot[64];
static void rb_put(uint32_t gp, int mode, int slot)
{
    for (int i = 0; i < s_build_n; i++) if (s_build_gp[i] == gp) return;
    if (s_build_n < 64) { s_build_mode[s_build_n] = (uint8_t)mode; s_build_slot[s_build_n] = (uint16_t)slot;
                          s_build_gp[s_build_n++] = gp; }
}
static int rb_sort_of(uint32_t gp, int *mode, int *slot)
{
    for (int i = 0; i < s_build_n; i++)
        if (s_build_gp[i] == gp) { *mode = s_build_mode[i]; *slot = s_build_slot[i]; return 1; }
    return 0;
}

/* Walk each instruction once: routines share tails and loop back on
 * themselves, and without this the replay spins until the step cap. */
static uint32_t s_seen_pc[4096]; static int s_seen_n = 0;
static int rb_seen(uint32_t pc)
{
    for (int i = 0; i < s_seen_n; i++) if (s_seen_pc[i] == pc) return 1;
    if (s_seen_n < 4096) s_seen_pc[s_seen_n++] = pc;
    return 0;
}

