static void rbc_destroy(int slot) { if (slot >= 0 && slot < 64) { s_rbc_slot[slot] = 0u; s_rbc_vis[slot] = 0; s_rbc_anygp[slot] = 0u; s_rbc_pc[slot] = 0u; if (s_rbc_camph) { s_rbc_camset[slot] = 0; s_rbc_camoff[slot] = 0; } } }
static void rbc_show(int slot, int on) { if (slot >= 0 && slot < 64) { s_rbc_vis[slot] = (uint8_t)(on ? 1 : 0); if (s_rbc_camph) { s_rbc_camset[slot] = (uint8_t)(on ? 1 : 0); s_rbc_camoff[slot] = (uint8_t)(on ? 0 : 1); } } }

