static uint16_t s_sf_onflag[16]; static int s_sf_onflag_n = 0;      /* (банк << 8 | бит) флагов развилок с заменой, которые сейчас СТОЯТ */
static int sf_has(const uint32_t *a, int n, uint32_t gp) { for (int i = 0; i < n; i++) if (a[i] == gp) return 1; return 0; }
static int sf_is_dead(uint32_t gp) { return sf_env() && sf_has(s_sf_dead, s_sf_dead_n, gp & 0x1FFFFFu); }
static int sf_is_live(uint32_t gp) { return sf_env() && sf_has(s_sf_live, s_sf_live_n, gp & 0x1FFFFFu); }
static uint32_t sf_cmd_len(const uint8_t *ram, uint32_t pc) {       /* длина команды, 0 — неизвестная */
    uint8_t op = ram[pc];
    if (op == 0x23) return 32u;
    if (op == 0x01 || op == 0x04 || op == 0x05 || op == 0x0C || op == 0x0E || op == 0x0F || op == 0x10 || op == 0x26 || op == 0x2F || op == 0x48) return 4u;   /* управляющие: в таблице длин их нет */
    if (op == 0x5A) return 4u + 8u * (uint32_t)ram[pc + 3];
    if (op == 0x28) { uint8_t b2 = ram[pc + 2]; if (b2 >= 12u) return 0u;
        uint32_t t = rrm_u32(ram, 0x19310u + (uint32_t)b2 * 4u);
        return (t == 0x80057464u) ? 48u : (t == 0x80057470u) ? 40u : (t == 0x8005747Cu) ? 36u : (t == 0x80057488u) ? 44u : (t == 0x800574B0u) ? 52u : 32u; }
    return s_op_size[op & 127];
}
/* проигрыш с адреса pc до RETURN с флагами из RAM: последний жилец каждого слота секций */
static void sf_play(const uint8_t *ram, uint32_t scr, uint32_t pc, int depth, uint32_t *slotgp, int *steps) {
    int cond = 0;
    while (depth <= 8 && pc >= 0x100000u && pc + 32u <= 0x200000u && (*steps)++ < 6000) {
        uint8_t op = ram[pc];
        if (op == 0x04 || op == 0x10) return;
        if (op == 0x0F || op == 0x01 || op == 0x05) {
            uint32_t tb = scr + (uint32_t)(int)(int16_t)(uint16_t)(ram[pc + 2] | (ram[pc + 3] << 8)) * 4u;
            if (tb + 4u < 0x200000u) sf_play(ram, scr, scr + rrm_u32(ram, tb), depth + 1, slotgp, steps);
            if (op == 0x05) return;
            pc += 4; continue;
        }
        if (op == 0x0C) { pc += (uint32_t)(int32_t)(int16_t)(uint16_t)(ram[pc + 2] | (ram[pc + 3] << 8)); continue; }
        if (op == 0x26) { cond = rb_flag(ram, ram[pc + 1], ram[pc + 2]) ? 2 : 64; pc += 4; continue; }
        if (op == 0x0E) { int n = (int8_t)ram[pc + 1];
            if (n == 0 || ((cond >> n) & 1)) pc += (uint32_t)(int32_t)(int16_t)(uint16_t)(ram[pc + 2] | (ram[pc + 3] << 8)); else pc += 4;
            continue; }
        if (op == 0x23) { if (ram[pc + 1] < 64) slotgp[ram[pc + 1]] = rrm_u32(ram, pc + 8u) & 0x1FFFFFu; pc += 32; continue; }
        if (op == 0x2F) { if (ram[pc + 1] == 3 && ram[pc + 2] < 64) slotgp[ram[pc + 2]] = 0u; pc += 4; continue; }
        { uint32_t sz = sf_cmd_len(ram, pc); if (!sz) return; pc += sz; }
    }
}
/* ⭐ 21.09.2026 (игрок: «чтобы игра шла гладко в 60 фпс»; замер DC_SIMSPIKE, слот 0: на смене ракурса такт 27-29 мс,
 * из них 15-22 мс - этот разбор развилок). В комнате 65 подпрограммы ракурсов переключают флаг зоны 3/32, подпись
 * состояния меняется, и комната пересобирается на КАЖДОЙ такой смене; а разбор на каждой развилке TESTFLAG+BRANCH
 * проигрывал ОБЕ ветки до конца подпрограммы - квадрат от длины скрипта (комната 65: ~1200 развилок на сборку). Почти
 * все развилки слотов секций не касаются: ветки сходятся через несколько команд. Идём по обеим веткам ШАГ В ШАГ (вперёд -
 * та, что отстала по адресу) до общей точки с одинаковым условием: дальше у веток одно и то же продолжение, и «замена»
 * (слот, занятый в обоих итогах разными группами) возможна, только если спорный слот есть уже сейчас. Нет спорного слота -
 * развилка без замены, ровно как дал бы полный проигрыш. Есть, ветки не сошлись или кончился запас шагов - прежний
 * полный проигрыш. Отличие возможно только там, где прежний упирался в потолок 6000 шагов.
 * DC_SF_FAST=0 - как было; =2 - самопроверка: считает обоими способами и пишет `sf check:`. */
typedef struct { uint32_t pc; int cond, done; uint32_t t[64]; } SfPath;
static void sf_path_step(const uint8_t *ram, uint32_t scr, int depth, SfPath *p, int *steps) {
    uint32_t pc = p->pc;
    if (!(depth <= 8 && pc >= 0x100000u && pc + 32u <= 0x200000u)) { p->done = 1; return; }
    uint8_t op = ram[pc];
    if (op == 0x04 || op == 0x10) { p->done = 1; return; }
    if (op == 0x0F || op == 0x01 || op == 0x05) {
        uint32_t tb = scr + (uint32_t)(int)(int16_t)(uint16_t)(ram[pc + 2] | (ram[pc + 3] << 8)) * 4u;
        if (tb + 4u < 0x200000u) sf_play(ram, scr, scr + rrm_u32(ram, tb), depth + 1, p->t, steps);
        if (op == 0x05) { p->done = 1; return; }
        p->pc = pc + 4; return;
    }
    if (op == 0x0C) { p->pc = pc + (uint32_t)(int32_t)(int16_t)(uint16_t)(ram[pc + 2] | (ram[pc + 3] << 8)); return; }
    if (op == 0x26) { p->cond = rb_flag(ram, ram[pc + 1], ram[pc + 2]) ? 2 : 64; p->pc = pc + 4; return; }
    if (op == 0x0E) { int n = (int8_t)ram[pc + 1];
        if (n == 0 || ((p->cond >> n) & 1)) p->pc = pc + (uint32_t)(int32_t)(int16_t)(uint16_t)(ram[pc + 2] | (ram[pc + 3] << 8)); else p->pc = pc + 4;
        return; }
    if (op == 0x23) { if (ram[pc + 1] < 64) p->t[ram[pc + 1]] = rrm_u32(ram, pc + 8u) & 0x1FFFFFu; p->pc = pc + 32; return; }
    if (op == 0x2F) { if (ram[pc + 1] == 3 && ram[pc + 2] < 64) p->t[ram[pc + 2]] = 0u; p->pc = pc + 4; return; }
    { uint32_t sz = sf_cmd_len(ram, pc); if (!sz) { p->done = 1; return; } p->pc = pc + sz; }
}
static long s_sf_why[2] = { 0, 0 }; static int s_sf_why_shown = 0;      /* замер: почему быстрый путь не сработал (спорный слот / не сошлись) */
/* 1 - доказано, что обе ветки дают один и тот же итоговый набор слотов; 0 - не доказано (нужен полный проигрыш) */
static int sf_fork_same(const uint8_t *ram, uint32_t scr, uint32_t pa, uint32_t pb, int depth, const uint32_t *cur, int steps0) {
    SfPath X, Y; X.pc = pa; Y.pc = pb; X.cond = Y.cond = 0; X.done = Y.done = 0;       /* sf_play начинает с cond = 0 */
    memcpy(X.t, cur, sizeof X.t); memcpy(Y.t, cur, sizeof Y.t);
    for (int it = 0; it < 600; it++) {
        /* «Замена» у полного проигрыша - слот, занятый в ОБОИХ итогах разными группами. В общей точке с одинаковым условием
         * продолжение у веток одно и то же: слоты, которые оно перепишет, в итогах совпадут, остальные останутся как сейчас.
         * Значит, нет спорного слота сейчас - не будет и в итоге (точно); есть - решит полный проигрыш (перепишет ли его
         * продолжение). Условия разные (вложенный TESTFLAG в одной из веток) - идём дальше до следующей общей точки. */
        if ((!X.done && !Y.done && X.pc == Y.pc && X.cond == Y.cond) || (X.done && Y.done)) {
            for (int q = 0; q < 64; q++) if (X.t[q] && Y.t[q] && X.t[q] != Y.t[q]) { s_sf_why[0]++; return 0; }
            sf_ovl_note(X.t, Y.t, cur);                                     /* 12.10: X - взятая ветка */
            return 1;
        }
        SfPath *p = X.done ? &Y : (Y.done ? &X : (X.pc <= Y.pc ? &X : &Y));
        int st = steps0;
        sf_path_step(ram, scr, depth, p, &st);
    }
    s_sf_why[1]++;
    if (s_sf_why_shown < 6) { s_sf_why_shown++;
        fprintf(stderr, "sf check: no join in 600 steps - fork targets %06X / %06X, now X %06X%s cond %d, Y %06X%s cond %d%c",
                pa & 0xFFFFFFu, pb & 0xFFFFFFu, X.pc & 0xFFFFFFu, X.done ? " done" : "", X.cond, Y.pc & 0xFFFFFFu, Y.done ? " done" : "", Y.cond, 10); }
    return 0;
}
static long s_sf_chk_forks = 0, s_sf_chk_same = 0, s_sf_chk_bad = 0;
static int s_sf_force = -1;                                               /* сверка DC_SF_FAST=3: способ на время одного расчёта */
static int sf_fast(void) { static int v = -1; if (v < 0) { const char *e = getenv("DC_SF_FAST"); v = e ? atoi(e) : 1; if (v < 0 || v > 3) v = 1; }
                           return (s_sf_force >= 0) ? s_sf_force : v; }
/* основной проход по взятым веткам; на каждой развилке TESTFLAG+BRANCH сравниваются обе ветки */
static void sf_scan(const uint8_t *ram, uint32_t scr, uint32_t pc, int depth, uint32_t *cur, int *steps, int sub_for_log) {
    int cond = 0, fb = -1, fbit = -1, fresh = 0;
    /* 21.09.2026: ПЕТЛЯ ОЖИДАНИЯ. Подпрограмма, которая ждёт флага (TESTFLAG; BRANCH назад), в разборе не кончается: та же
     * развилка с тем же условием и тем же набором слотов приходит снова и снова, пока не выйдет общий запас 6000 шагов, -
     * и на каждом круге обе ветки проигрывались заново (замер, комната 65, флаг 3/32 = 1: одна развилка 13ACCC ~1190 раз
     * за сборку, 20+ мс). Состояние разбора детерминировано, поэтому повтор развилки с тем же состоянием - уже петля:
     * выходим сразу, а запас шагов объявляем исчерпанным - ровно с тем, с чем вышел бы прежний разбор (вызвавшие уровни
     * тоже останавливаются, как останавливались). */
    uint32_t lp_pc[4], lp_t[4][64]; int lp_cond[4], lp_n = 0, lp_w = 0;
    while (depth <= 8 && pc >= 0x100000u && pc + 32u <= 0x200000u && (*steps)++ < 6000) {
        uint8_t op = ram[pc];
        if (op == 0x04 || op == 0x10) return;
        if (op == 0x0F || op == 0x01 || op == 0x05) {
            uint32_t tb = scr + (uint32_t)(int)(int16_t)(uint16_t)(ram[pc + 2] | (ram[pc + 3] << 8)) * 4u;
            if (tb + 4u < 0x200000u) sf_scan(ram, scr, scr + rrm_u32(ram, tb), depth + 1, cur, steps, sub_for_log);
            if (op == 0x05) return;
            pc += 4; fresh = 0; continue;
        }
        if (op == 0x0C) { pc += (uint32_t)(int32_t)(int16_t)(uint16_t)(ram[pc + 2] | (ram[pc + 3] << 8)); fresh = 0; continue; }
        if (op == 0x26) { fb = ram[pc + 1]; fbit = ram[pc + 2]; cond = rb_flag(ram, fb, fbit) ? 2 : 64; fresh = 1; pc += 4; continue; }
        if (op == 0x0E) {
            int n = (int8_t)ram[pc + 1];
            uint32_t pj = pc + (uint32_t)(int32_t)(int16_t)(uint16_t)(ram[pc + 2] | (ram[pc + 3] << 8)), pn = pc + 4u;
            int take = (n == 0 || ((cond >> n) & 1));
            int fk_same = 0;
            if (n != 0 && fresh && sf_fast() == 1) {
                int seen = 0, at = -1;
                for (int v = 0; v < lp_n; v++) if (lp_pc[v] == pc) { at = v; if (lp_cond[v] == cond && memcmp(lp_t[v], cur, sizeof lp_t[v]) == 0) seen = 1; break; }
                if (seen) { *steps = 6001; return; }
                if (at < 0) { if (lp_n < 4) at = lp_n++; else { at = lp_w; lp_w = (lp_w + 1) & 3; } }
                lp_pc[at] = pc; lp_cond[at] = cond; memcpy(lp_t[at], cur, sizeof lp_t[at]);
            }
            if (n != 0 && fresh && sf_fast()) { fk_same = sf_fork_same(ram, scr, take ? pj : pn, take ? pn : pj, depth, cur, *steps);
                                                s_sf_chk_forks++; if (fk_same) s_sf_chk_same++; }
            if (n != 0 && fresh && (!fk_same || sf_fast() == 2)) {       /* развилка по флагу: сравнить ветки */
                uint32_t A[64], B[64]; int st2 = *steps;
                memcpy(A, cur, sizeof A); memcpy(B, cur, sizeof B);
                sf_play(ram, scr, take ? pj : pn, depth, A, &st2); st2 = *steps;
                sf_play(ram, scr, take ? pn : pj, depth, B, &st2);
                int replaced = 0;
                for (int q = 0; q < 64; q++) if (A[q] && B[q] && A[q] != B[q]) { replaced = 1; break; }
                sf_ovl_note(A, B, cur);                                         /* 12.10: A - взятая ветка */
                if (fk_same && replaced) { s_sf_chk_bad++;                 /* самопроверка: быстрый путь сказал «одинаково», полный - «замена» */
                    fprintf(stderr, "sf check: MISMATCH room %d routine %d fork at %06X flag %d/%d%c", dc_room_current(), sub_for_log, pc & 0xFFFFFFu, fb, fbit, 10); }
                if (replaced) {
                    if (cond == 2 && fb >= 0 && s_sf_onflag_n < 16) s_sf_onflag[s_sf_onflag_n++] = (uint16_t)((fb << 8) | fbit);
                    char dl[240], ll[240]; int dn = 0, ln2 = 0; dl[0] = 0; ll[0] = 0;
                    for (int q = 0; q < 64; q++) {
                        if (B[q] && !sf_has(A, 64, B[q]) && !sf_has(s_sf_dead, s_sf_dead_n, B[q]) && s_sf_dead_n < 64) {
                            s_sf_dead[s_sf_dead_n++] = B[q]; if (dn < 220) dn += snprintf(dl + dn, sizeof dl - (size_t)dn, " %06X", B[q]); }
                        if (A[q] && !sf_has(B, 64, A[q]) && !sf_has(s_sf_live, s_sf_live_n, A[q]) && s_sf_live_n < 64) {
                            s_sf_live[s_sf_live_n++] = A[q]; if (ln2 < 220) ln2 += snprintf(ll + ln2, sizeof ll - (size_t)ln2, " %06X", A[q]); }
                    }
                    if (dn || ln2) fprintf(stderr, "story fork: room %d routine %d - flag %d/%d = %d switches a place: current version%s; the branch not taken (left out of the assembled room)%s (DC_STORY_FORK=0 off)%c",
                                           dc_room_current(), sub_for_log, fb, fbit, cond == 2, ln2 ? ll : " -", dn ? dl : " -", 10);
                }
            }
            pc = take ? pj : pn; fresh = 0; continue;
        }
        fresh = 0;
        if (op == 0x23) { if (ram[pc + 1] < 64) cur[ram[pc + 1]] = rrm_u32(ram, pc + 8u) & 0x1FFFFFu; pc += 32; continue; }
        if (op == 0x2F) { if (ram[pc + 1] == 3 && ram[pc + 2] < 64) cur[ram[pc + 2]] = 0u; pc += 4; continue; }
        { uint32_t sz = sf_cmd_len(ram, pc); if (!sz) return; pc += sz; }
    }
}
static int sf_is_dead_fwd(uint32_t gp) { return sf_is_dead(gp); }
static void sf_build_core(const uint8_t *ram, uint32_t cams, uint32_t scr, uint32_t ncam);
static int sf_set_eq(const uint32_t *a, int na, const uint32_t *b, int nb) {
    for (int i = 0; i < na; i++) if (!sf_has(b, nb, a[i])) return 0;
    for (int i = 0; i < nb; i++) if (!sf_has(a, na, b[i])) return 0;
    return 1;
}
static void sf_build(const uint8_t *ram, uint32_t cams, uint32_t scr, uint32_t ncam) {
    if (sf_fast() != 3) { sf_build_core(ram, cams, scr, ncam); return; }
    uint32_t d1[64], l1[64], f1[16], f2[16]; int dn, ln, fn;
    s_sf_force = 1; sf_build_core(ram, cams, scr, ncam);
    dn = s_sf_dead_n; ln = s_sf_live_n; fn = s_sf_onflag_n;
    memcpy(d1, s_sf_dead, sizeof d1); memcpy(l1, s_sf_live, sizeof l1);
    for (int i = 0; i < 16; i++) f1[i] = s_sf_onflag[i];
    s_sf_force = 0; sf_build_core(ram, cams, scr, ncam);
    s_sf_force = -1;
    for (int i = 0; i < 16; i++) f2[i] = s_sf_onflag[i];
    int ok = sf_set_eq(d1, dn, s_sf_dead, s_sf_dead_n) && sf_set_eq(l1, ln, s_sf_live, s_sf_live_n) && sf_set_eq(f1, fn, f2, s_sf_onflag_n);
    fprintf(stderr, "sf dual: room %d - fast walk %s the full replay (branches left out %d/%d, current versions %d/%d, fork flags on %d/%d)%c",
            dc_room_current(), ok ? "MATCHES" : "DIFFERS FROM", dn, s_sf_dead_n, ln, s_sf_live_n, fn, s_sf_onflag_n, 10);
}
static void sf_build_core(const uint8_t *ram, uint32_t cams, uint32_t scr, uint32_t ncam) {
    s_sf_dead_n = 0; s_sf_live_n = 0; s_sf_onflag_n = 0; s_sf_ovl_n = 0;
    if (!sf_env()) return;
    uint32_t cur[64]; int steps = 0;
    memset(cur, 0, sizeof cur);
    if (scr + 4u < 0x200000u) sf_scan(ram, scr, scr + rrm_u32(ram, scr), 0, cur, &steps, 0);      /* инициализация */
    uint8_t done[256]; memset(done, 0, sizeof done);
    for (uint32_t c = 0; c < ncam && c < 64u; c++) {
        uint32_t cr = cams + 4u + c * 68u; if (cr + 68u >= 0x200000u) break;
        int sub = ram[cr + 2]; if (!sub || done[sub] || !s_rb_cam_use[c]) continue;
        done[sub] = 1;
        uint32_t tb = scr + (uint32_t)sub * 4u; if (tb + 4u >= 0x200000u) continue;
        uint32_t c2[64]; memcpy(c2, cur, sizeof c2); steps = 0;
        sf_scan(ram, scr, scr + rrm_u32(ram, tb), 0, c2, &steps, sub);
    }
    if (sf_fast() == 2)
        fprintf(stderr, "sf check: room %d - %ld forks, %ld proven the same by the lockstep walk (not proven: contested slot %ld, no join %ld), %ld mismatches against the full replay%c",
                dc_room_current(), s_sf_chk_forks, s_sf_chk_same, s_sf_why[0], s_sf_why[1], s_sf_chk_bad, 10);
    s_sf_chk_forks = s_sf_chk_same = 0; s_sf_why[0] = s_sf_why[1] = 0;
    /* действующая версия важнее: группа, которую где-то создаёт взятая ветка, не «невзятая» */
    for (int i = 0; i < s_sf_dead_n; ) { if (sf_has(s_sf_live, s_sf_live_n, s_sf_dead[i])) s_sf_dead[i] = s_sf_dead[--s_sf_dead_n]; else i++; }
    if (s_sf_ovl_n > 0 && sf_ovl_env()) {                              /* 12.10: сюжетные накладки (sf_ovl_*) */
        char ol[400]; int on = 0; ol[0] = 0;
        for (int i = 0; i < s_sf_ovl_n && on < 380; i++) on += snprintf(ol + on, sizeof ol - (size_t)on, " %06X", s_sf_ovl[i]);
        fprintf(stderr, "story overlay: room %d - groups created only by the taken branch of a flag test:%s - in the completion "
                        "drawn live, over their twins (DC_STORY_OVERLAY=0 off)%c", dc_room_current(), ol, 10);
    }
}
