/* 19.10.2026: подпись зовут 150-300 раз за кадр (обход, проход игры, панель). Хеш 136 байт заменён сверкой тех же байт с прошлым
 * вызовом: байты те же - подпись та же (она от них одних и зависит). DC_SS_SIG_MEMO=0 - как было. */
static uint32_t ss_room_sig(const uint8_t *ram) {
    static int memo = -1;
    if (memo < 0) { const char *e = getenv("DC_SS_SIG_MEMO"); memo = (e && *e == '0') ? 0 : 1; }
    static uint8_t last[136]; static uint32_t last_h = 0;
    uint32_t h = 2166136261u, scr = rrm_u32(ram, 0x100014u) & 0x1FFFFFu;
    const int has_scr = (scr >= 0x100000u && scr + 96u < 0x200000u);
    if (memo && last_h && memcmp(last, ram + 0x100000u, 40u) == 0 && (!has_scr || memcmp(last + 40, ram + scr, 96u) == 0))
        return last_h;                       /* первые 40 байт те же - и указатель scr (0x100014) тот же */
    for (uint32_t i = 0; i < 40u; i++) h = (h ^ ram[0x100000u + i]) * 16777619u;
    if (has_scr) for (uint32_t i = 0; i < 96u; i++) h = (h ^ ram[scr + i]) * 16777619u;
    h = h ? h : 1u;
    if (memo) { memcpy(last, ram + 0x100000u, 40u); if (has_scr) memcpy(last + 40, ram + scr, 96u); last_h = h; }
    return h;
}
