static int      s_vz_n = 0;
static long     s_vz_skipped = 0;
static uint32_t s_vz_sig = 0, s_vz_fsig = 0; static int s_vz_live = 0;
static uint32_t s_vz_g[64]; static uint8_t s_vz_gv[64]; static int s_vz_gn = 0;   /* 27.10: группы разбора и есть ли у них грани-версии */
/* начало обхода: снимок решений годен только для той же комнаты и тех же флагов (адреса групп у всех комнат одни) */
static void vz_frame_check(const uint8_t *ram) {
    s_vz_live = (s_vz_n > 0 && s_build_n > 0 && s_vz_sig == rrm_signature(ram) && s_vz_fsig == s_build_flagsig) ? 1 : 0;
    /* ⭐ 22.09.2026 (игрок, слот 12: «геометрия уровня в сцене не полная, а должна быть полной — та, что в кадре,
     * как в оригинале»). Пока кадром правит камера ИГРЫ (скрипт держит игрока / признак сцены / режим 4 / ролик),
     * правило «версия места из набора чужого ракурса» не применяется: у родного кадра сцены свой ракурс, и куски,
     * которые наше правило считает «чужими», в нём как раз видны (замер: с DC_VARIANT_ZONE=0 кадр сцены заполнялся,
     * 1120 треугольников против ~600, пропадала чёрная дыра слева вверху). Решение — раз за кадр, не на полигон.
     * DC_SCENE_FULLROOM=0 — как было. */
    if (s_vz_live) {
        static int sf = -1;
        if (sf < 0) { const char *e = getenv("DC_SCENE_FULLROOM"); sf = (e && *e == '0') ? 0 : 1; }
        if (sf) {
            extern int dc_cut_camera(void); extern int dc_scripted_now(void); extern int dc_scene_cam_ready(void);
            if ((dc_cut_camera() || dc_scripted_now()) && dc_scene_cam_ready()) {
                s_vz_live = 0;
                static int said = 0; static unsigned long long n = 0;
                if (!said || (++n % 600) == 0) { said = 1;
                    fprintf(stderr, "versions: scene - the whole room, other-shot versions are kept (DC_SCENE_FULLROOM=0 off)%c", 10); }
            }
        }
    }
}
static int vz_has(uint32_t rec) {                   /* запись выброшена правилом (без счётчика кадра) */
    rec &= 0x1FFFFFu;
    uint32_t i = (rec * 2654435761u) >> 18;
    for (uint32_t pr = 0; pr < VZ_HASHN; pr++, i = (i + 1u) & (VZ_HASHN - 1u)) {
        if (s_vz_hash[i] == rec + 1u) return 1;
        if (!s_vz_hash[i]) return 0;
    }
    return 0;
}
/* 27.10: группа по последнему разбору этой комнаты - вариант места (у неё есть грани, которые покрывает кусок чужого ракурса, 1),
 * единственный кусок (0); разбора нет или он не для этой комнаты и флагов (-1) */
static int vz_group_kind(const uint8_t *ram, uint32_t gp) {
    if (s_vz_gn <= 0 || s_build_n <= 0 || s_vz_sig != rrm_signature(ram) || s_vz_fsig != s_build_flagsig) return -1;
    gp &= 0x1FFFFFu;
    for (int g = 0; g < s_vz_gn; g++) if (s_vz_g[g] == gp) return s_vz_gv[g];
    return -1;
}
static int vz_skip_poly(uint32_t rec) {
    if (s_vz_n <= 0 || !s_vz_live) return 0;
    rec &= 0x1FFFFFu;
    uint32_t i = (rec * 2654435761u) >> 18;
    for (uint32_t pr = 0; pr < VZ_HASHN; pr++, i = (i + 1u) & (VZ_HASHN - 1u)) {
        if (s_vz_hash[i] == rec + 1u) { if (s_rl_target & 1) s_vz_skipped++; return 1; }
        if (!s_vz_hash[i]) return 0;
    }
    return 0;
}
static void vz_add(uint32_t rec) {
    rec &= 0x1FFFFFu;
    if ((uint32_t)s_vz_n >= VZ_HASHN / 2u) return;
    uint32_t i = (rec * 2654435761u) >> 18;
    for (uint32_t pr = 0; pr < VZ_HASHN; pr++, i = (i + 1u) & (VZ_HASHN - 1u)) {
        if (s_vz_hash[i] == rec + 1u) return;
        if (!s_vz_hash[i]) { s_vz_hash[i] = rec + 1u; s_vz_n++; return; }
    }
}
static void vz_walk_log(void) {
    static unsigned last_t = 0; static long nlog = 0;
    extern unsigned int SDL_GetTicks(void);
    if (!vz_env() || s_vz_n <= 0) return;
    unsigned t = SDL_GetTicks();
    if (t - last_t < 5000u || nlog >= 200) return;
    last_t = t; nlog++;
    fprintf(stderr, "versions: other-shot versions not drawn %ld (5 s)%c", s_vz_skipped, 10);
    s_vz_skipped = 0;
}
typedef struct { float a[3], b[3], c[3]; float n[3]; uint8_t g; } VzTri;   /* n (28.09): единичная нормаль, 0 — вырожденный */
/* 28.09: единичная нормаль треугольника (0 — вырожденный) */
static void vz_tri_normal(const float *a, const float *b, const float *c, float *n) {
    const float ux = b[0] - a[0], uy = b[1] - a[1], uz = b[2] - a[2], vx = c[0] - a[0], vy = c[1] - a[1], vz = c[2] - a[2];
    float nx = uy * vz - uz * vy, ny = uz * vx - ux * vz, nz = ux * vy - uy * vx;
    const float l = sqrtf(nx * nx + ny * ny + nz * nz);
    if (l < 1e-3f) { n[0] = n[1] = n[2] = 0.f; return; }
    n[0] = nx / l; n[1] = ny / l; n[2] = nz / l;
}
static float vz_pt_tri_d2(const float *p, const float *a, const float *b, const float *c) {
    /* квадрат расстояния от точки до треугольника (ближайшая точка по Эриксону) */
    float ab[3], ac[3], ap[3], q[3];
    for (int i = 0; i < 3; i++) { ab[i] = b[i] - a[i]; ac[i] = c[i] - a[i]; ap[i] = p[i] - a[i]; }
    float d1 = ab[0]*ap[0] + ab[1]*ap[1] + ab[2]*ap[2], d2 = ac[0]*ap[0] + ac[1]*ap[1] + ac[2]*ap[2];
    if (d1 <= 0.f && d2 <= 0.f) { for (int i = 0; i < 3; i++) q[i] = a[i]; goto done; }
    { float bp[3]; for (int i = 0; i < 3; i++) bp[i] = p[i] - b[i];
      float d3 = ab[0]*bp[0] + ab[1]*bp[1] + ab[2]*bp[2], d4 = ac[0]*bp[0] + ac[1]*bp[1] + ac[2]*bp[2];
      if (d3 >= 0.f && d4 <= d3) { for (int i = 0; i < 3; i++) q[i] = b[i]; goto done; }
      float vc = d1 * d4 - d3 * d2;
      if (vc <= 0.f && d1 >= 0.f && d3 <= 0.f) { float v = d1 / (d1 - d3); for (int i = 0; i < 3; i++) q[i] = a[i] + v * ab[i]; goto done; }
      float cp[3]; for (int i = 0; i < 3; i++) cp[i] = p[i] - c[i];
      float d5 = ab[0]*cp[0] + ab[1]*cp[1] + ab[2]*cp[2], d6 = ac[0]*cp[0] + ac[1]*cp[1] + ac[2]*cp[2];
      if (d6 >= 0.f && d5 <= d6) { for (int i = 0; i < 3; i++) q[i] = c[i]; goto done; }
      float vb = d5 * d2 - d1 * d6;
      if (vb <= 0.f && d2 >= 0.f && d6 <= 0.f) { float w = d2 / (d2 - d6); for (int i = 0; i < 3; i++) q[i] = a[i] + w * ac[i]; goto done; }
      float va = d3 * d6 - d5 * d4;
      if (va <= 0.f && (d4 - d3) >= 0.f && (d5 - d6) >= 0.f) {
          float w = (d4 - d3) / ((d4 - d3) + (d5 - d6)); for (int i = 0; i < 3; i++) q[i] = b[i] + w * (c[i] - b[i]); goto done; }
      float den = 1.f / (va + vb + vc); float v = vb * den, w = vc * den;
      for (int i = 0; i < 3; i++) q[i] = a[i] + ab[i] * v + ac[i] * w; }
done:
    { float dx = p[0] - q[0], dy = p[1] - q[1], dz = p[2] - q[2]; return dx*dx + dy*dy + dz*dz; }
}
static int vz_in_quad(const float *q, float x, float z) {
    int s = 0;
    for (int j = 0; j < 4; j++) {
        float ax = q[j * 2], az = q[j * 2 + 1], bx = q[((j + 1) % 4) * 2], bz = q[((j + 1) % 4) * 2 + 1];
        float cr = (bx - ax) * (z - az) - (bz - az) * (x - ax);
        if (cr > 1e-3f) { if (s < 0) return 0; s = 1; }
        else if (cr < -1e-3f) { if (s > 0) return 0; s = -1; }
    }
    return 1;
}
static float vz_quad_dist(const float *q, float x, float z) {
    if (vz_in_quad(q, x, z)) return 0.f;
    float best = 1e30f;
    for (int j = 0; j < 4; j++) {
        float ax = q[j * 2], az = q[j * 2 + 1], bx = q[((j + 1) % 4) * 2], bz = q[((j + 1) % 4) * 2 + 1];
        float ex = bx - ax, ez = bz - az, l2 = ex * ex + ez * ez;
        float t = (l2 > 1e-6f) ? ((x - ax) * ex + (z - az) * ez) / l2 : 0.f;
        if (t < 0.f) t = 0.f; if (t > 1.f) t = 1.f;
        float dx = x - (ax + t * ex), dz = z - (az + t * ez), d = dx * dx + dz * dz;
        if (d < best) best = d;
    }
    return sqrtf(best);
}
#define VZ_CELL 1024.f
#define VZ_GRID 64
/* 21.09.2026: вынесено из vz_build без изменений - мягкий отодвиг нужен и тогда, когда результат правила взят из памяти */
static int vz_softpush(const uint8_t *ram, int ng) {
    int soft_n = 0;
    static int soft_on = -1;
    if (soft_on < 0) { const char *eu = getenv("DC_VARIANT_ZONE_VA"); soft_on = (eu && *eu == '0') ? 0 : 1; }
    if ((g_dc_vz_vaundo_ovr >= 0 ? g_dc_vz_vaundo_ovr : soft_on) && va_active() && s_va && s_vz_n > 0) {
        for (int g = 0; g < ng; g++) {        /* живые (не выброшенные) копии дальнего вида у решённых граней */
            uint32_t gp = s_build_gp[g] & 0x1FFFFFu;
            if (gp < 0x100000u || gp + 12u >= 0x200000u) continue;
            uint32_t tri = rrm_u32(ram, gp) & 0x1FFFFFu, quad = rrm_u32(ram, gp + 4u) & 0x1FFFFFu;
            int ntt = rrm_u16(ram, gp + 8u), nqq = rrm_u16(ram, gp + 10u);
            for (int ps = 0; ps < 2; ps++) {
                uint32_t base = ps ? quad : tri; int n = ps ? nqq : ntt, nv = ps ? 4 : 3; uint32_t sz = ps ? 52u : 40u;
                if (n <= 0 || n > 8000 || base < 0x100000u || base + (uint32_t)n * sz > 0x200000u) continue;
                for (int i = 0; i < n; i++) {
                    uint32_t rec = base + (uint32_t)i * sz;
                    VaEnt *m = va_slot(va_key(ram, rec, nv), 0);
                    if (!m || m->st != 3 || va_is_near(m, va_look(ram, rec, nv)) || vz_has(rec)) continue;
                    if (m->alive < 65535u) m->alive++;
                }
            }
        }
        for (uint32_t i = 0; i < VA_TABN; i++)
            if (s_va[i].key && s_va[i].st == 3 && !s_va[i].alive) { s_va[i].soft = 1; soft_n++; }
    }
    return soft_n;
}
/* ⭐ 21.09.2026 (гладкие смены ракурса): правило считает покрытие полигонов сеткой треугольников - ~5.7 мс в комнате 65, а
 * комната там пересобирается на каждой смене ракурса (флаг зоны 3/32 туда-обратно). Результат - функция входов: блок
 * комнаты, собранный набор групп, наборы и зоны ракурсов, группы «не покрывают», действующие сюжетные версии, допуски.
 * Те же входы, что у одной из прошлых сборок, - берём её результат (таблица выброшенных записей), пересчёта нет.
 * DC_VZ_MEMO=0 - как было. */
#define VZ_MEMO_N 4
typedef struct { uint64_t key; int valid, n, ndrop, nhome, nkept; unsigned age; uint32_t hash[VZ_HASHN]; uint32_t g[64]; uint8_t gv[64]; int gn; } VzMemo;
static VzMemo s_vz_memo[VZ_MEMO_N]; static unsigned s_vz_memo_clock = 0;
static int vz_memo_on(void) { static int v = -1; if (v < 0) { const char *e = getenv("DC_VZ_MEMO"); v = (e && *e == '0') ? 0 : 1; } return v; }
static uint64_t vz_h64(uint64_t h, const void *p, size_t n) { const uint8_t *b = (const uint8_t *)p; for (size_t i = 0; i < n; i++) { h ^= b[i]; h *= 1099511628211ull; } return h; }
static VzMemo *vz_memo_get(uint64_t key) {
    for (int i = 0; i < VZ_MEMO_N; i++) if (s_vz_memo[i].valid && s_vz_memo[i].key == key) { s_vz_memo[i].age = ++s_vz_memo_clock; return &s_vz_memo[i]; }
    return NULL;
}
static void vz_memo_put(uint64_t key, int ndrop, int nhome, int nkept) {
    int w = 0;
    for (int i = 0; i < VZ_MEMO_N; i++) { if (!s_vz_memo[i].valid) { w = i; break; } if (s_vz_memo[i].age < s_vz_memo[w].age) w = i; }
    VzMemo *m = &s_vz_memo[w];
    m->key = key; m->valid = 1; m->n = s_vz_n; m->ndrop = ndrop; m->nhome = nhome; m->nkept = nkept; m->age = ++s_vz_memo_clock;
    memcpy(m->hash, s_vz_hash, sizeof m->hash);
    memcpy(m->g, s_vz_g, sizeof m->g); memcpy(m->gv, s_vz_gv, sizeof m->gv); m->gn = s_vz_gn;   /* 27.10 */
}
static void vz_build(const uint8_t *ram, uint32_t cams, uint32_t scr, uint32_t ncam) {
    memset(s_vz_hash, 0, sizeof s_vz_hash); s_vz_n = 0; s_vz_live = 0; s_vz_sig = rrm_signature(ram); s_vz_fsig = s_build_flagsig; s_vz_gn = 0;
    extern unsigned int SDL_GetTicks(void);
    unsigned vz_t0 = SDL_GetTicks();
    if (!vz_env() || s_build_n <= 0 || ncam == 0u || ncam > 64u) return;
    static float tol = -1.f, covf = -1.f, parf = -1.f; static int dbg = -1;
    if (tol < 0.f) { const char *e = getenv("DC_VARIANT_ZONE_TOL"); tol = e ? (float)atof(e) : 150.f; if (tol < 1.f) tol = 1.f;
                     e = getenv("DC_VARIANT_ZONE_COV"); covf = e ? (float)atof(e) : 0.9f;
                     e = getenv("DC_VARIANT_ZONE_PAR"); parf = e ? (float)atof(e) : -0.5f;   /* 28.09: обратная сторона не покрывает (0 — выкл) */
                     e = getenv("DC_VARIANT_ZONE_LOG"); dbg = (e && *e == '1') ? 1 : 0; }
    const int ng = s_build_n;
    /* группы, которые достройка не рисует (DC_ROOM_SKIP), и мелкие куски — не покрывают */
    uint64_t nocover = 0; int gpoly[64];
    { const char *es = g_dc_room_skip_ovr_on ? g_dc_room_skip_ovr : getenv("DC_ROOM_SKIP");   /* 17.09 день: порт zf_var roomskip */
      for (int g = 0; g < ng; g++) {
          uint32_t gp = s_build_gp[g] & 0x1FFFFFu;
          gpoly[g] = (gp + 12u < 0x200000u) ? (int)rrm_u16(ram, gp + 8u) + (int)rrm_u16(ram, gp + 10u) : 0;
          if (gpoly[g] < 3) nocover |= 1ull << g;
          if (es) { char pat[8]; snprintf(pat, sizeof pat, "%06X", gp); if (strstr(es, pat)) nocover |= 1ull << g; }
      } }
    /* (1) наборы ракурсов и их зоны */
    uint64_t cmask[64]; float cq[64][8]; int nc = 0;
    for (uint32_t c = 0; c < ncam; c++) {
        uint32_t cr = cams + 4u + c * 68u;
        if (cr + 68u >= 0x200000u) break;
        int sub = ram[cr + 2];
        if (!sub) continue;
        if (c < 64u && !s_rb_cam_use[c]) continue;        /* 17.09 день: ракурс другой фазы на тех же местах (rp_*) */
        memset(s_rbc_slot, 0, sizeof s_rbc_slot); memset(s_rbc_vis, 0, sizeof s_rbc_vis);
        s_rbc_on = 1;
        s_seen_n = 0; rb_run(ram, scr, 0, 0);
        s_seen_n = 0; rb_run(ram, scr, sub, 0);
        s_rbc_on = 0; s_seen_n = 0;
        uint64_t m = 0;
        for (int sl = 0; sl < 64; sl++) {
            uint32_t gp = s_rbc_slot[sl];
            if (!gp || gp == 0xFFFFFFFFu || !s_rbc_vis[sl]) continue;
            gp &= 0x1FFFFFu;
            for (int g = 0; g < ng; g++) if ((s_build_gp[g] & 0x1FFFFFu) == gp) { m |= 1ull << g; break; }
        }
        if (!m) continue;
        cmask[nc] = m;
        for (int j = 0; j < 8; j++) cq[nc][j] = (float)rrm_s16(ram, cr + 4u + (uint32_t)j * 2u);
        if (dbg) {
            char gl[400]; int gn = 0; gl[0] = 0;
            for (int g = 0; g < ng && gn < 380; g++) if ((m >> g) & 1ull) gn += snprintf(gl + gn, sizeof gl - (size_t)gn, " %06X", s_build_gp[g] & 0x1FFFFFu);
            fprintf(stderr, "versions: shot %u type %d sub %d zone (%.0f,%.0f) (%.0f,%.0f) (%.0f,%.0f) (%.0f,%.0f) groups%s%c",
                    c, ram[cr], sub, cq[nc][0], cq[nc][1], cq[nc][2], cq[nc][3], cq[nc][4], cq[nc][5], cq[nc][6], cq[nc][7], gl, 10);
        }
        nc++;
    }
    if (nc < 2) return;
    uint64_t allm = 0; for (int i = 0; i < nc; i++) allm |= cmask[i];
    int exclusive = 0;
    for (int i = 0; i < nc && !exclusive; i++) if (cmask[i] != allm) exclusive = 1;
    if (!exclusive) {
        fprintf(stderr, "versions: every shot shows the same room groups (%d shots) - nothing to choose%c", nc, 10);
        return;
    }
    uint64_t vzk = 0;
    if (vz_memo_on()) {
        uint64_t h = 1469598103934665603ull; int room_k = dc_room_current();
        uint64_t livem_k = 0; for (int g2 = 0; g2 < ng; g2++) if (sf_is_live(s_build_gp[g2])) livem_k |= 1ull << g2;
        h = vz_h64(h, &room_k, sizeof room_k); h = vz_h64(h, &s_vz_sig, sizeof s_vz_sig); h = vz_h64(h, &ng, sizeof ng);
        for (int g = 0; g < ng; g++) {
            uint32_t gp = s_build_gp[g] & 0x1FFFFFu;
            h = vz_h64(h, &gp, sizeof gp); h = vz_h64(h, &gpoly[g], sizeof gpoly[g]);
            if (gp >= 0x100000u && gp + 12u < 0x200000u) {
                h = vz_h64(h, ram + gp, 12);                                         /* указатели и счётчики группы */
                uint32_t tri = rrm_u32(ram, gp) & 0x1FFFFFu, quad = rrm_u32(ram, gp + 4u) & 0x1FFFFFu;
                int ntt = rrm_u16(ram, gp + 8u), nqq = rrm_u16(ram, gp + 10u);
                if (ntt > 0 && tri >= 0x100000u && tri + 160u <= 0x200000u) h = vz_h64(h, ram + tri, (size_t)(ntt < 4 ? ntt : 4) * 40u);
                if (nqq > 0 && quad >= 0x100000u && quad + 208u <= 0x200000u) h = vz_h64(h, ram + quad, (size_t)(nqq < 4 ? nqq : 4) * 52u);
            }
        }
        h = vz_h64(h, &nocover, sizeof nocover); h = vz_h64(h, &nc, sizeof nc);
        h = vz_h64(h, cmask, sizeof(uint64_t) * (size_t)nc); h = vz_h64(h, cq, sizeof(float) * 8u * (size_t)nc);
        h = vz_h64(h, &livem_k, sizeof livem_k); h = vz_h64(h, &tol, sizeof tol); h = vz_h64(h, &covf, sizeof covf);
        h = vz_h64(h, &parf, sizeof parf);                                        /* 28.09 */
        vzk = h ? h : 1ull;
        VzMemo *m = vz_memo_get(vzk);
        if (m) {
            memcpy(s_vz_hash, m->hash, sizeof s_vz_hash); s_vz_n = m->n;
            memcpy(s_vz_g, m->g, sizeof s_vz_g); memcpy(s_vz_gv, m->gv, sizeof s_vz_gv); s_vz_gn = m->gn;   /* 27.10 */
            int soft_n = vz_softpush(ram, ng);
            s_vz_live = (s_vz_n > 0);
            fprintf(stderr, "versions: place look from its shot zone - same inputs as an earlier build of this room, result reused: polygons at home %d, "
                            "other-shot versions not drawn %d, not covered kept %d; soft push %d; %u ms (DC_VZ_MEMO=0 recomputes)%c",
                    m->nhome, m->ndrop, m->nkept, soft_n, SDL_GetTicks() - vz_t0, 10);
            return;
        }
    }
    /* (2) непрозрачные треугольники всех мировых групп по сетке x,z */
    int ntri = 0;
    for (int g = 0; g < ng; g++) if (!((nocover >> g) & 1ull)) {
        uint32_t gp = s_build_gp[g] & 0x1FFFFFu;
        int nt = rrm_u16(ram, gp + 8u), nq = rrm_u16(ram, gp + 10u);
        ntri += nt + 2 * nq;
    }
    if (ntri <= 0 || ntri > 200000) return;
    VzTri *tr = (VzTri *)malloc((size_t)ntri * sizeof *tr);
    static int cellc[VZ_GRID * VZ_GRID + 1];
    if (!tr) return;
    int nt_all = 0;
    for (int g = 0; g < ng; g++) {
        if ((nocover >> g) & 1ull) continue;
        uint32_t gp = s_build_gp[g] & 0x1FFFFFu;
        uint32_t tri = rrm_u32(ram, gp) & 0x1FFFFFu, quad = rrm_u32(ram, gp + 4u) & 0x1FFFFFu;
        int ntt = rrm_u16(ram, gp + 8u), nqq = rrm_u16(ram, gp + 10u);
        for (int pass = 0; pass < 2; pass++) {
            uint32_t base = pass ? quad : tri; int n = pass ? nqq : ntt, nv = pass ? 4 : 3; uint32_t sz = pass ? 52u : 40u;
            if (n <= 0 || base < 0x100000u || base + (uint32_t)n * sz > 0x200000u) continue;
            for (int i = 0; i < n; i++) {
                uint32_t rec = base + (uint32_t)i * sz;
                if (ram[rec + ((nv == 3) ? 31u : 39u)] & 2u) continue;          /* полупрозрачный — не покрывает */
                float V[4][3]; int big = 0;
                for (int k = 0; k < nv; k++) for (int q = 0; q < 3; q++) {
                    V[k][q] = (float)rrm_s16(ram, rec + (uint32_t)k * 8u + (uint32_t)q * 2u);
                    if (V[k][q] > 30000.f || V[k][q] < -30000.f) big = 1;
                }
                if (big) continue;                                                  /* задники неба */
                for (int t = 0; t < ((nv == 4) ? 2 : 1); t++) {
                    static const int ti[2][3] = { { 0, 1, 2 }, { 1, 3, 2 } };
                    VzTri *o = &tr[nt_all++];
                    for (int q = 0; q < 3; q++) { o->a[q] = V[ti[t][0]][q]; o->b[q] = V[ti[t][1]][q]; o->c[q] = V[ti[t][2]][q]; }
                    vz_tri_normal(o->a, o->b, o->c, o->n);
                    o->g = (uint8_t)g;
                }
            }
        }
    }
    /* сетка: ячейки 1024 ед. по x,z, треугольник — во все ячейки своего габарита + допуск */
    memset(cellc, 0, sizeof cellc);
    #define VZ_CIDX(v) ((int)floorf(((v) + 32768.f) / VZ_CELL))
    for (int pass = 0; pass < 2; pass++) {
        static int *cells = NULL; static int cells_cap = 0; int total = 0;
        if (pass == 1) {
            for (int i = 0; i < VZ_GRID * VZ_GRID; i++) { int c0 = cellc[i]; cellc[i] = total; total += c0; }
            cellc[VZ_GRID * VZ_GRID] = total;
            if (total > cells_cap) { free(cells); cells = (int *)malloc((size_t)total * sizeof(int)); cells_cap = cells ? total : 0; }
            if (!cells) { free(tr); return; }
        }
        static int *fillp = NULL; static int fillp_cap = 0;
        if (pass == 1) {
            if (fillp_cap < VZ_GRID * VZ_GRID) { free(fillp); fillp = (int *)malloc(sizeof(int) * VZ_GRID * VZ_GRID); fillp_cap = fillp ? VZ_GRID * VZ_GRID : 0; }
            if (!fillp) { free(tr); return; }
            for (int i = 0; i < VZ_GRID * VZ_GRID; i++) fillp[i] = cellc[i];
        }
        for (int i = 0; i < nt_all; i++) {
            float mnx = fminf(fminf(tr[i].a[0], tr[i].b[0]), tr[i].c[0]) - tol, mxx = fmaxf(fmaxf(tr[i].a[0], tr[i].b[0]), tr[i].c[0]) + tol;
            float mnz = fminf(fminf(tr[i].a[2], tr[i].b[2]), tr[i].c[2]) - tol, mxz = fmaxf(fmaxf(tr[i].a[2], tr[i].b[2]), tr[i].c[2]) + tol;
            int x0 = VZ_CIDX(mnx), x1 = VZ_CIDX(mxx), z0 = VZ_CIDX(mnz), z1 = VZ_CIDX(mxz);
            if (x0 < 0) x0 = 0; if (z0 < 0) z0 = 0; if (x1 >= VZ_GRID) x1 = VZ_GRID - 1; if (z1 >= VZ_GRID) z1 = VZ_GRID - 1;
            for (int cx = x0; cx <= x1; cx++) for (int cz = z0; cz <= z1; cz++) {
                int ci = cz * VZ_GRID + cx;
                if (pass == 0) cellc[ci]++; else cells[fillp[ci]++] = i;
            }
        }
        if (pass == 1) {
            /* (3) полигоны-кандидаты */
            float tol2 = tol * tol;
            uint64_t sf_livem = 0; for (int g2 = 0; g2 < ng; g2++) if (sf_is_live(s_build_gp[g2])) sf_livem |= 1ull << g2;
            int ndrop = 0, nhome = 0, nkept = 0, byg[64]; memset(byg, 0, sizeof byg);
            for (int g = 0; g < ng; g++) {
                if (gpoly[g] < 3) continue;
                uint32_t gp = s_build_gp[g] & 0x1FFFFFu;
                uint32_t tri = rrm_u32(ram, gp) & 0x1FFFFFu, quad = rrm_u32(ram, gp + 4u) & 0x1FFFFFu;
                int ntt = rrm_u16(ram, gp + 8u), nqq = rrm_u16(ram, gp + 10u);
                for (int ps = 0; ps < 2; ps++) {
                    uint32_t base = ps ? quad : tri; int n = ps ? nqq : ntt, nv = ps ? 4 : 3; uint32_t sz = ps ? 52u : 40u;
                    if (n <= 0 || base < 0x100000u || base + (uint32_t)n * sz > 0x200000u) continue;
                    for (int i = 0; i < n; i++) {
                        uint32_t rec = base + (uint32_t)i * sz;
                        float V[4][3], cxz[2] = { 0.f, 0.f };
                        for (int k = 0; k < nv; k++) {
                            for (int q = 0; q < 3; q++) V[k][q] = (float)rrm_s16(ram, rec + (uint32_t)k * 8u + (uint32_t)q * 2u);
                            cxz[0] += V[k][0] / (float)nv; cxz[1] += V[k][2] / (float)nv;
                        }
                        uint64_t home = 0; float dmin = 1e30f;
                        for (int c = 0; c < nc; c++) if (vz_in_quad(cq[c], cxz[0], cxz[1])) home |= cmask[c];
                        if (!home) {
                            for (int c = 0; c < nc; c++) { float d = vz_quad_dist(cq[c], cxz[0], cxz[1]); if (d < dmin) dmin = d; }
                            for (int c = 0; c < nc; c++) if (vz_quad_dist(cq[c], cxz[0], cxz[1]) <= dmin + 1.f) home |= cmask[c];
                        }
                        if (!home || ((home >> g) & 1ull) || ((sf_livem >> g) & 1ull)) { nhome++; continue; }   /* 20.09 вечер: действующая сюжетная версия — дома везде */
                        uint64_t cov_m = (home | sf_livem) & ~nocover & ~(1ull << g);
                        if (!cov_m) { nkept++; continue; }
                        /* точки сетки на полигоне */
                        int npts = 0, ncov = 0;
                        for (int t = 0; t < ((nv == 4) ? 2 : 1); t++) {
                            static const int ti[2][3] = { { 0, 1, 2 }, { 1, 3, 2 } };
                            const float *A = V[ti[t][0]], *B = V[ti[t][1]], *C = V[ti[t][2]];
                            float pn[3]; vz_tri_normal(A, B, C, pn);                     /* 28.09: нормаль проверяемого */
                            const int use_par = parf != 0.f && (pn[0] != 0.f || pn[1] != 0.f || pn[2] != 0.f);
                            for (int a = 0; a <= 3; a++) for (int b = 0; a + b <= 3; b++) {
                                float u = ((float)a + 0.34f) / 4.f, w = ((float)b + 0.34f) / 4.f;
                                if (u + w > 1.f) continue;
                                float p[3];
                                for (int q = 0; q < 3; q++) p[q] = A[q] + u * (B[q] - A[q]) + w * (C[q] - A[q]);
                                npts++;
                                int cxi = VZ_CIDX(p[0]), czi = VZ_CIDX(p[2]), hit = 0;
                                if (cxi >= 0 && czi >= 0 && cxi < VZ_GRID && czi < VZ_GRID) {
                                    int ci = czi * VZ_GRID + cxi;
                                    for (int e = cellc[ci]; e < cellc[ci + 1]; e++) {
                                        const VzTri *o = &tr[cells[e]];
                                        if (!((cov_m >> o->g) & 1ull)) continue;
                                        if (use_par && o->n[0] * pn[0] + o->n[1] * pn[1] + o->n[2] * pn[2] < parf) continue;   /* 28.09: поперёк или обратная сторона — не та же поверхность */
                                        if (vz_pt_tri_d2(p, o->a, o->b, o->c) <= tol2) { hit = 1; break; }
                                    }
                                }
                                if (hit) ncov++;
                            }
                        }
                        if (npts > 0 && (float)ncov >= covf * (float)npts) { vz_add(rec); ndrop++; byg[g]++; }
                        else nkept++;
                    }
                }
            }
            /* 17.09 день (слот 7, загиб трубы у двери): у грани с несколькими видами правило va_* отодвигает копии «ближнего слоя»
             * назад на 1.5 % глубины, чтобы была видна копия «дальнего» вида. Если здесь все копии дальнего вида выброшены как
             * версии чужого ракурса, отодвинутая копия — единственная, а 1.5 % (115 ед. на 7700) уводят её за соседнюю поверхность
             * (замер: 10001C и 1032FC — одни вершины, палитры 7EB4/7EB5; труба в 38 ед. от стены — обрывалась в воздухе). Такой грани
             * отодвиг «мягкий»: DC_VARIANT_ZONE_SOFTPUSH единиц (16) — меньше зазора до стены, но больше ручных сдвигов G (слот 8:
             * решётки стоков со сдвигом -4 лежат над плиткой пола, отодвинутой va). Пробы, которые ломали: снять решение va — пол
             * закрыл решётки; вернуть выброшенные копии дальнего вида — сменился вид пола у решёток. DC_VARIANT_ZONE_VA=0 — как утром. */
            int soft_n = vz_softpush(ram, ng);
            char gl[600]; int gn = 0; gl[0] = 0;
            for (int g = 0; g < ng && gn < 560; g++) if (byg[g]) gn += snprintf(gl + gn, sizeof gl - (size_t)gn, " %06X:%d", s_build_gp[g] & 0x1FFFFFu, byg[g]);
            s_vz_live = (s_vz_n > 0);
            for (int g = 0; g < ng; g++) { s_vz_g[g] = s_build_gp[g] & 0x1FFFFFu; s_vz_gv[g] = byg[g] > 0; }   /* 27.10: для op_build */
            s_vz_gn = ng;
            fprintf(stderr, "versions: place look from its shot zone - %d shots with their own group sets, world groups %d; polygons at home %d, "
                            "other-shot versions not drawn %d (%s ), not covered kept %d; faces whose pushed-back copy is the only one left "
                            "(soft push) %d; %u ms (DC_VARIANT_ZONE=0 off)%c",
                    nc, ng, nhome, ndrop, gl, nkept, soft_n, SDL_GetTicks() - vz_t0, 10);
            if (vzk) vz_memo_put(vzk, ndrop, nhome, nkept);
        }
    }
    #undef VZ_CIDX
    free(tr);
}

/* ⭐ ФАЗА ЗОН КАМЕР — КАКИЕ РАКУРСЫ КОМНАТЫ ДОСТУПНЫ В ТЕКУЩЕМ СЦЕНАРИИ (17.09.2026 день, игрок: «если убрать 10001C, обломки
 * не вернутся? они по сценарию должны сменять прежние части комнаты. Но на данный момент по сюжету комната цела»).
 * ЛОГИКА ИГРЫ (func_80026B14 — выбор ракурса по зонам; кто пишет номер ракурса 0x800B796C — замер wtrace в слоте 8):
 *  • запись таблицы ракурсов (ptr[3], 68 б): +0 тип, +1 МАСКА ФАЗ (младшие 4 бита; 0x40/0x80 — свои флаги перехода),
 *    +2 номер ракурса (он же подпрограмма скрипта), +3 «этаж» (сравнивается с байтом +72 объекта 0x800B928C), +4..+19 квад
 *    зоны. Зона срабатывает, только если (маска & (1 << фаза)) != 0. Фаза — байт +131 структуры камеры 0x800B7904: загрузка
 *    комнаты ставит 0 (0x80026268), дальше её ставит только скрипт — 22 05 00 00 (структура камеры), 2A 00 0A 00 <v>
 *    (переменная 10 категории 5 -> +131, func_8005580C). Записи «переход фазы» (тип 0, биты фазы в +44) на диске есть только
 *    с маской 0 — не срабатывают.
 *  • ST201 (слот 8): инициализация ставит фазу 0, а при флаге сюжета bank0 bit60 (событие было) — фазу 1; катсцена события
 *    (подпрограмма 19) ставит фазу 1 в начале и по ходу создаёт насыпь 10001C. Фаза 0 (комната цела) — ракурсы 1–4;
 *    фаза 1 — ракурсы 3–7 на ТЕХ ЖЕ местах (зона записи 4 = зона записи 1, записи 5–7 внутри зоны записи 0), но с обломками:
 *    10001C (насыпь), 10A470, 11340C, 114B68, 116274, 116454. Достройка обходила все записи и брала обе версии — отсюда
 *    насыпь в целой комнате и затычка DC_ROOM_SKIP=10001C, которая резала первую группу КАЖДОЙ комнаты (в комнате решётки
 *    и в зале слотов 5/7 это тело ракурсов).
 *  • по диску записи с разными масками фаз — у 35 комнат (phase_survey*.py 17.09).
 * ПРАВИЛО: запись берётся в сборку, если её зона активна в текущей фазе. Запись другой фазы, чья зона лежит на местах зон
 * текущей фазы (не меньше половины точек её квада внутри них), — другая версия тех же мест: её набор не берётся (и в
 * правилах блоков va_ и vz_ не участвует). Запись другой фазы на других местах (часть комнаты, куда фазу переключит скрипт по ходу)
 * берётся, как раньше, — чтобы не было дыр. Запись с вырожденной зоной — как раньше. Фаза входит в подпись сборки:
 * сменилась (катсцена события) — комната пересобирается. Лог `room phase: ...`; DC_ROOM_PHASE=0 — все записи, как было. */
static int rp_env(void) { static int v = -1; if (v < 0) { const char *e = getenv("DC_ROOM_PHASE"); v = (e && *e == '0') ? 0 : 1; }
                          return (g_dc_room_phase_ovr >= 0) ? g_dc_room_phase_ovr : v; }   /* порт zf_var roomphase */
static int rp_phase(const uint8_t *ram) {
    const uint8_t *sp = memory_get_scratchpad_ptr();
    if (!sp || !ram) return -1;
    uint32_t S = ((uint32_t)sp[0] | ((uint32_t)sp[1] << 8) | ((uint32_t)sp[2] << 16) | ((uint32_t)sp[3] << 24)) & 0x1FFFFFFFu;
    if (S < 0x10000u || S + 180u + 132u >= 0x200000u) return -1;
    return ram[S + 180u + 131u];
}
/* подпись состояния, от которого зависит сборка: флаги, которые спрашивал обход, и фаза зон */
static uint32_t rp_statesig(const uint8_t *ram) {
    uint32_t h = rb_flagsig(ram);
    if (rp_env()) h = (h ^ (uint32_t)(rp_phase(ram) + 2)) * 16777619u;
    return h ? h : 1u;
}
static float rp_quad_area(const float *q) {
    float a = 0.f;
    for (int j = 0; j < 4; j++) a += q[j * 2] * q[((j + 1) % 4) * 2 + 1] - q[((j + 1) % 4) * 2] * q[j * 2 + 1];
    return fabsf(a) * 0.5f;
}
static int vz_in_quad(const float *q, float x, float z);
/* s_rb_cam_use[] по фазе; ph < 0 — фаза неизвестна, берутся все */
static void rp_classify(const uint8_t *ram, uint32_t cams, uint32_t ncam, int ph, char *act_s, char *alt_s, char *nav_s, int ssz) {
    float q[64][8]; uint8_t act[64];
    act_s[0] = alt_s[0] = nav_s[0] = 0;
    int la = 0, lt = 0, ln = 0;
    for (uint32_t c = 0; c < ncam && c < 64u; c++) {
        uint32_t cr = cams + 4u + c * 68u;
        s_rb_cam_use[c] = 1; act[c] = 1;
        if (cr + 68u >= 0x200000u) continue;
        for (int j = 0; j < 8; j++) q[c][j] = (float)rrm_s16(ram, cr + 4u + (uint32_t)j * 2u);
        if (ph < 0 || !rp_env()) continue;
        act[c] = (ph < 4 && ((ram[cr + 1] & 0x0F) >> ph) & 1) ? 1 : 0;
    }
    if (ph < 0 || !rp_env()) return;
    for (uint32_t c = 0; c < ncam && c < 64u; c++) {
        uint32_t cr = cams + 4u + c * 68u;
        if (cr + 68u >= 0x200000u || !ram[cr + 2]) continue;
        if (act[c]) { if (la < ssz - 8) la += snprintf(act_s + la, (size_t)(ssz - la), " %u/%d", c, ram[cr + 2]); continue; }
        int in = 0, tot = 0;
        if (rp_quad_area(q[c]) >= 1.f) {
            for (int a = 0; a < 5; a++) for (int b = 0; b < 5; b++) {
                float u = ((float)a + 0.5f) / 5.f, v = ((float)b + 0.5f) / 5.f;
                float x0 = q[c][0] + u * (q[c][2] - q[c][0]), z0 = q[c][1] + u * (q[c][3] - q[c][1]);
                float x1 = q[c][6] + u * (q[c][4] - q[c][6]), z1 = q[c][7] + u * (q[c][5] - q[c][7]);
                float x = x0 + v * (x1 - x0), z = z0 + v * (z1 - z0);
                tot++;
                for (uint32_t o = 0; o < ncam && o < 64u; o++) {
                    uint32_t orr = cams + 4u + o * 68u;
                    if (!act[o] || o == c || orr + 68u >= 0x200000u || !ram[orr + 2] || rp_quad_area(q[o]) < 1.f) continue;
                    if (vz_in_quad(q[o], x, z)) { in++; break; }
                }
            }
        }
        if (tot > 0 && in * 2 >= tot) {
            s_rb_cam_use[c] = 0;
            if (lt < ssz - 8) lt += snprintf(alt_s + lt, (size_t)(ssz - lt), " %u/%d", c, ram[cr + 2]);
        } else if (ln < ssz - 8) ln += snprintf(nav_s + ln, (size_t)(ssz - ln), " %u/%d", c, ram[cr + 2]);
    }
}

/* Assemble the room the script would have built for the state we are in. */
void dc_room_script_build(void)
{
    static int en = -1;
    if (en < 0) { const char *e = getenv("DC_ROOM_BUILD"); en = (e && *e == '0') ? 0 : 1; }
    if (!en) { s_build_n = 0; s_bp_n = 0; return; }
    const uint8_t *ram = memory_get_ram_ptr();
    if (!ram) return;
    if (rrm_u32(ram, RRM_BASE + 7 * 4) != RRM_VADDR + 0x28) { s_build_n = 0; s_bp_n = 0; s_rsv_ready = 0; return; }
    if (rrm_refresh() <= 0) { s_build_n = 0; s_bp_n = 0; s_rsv_ready = 0; return; }
    { uint32_t fs = rp_statesig(ram);           /* 17.09 день: флаги + фаза зон (rp_*) */
      if (!g_dc_room_rebuild_req && s_build_sig == s_rrm_sig && s_build_flagsig == fs && s_build_n > 0) { if (s_ss_ready) shot_stamp(); return; }
      if (g_rlprof_on) {                         /* 21.09: замер - что сменилось с прошлой сборки */
          char wl[300]; int wn = 0; wl[0] = 0;
          for (int i = 0; i < s_flagq_n && wn < 270; i++) {
              int bank = (s_flagq[i] >> 8) & 0xFF, bit = s_flagq[i] & 0xFF, v = rb_flag(ram, bank, bit);
              if (v != s_flagq_val[i]) wn += snprintf(wl + wn, sizeof wl - (size_t)wn, " %d/%d:%d->%d", bank, bit, s_flagq_val[i], v);
          }
          fprintf(stderr, "room rebuild why: req=%d block %s, phase %d->%d, flags changed:%s%c", g_dc_room_rebuild_req,
                  s_build_sig == s_rrm_sig ? "same" : "NEW", s_build_phase_was, rp_phase(ram), wn ? wl : " none", 10);
      } }
    g_dc_room_rebuild_req = 0;
    double bp_t[8]; bp_t[0] = g_rlprof_on ? rlp_ms() : 0.0;        /* 21.09: замер этапов пересборки (buildprof:) */
    s_build_sig = s_rrm_sig; s_build_n = 0; s_build_cams = 0; s_seen_n = 0;
    s_rsv_n = 0; s_rsv_ready = 0; s_ss_ready = 0;  /* 20.09: таблицы состояния строятся заново ниже */
    bp_reset();                                    /* 24.09: поставленные куски ракурсов (bp_*) — тоже */
    ig_build_begin();                              /* 19.10: предметы ракурсов (ig_*) — тоже */
    s_flagq_n = 0; s_flagq_rec = 1;                /* re-learn what we depend on */
    uint32_t cams = rrm_u32(ram, RRM_BASE + 3 * 4) & 0x1FFFFFu;
    uint32_t scr  = rrm_u32(ram, RRM_BASE + 5 * 4) & 0x1FFFFFu;
    if (cams < 0x100000u || cams + 4u >= 0x200000u) return;
    if (scr  < 0x100000u || scr  + 4u >= 0x200000u) return;
    uint32_t ncam = rrm_u32(ram, cams);
    if (ncam == 0u || ncam > 64u) return;
    int phase = rp_phase(ram);
    char ph_act[256], ph_alt[256], ph_nav[256];
    rp_classify(ram, cams, ncam, phase, ph_act, ph_alt, ph_nav, (int)sizeof ph_act);
    s_ig_rec = 1; ig_run_next(-1);                /* 19.10: команды «создать предмет» этого прохода (ig_note) */
    rb_run(ram, scr, 0, 0);                       /* room init */
    for (uint32_t c = 0; c < ncam; c++) {
        uint32_t rec = cams + 4u + c * 68u;
        if (rec + 68u >= 0x200000u) break;
        int sub = ram[rec + 2];
        if (!sub) continue;
        if (c < 64u && !s_rb_cam_use[c]) continue;   /* 17.09 день: другая фаза на тех же местах */
        ig_run_next((int)c);                       /* 19.10: подпрограмма ракурса c (ig_*) */
        rb_run(ram, scr, sub, 0);
        s_build_cams++;
    }
    s_flagq_rec = 0;
    s_ig_rec = 0; ig_build_end(ram);
    s_build_flagsig = rp_statesig(ram);
    for (int i = 0; i < s_flagq_n; i++) s_flagq_val[i] = (uint8_t)rb_flag(ram, (s_flagq[i] >> 8) & 0xFF, s_flagq[i] & 0xFF);   /* 21.09: для замера */
    s_build_phase_was = rp_phase(ram);
    bp_t[1] = g_rlprof_on ? rlp_ms() : 0.0;
    fprintf(stderr, "room build: %d cameras, %d world groups assembled, %d flags%c",
            s_build_cams, s_build_n, s_flagq_n, 10);
    if (phase >= 0 && rp_env()) {
        /* группы, которые дали бы только оставленные записи, — для лога */
        char gl[400]; int gn = 0; gl[0] = 0;
        if (ph_alt[0]) {
            uint32_t seen_g[64]; int ns = 0;
            for (uint32_t c = 0; c < ncam && c < 64u; c++) {
                uint32_t cr = cams + 4u + c * 68u;
                if (cr + 68u >= 0x200000u || s_rb_cam_use[c] || !ram[cr + 2]) continue;
                memset(s_rbc_slot, 0, sizeof s_rbc_slot); memset(s_rbc_vis, 0, sizeof s_rbc_vis);
                s_rbc_on = 1;
                s_seen_n = 0; rb_run(ram, scr, 0, 0);
                s_seen_n = 0; rb_run(ram, scr, ram[cr + 2], 0);
                s_rbc_on = 0; s_seen_n = 0;
                for (int sl = 0; sl < 64; sl++) {
                    uint32_t gp = s_rbc_slot[sl];
                    if (!gp || gp == 0xFFFFFFFFu || !s_rbc_vis[sl]) continue;
                    gp &= 0x1FFFFFu;
                    int have = 0;
                    for (int g = 0; g < s_build_n && !have; g++) if ((s_build_gp[g] & 0x1FFFFFu) == gp) have = 1;
                    for (int g = 0; g < ns && !have; g++) if (seen_g[g] == gp) have = 1;
                    if (have || ns >= 64) continue;
                    seen_g[ns++] = gp;
                    if (gn < 380) gn += snprintf(gl + gn, sizeof gl - (size_t)gn, " %06X", gp);
                }
            }
        }
        fprintf(stderr, "room phase: zone phase %d (set by the room script) - shots of this phase (record/view):%s; other-phase shots over the "
                        "same places left out:%s%s%s%s; other-phase shots over other places kept:%s (DC_ROOM_PHASE=0 off)%c",
                phase, ph_act[0] ? ph_act : " none", ph_alt[0] ? ph_alt : " none", ph_alt[0] ? " (groups only they show:" : "",
                ph_alt[0] ? (gl[0] ? gl : " none") : "", ph_alt[0] ? ")" : "", ph_nav[0] ? ph_nav : " none", 10);
    }
    bp_t[2] = g_rlprof_on ? rlp_ms() : 0.0;
    /* 20.09 вечер: сюжетные развилки — группы невзятой ветки в сборку не идут (sf_*) */
    sf_build(ram, cams, scr, ncam);
    sd_scan(ram, scr);                            /* 20.09 вечер: завершённые эпизоды (диспетчер + обработчики) */
    if (s_sf_dead_n > 0) { int kept2 = 0;
        for (int g = 0; g < s_build_n; g++) { if (sf_is_dead(s_build_gp[g])) continue;
            s_build_gp[kept2] = s_build_gp[g]; s_build_mode[kept2] = s_build_mode[g]; s_build_slot[kept2] = s_build_slot[g]; kept2++; }
        s_build_n = kept2; }
    bp_t[3] = g_rlprof_on ? rlp_ms() : 0.0;
    /* 20.09: состояние комнаты по скрипту — что вообще показывает хоть один ракурс фазы при текущих флагах */
    {
        s_rsv_n = 0;
        int ss_shots = 0; s_ss_ready = 0; rvo_reset();
        memset(s_ss_gp, 0, sizeof s_ss_gp); memset(s_ss_vis, 0, sizeof s_ss_vis); memset(s_ss_mixed, 0, sizeof s_ss_mixed);
        memset(s_ss_camvis, 0, sizeof s_ss_camvis); memset(s_ss_camhide, 0, sizeof s_ss_camhide);
        for (uint32_t c = 0; c < ncam && c < 64u; c++) {
            uint32_t cr = cams + 4u + c * 68u;
            if (cr + 68u >= 0x200000u || !ram[cr + 2] || !s_rb_cam_use[c]) continue;
            memset(s_rbc_slot, 0, sizeof s_rbc_slot); memset(s_rbc_vis, 0, sizeof s_rbc_vis);
            memset(s_rbc_anygp, 0, sizeof s_rbc_anygp);
            memset(s_rbc_omode, 0, sizeof s_rbc_omode); memset(s_rbc_oslot, 0, sizeof s_rbc_oslot);
            memset(s_rbc_pc, 0, sizeof s_rbc_pc); memset(s_rbc_pcam, 0, sizeof s_rbc_pcam);   /* 24.09: bp_* */
            s_rbc_on = 1;
            s_seen_n = 0; rb_run(ram, scr, 0, 0);
            memset(s_rbc_camset, 0, sizeof s_rbc_camset); memset(s_rbc_camoff, 0, sizeof s_rbc_camoff); s_rbc_camph = 1;   /* 21.09 ночь: что с видимостью делает сама подпрограмма ракурса */
            s_seen_n = 0; rb_run(ram, scr, ram[cr + 2], 0);
            s_rbc_camph = 0;
            s_rbc_on = 0; s_seen_n = 0;
            rvo_feed();                                               /* 20.09 вечер: кто кого рисует раньше в этом ракурсе (для rv_*) */
            sd_apply(ram, s_rbc_anygp);                               /* 20.09 вечер: доломать то, что завершённый эпизод заменяет в этом наборе */
            bp_note_shot(ram);                                        /* 24.09: поставленные куски этого ракурса (bp_*) */
            if (c < 64u) { uint64_t m = 0;                            /* 04.10 (3): что этот ракурс оставляет видимым (версии мест, s_pv_vis) */
                for (int sl = 0; sl < 64; sl++) if (s_rbc_anygp[sl] && s_rbc_vis[sl]) m |= 1ull << sl;
                s_pv_vis[c] = m; s_pv_have[c] = 1; }
            for (int sl = 0; sl < 64; sl++) if (s_rbc_anygp[sl]) rsv_note(s_rbc_anygp[sl], s_rbc_vis[sl]);
            for (int sl = 0; sl < 64; sl++) if (s_rbc_anygp[sl]) {        /* 20.09 день: то же по слотам (ss_*) */
                if (!s_ss_gp[sl]) s_ss_gp[sl] = s_rbc_anygp[sl]; else if (s_ss_gp[sl] != s_rbc_anygp[sl]) s_ss_mixed[sl] = 1;
                if (s_rbc_vis[sl]) s_ss_vis[sl] = 1;
                if (s_rbc_vis[sl] && s_rbc_camset[sl] && !s_ss_camvis[sl]) { s_ss_camvis[sl] = 1; s_ss_camvis_shot[sl] = (uint8_t)c; }
                if (!s_rbc_vis[sl] && s_rbc_camoff[sl]) s_ss_camhide[sl] = 1; }                   /* 28.09 (3) */
            ss_shots++;
        }
        if (!ss_shots) {                                              /* ни у одного ракурса нет подпрограммы — одна инициализация */
            memset(s_rbc_slot, 0, sizeof s_rbc_slot); memset(s_rbc_vis, 0, sizeof s_rbc_vis); memset(s_rbc_anygp, 0, sizeof s_rbc_anygp);
            s_rbc_on = 1; s_seen_n = 0; rb_run(ram, scr, 0, 0); s_rbc_on = 0; s_seen_n = 0;
            rvo_feed();
            for (int sl = 0; sl < 64; sl++) if (s_rbc_anygp[sl]) { s_ss_gp[sl] = s_rbc_anygp[sl]; s_ss_vis[sl] = s_rbc_vis[sl]; }
        }
        bp_finish(ram);                                               /* 24.09: список поставленных кусков ракурсов фазы и лог */
        if (s_sd_gone_n > 0) { int kept3 = 0;                         /* доломанное — вон из сборки */
            for (int g = 0; g < s_build_n; g++) { int gone3 = 0; for (int q = 0; q < s_sd_gone_n; q++) if (s_sd_gone[q] == (s_build_gp[g] & 0x1FFFFFu)) gone3 = 1;
                if (gone3) continue; s_build_gp[kept3] = s_build_gp[g]; s_build_mode[kept3] = s_build_mode[g]; s_build_slot[kept3] = s_build_slot[g]; kept3++; }
            s_build_n = kept3; }
        ss_index(ram); ss_task_replay(ram); s_ss_ready = 1;            /* 01.10 (k): идущие задачи события (ss_task_replay) */
        shot_stamp();                                                 /* 22.10 день: разбор ракурсов готов (правило порядка консоли) */
        { int nh = 0; char sl_l[200]; int sn = 0; sl_l[0] = 0;
          for (int sl = 0; sl < 64; sl++) if (s_ss_gp[sl] && !s_ss_mixed[sl] && !s_ss_vis[sl] && !s_ss_camshow[sl]) { nh++; if (sn < 180) sn += snprintf(sl_l + sn, sizeof sl_l - (size_t)sn, " %d:%06X", sl, s_ss_gp[sl]); }
          fprintf(stderr, "slot story: room %d - %d slots no shot shows at the current flags (hidden by the story):%s (DC_SLOT_STORY=0 off)%c",
                  dc_room_current(), nh, nh ? sl_l : " none", 10); }
        int hidden = 0, created = s_rsv_n; char hl[320]; int hn = 0; hl[0] = 0;
        for (int i = 0; i < s_rsv_n; i++)
            if (!s_rsv_vis[i]) { hidden++; if (hn < 300) hn += snprintf(hl + hn, sizeof hl - (size_t)hn, " %06X", s_rsv_gp[i]); }
        int kept = 0;
        for (int g = 0; g < s_build_n; g++) {
            if (rsv_env() && rsv_lookup(s_build_gp[g]) == 0) continue;   /* спрятана во всех ракурсах — не рисуем */
            s_build_gp[kept] = s_build_gp[g]; s_build_mode[kept] = s_build_mode[g]; s_build_slot[kept] = s_build_slot[g];
            kept++;
        }
        int dropped = s_build_n - kept;
        s_build_n = kept;
        s_rsv_ready = 1;
        fprintf(stderr, "room state: %d groups created by the script, %d hidden in every shot at the current flags (state variants:%s)"
                        " - %d left the assembled set, union claims refused%c",
                created, hidden, hidden ? hl : " none", dropped, 10);
    }
    bp_t[4] = g_rlprof_on ? rlp_ms() : 0.0;
    va_build(ram, cams, scr, ncam);               /* 16.09 ночь: вид граней на всю комнату */
    bp_t[5] = g_rlprof_on ? rlp_ms() : 0.0;
    vz_build(ram, cams, scr, ncam);               /* 17.09: место — версией ракурса своей зоны */
    if (g_rlprof_on) { bp_t[6] = rlp_ms();
        fprintf(stderr, "buildprof: assemble %.2f | phase log %.2f | forks+episodes %.2f | state %.2f | va %.2f | vz %.2f | total %.2f ms%c",
                bp_t[1] - bp_t[0], bp_t[2] - bp_t[1], bp_t[3] - bp_t[2], bp_t[4] - bp_t[3], bp_t[5] - bp_t[4], bp_t[6] - bp_t[5],
                bp_t[6] - bp_t[0], 10); }
}

/* DC_ROOM_SHOWALL=1 — keep every ROOM portion visible.
 * Proven by watching the draw list being built: at room load func_800570F8
 * publishes eight entries, each already carrying its own mesh-group pointer
 * (+60) AND its own object/matrix pointer (+64) — e.g. 0x8010001C, 0x80102D48,
 * 0x801037E4, 0x80104C0C, 0x80106824, 0x801083F0, 0x80108604, 0x8010C5C0.
 * Everything is set up correctly from the start; the script (func_8005580C)
 * only flips the visibility word at +48 as the camera moves, which is the PS1
 * economy measure that shows as the room arriving in pieces.
 * So nothing has to be cloned and no matrix has to be guessed — just refuse to
 * let a portion be switched off. Only entries whose group pointer lies inside
 * the room block are touched, which is what makes this safe: uninitialised
 * slots (the ones that crashed the earlier blanket approach) are never enabled.
 */
static int s_showall_forced = 0;
/* Сколько кусков комнаты дожгли в последнем кадре — для разбора чёрного
 * экрана: ловец в main.cpp печатает это в момент, когда картинка пропала. */
int dc_showall_last_forced(void) { return s_showall_forced; }

/* ⭐ 27.10.2026 - КУСОК КОМНАТЫ, КОТОРЫЙ ЗАБЫЛ РАКУРС СЦЕНЫ (игрок, слот 43: «катсцена ... И опять же в одном ракурсе нет куска
 * того забора, сетки»). ST10D, сцена с рацией после двери: последний облёт (камера поворачивается от киоска к бассейну с оранжевой
 * лампой) ставит гейты 1011000101001110 и оставляет выключенной запись 8 - забор с сеткой, группа 101770 (тот же забор, что в
 * слоте 0: тип 0, 2+91 полигон). Так рисует и сама игра: в кадре консоли (DC_ORIG_NATIVE_DRAW=1) за киоском тоже бассейн без
 * забора - промах ракурса оригинала; бит, включённый через порт, возвращает забор и нам, и консоли. В сценах дожигание стоит
 * (сцены прячут куски нарочно, двери перестраивают таблицу), поэтому здесь только список «комната:группа:полигонов»: в сцене
 * (режим 4) в этой комнате запись с этой группой (тип 0, матрица камеры +64 == 0, полигонов столько же) держится видимой, если
 * запись стоит в таблице хотя бы DC_SCENE_KEEP_SETTLE тактов. Её бит снимают смены ракурсов сцены, а возвращаем мы - признак
 * «переключает игра» (animated) такой записи в сцене не ставится.
 * DC_SCENE_KEEP_PIECES=0 - как было; формат 10D:101770:93[,...] (комната ST, группа, полигонов; 0 полигонов - не сверять). */
static struct { int st; uint32_t grp; int np; } s_sk[8];
static int s_sk_n = -1;
static uint32_t s_sk_seen[36];
static uint16_t s_sk_age[36];
static int scene_keep_listed(const uint8_t *ram, uint32_t gpa) {
    if (s_sk_n < 0) {
        s_sk_n = 0;
        const char *e = getenv("DC_SCENE_KEEP_PIECES");
        const char *p = e ? e : "10D:101770:93";
        if (!(p[0] == '0' && p[1] == 0)) {
            while (*p && s_sk_n < 8) {
                char *q;
                const unsigned long st = strtoul(p, &q, 16);
                if (*q != ':') break;
                const unsigned long g = strtoul(q + 1, &q, 16);
                long np = 0;
                if (*q == ':') np = strtol(q + 1, &q, 10);
                s_sk[s_sk_n].st = (int)st; s_sk[s_sk_n].grp = (uint32_t)g & 0x1FFFFFu; s_sk[s_sk_n].np = (int)np; s_sk_n++;
                while (*q && *q != ',') q++;
                p = (*q == ',') ? q + 1 : q;
            }
        }
        fprintf(stderr, "scene keep: %d listed room pieces stay on in scenes (DC_SCENE_KEEP_PIECES=0 off)%c", s_sk_n, 10);
    }
    if (!s_sk_n) return 0;
    const int stc = dc_room_stcode();
    const uint32_t a = gpa & 0x1FFFFFu;
    for (int j = 0; j < s_sk_n; j++) {
        if (s_sk[j].st != stc || s_sk[j].grp != a) continue;
        if (s_sk[j].np > 0) {
            if (a + 12u >= 0x200000u) continue;
            if ((int)rrm_u16(ram, a + 8) + (int)rrm_u16(ram, a + 10) != s_sk[j].np) continue;
        }
        return 1;
    }
    return 0;
}

void dc_room_showall_tick(void) {
    /* O key: original mode — do not force room portions on (2026-08-30);
     * 15.09 вечер: только при DC_ORIG_NATIVE_DRAW=1 — по умолчанию оригинальный режим дожигает куски, как современный */
    { extern int dc_orig_native_draw(void); if (dc_orig_native_draw()) return; }
    static int en = -1;
    if (en < 0) { const char *e = getenv("DC_ROOM_SHOWALL"); en = (e && *e == '1') ? 1 : 0; }
    if (!en) return;
    const uint8_t *sp = memory_get_scratchpad_ptr();
    uint8_t *ram = (uint8_t*)memory_get_ram_ptr();
    if (!sp || !ram) return;
    uint32_t S = ((uint32_t)sp[0] | ((uint32_t)sp[1] << 8) | ((uint32_t)sp[2] << 16) | ((uint32_t)sp[3] << 24)) & 0x1FFFFFFFu;
    /* ⭐ ОТДАТЬ ИГРЕ ЕЁ БИТЫ, КАК ТОЛЬКО ЭКРАН ПЕРЕСТАЛ БЫТЬ МИРОМ (2026-09-01).
     * Байт экрана игры — 0x800B7878: 3 = мир, 5 = меню предметов, 8 = OPTION,
     * 0 = логотипы/титул. Мы дожигаем куски комнаты, переписывая слово +48 в
     * 36 слотах; в меню игра работает с этой же памятью, и наши включённые
     * биты стоили чёрного экрана на выходе — замер по 4 циклам смены оружия
     * в EQUIP: без showall чернота 39-58 кадров, с ним 387-1062 кадра (до 17
     * секунд, «от секунды до бесконечности»). Поэтому: пока на экране не мир,
     * ничего не форсим и ВОЗВРАЩАЕМ каждому слоту то значение, которое там
     * было до нас — и только если с тех пор его никто не менял.
     * DC_SHOWALL_GATE=0 — вернуть прежнее поведение. */
    static uint32_t s_sa_saved[36], s_sa_wrote[36];
    static uint8_t  s_sa_have[36];
    /* ⭐ УСТАРЕВШИЕ ЗАПИСИ ВОЗВРАТА (14.09.2026, игрок, слот 6: «пропадает окружение в сцене» —
     * Регина лезет по верёвке, а стен коридора нет, дым и висящие огни; «не всегда, но часто»).
     * Воспроизведение: слот 6 → Yes → дойти до следующей комнаты (там дожигаются слоты 2–5,
     * записи «было 00000001») → снова загрузить слот 6 → Yes. Записи пережили загрузку, и на
     * экране 6 (переход начат, кадр с верёвкой ещё идёт) возврат записал «выключено» в слоты 2–4
     * коридора: там значение 3, совпавшее с «нашей записью», — только выставила его уже игра.
     * Лог: «room showall: 3 portions handed back (screen 6)», в таблице 10 → 7 включённых.
     * Теперь: (1) загрузка снимка стирает записи; (2) в скриптовой сцене (режим 4) биты не
     * возвращаются — сцена ещё показывает комнату, а её таблица уйдёт вместе с комнатой, записи
     * просто забываются; (3) возврат только в тот же кусок (группа +60 та, что при записи).
     * DC_SHOWALL_SCENE_BACK=1 — возвращать и в сцене, как было. */
    static uint32_t s_sa_grp[36];
    { extern int g_savestate_loads; static int sa_ep = 0;
      if (sa_ep != g_savestate_loads) {
          int nrec = 0;
          for (int i = 0; i < 36; i++) nrec += s_sa_have[i];
          sa_ep = g_savestate_loads;
          memset(s_sa_have, 0, sizeof s_sa_have);
          if (nrec) fprintf(stderr, "room showall: snapshot loaded - %d hand-back records dropped%c", nrec, 10);
      } }
    { static int gate = -1;
      if (gate < 0) { const char *e = getenv("DC_SHOWALL_GATE"); gate = (e && *e == '0') ? 0 : 1; }
      if (gate && ram[0xB7878] != 3) {
        if (S && S < 0x200000u) {
            int back = 0, dropped = 0;
            static int scene_back = -1;
            if (scene_back < 0) { const char *e = getenv("DC_SHOWALL_SCENE_BACK"); scene_back = (e && *e == '1') ? 1 : 0; }
            int scripted = (ram[0xB92C8] == 4) && !scene_back;
            for (int i = 0; i < 36; i++) {
                if (!s_sa_have[i]) continue;
                uint32_t e2 = S + 0x7CDCu + (uint32_t)i * 136u;
                if (e2 + 136u > 0x200000u) continue;
                if (scripted || (rrm_u32(ram, e2 + 60) & 0x1FFFFFFFu) != s_sa_grp[i]) dropped++;
                else if (rrm_u32(ram, e2 + 48) == s_sa_wrote[i]) {
                    uint32_t v = s_sa_saved[i];
                    ram[e2 + 48] = (uint8_t)(v & 0xFF);         ram[e2 + 49] = (uint8_t)((v >> 8) & 0xFF);
                    ram[e2 + 50] = (uint8_t)((v >> 16) & 0xFF); ram[e2 + 51] = (uint8_t)((v >> 24) & 0xFF);
                    back++;
                }
                s_sa_have[i] = 0;
            }
            if (back) fprintf(stderr, "room showall: %d portions handed back (screen %u)%c",
                              back, ram[0xB7878], 10);
            if (dropped) fprintf(stderr, "room showall: %d hand-back records dropped (%s, screen %u)%c",
                                 dropped, scripted ? "scripted scene" : "slot has another piece", ram[0xB7878], 10);
        }
        s_showall_forced = 0;
        return;
      } }
    if (!S || S >= 0x200000u) return;
    uint32_t lo = S + 0x7CDCu;
    int on = 0, forced = 0;
    for (int i = 0; i < 36; i++) {
        uint32_t e = lo + (uint32_t)i * 136u;
        if (e + 136u > 0x200000u) break;
        uint32_t gp = rrm_u32(ram, e + 60);
        uint32_t mx = rrm_u32(ram, e + 64);
        uint32_t st = rrm_u32(ram, e + 48);
        if (gp < RRM_VADDR || gp >= RRM_VADDR + 0x100000u) continue;  /* room block only */
        /* ⭐ 28.09 (6) — ТОЛЬКО КУСКИ КОМНАТЫ (тип записи +46 == 0), ПРЕДМЕТЫ И СДВИГАЕМЫЕ ОБЪЕКТЫ — ЛОГИКОЙ ИГРЫ (игрок, слот 13,
         * ST30B: «шкаф слева — под ним видно предмет; предмета не видно, пока Регина не отодвинет шкаф, ящик»; «оригинальный код
         * примени, а не своё выдумывай»). Обработчик предметов игры (тип 2, 0x8007F7A8 из таблицы 0x800C23A0, её зовёт
         * func_8004A2CC): предмет с меткой +47 ≠ 0 лежит СКРЫТЫМ (бит 1 слова +48 снят), пока сдвиг объекта не поднимет флаг
         * (2,27) — тогда обработчик снимает флаг и ставит бит 1. Модель предмета (0x80180000) лежит в блоке комнаты, и дожигание
         * принимало его за кусок комнаты — зажигало бит само: предмет в шкафу стоял видимым с самого входа. Теперь запись не
         * типа 0 не трогается. DC_SHOWALL_TYPE0=0 — как было. */
        { static int t0 = -1;
          if (t0 < 0) { const char *et = getenv("DC_SHOWALL_TYPE0"); t0 = (et && *et == '0') ? 0 : 1; }
          if (t0 && (int8_t)ram[e + 46] != 0) continue; }
        /* 27.10: запись из списка сцен (scene_keep_listed выше) - в сцене держится видимой */
        int skeep = 0;
        if (i < 36) {
            static int settle = -1;
            if (settle < 0) { const char *es = getenv("DC_SCENE_KEEP_SETTLE"); settle = es ? atoi(es) : 30; if (settle < 0) settle = 0; }
            if (s_sk_seen[i] != gp) { s_sk_seen[i] = gp; s_sk_age[i] = 0; } else if (s_sk_age[i] < 60000u) s_sk_age[i]++;
            if (ram[0xB92C8] == 4 && (int8_t)ram[e + 46] == 0 && mx == 0 && s_sk_age[i] >= (uint16_t)settle &&
                scene_keep_listed(ram, gp & 0x1FFFFFFFu)) skeep = 1;
        }
        /* LEAVE ANYTHING THE GAME IS ANIMATING ALONE.
         * Telling a static piece from a blinking one by structure was wrong -
         * plenty of room pieces carry an object of their own too, and gating
         * on that brought the piecewise loading straight back. Behaviour tells
         * them apart cleanly instead: the per-shot cull switches a piece off
         * ONCE when the camera cuts and leaves it off, while an equipment
         * panel flips back and forth the whole time. So count the flips: a
         * slot that has toggled recently is the game animating something and
         * is never forced; a slot that has been quietly off is the cull, and
         * that is the one to re-light. */
        {
            /* WHO OWNS THIS SLOT: the per-shot cull, or the game's own logic?
             * Both switch pieces off, and forcing the wrong one back on is
             * either a room that loads a piece at a time (if we back off too
             * readily) or two variants of an equipment panel lit at once (if
             * we force too eagerly - the panels are a switch: one variant on,
             * the other off, by game logic).
             * Counting flips in a window could not separate them: a panel that
             * blinks slowly looks exactly like a piece the cull switched off.
             * What DOES separate them is WHEN the flip happens. The cull fires
             * on a camera change, and nowhere else; the panel logic runs on
             * its own clock. So watch the engine's camera matrix, and treat a
             * flip that lands away from a camera change as the game animating
             * the piece - from then on that slot is the game's, for as long as
             * we stay in this room. Everything else is force-lit from the
             * first frame, so the room still arrives whole. */
            static uint8_t prev[90], animated[90];
            static float lastR[9]; static int lastR_have = 0;
            static uint32_t lastRoom = 0xFFFFFFFFu;
            static uint64_t camchg = 0;
            extern uint64_t s_frame_count_ref(void);
            uint64_t f = s_frame_count_ref();
            uint32_t room = rrm_u32(ram, 0xB0FA0u);
            if (room != lastRoom) {                 /* new room: learn it afresh */
                lastRoom = room;
                memset(animated, 0, sizeof animated);
                memset(prev, 0, sizeof prev);
                lastR_have = 0;
            }
            { float R[9]; int diff = 0;
              for (int k = 0; k < 9; k++) R[k] = (float)rrm_s16(ram, 0xBF9F4u + (uint32_t)k * 2u) * (1.0f/4096.0f);
              if (!lastR_have) { lastR_have = 1; camchg = f; }
              else for (int k = 0; k < 9; k++) { float d = R[k] - lastR[k]; if (d < 0) d = -d;
                                                 if (d > 0.02f) { diff = 1; break; } }
              if (diff) camchg = f;
              for (int k = 0; k < 9; k++) lastR[k] = R[k]; }
            uint8_t now = (uint8_t)((st & 3u) == 3u);
            if (i < 90) {
                if (now != prev[i] && f - camchg > 20 && !skeep) animated[i] = 1;
                prev[i] = now;
                if (animated[i] && !skeep) continue;          /* the game's switch: hands off */
            }
        }
        if (skeep) {                                /* 27.10: кусок, который забыл ракурс сцены (scene_keep_listed) */
            if ((st & 3u) == 3u) { on++; continue; }
            { extern int g_dc_showall_force; if (!g_dc_showall_force) continue; }
            const uint32_t nv = (st & ~3u) | 3u;
            if (!s_sa_have[i] || s_sa_grp[i] != (gp & 0x1FFFFFFFu)) { s_sa_saved[i] = st; s_sa_have[i] = 1; s_sa_grp[i] = gp & 0x1FFFFFFFu; }
            s_sa_wrote[i] = nv;
            ram[e + 48] = (uint8_t)(nv & 0xFF);        ram[e + 49] = (uint8_t)((nv >> 8) & 0xFF);
            ram[e + 50] = (uint8_t)((nv >> 16) & 0xFF); ram[e + 51] = (uint8_t)((nv >> 24) & 0xFF);
            forced++;
            { static long nk = 0; extern uint64_t s_frame_count_ref(void);
              if (++nk < 60)
                  fprintf(stderr, "scene keep: f=%llu ST%03X slot %d grp %06X - the scene's shot left it off, kept on %08X -> %08X%c",
                          (unsigned long long)s_frame_count_ref(), dc_room_stcode(), i, gp & 0xFFFFFFu, st, nv, 10); }
            continue;
        }
        /* NEVER FORCE A PLACED OBJECT.
         * The per-shot cull hides pieces of the room's BODY - walls, floors,
         * ceilings - and those all ride the camera transform, so their
         * translation is the camera's. A keypad, a readout or a sign is placed:
         * it carries a translation of its own, and it is switched by game
         * logic, not by the cull. Those are the ones that come in pairs - one
         * variant lit, the other dark - and forcing the dark one back on is
         * what lit both at once (user: "надо чтоб одна как в оригинале - это
         * переключатель по логике"). The room still arrives whole, because
         * what the cull hides is never one of these. */
        { float cTx = (float)(int32_t)rrm_u32(ram, 0xBFA08u);
          float cTy = (float)(int32_t)rrm_u32(ram, 0xBFA0Cu);
          float cTz = (float)(int32_t)rrm_u32(ram, 0xBFA10u);
          float tx = (float)(int32_t)rrm_u32(ram, e + 20u);
          float ty = (float)(int32_t)rrm_u32(ram, e + 24u);
          float tz = (float)(int32_t)rrm_u32(ram, e + 28u);
          if (fabsf(tx-cTx) + fabsf(ty-cTy) + fabsf(tz-cTz) > 1.0f) continue; }
        /* НИКОГДА НЕ ЗАЖИГАТЬ ГРУППУ ИЗ ОДНОГО-ДВУХ ПОЛИГОНОВ (13.09.2026, игрок:
         * «декаль-переключатель показывает оба цвета — и красный, и зелёный»).
         * Лампы кодового замка комнаты 3 — четыре секции подряд (10D948..10DA08),
         * в каждой РОВНО ОДИН квад: красная (ff/64/64) мигает по логике игры,
         * зелёная (67/ff/67) держится выключенной, пока код не введён. Смена
         * комнаты сбрасывает «анимированные» слоты, а зелёная никогда не
         * переключается — и первый же кадр зажигал её как «спрятанную
         * отсечкой». Отсечка ракурсов прячет ТЕЛО комнаты, а не одиночные
         * квады: такие группы — всегда варианты индикатора, их решает игра.
         * Замер: showall: FORCE slot 9 grp 10D988 00000001 -> 00000003 при
         * входе в ST103. DC_SHOWALL_MINPOLY=0 — прежнее поведение. */
        { static int minpoly = -1;
          if (minpoly < 0) { const char *e = getenv("DC_SHOWALL_MINPOLY"); minpoly = e ? atoi(e) : 3; }
          uint32_t gpa = gp & 0x1FFFFFFFu;
          if (minpoly > 0 && gpa + 12u < 0x200000u) {
              int npoly = (int)rrm_u16(ram, gpa + 8) + (int)rrm_u16(ram, gpa + 10);
              if (npoly < minpoly) {
                  static long nskip = 0;
                  if (((st & 3u) != 3u) && ++nskip < 40)
                      fprintf(stderr, "showall: slot %d grp %06X - %d polys, indicator variant, not forced%c",
                              i, gpa, npoly, 10);
                  continue;
              } } }
        /* and never while the game is loading or in a scripted sequence: the
         * entries are being rebuilt, and forcing half-written ones is what
         * made the panels vanish during a room load */
        { extern int dc_scene_stairs_keep(void);   /* 04.10 (4): ходьба по лестнице под нашей камерой — дожигаем, как в игре */
          extern int dc_scene_ourcam_play(void);   /* 07.10: и любая сцена под нашей камерой в той же комнате */
          if (ram[0xB92C8] == 4 && !dc_scene_stairs_keep() && !dc_scene_ourcam_play()) continue; }
        /* +64 == 0 is normal for the room itself: the walker then takes the
         * default transform at [0x1F800000]+180 instead of an object's own. */
        if (mx && ((mx & 0x1FFFFFFFu) == 0 || (mx & 0x1FFFFFFFu) >= 0x200000u)) continue;
        if ((st & 3u) == 3u) { on++; continue; }
        /* ⭐ ДОЖИГАТЬ ТОЛЬКО ТО, ЧТО ИГРА САМА ПОКАЗЫВАЛА (18.09.2026, игрок: «в первой загадке есть
         * лишняя моделька — она скрыта в оригинале»). Скрипт комнаты щитка создаёт ПЯТУЮ секцию с
         * моделью батареи и тут же прячет её (CREATE slot 4 + SHOW slot 4 on 0); во всех 32
         * подпрограммах команды показать её нет — это заготовка для второй загадки, где батарею
         * вставляют. Дожигание возвращало ей бит, и в щитке стояло пять батарей вместо четырёх
         * (замер: группа 10C5B4 рисовалась 126 полигонами вместо 63). Объединение кусков такую
         * секцию не принимает — оно требует DC_UNION_CLAIM кадров подряд с битом от самой игры и
         * пишет в журнал «transient ON ... not claimed». Теперь дожигание спрашивает у него: слот,
         * который игра никогда не держала включённым, не зажигаем. Отсечка ракурсов прячет куски,
         * которые игра показывает на своём ракурсе, — их заявка есть, они дожигаются как прежде.
         * DC_SHOWALL_CLAIM=0 — прежнее поведение (зажигать всё). */
        { static int cl = -1;
          if (cl < 0) { const char *ec = getenv("DC_SHOWALL_CLAIM"); cl = (ec && *ec == '0') ? 0 : 1; }
          extern uint8_t g_dc_union_claim[90]; extern uint32_t g_dc_union_claim_grp[90];
          extern int g_dc_union_claim_on, g_dc_union_claim_ready;
          if (cl && g_dc_union_claim_on && g_dc_union_claim_ready && i < 90) {
              uint32_t gpc = gp & 0x1FFFFFFFu;
              /* ⭐ 18.09 вечер (игрок, слот 3: «надо починить опять сетку за ним»): правило выше
               * гасило и куски, которые игра прячет по ракурсу, — в сцене с напарником пропала
               * решётка. Отличие лишней батареи в том, что она ДУБЛИКАТ: её группу уже рисует
               * другая, видимая секция. Уникальную группу не трогаем — её просто некому показать
               * вместо неё. */
              int dup_visible = 0;
              for (int j = 0; j < 36 && !dup_visible; j++) {
                  if (j == i) continue;
                  uint32_t ej = S + 0x7CDCu + 136u * (uint32_t)j;
                  if (ej + 136u > 0x200000u) break;
                  if ((rrm_u32(ram, ej + 60) & 0x1FFFFFFFu) != gpc) continue;
                  if ((rrm_u32(ram, ej + 48) & 3u) == 3u) dup_visible = 1;
              }
              if (dup_visible && (!g_dc_union_claim[i] || g_dc_union_claim_grp[i] != gpc)) {
                  static long nsk = 0; static uint32_t lk = 0xFFFFFFFFu, lg = 0;
                  if (((uint32_t)i != lk || gpc != lg) && ++nsk < 120) {
                      lk = (uint32_t)i; lg = gpc;
                      fprintf(stderr, "showall: slot %d grp %06X - the game never had it on, not forced%c",
                              i, gpc, 10);
                  }
                  continue;
              }
          } }
        if (dc_room_version_off(i, gp & 0x1FFFFFFFu) || dc_room_script_anim(i) || dc_room_debris_slot(i)) {   /* 04.10 (3): версия места чужого ракурса / анимация скрипта / закрашенная копия */
            static long nva = 0; static uint32_t lk3 = 0xFFFFFFFFu, lg3 = 0;
            if (((uint32_t)i != lk3 || (gp & 0x1FFFFFFFu) != lg3) && ++nva < 60) { lk3 = (uint32_t)i; lg3 = gp & 0x1FFFFFFFu;
                fprintf(stderr, "showall: slot %d grp %06X - %s, not forced%c", i, gp & 0xFFFFFFu,
                        dc_room_script_anim(i) ? "the script animates its visibility" : dc_room_debris_slot(i) ? "a copy the console paints over" :
                        "a version of its place the current shot hides", 10); }
            continue;
        }
        if (dc_room_slot_story_hidden(i, gp & 0x1FFFFFFFu)) {       /* 20.09 день: слот спрятан сюжетом, а не ракурсом (ss_*) */
            static long nss = 0; static uint32_t lk2 = 0xFFFFFFFFu, lg2 = 0;
            if (((uint32_t)i != lk2 || (gp & 0x1FFFFFFFu) != lg2) && ++nss < 120) { lk2 = (uint32_t)i; lg2 = gp & 0x1FFFFFFFu;
                fprintf(stderr, "showall: slot %d grp %06X - hidden by the story (room script), not forced%c", i, gp & 0xFFFFFFu, 10); }
            continue;
        }
        uint32_t nv = (st & ~3u) | 3u;
        /* LASER SUSPECT #2 (2026-09-04): this forces a section's visibility
         * bits back on. Key 8 (g_dc_showall_force) gates only the write. */
        { extern int g_dc_showall_force;
          if (!g_dc_showall_force) continue; }
        if (i < 36 && (!s_sa_have[i] || s_sa_grp[i] != (gp & 0x1FFFFFFFu))) {
            s_sa_saved[i] = st; s_sa_have[i] = 1; s_sa_grp[i] = gp & 0x1FFFFFFFu; }
        if (i < 36) s_sa_wrote[i] = nv;
        ram[e + 48] = (uint8_t)(nv & 0xFF);        ram[e + 49] = (uint8_t)((nv >> 8) & 0xFF);
        ram[e + 50] = (uint8_t)((nv >> 16) & 0xFF); ram[e + 51] = (uint8_t)((nv >> 24) & 0xFF);
        forced++;
        { uint32_t gpf = rrm_u32(ram, e + 60) & 0x1FFFFFFFu;
          static long nf = 0; static uint32_t lasti = 0xFFFFFFFFu, lastg = 0;
          if ((( uint32_t)i != lasti || gpf != lastg) && ++nf < 200) {
              lasti = (uint32_t)i; lastg = gpf;
              fprintf(stderr, "showall: FORCE slot %d grp %06X %08X -> %08X%c",
                      i, gpf, st, nv, 10);
          } }
    }
    { static int la = -1, lf = -1;
      if (on != la || forced != lf) { la = on; lf = forced;
          fprintf(stderr, "room showall: %d room portions already on, %d forced back on%c",
                  on, forced, 10); } }
    s_showall_forced = forced;
}
